try:
    from zoneinfo import ZoneInfo as _ZoneInfo
    _LAGOS_TZ = _ZoneInfo("Africa/Lagos")
except Exception:
    _LAGOS_TZ = None


class _LagosTsFormatter(Formatter):
    """Console timestamps in Lagos time (matches main.py) so every log
    stream agrees on one timezone instead of mixing UTC and +01:00."""

    def formatTime(self, record, datefmt=None):
        if _LAGOS_TZ is not None:
            try:
                dt = datetime.fromtimestamp(record.created, _LAGOS_TZ)
                return dt.strftime('%Y-%m-%d %H:%M:%S,') + "%03d" % (dt.microsecond // 1000)
            except Exception:
                pass
        return Formatter.formatTime(self, record, datefmt)


logger = logging.getLogger(__name__)
if not logger.handlers:
    handler = StreamHandler(sys.stdout)
    formatter = _LagosTsFormatter('[%(asctime)s] [%(levelname)s] [%(name)s] %(message)s')
    handler.setFormatter(formatter)
    logger.addHandler(handler)
    logger.setLevel(os.getenv("LOG_LEVEL", "INFO").upper())

