def _json_safe_default(obj):
    if isinstance(obj, (pd.Timestamp, datetime)):
        return obj.isoformat()
    if isinstance(obj, (np.integer,)):
        return int(obj)
    if isinstance(obj, (np.floating,)):
        return None if np.isnan(obj) else float(obj)
    if isinstance(obj, (np.bool_,)):
        return bool(obj)
    return str(obj)


def _to_json_safe(obj):
    if isinstance(obj, dict):
        return {str(key): _to_json_safe(value) for key, value in obj.items()}
    if isinstance(obj, (list, tuple, set)):
        return [_to_json_safe(value) for value in obj]
    if isinstance(obj, (pd.Timestamp, datetime, np.integer, np.floating, np.bool_)):
        return _json_safe_default(obj)
    return obj


def _append_jsonl(path, payload):
    try:
        with open(path, 'a', encoding='utf-8') as handle:
            handle.write(json.dumps(payload, default=_json_safe_default, sort_keys=True))
            handle.write('\n')
    except Exception as e:
        logger.warning(f"Could not append JSONL record to {path}: {e}")


def _write_jsonl_rows(path, rows):
    tmp_path = None
    try:
        parent = os.path.dirname(path)
        if parent:
            os.makedirs(parent, exist_ok=True)
        tmp_path = f"{path}.tmp"
        with open(tmp_path, 'w', encoding='utf-8') as handle:
            for row in rows or []:
                handle.write(json.dumps(row, default=_json_safe_default, sort_keys=True))
                handle.write('\n')
        try:
            os.replace(tmp_path, path)
        except Exception:
            with open(path, 'w', encoding='utf-8') as handle:
                for row in rows or []:
                    handle.write(json.dumps(row, default=_json_safe_default, sort_keys=True))
                    handle.write('\n')
            if tmp_path and os.path.exists(tmp_path):
                try:
                    os.remove(tmp_path)
                except Exception:
                    pass
    except Exception as e:
        if tmp_path and os.path.exists(tmp_path):
            try:
                os.remove(tmp_path)
            except Exception:
                pass
        logger.warning(f"Could not rewrite JSONL file {path}: {e}")


def _load_json_file(path, default=None):
    default = {} if default is None else default
    if not os.path.exists(path):
        return default
    try:
        with open(path, 'r', encoding='utf-8-sig') as handle:
            payload = json.load(handle)
        return payload
    except Exception as e:
        logger.warning(f"Could not load JSON file {path}: {e}")
        return default


def _save_json_file(path, payload):
    tmp_path = None
    try:
        parent = os.path.dirname(path)
        if parent:
            os.makedirs(parent, exist_ok=True)
        tmp_path = f"{path}.tmp"
        with open(tmp_path, 'w', encoding='utf-8') as handle:
            json.dump(payload, handle, indent=2, default=_json_safe_default)
        last_exc = None
        for attempt in range(5):
            try:
                os.replace(tmp_path, path)
                last_exc = None
                break
            except PermissionError as exc:
                last_exc = exc
                time.sleep(0.2 * (attempt + 1))
        if last_exc is not None:
            with open(path, 'w', encoding='utf-8') as handle:
                json.dump(payload, handle, indent=2, default=_json_safe_default)
            try:
                os.remove(tmp_path)
            except Exception:
                pass
    except Exception as e:
        if tmp_path and os.path.exists(tmp_path):
            try:
                os.remove(tmp_path)
            except Exception:
                pass
        logger.warning(f"Could not save JSON file {path}: {e}")


def _touch_text_file(path):
    try:
        parent = os.path.dirname(path)
        if parent:
            os.makedirs(parent, exist_ok=True)
        if not os.path.exists(path):
            with open(path, 'a', encoding='utf-8'):
                pass
    except Exception as e:
        logger.warning(f"Could not materialize file {path}: {e}")


