def _has_live_of_gate_shadow_pending(symbol=None):
    if not _live_of_gate_shadow_pending:
        return False
    if not symbol:
        return True
    return any(str(row.get('symbol')) == str(symbol) for row in _live_of_gate_shadow_pending.values())


def _load_jsonl_rows(path):
    rows = []
    if not os.path.exists(path):
        return rows
    try:
        with open(path, 'r', encoding='utf-8-sig') as handle:
            for line in handle:
                line = str(line).strip()
                if not line:
                    continue
                try:
                    rows.append(json.loads(line))
                except Exception:
                    continue
    except Exception as e:
        logger.warning(f"Could not read JSONL records from {path}: {e}")
    return rows


def _trade_audit_identity_key(row):
    row = row or {}
    symbol = str(row.get("symbol") or "").strip().upper()
    order_id = str(row.get("order_id") or "").strip()
    client_oid = str(row.get("client_oid") or "").strip()
    if symbol and order_id:
        return ("order_id", symbol, order_id)
    if symbol and client_oid:
        return ("client_oid", symbol, client_oid)
    return None

def _build_trade_audit_resolution_key(row):
    row = row or {}
    identity = _trade_audit_identity_key(row)
    if identity is not None:
        return ("trade_identity",) + identity
    return (
        str(row.get("record_id") or ""),
        str(row.get("audit_id") or ""),
        str(row.get("order_id") or ""),
        str(row.get("client_oid") or ""),
        str(row.get("symbol") or ""),
        str(row.get("trigger_type") or row.get("primary_setup") or ""),
        str(row.get("direction") or ""),
        str(row.get("audit_status") or ""),
        str(row.get("resolution_status") or ""),
        str(row.get("placement_time") or ""),
    )


def _dedupe_trade_audit_resolved_rows(rows):
    latest_by_key = {}
    for row in rows or []:
        key = _build_trade_audit_resolution_key(row)
        current = latest_by_key.get(key)
        if current is None:
            latest_by_key[key] = row
            continue
        current_ts = _parse_any_timestamp(
            current.get("resolved_at")
            or current.get("exit_time")
            or current.get("placement_time")
        ) or pd.Timestamp.min.tz_localize("UTC")
        row_ts = _parse_any_timestamp(
            row.get("resolved_at")
            or row.get("exit_time")
            or row.get("placement_time")
        ) or pd.Timestamp.min.tz_localize("UTC")
        if row_ts >= current_ts:
            latest_by_key[key] = row
    return list(latest_by_key.values())


def _stable_shadow_numeric_token(value, *, price_place=None):
    numeric = _safe_float(value)
    if numeric is None:
        return ""
    decimals = price_place if price_place is not None else 8
    decimals = max(0, min(_safe_int(decimals, 8), 10))
    rounded = round(float(numeric), decimals)
    if decimals == 0:
        return str(int(round(rounded)))
    return f"{rounded:.{decimals}f}"


def _build_live_rejected_shadow_fingerprint(payload):
    payload = payload or {}
    symbol = _normalize_bitget_symbol(payload.get("symbol"))
    if not symbol:
        return None
    decision_ms = (
        _safe_int(payload.get("decision_candle_ts_ms"), None)
        or _timestamp_to_ms(payload.get("decision_candle_time"))
        or _timestamp_to_ms(payload.get("decision_ts"))
    )
    if decision_ms is None:
        return None
    price_place = _safe_int(payload.get("price_place"), None)
    parts = (
        symbol,
        str(payload.get("direction") or "").strip().upper(),
        str(payload.get("trigger_type") or payload.get("primary_setup") or "unknown").strip().lower(),
        str(payload.get("selected_level_type") or "").strip().lower(),
        str(decision_ms),
        str(payload.get("rejection_stage") or "unknown").strip().lower(),
        str(payload.get("rejection_reason_code") or "unknown").strip().lower(),
        _stable_shadow_numeric_token(payload.get("entry_price"), price_place=price_place),
        _stable_shadow_numeric_token(payload.get("stop_loss"), price_place=price_place),
        _stable_shadow_numeric_token(payload.get("take_profit_1"), price_place=price_place),
        _stable_shadow_numeric_token(payload.get("take_profit_2"), price_place=price_place),
    )
    digest = hashlib.sha1("|".join(parts).encode("utf-8")).hexdigest()[:20]
    return f"rejshadow_{digest}"


def _merge_live_rejected_shadow_record(existing, incoming):
    existing = dict(existing or {})
    incoming = dict(incoming or {})
    first_seen_at = (
        existing.get("first_seen_at")
        or existing.get("logged_at")
        or incoming.get("first_seen_at")
        or incoming.get("logged_at")
        or _utc_now_iso()
    )
    existing_seen = max(1, _safe_int(existing.get("seen_count"), 1))
    existing_hits = max(existing_seen, _safe_int(existing.get("rejection_hits"), existing_seen))
    merged = dict(existing)
    merged.update(incoming)
    merged["rejected_shadow_id"] = existing.get("rejected_shadow_id") or incoming.get("rejected_shadow_id")
    merged["setup_fingerprint"] = existing.get("setup_fingerprint") or incoming.get("setup_fingerprint")
    merged["logged_at"] = existing.get("logged_at") or incoming.get("logged_at") or first_seen_at
    merged["first_seen_at"] = first_seen_at
    merged["last_seen_at"] = incoming.get("logged_at") or _utc_now_iso()
    merged["seen_count"] = existing_seen + 1
    merged["rejection_hits"] = existing_hits + 1
    return merged


def _load_live_rejected_shadow_resolved_fingerprints():
    global _live_rejected_shadow_resolved_fingerprints
    fingerprints = set()
    for row in _load_jsonl_rows(_LIVE_REJECTED_SHADOW_RESOLVED_FILE):
        fingerprint = (
            str(row.get("setup_fingerprint") or "").strip()
            or _build_live_rejected_shadow_fingerprint(row)
        )
        if fingerprint:
            fingerprints.add(fingerprint)
    _live_rejected_shadow_resolved_fingerprints = fingerprints


def _refresh_live_of_gate_shadow_summary():
    try:
        pending_rows = list(_live_of_gate_shadow_pending.values())
        resolved_rows = _load_jsonl_rows(_LIVE_OF_SHADOW_RESOLVED_FILE)

        pending_by_decision = Counter(str(row.get('of_gate_decision') or 'unknown') for row in pending_rows)
        resolved_by_decision = Counter(str(row.get('of_gate_decision') or 'unknown') for row in resolved_rows)
        resolved_by_bucket = Counter(
            (
                str(row.get('of_gate_decision') or 'unknown'),
                str(row.get('outcome_bucket') or 'unknown'),
            )
            for row in resolved_rows
        )
        summary = {
            'updated_at': _utc_now_iso(),
            'pending_count': len(pending_rows),
            'pending_by_decision': dict(sorted(pending_by_decision.items())),
            'resolved_count': len(resolved_rows),
            'resolved_by_decision': dict(sorted(resolved_by_decision.items())),
            'resolved_by_decision_and_outcome': [
                {
                    'of_gate_decision': decision,
                    'outcome_bucket': outcome,
                    'count': count,
                }
                for (decision, outcome), count in sorted(resolved_by_bucket.items(), key=lambda item: (-item[1], item[0][0], item[0][1]))
            ],
            'blocked_winners': sum(
                1 for row in resolved_rows
                if str(row.get('of_gate_decision', '')).startswith('blocked')
                and str(row.get('outcome_bucket')) == 'winner'
            ),
            'soft_bypassed_winners': sum(
                1 for row in resolved_rows
                if str(row.get('of_gate_decision', '')).startswith('soft_bypassed')
                and str(row.get('outcome_bucket')) == 'winner'
            ),
            'passed_winners': sum(
                1 for row in resolved_rows
                if str(row.get('of_gate_decision')) == 'passed'
                and str(row.get('outcome_bucket')) == 'winner'
            ),
        }
        with open(_LIVE_OF_SHADOW_SUMMARY_FILE, 'w', encoding='utf-8') as handle:
            json.dump(summary, handle, indent=2, default=_json_safe_default)
    except Exception as e:
        logger.warning(f"Could not refresh live OF shadow summary: {e}")


def _to_df_comparable_timestamp(raw_ts, df_index):
    if raw_ts is None:
        return None
    try:
        ts = pd.Timestamp(raw_ts)
    except Exception:
        return None
    if pd.isna(ts):
        return None
    if ts.tzinfo is None:
        ts = ts.tz_localize('UTC')
    else:
        ts = ts.tz_convert('UTC')
    index_tz = getattr(df_index, 'tz', None)
    return ts.tz_localize(None) if index_tz is None else ts.tz_convert(index_tz)


def _last_df_timestamp(df):
    if df is None or getattr(df, 'empty', True):
        return None
    try:
        idx = df.index[-1]
    except Exception:
        return None
    try:
        ts = pd.Timestamp(idx)
    except Exception:
        return None
    if pd.isna(ts):
        return None
    return ts.tz_localize('UTC') if ts.tzinfo is None else ts.tz_convert('UTC')


def _build_live_shadow_geometry(
    signal,
    entry_price=None,
    atr_value=None,
    df_for_sl=None,
    price_place=None,
    direction=None,
    trigger_type=None,
    swept_level=None,
):
    direction = direction or signal.get('direction')
    trigger_type = trigger_type or signal.get('trigger_type')
    price_place = int(price_place if price_place is not None else signal.get('price_place', 4) or 4)
    atr_value = float(atr_value if atr_value is not None else signal.get('atr_value', 0.0) or 0.0)
    target_entry = float(entry_price if entry_price is not None else signal.get('entry_price', 0.0) or 0.0)
    if target_entry <= 0:
        return {}

    existing_entry = float(signal.get('entry_price', target_entry) or target_entry)
    existing_sl = signal.get('stop_loss')
    existing_tp1 = signal.get('take_profit_1')
    existing_tp2 = signal.get('take_profit_2')
    existing_tsl = signal.get('trailing_stop_loss')
    needs_recalc = (
        existing_sl is None
        or existing_tp1 is None
        or abs(existing_entry - target_entry) > 1e-9
    )
    if not needs_recalc:
        return {
            'entry_price': round(target_entry, price_place),
            'stop_loss': existing_sl,
            'take_profit_1': existing_tp1,
            'take_profit_2': existing_tp2,
            'trailing_stop_loss': existing_tsl,
            'geometry_source': 'signal_existing',
        }

    try:
        sl, tp1, tp2, trailing_sl = calculate_sl_tp(
            target_entry,
            direction,
            atr_value,
            df_for_sl,
            price_place,
            swept_level=swept_level,
            trigger_type=trigger_type,
        )
        return {
            'entry_price': round(target_entry, price_place),
            'stop_loss': sl,
            'take_profit_1': tp1,
            'take_profit_2': tp2,
            'trailing_stop_loss': trailing_sl,
            'geometry_source': 'recomputed_for_shadow',
        }
    except Exception as e:
        logger.warning(f"[{signal.get('symbol', '?')}] Could not recompute shadow geometry: {e}")
        return {
            'entry_price': round(target_entry, price_place),
            'stop_loss': existing_sl,
            'take_profit_1': existing_tp1,
            'take_profit_2': existing_tp2,
            'trailing_stop_loss': existing_tsl,
            'geometry_source': 'signal_existing_fallback',
        }


def _build_tp15_shadow_geometry_from_live_audit(parent_payload):
    parent_payload = parent_payload or {}
    direction = str(parent_payload.get("direction") or "").strip().upper()
    price_place = int(_safe_int(parent_payload.get("price_place"), 4) or 4)
    entry_price = _safe_float(parent_payload.get("entry_price"))
    stop_loss = _safe_float(parent_payload.get("stop_loss"))
    if direction not in {"BUY", "SELL"} or entry_price is None or stop_loss is None:
        return {}

    risk = abs(float(entry_price) - float(stop_loss))
    if risk <= 0:
        return {}

    tp_multiplier = _safe_float(SIGNAL_CONFIG.get("shadow_tp_rr_multiplier", 1.5), 1.5) or 1.5
    if direction == "BUY":
        target_price = float(entry_price) + (risk * tp_multiplier)
    else:
        target_price = float(entry_price) - (risk * tp_multiplier)

    precision = max(price_place, 4)
    while precision < 10:
        rounded_entry = round(float(entry_price), precision)
        rounded_sl = round(float(stop_loss), precision)
        rounded_tp = round(float(target_price), precision)
        if (
            rounded_entry > 0
            and rounded_sl > 0
            and rounded_tp > 0
            and abs(rounded_entry - rounded_sl) > 0
            and abs(rounded_entry - rounded_tp) > 0
        ):
            break
        precision += 1
    else:
        rounded_entry = round(float(entry_price), precision)
        rounded_sl = round(float(stop_loss), precision)
        rounded_tp = round(float(target_price), precision)

    return {
        "entry_price": rounded_entry,
        "stop_loss": rounded_sl,
        "take_profit_1": rounded_tp,
        "take_profit_2": rounded_tp,
        "trailing_stop_loss": rounded_tp,
        "shadow_entry_price_exact": float(entry_price),
        "shadow_stop_loss_exact": float(stop_loss),
        "shadow_take_profit_1_exact": float(target_price),
        "shadow_take_profit_2_exact": float(target_price),
        "geometry_source": "shadow_tp15_rr_from_live_risk",
        "shadow_tp_rr_multiplier": round(float(tp_multiplier), 4),
        "shadow_price_place_used": precision,
        "shadow_live_risk_distance": round(risk, price_place + 2),
    }


def _build_trade_audit_identity_index(rows):
    audit_ids = set()
    identity_keys = set()
    by_audit_id = {}
    by_identity = {}
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        audit_id = str(row.get("audit_id") or "").strip()
        if audit_id:
            audit_ids.add(audit_id)
            by_audit_id[audit_id] = row
        identity = _trade_audit_identity_key(row)
        if identity is not None:
            identity_keys.add(identity)
            by_identity[identity] = row
    return {
        "audit_ids": audit_ids,
        "identity_keys": identity_keys,
        "by_audit_id": by_audit_id,
        "by_identity": by_identity,
    }


def _shadow_parent_trade_identity(record):
    record = record or {}
    symbol = str(record.get("symbol") or "").strip().upper()
    order_id = str(record.get("shadow_parent_order_id") or record.get("order_id") or "").strip()
    client_oid = str(record.get("shadow_parent_client_oid") or record.get("client_oid") or "").strip()
    if symbol and order_id:
        return ("order_id", symbol, order_id)
    if symbol and client_oid:
        return ("client_oid", symbol, client_oid)
    return None


def _sanitize_live_trade_audit_tp15_pending(pending=None, *, resolved_index=None):
    pending = dict(pending or {})
    resolved_index = resolved_index or _build_trade_audit_identity_index(
        _dedupe_trade_audit_resolved_rows(_load_jsonl_rows(_LIVE_TRADE_AUDIT_TP15_RESOLVED_FILE))
    )
    normalized_pending = {}
    seen_parent_identities = set()
    changed = False

    for record_id, record in pending.items():
        row = dict(record or {})
        audit_id = str(row.get("audit_id") or record_id or "").strip()
        if not audit_id:
            changed = True
            continue
        if audit_id in resolved_index.get("audit_ids", set()):
            changed = True
            continue

        parent_identity = _shadow_parent_trade_identity(row)
        if parent_identity is not None and parent_identity in resolved_index.get("identity_keys", set()):
            changed = True
            continue
        if parent_identity is not None and parent_identity in seen_parent_identities:
            changed = True
            continue

        row["audit_id"] = audit_id
        row["shadow_audit_id"] = str(row.get("shadow_audit_id") or audit_id).strip() or audit_id
        row["shadow_experiment"] = row.get("shadow_experiment") or "tp_rr_multiplier_1p5"
        row["tracking_enabled"] = bool(row.get("tracking_enabled"))
        normalized_pending[audit_id] = row
        if parent_identity is not None:
            seen_parent_identities.add(parent_identity)
        if audit_id != str(record_id or "").strip():
            changed = True

    return normalized_pending, changed


def _build_live_trade_audit_tp15_terminal_resolution(
    record,
    *,
    parent_resolved_row=None,
    exit_reason,
    outcome_bucket="flat",
    realized_r=0.0,
    exit_price=None,
    tp2_touched=False,
    first_hit_ts_ms=None,
    observed_candles=0,
    bars_until_resolution=0,
    resolution_basis="standardized_tp1_vs_sl_on_15m",
):
    record = dict(record or {})
    parent_resolved_row = parent_resolved_row or {}
    decision_ts = _parse_any_timestamp(
        record.get("placement_time")
        or record.get("decision_candle_time")
        or record.get("logged_at")
    )
    parent_ts = _parse_any_timestamp(
        parent_resolved_row.get("exit_time")
        or parent_resolved_row.get("resolved_at")
        or parent_resolved_row.get("resolved_at_ms")
        or parent_resolved_row.get("first_hit_ts_ms")
    )
    end_ts = _parse_any_timestamp(first_hit_ts_ms) if first_hit_ts_ms is not None else parent_ts
    time_to_resolution_minutes = None
    if decision_ts is not None and end_ts is not None:
        time_to_resolution_minutes = round((end_ts.timestamp() - decision_ts.timestamp()) / 60.0, 2)

    resolved = dict(record)
    resolved.update(
        {
            "resolved_at": _utc_now_iso(),
            "exit_time": _json_safe_default(end_ts) if end_ts is not None else None,
            "exit_reason": exit_reason,
            "exit_price": exit_price,
            "outcome_bucket": outcome_bucket,
            "realized_r": realized_r,
            "bars_until_resolution": int(max(0, bars_until_resolution or 0)),
            "tp2_touched": bool(tp2_touched),
            "resolution_basis": resolution_basis,
            "observed_candles": int(max(0, observed_candles or 0)),
            "time_to_resolution_minutes": time_to_resolution_minutes,
            "would_have_won": outcome_bucket == "winner",
            "would_have_lost": outcome_bucket == "loser",
            "shadow_parent_resolution_status": parent_resolved_row.get("resolution_status"),
            "shadow_parent_exit_time": parent_resolved_row.get("exit_time"),
            "shadow_parent_resolved_at": parent_resolved_row.get("resolved_at"),
        }
    )
    return resolved


def _is_tp15_shadow_parent_resolved(record, resolved_index):
    record = record or {}
    parent_audit_id = str(record.get("shadow_parent_audit_id") or "").strip()
    if parent_audit_id and parent_audit_id in _live_trade_audit_pending:
        return False

    parent_identity = _shadow_parent_trade_identity(record)
    resolved_index = resolved_index or {"audit_ids": set(), "identity_keys": set()}
    if parent_audit_id and parent_audit_id in resolved_index.get("audit_ids", set()):
        return True
    if parent_identity is not None and parent_identity in resolved_index.get("identity_keys", set()):
        return True
    return False


def _get_tp15_shadow_parent_resolved_row(record, resolved_index):
    record = record or {}
    resolved_index = resolved_index or {}
    parent_audit_id = str(record.get("shadow_parent_audit_id") or "").strip()
    if parent_audit_id:
        row = (resolved_index.get("by_audit_id") or {}).get(parent_audit_id)
        if isinstance(row, dict):
            return row
    parent_identity = _shadow_parent_trade_identity(record)
    if parent_identity is not None:
        row = (resolved_index.get("by_identity") or {}).get(parent_identity)
        if isinstance(row, dict):
            return row
    return None


def _fetch_live_trade_audit_tp15_resolution_candles(symbol, start_ms, *, end_ms=None, horizon_hours=None):
    symbol = str(symbol or "").strip().upper()
    start_ms = _safe_int(start_ms, None)
    if not symbol or start_ms is None:
        return []
    try:
        interval = SIGNAL_CONFIG.get("candlestick_interval", "15m")
        interval_ms = max(_interval_to_seconds(interval), 60) * 1000
        horizon_hours = float(
            horizon_hours
            if horizon_hours is not None
            else SIGNAL_CONFIG.get("live_intelligence_horizon_hours", 72) or 72
        )
        batch_limit = min(int(SIGNAL_CONFIG.get("live_intelligence_candle_batch_limit", 200) or 200), 200)
        fetch_start = max(int(start_ms - 60 * 60 * 1000), 0)
        default_end = int(start_ms + (horizon_hours * 3600 * 1000))
        fetch_end = min(int(time.time() * 1000), int(end_ms if end_ms is not None else default_end))
        if fetch_end <= fetch_start:
            return []

        rows_by_ts = {}
        cursor = fetch_start
        max_batches = 12
        for _ in range(max_batches):
            if cursor >= fetch_end:
                break
            batch = get_candlestick_data(
                symbol,
                interval,
                limit=batch_limit,
                start_time=cursor,
                end_time=fetch_end,
            ) or []
            if not batch:
                break
            last_ts = None
            for candle in batch:
                ts = _safe_int((candle or {}).get("timestamp"), None)
                if ts is None:
                    continue
                rows_by_ts[ts] = candle
                last_ts = ts
            if last_ts is None:
                break
            next_cursor = last_ts + interval_ms
            if next_cursor <= cursor:
                break
            cursor = next_cursor
            if len(batch) < batch_limit:
                break
        return [rows_by_ts[ts] for ts in sorted(rows_by_ts)]
    except Exception as exc:
        logger.warning(f"[{symbol}] Could not fetch TP1.5 shadow resolution candles: {exc}")
        return []


def _resolve_live_trade_audit_tp15_shadow_record(record, candles, *, parent_resolved_row=None):
    record = dict(record or {})
    direction = str(record.get("direction") or "").strip().upper()
    entry_price = _safe_float(record.get("shadow_entry_price_exact"))
    if entry_price is None:
        entry_price = _safe_float(record.get("entry_price"), 0.0) or 0.0
    stop_loss = _safe_float(record.get("shadow_stop_loss_exact"))
    if stop_loss is None:
        stop_loss = _safe_float(record.get("stop_loss"), 0.0) or 0.0
    take_profit_1 = _safe_float(record.get("shadow_take_profit_1_exact"))
    if take_profit_1 is None:
        take_profit_1 = _safe_float(record.get("take_profit_1"), 0.0) or 0.0
    take_profit_2 = _safe_float(record.get("shadow_take_profit_2_exact"))
    if take_profit_2 is None:
        take_profit_2 = _safe_float(record.get("take_profit_2"))
    if direction not in {"BUY", "SELL"} or entry_price <= 0 or stop_loss <= 0 or take_profit_1 <= 0:
        return _build_live_trade_audit_tp15_terminal_resolution(
            record,
            parent_resolved_row=parent_resolved_row,
            exit_reason="shadow_geometry_invalid_non_positive",
            outcome_bucket="flat",
            realized_r=0.0,
            resolution_basis="standardized_tp1_vs_sl_on_15m_invalid_geometry",
        )

    decision_ts = _parse_any_timestamp(
        record.get("placement_time")
        or record.get("decision_candle_time")
        or record.get("logged_at")
    )
    if decision_ts is None:
        return _build_live_trade_audit_tp15_terminal_resolution(
            record,
            parent_resolved_row=parent_resolved_row,
            exit_reason="shadow_metadata_missing_placement_time",
            outcome_bucket="flat",
            realized_r=0.0,
            resolution_basis="standardized_tp1_vs_sl_on_15m_missing_metadata",
        )
    decision_ms = int(decision_ts.timestamp() * 1000)

    parent_ts = _parse_any_timestamp(
        (parent_resolved_row or {}).get("exit_time")
        or (parent_resolved_row or {}).get("resolved_at")
        or (parent_resolved_row or {}).get("resolved_at_ms")
        or (parent_resolved_row or {}).get("first_hit_ts_ms")
    )
    parent_end_ms = int(parent_ts.timestamp() * 1000) if parent_ts is not None else int(time.time() * 1000)

    if not candles:
        return _build_live_trade_audit_tp15_terminal_resolution(
            record,
            parent_resolved_row=parent_resolved_row,
            exit_reason="parent_resolved_without_tp15_candles",
            outcome_bucket="flat",
            realized_r=0.0,
            resolution_basis="standardized_tp1_vs_sl_on_15m_no_candles",
        )

    eligible_candles = [
        candle for candle in candles
        if _safe_int((candle or {}).get("timestamp"), 0) > decision_ms
        and _safe_int((candle or {}).get("timestamp"), 0) <= parent_end_ms
    ]
    if not eligible_candles:
        return _build_live_trade_audit_tp15_terminal_resolution(
            record,
            parent_resolved_row=parent_resolved_row,
            exit_reason="parent_resolved_without_eligible_15m_bar",
            outcome_bucket="flat",
            realized_r=0.0,
            observed_candles=0,
            bars_until_resolution=0,
            resolution_basis="standardized_tp1_vs_sl_on_15m_no_eligible_bar",
        )

    risk = abs(entry_price - stop_loss)
    if risk <= 0:
        return _build_live_trade_audit_tp15_terminal_resolution(
            record,
            parent_resolved_row=parent_resolved_row,
            exit_reason="shadow_geometry_invalid_zero_risk",
            outcome_bucket="flat",
            realized_r=0.0,
            observed_candles=len(eligible_candles),
            bars_until_resolution=0,
            resolution_basis="standardized_tp1_vs_sl_on_15m_invalid_geometry",
        )

    first_hit_ts_ms = None
    exit_reason = None
    exit_price = None
    outcome_bucket = "flat"
    realized_r = 0.0
    tp2_touched = False

    for bars_seen, candle in enumerate(eligible_candles, start=1):
        high = _safe_float((candle or {}).get("high"))
        low = _safe_float((candle or {}).get("low"))
        if high is None or low is None:
            continue

        if direction == "BUY":
            tp1_hit = high >= take_profit_1
            tp2_hit = (take_profit_2 is not None) and (high >= take_profit_2)
            sl_hit = low <= stop_loss
            standardized_win_r = (take_profit_1 - entry_price) / risk
        else:
            tp1_hit = low <= take_profit_1
            tp2_hit = (take_profit_2 is not None) and (low <= take_profit_2)
            sl_hit = high >= stop_loss
            standardized_win_r = (entry_price - take_profit_1) / risk

        if tp1_hit and sl_hit:
            outcome_bucket = "ambiguous_same_bar"
            exit_reason = "tp1_and_sl_same_bar"
            exit_price = None
            realized_r = None
            tp2_touched = bool(tp2_hit)
            first_hit_ts_ms = _safe_int((candle or {}).get("timestamp"), None)
            break
        if tp1_hit:
            outcome_bucket = "winner"
            exit_reason = "take_profit_2_reached" if tp2_hit else "take_profit_1_hit"
            exit_price = take_profit_2 if tp2_hit and take_profit_2 is not None else take_profit_1
            realized_r = round(float(standardized_win_r), 4)
            tp2_touched = bool(tp2_hit)
            first_hit_ts_ms = _safe_int((candle or {}).get("timestamp"), None)
            break
        if sl_hit:
            outcome_bucket = "loser"
            exit_reason = "stop_loss_hit"
            exit_price = stop_loss
            realized_r = -1.0
            tp2_touched = False
            first_hit_ts_ms = _safe_int((candle or {}).get("timestamp"), None)
            break

    if exit_reason is None:
        exit_reason = "parent_resolved_without_shadow_hit"
        exit_price = None
        realized_r = 0.0

    bars_until_resolution = len(eligible_candles) if first_hit_ts_ms is None else next(
        (idx for idx, candle in enumerate(eligible_candles, start=1) if _safe_int((candle or {}).get("timestamp"), None) == first_hit_ts_ms),
        len(eligible_candles),
    )
    return _build_live_trade_audit_tp15_terminal_resolution(
        record,
        parent_resolved_row=parent_resolved_row,
        exit_reason=exit_reason,
        outcome_bucket=outcome_bucket,
        realized_r=realized_r,
        exit_price=exit_price,
        tp2_touched=tp2_touched,
        first_hit_ts_ms=first_hit_ts_ms,
        observed_candles=len(eligible_candles),
        bars_until_resolution=bars_until_resolution,
        resolution_basis="standardized_tp1_vs_sl_on_15m",
    )


def _record_live_of_gate_shadow(
    signal,
    *,
    stage,
    of_gate_decision,
    of_gate_reason_code,
    of_gate_reason_text,
    final_score,
    static_score,
    min_score_final,
    of_score,
    of_votes,
    microstructure_score,
    directional_pressure,
    imbalance,
    decision_candle_time=None,
    entry_price_override=None,
    atr_value=None,
    df_for_sl=None,
    price_place=None,
    direction=None,
    trigger_type=None,
    swept_level=None,
):
    if _track_only_live_placed_trades():
        return None
    symbol = str(signal.get('symbol') or '')
    if not symbol:
        return None

    geometry = _build_live_shadow_geometry(
        signal,
        entry_price=entry_price_override,
        atr_value=atr_value,
        df_for_sl=df_for_sl,
        price_place=price_place,
        direction=direction,
        trigger_type=trigger_type,
        swept_level=swept_level,
    )
    decision_ts = decision_candle_time or _utc_now_dt()
    shadow_id = f"ofshadow_{symbol}_{int(time.time() * 1000)}_{uuid4().hex[:8]}"
    trackable = bool(geometry.get('entry_price') and geometry.get('stop_loss') and geometry.get('take_profit_1'))

    record = {
        'shadow_id': shadow_id,
        'logged_at': _utc_now_iso(),
        'decision_candle_time': _json_safe_default(decision_ts),
        'symbol': symbol,
        'direction': direction or signal.get('direction'),
        'trigger_type': trigger_type or signal.get('trigger_type'),
        'of_gate_stage': stage,
        'of_gate_decision': of_gate_decision,
        'of_gate_reason_code': of_gate_reason_code,
        'of_gate_reason_text': of_gate_reason_text,
        'static_score': int(static_score or 0),
        'final_score': None if final_score is None else int(final_score),
        'min_score_final': None if min_score_final is None else int(min_score_final),
        'of_score': int(of_score or 0),
        'of_votes_raw': int(of_votes or 0),
        'of_vote_points': int((of_votes or 0) * 2),
        'microstructure_score': int(microstructure_score or 0),
        'directional_pressure': float(directional_pressure) if directional_pressure is not None else None,
        'imbalance': float(imbalance) if imbalance is not None else None,
        'market_regime': signal.get('market_regime'),
        'symbol_bucket': signal.get('symbol_bucket'),
        'session_bucket': signal.get('session_bucket'),
        'research_trend_regime': signal.get('research_trend_regime'),
        'research_vol_regime': signal.get('research_vol_regime'),
        'research_adx_regime': signal.get('research_adx_regime'),
        'entry_status_at_review': signal.get('entry_status'),
        'rationale': list(signal.get('rationale', [])),
        'tracking_enabled': trackable,
        **geometry,
    }
    _append_jsonl(_LIVE_OF_SHADOW_EVENTS_FILE, record)

    if trackable:
        _live_of_gate_shadow_pending[shadow_id] = dict(record)
        _save_live_of_gate_shadow_pending()
    _refresh_live_of_gate_shadow_summary()
    return shadow_id


def _resolve_live_of_gate_shadow_record(record, df):
    if df is None or getattr(df, 'empty', True):
        return None
    if 'high' not in df.columns or 'low' not in df.columns:
        return None

    decision_ts = _to_df_comparable_timestamp(record.get('decision_candle_time'), df.index)
    if decision_ts is None:
        return None

    future_df = df[df.index > decision_ts]
    if future_df.empty:
        return None

    direction = str(record.get('direction') or '')
    entry_price = float(record.get('entry_price') or 0.0)
    stop_loss = float(record.get('stop_loss') or 0.0)
    take_profit_1 = float(record.get('take_profit_1') or 0.0)
    if direction not in ('BUY', 'SELL') or entry_price <= 0 or stop_loss <= 0 or take_profit_1 <= 0:
        return None

    risk = abs(entry_price - stop_loss)
    if risk <= 0:
        return None

    for bars_seen, (ts, row) in enumerate(future_df.iterrows(), start=1):
        high = float(row.get('high', np.nan))
        low = float(row.get('low', np.nan))
        if np.isnan(high) or np.isnan(low):
            continue

        if direction == 'BUY':
            tp_hit = high >= take_profit_1
            sl_hit = low <= stop_loss
            win_r = (take_profit_1 - entry_price) / risk
        else:
            tp_hit = low <= take_profit_1
            sl_hit = high >= stop_loss
            win_r = (entry_price - take_profit_1) / risk

        if tp_hit and sl_hit:
            outcome_bucket = 'ambiguous_same_bar'
            exit_reason = 'tp1_and_sl_same_bar'
            exit_price = None
            realized_r = None
        elif tp_hit:
            outcome_bucket = 'winner'
            exit_reason = 'take_profit_1_hit'
            exit_price = take_profit_1
            realized_r = round(float(win_r), 4)
        elif sl_hit:
            outcome_bucket = 'loser'
            exit_reason = 'stop_loss_hit'
            exit_price = stop_loss
            realized_r = -1.0
        else:
            continue

        resolved = dict(record)
        resolved.update({
            'resolved_at': _utc_now_iso(),
            'exit_time': _json_safe_default(ts),
            'exit_reason': exit_reason,
            'exit_price': exit_price,
            'outcome_bucket': outcome_bucket,
            'realized_r': realized_r,
            'bars_until_resolution': bars_seen,
            'resolution_basis': 'tp1_vs_sl_on_15m',
        })
        return resolved

    return None


def _update_live_of_gate_shadow_outcomes(symbol, df):
    if not symbol or df is None or getattr(df, 'empty', True):
        return 0

    resolved_count = 0
    changed = False
    for shadow_id, record in list(_live_of_gate_shadow_pending.items()):
        if str(record.get('symbol')) != str(symbol):
            continue
        resolved = _resolve_live_of_gate_shadow_record(record, df)
        if not resolved:
            continue
        _append_jsonl(_LIVE_OF_SHADOW_RESOLVED_FILE, resolved)
        _live_of_gate_shadow_pending.pop(shadow_id, None)
        resolved_count += 1
        changed = True

    if changed:
        _save_live_of_gate_shadow_pending()
        _refresh_live_of_gate_shadow_summary()
    return resolved_count


_load_live_of_gate_shadow_pending()


