def _load_live_trade_audit_pending():
    global _live_trade_audit_pending
    raw = _load_json_file(_LIVE_TRADE_AUDIT_PENDING_FILE, default={})
    _live_trade_audit_pending = raw if isinstance(raw, dict) else {}


def _save_live_trade_audit_tp15_pending():
    global _live_trade_audit_tp15_pending
    _live_trade_audit_tp15_pending, _ = _sanitize_live_trade_audit_tp15_pending(_live_trade_audit_tp15_pending)
    _save_json_file(_LIVE_TRADE_AUDIT_TP15_PENDING_FILE, _live_trade_audit_tp15_pending)


def _rebuild_live_trade_audit_tp15_pending_from_events():
    rows = _load_jsonl_rows(_LIVE_TRADE_AUDIT_TP15_EVENTS_FILE)
    if not rows:
        return {}

    resolved_index = _build_trade_audit_identity_index(
        _dedupe_trade_audit_resolved_rows(_load_jsonl_rows(_LIVE_TRADE_AUDIT_TP15_RESOLVED_FILE))
    )
    rebuilt_pending = {}
    for row in rows:
        if not isinstance(row, dict):
            continue
        if not bool(row.get("tracking_enabled")):
            continue
        normalized = dict(row)
        audit_id = str(normalized.get("audit_id") or normalized.get("shadow_audit_id") or "").strip()
        if not audit_id:
            continue
        if audit_id in resolved_index.get("audit_ids", set()):
            continue
        normalized["audit_id"] = audit_id
        normalized["shadow_audit_id"] = str(normalized.get("shadow_audit_id") or audit_id).strip() or audit_id
        normalized["shadow_experiment"] = normalized.get("shadow_experiment") or "tp_rr_multiplier_1p5"
        normalized["tracking_enabled"] = bool(normalized.get("tracking_enabled"))
        rebuilt_pending[audit_id] = normalized
    return rebuilt_pending


def _load_live_trade_audit_tp15_pending():
    global _live_trade_audit_tp15_pending
    pending_file_exists = os.path.exists(_LIVE_TRADE_AUDIT_TP15_PENDING_FILE)
    events_file_exists = os.path.exists(_LIVE_TRADE_AUDIT_TP15_EVENTS_FILE)
    raw = _load_json_file(_LIVE_TRADE_AUDIT_TP15_PENDING_FILE, default={})
    pending = raw if isinstance(raw, dict) else {}
    if not pending and events_file_exists:
        pending = _rebuild_live_trade_audit_tp15_pending_from_events()
    resolved_index = _build_trade_audit_identity_index(
        _dedupe_trade_audit_resolved_rows(_load_jsonl_rows(_LIVE_TRADE_AUDIT_TP15_RESOLVED_FILE))
    )

    normalized_pending, changed = _sanitize_live_trade_audit_tp15_pending(
        pending,
        resolved_index=resolved_index,
    )
    _live_trade_audit_tp15_pending = normalized_pending
    if changed or (normalized_pending and not pending_file_exists):
        _save_live_trade_audit_tp15_pending()


def _save_live_rejected_shadow_pending():
    _save_json_file(_LIVE_REJECTED_SHADOW_PENDING_FILE, _live_rejected_shadow_pending)


def _rebuild_live_rejected_shadow_pending_from_events():
    rows = _load_jsonl_rows(_LIVE_REJECTED_SHADOW_EVENTS_FILE)
    if not rows:
        return {}

    rebuilt_pending = {}
    for row in rows:
        if not isinstance(row, dict):
            continue
        if not bool(row.get("tracking_enabled")):
            continue

        normalized = dict(row)
        normalized["decision_candle_ts_ms"] = (
            _safe_int(normalized.get("decision_candle_ts_ms"), None)
            or _timestamp_to_ms(normalized.get("decision_candle_time"))
        )
        fingerprint = (
            str(normalized.get("setup_fingerprint") or "").strip()
            or _build_live_rejected_shadow_fingerprint(normalized)
            or str(normalized.get("rejected_shadow_id") or "").strip()
        )
        if not fingerprint or fingerprint in _live_rejected_shadow_resolved_fingerprints:
            continue

        normalized["setup_fingerprint"] = fingerprint
        normalized["rejected_shadow_id"] = fingerprint
        normalized["first_seen_at"] = normalized.get("first_seen_at") or normalized.get("logged_at") or _utc_now_iso()
        normalized["last_seen_at"] = normalized.get("last_seen_at") or normalized.get("logged_at") or normalized["first_seen_at"]
        normalized["seen_count"] = max(1, _safe_int(normalized.get("seen_count"), 1))
        normalized["rejection_hits"] = max(
            normalized["seen_count"],
            _safe_int(normalized.get("rejection_hits"), normalized["seen_count"]),
        )

        if fingerprint in rebuilt_pending:
            rebuilt_pending[fingerprint] = _merge_live_rejected_shadow_record(
                rebuilt_pending[fingerprint],
                normalized,
            )
        else:
            rebuilt_pending[fingerprint] = normalized

    return rebuilt_pending


def _load_live_rejected_shadow_pending():
    global _live_rejected_shadow_pending
    pending_file_exists = os.path.exists(_LIVE_REJECTED_SHADOW_PENDING_FILE)
    events_file_exists = os.path.exists(_LIVE_REJECTED_SHADOW_EVENTS_FILE)
    raw = _load_json_file(_LIVE_REJECTED_SHADOW_PENDING_FILE, default={})
    pending = raw if isinstance(raw, dict) else {}
    _load_live_rejected_shadow_resolved_fingerprints()

    if not pending and events_file_exists:
        rebuilt_pending = _rebuild_live_rejected_shadow_pending_from_events()
        if rebuilt_pending:
            pending = rebuilt_pending

    normalized_pending = {}
    changed = False

    for record_id, record in pending.items():
        row = dict(record or {})
        row["decision_candle_ts_ms"] = (
            _safe_int(row.get("decision_candle_ts_ms"), None)
            or _timestamp_to_ms(row.get("decision_candle_time"))
        )
        fingerprint = (
            str(row.get("setup_fingerprint") or "").strip()
            or _build_live_rejected_shadow_fingerprint(row)
        )
        if not fingerprint:
            fingerprint = str(record_id or "").strip()
        row["setup_fingerprint"] = fingerprint
        row["rejected_shadow_id"] = fingerprint
        row["first_seen_at"] = row.get("first_seen_at") or row.get("logged_at") or _utc_now_iso()
        row["last_seen_at"] = row.get("last_seen_at") or row.get("logged_at") or row["first_seen_at"]
        row["seen_count"] = max(1, _safe_int(row.get("seen_count"), 1))
        row["rejection_hits"] = max(row["seen_count"], _safe_int(row.get("rejection_hits"), row["seen_count"]))

        if fingerprint in normalized_pending:
            normalized_pending[fingerprint] = _merge_live_rejected_shadow_record(normalized_pending[fingerprint], row)
            changed = True
        else:
            normalized_pending[fingerprint] = row
            if fingerprint != str(record_id or "").strip():
                changed = True

    _live_rejected_shadow_pending = normalized_pending
    if changed or (normalized_pending and not os.path.exists(_LIVE_REJECTED_SHADOW_PENDING_FILE)):
        _save_live_rejected_shadow_pending()
    elif not normalized_pending and not events_file_exists:
        if not pending_file_exists:
            _save_live_rejected_shadow_pending()
        _refresh_live_rejected_shadow_summary()


def _parse_any_timestamp(raw_ts):
    if raw_ts is None:
        return None
    try:
        ts = pd.Timestamp(raw_ts)
    except Exception:
        return None
    if pd.isna(ts):
        return None
    if ts.tzinfo is None:
        ts = ts.tz_localize('UTC')
    else:
        ts = ts.tz_convert('UTC')
    return ts


def _safe_float(value, default=None):
    try:
        if value is None:
            return default
        value = float(value)
        if np.isnan(value):
            return default
        return value
    except Exception:
        return default


def _safe_int(value, default=0):
    try:
        if value is None:
            return default
        return int(value)
    except Exception:
        return default


def _normalize_bitget_symbol(symbol):
    return str(symbol or "").replace("_UMCBL", "").replace("/", "").strip().upper()


def _timestamp_to_ms(raw_ts):
    ts = _parse_any_timestamp(raw_ts)
    if ts is None:
        return None
    return int(ts.timestamp() * 1000)


def _parse_exchange_timestamp(raw_ts):
    if raw_ts in (None, ""):
        return None
    if isinstance(raw_ts, (int, float, np.integer, np.floating)) or str(raw_ts).strip().isdigit():
        try:
            value = int(float(raw_ts))
            unit = "ms" if abs(value) >= 10**11 else "s"
            return pd.to_datetime(value, unit=unit, utc=True)
        except Exception:
            return None
    return _parse_any_timestamp(raw_ts)


def _extract_bitget_rows(response):
    if not isinstance(response, dict) or str(response.get("code")) != "00000":
        return []
    data = response.get("data")
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        for key in (
            "entrustedList",
            "fillList",
            "orderList",
            "planList",
            "dataList",
            "items",
        ):
            rows = data.get(key)
            if isinstance(rows, list):
                return rows
        if data:
            return [data]
    return []


def _parse_fee_detail_total(fee_detail):
    payload = fee_detail
    if payload in (None, "", []):
        return 0.0
    if isinstance(payload, str):
        try:
            payload = json.loads(payload)
        except Exception:
            return _safe_float(payload, 0.0) or 0.0
    if isinstance(payload, dict):
        for key in ("totalFee", "fee", "deductionFee", "newFees", "actualFee"):
            value = _safe_float(payload.get(key))
            if value is not None:
                return value
        return 0.0
    if isinstance(payload, list):
        total = 0.0
        for item in payload:
            total += _parse_fee_detail_total(item)
        return total
    return _safe_float(payload, 0.0) or 0.0


def _extract_exchange_row_size(row):
    for key in ("baseVolume", "size", "filledQty", "fillQty", "volume", "qty"):
        value = _safe_float((row or {}).get(key))
        if value is not None and value > 0:
            return value
    return 0.0


def _extract_exchange_row_price(row, fallback=None):
    for key in ("fillPrice", "priceAvg", "averagePrice", "avgPrice", "price", "tradePrice"):
        value = _safe_float((row or {}).get(key))
        if value is not None and value > 0:
            return value
    return _safe_float(fallback)


def _extract_exchange_row_timestamp(row):
    row = row or {}
    for key in ("cTime", "uTime", "fillTime", "time", "ts"):
        ts = _parse_exchange_timestamp(row.get(key))
        if ts is not None:
            return ts
    return None


def _aggregate_exchange_fill_rows(rows):
    rows = list(rows or [])
    total_size = 0.0
    weighted_price = 0.0
    gross_profit_quote = 0.0
    total_fees_quote = 0.0
    fill_ids = []
    order_ids = set()
    trade_sides = set()
    first_ts = None
    last_ts = None

    for row in rows:
        size = _extract_exchange_row_size(row)
        price = _extract_exchange_row_price(row)
        if size > 0 and price is not None:
            total_size += size
            weighted_price += size * price
        gross_profit_quote += _safe_float((row or {}).get("profit"), 0.0) or 0.0
        total_fees_quote += _parse_fee_detail_total((row or {}).get("feeDetail"))
        fill_id = str((row or {}).get("tradeId") or (row or {}).get("fillId") or "").strip()
        if fill_id:
            fill_ids.append(fill_id)
        order_id = str((row or {}).get("orderId") or "").strip()
        if order_id:
            order_ids.add(order_id)
        trade_side = str((row or {}).get("tradeSide") or "").strip().lower()
        if trade_side:
            trade_sides.add(trade_side)
        ts = _extract_exchange_row_timestamp(row)
        if ts is not None:
            first_ts = ts if first_ts is None else min(first_ts, ts)
            last_ts = ts if last_ts is None else max(last_ts, ts)

    avg_price = (weighted_price / total_size) if total_size > 0 else None
    return {
        "fill_count": len(rows),
        "total_size": round(float(total_size), 10) if total_size > 0 else 0.0,
        "avg_price": round(float(avg_price), 10) if avg_price is not None else None,
        "gross_profit_quote": round(float(gross_profit_quote), 10),
        "total_fees_quote": round(float(total_fees_quote), 10),
        "net_realized_quote": round(float(gross_profit_quote + total_fees_quote), 10),
        "fill_ids": fill_ids,
        "order_ids": sorted(order_ids),
        "trade_sides": sorted(trade_sides),
        "first_fill_time": _json_safe_default(first_ts) if first_ts is not None else None,
        "last_fill_time": _json_safe_default(last_ts) if last_ts is not None else None,
    }


def _normalize_exchange_order_state(state):
    token = str(state or "").strip().lower()
    if token in {"cancelled", "canceled", "cancel"}:
        return "cancelled"
    if token in {"filled", "full_fill", "fully_filled"}:
        return "filled"
    if token in {"partial_fill", "partially_filled", "partial-filled"}:
        return "partial_fill"
    if token in {"init", "new", "live", "open"}:
        return "open"
    return token or "unknown"


def _is_close_trade_side(trade_side):
    token = str(trade_side or "").strip().lower()
    if not token:
        return False
    if token in {"close"}:
        return True
    return (
        "close" in token
        or token.startswith("reduce_")
        or token.startswith("burst_")
        or token.startswith("delivery_")
        or token.startswith("off_close")
        or token.startswith("dte_sys_adl")
    )


def _fetch_exchange_order_detail(record):
    symbol = _normalize_bitget_symbol(record.get("symbol"))
    params = {
        "symbol": symbol,
        "productType": "USDT-FUTURES",
    }
    order_id = str(record.get("order_id") or "").strip()
    client_oid = str(record.get("client_oid") or "").strip()
    if order_id:
        params["orderId"] = order_id
    elif client_oid:
        params["clientOid"] = client_oid
    else:
        return None
    return make_get_request("/api/v2/mix/order/detail", params=params)


def _fetch_exchange_order_history(record, *, order_id=None, start_ms=None, end_ms=None, limit=None):
    symbol = _normalize_bitget_symbol(record.get("symbol"))
    params = {
        "symbol": symbol,
        "productType": "USDT-FUTURES",
        "limit": str(limit or int(SIGNAL_CONFIG.get("live_trade_reconciliation_fill_limit", 100) or 100)),
    }
    resolved_order_id = str(order_id or "").strip()
    if resolved_order_id:
        params["orderId"] = resolved_order_id
    else:
        if start_ms is not None:
            params["startTime"] = str(int(start_ms))
        if end_ms is not None:
            params["endTime"] = str(int(end_ms))
    return make_get_request("/api/v2/mix/order/orders-history", params=params)


def _fetch_exchange_order_fills(record, *, order_id=None, start_ms=None, end_ms=None, limit=None):
    symbol = _normalize_bitget_symbol(record.get("symbol"))
    params = {
        "symbol": symbol,
        "productType": "USDT-FUTURES",
        "limit": str(limit or int(SIGNAL_CONFIG.get("live_trade_reconciliation_fill_limit", 100) or 100)),
    }
    resolved_order_id = str(order_id or "").strip()
    if resolved_order_id:
        params["orderId"] = resolved_order_id
    else:
        if start_ms is not None:
            params["startTime"] = str(int(start_ms))
        if end_ms is not None:
            params["endTime"] = str(int(end_ms))
    return make_get_request("/api/v2/mix/order/fills", params=params)


def _infer_exchange_exit_reason(record, close_fill_agg, close_order_row):
    exit_price = _safe_float(close_fill_agg.get("avg_price")) or _extract_exchange_row_price(close_order_row)
    stop_loss = _safe_float(record.get("stop_loss"))
    take_profit_2 = _safe_float(record.get("take_profit_2"))
    risk = abs((_safe_float(record.get("entry_price"), 0.0) or 0.0) - (stop_loss or 0.0))
    tolerance = risk * float(SIGNAL_CONFIG.get("live_trade_reconciliation_exit_match_tolerance_risk_fraction", 0.2) or 0.2)
    close_trade_side = str((close_order_row or {}).get("tradeSide") or "").strip().lower()
    order_source = str((close_order_row or {}).get("orderSource") or "").strip().lower()
    trailing_client_oid = str(record.get("trailing_client_oid") or "").strip()
    close_client_oid = str((close_order_row or {}).get("clientOid") or "").strip()

    if trailing_client_oid and close_client_oid and close_client_oid == trailing_client_oid:
        return "trailing_stop_executed"
    if "track" in order_source or "moving" in order_source:
        return "trailing_stop_executed"
    if exit_price is not None and stop_loss is not None and abs(exit_price - stop_loss) <= max(tolerance, 1e-9):
        return "stop_loss_closed"
    if exit_price is not None and take_profit_2 is not None and abs(exit_price - take_profit_2) <= max(tolerance, 1e-9):
        return "take_profit_closed"
    if _safe_float(close_fill_agg.get("net_realized_quote"), 0.0) > 0:
        return "profitable_exchange_close"
    if _safe_float(close_fill_agg.get("net_realized_quote"), 0.0) < 0:
        return "losing_exchange_close"
    if close_trade_side:
        return f"exchange_close_{close_trade_side}"
    return "exchange_close_fill"


def _resolve_live_trackable_record_from_exchange(record):
    if not bool(SIGNAL_CONFIG.get("enable_exchange_exact_trade_reconciliation", True)):
        return None

    placement_ts = _parse_any_timestamp(
        record.get("placement_time")
        or record.get("decision_candle_time")
        or record.get("logged_at")
    )
    if placement_ts is None:
        return None

    lookback_hours = float(SIGNAL_CONFIG.get("live_trade_reconciliation_lookback_hours", 96) or 96)
    start_ms = int((placement_ts - pd.Timedelta(hours=lookback_hours)).timestamp() * 1000)
    end_ms = int(pd.Timestamp.utcnow().timestamp() * 1000)

    order_detail_resp = _fetch_exchange_order_detail(record)
    order_detail_rows = _extract_bitget_rows(order_detail_resp)
    order_detail = dict(order_detail_rows[0]) if order_detail_rows else {}
    entry_state = _normalize_exchange_order_state(order_detail.get("state"))

    entry_fill_resp = _fetch_exchange_order_fills(record, order_id=record.get("order_id"), start_ms=start_ms, end_ms=end_ms)
    entry_fill_rows = _extract_bitget_rows(entry_fill_resp)
    entry_fill_agg = _aggregate_exchange_fill_rows(entry_fill_rows)

    if entry_fill_agg["total_size"] <= 0 and entry_state == "cancelled":
        resolved = dict(record)
        resolved.update(
            {
                "resolved_at": _utc_now_iso(),
                "exit_time": _json_safe_default(_parse_exchange_timestamp(order_detail.get("uTime") or order_detail.get("cTime"))),
                "exit_reason": "order_cancelled_unfilled",
                "exit_price": None,
                "outcome_bucket": "not_filled",
                "realized_r": None,
                "bars_until_resolution": None,
                "tp2_touched": False,
                "resolution_basis": "exchange_unfilled_cancellation",
                "exchange_entry_state": entry_state,
                "exchange_entry_fill_count": entry_fill_agg.get("fill_count"),
                "exchange_entry_order_detail": order_detail,
            }
        )
        return resolved

    symbol_fill_resp = _fetch_exchange_order_fills(record, start_ms=start_ms, end_ms=end_ms)
    symbol_fill_rows = _extract_bitget_rows(symbol_fill_resp)
    close_fill_rows = []
    for row in symbol_fill_rows:
        row_ts = _extract_exchange_row_timestamp(row)
        if row_ts is None or row_ts < placement_ts:
            continue
        row_order_id = str((row or {}).get("orderId") or "").strip()
        if row_order_id and row_order_id == str(record.get("order_id") or "").strip():
            continue
        if _is_close_trade_side((row or {}).get("tradeSide")):
            close_fill_rows.append(row)

    if not close_fill_rows:
        return None

    close_groups = defaultdict(list)
    for row in close_fill_rows:
        close_groups[str((row or {}).get("orderId") or "unknown")].append(row)

    ranked_close_groups = []
    for order_id, rows in close_groups.items():
        first_ts = min((_extract_exchange_row_timestamp(row) for row in rows), default=None)
        ranked_close_groups.append((first_ts or pd.Timestamp.max.tz_localize("UTC"), order_id, rows))
    ranked_close_groups.sort(key=lambda item: item[0])
    _, close_order_id, selected_close_rows = ranked_close_groups[0]
    close_fill_agg = _aggregate_exchange_fill_rows(selected_close_rows)

    close_order_history_resp = _fetch_exchange_order_history(
        record,
        order_id=close_order_id,
        start_ms=start_ms,
        end_ms=end_ms,
    )
    close_order_rows = _extract_bitget_rows(close_order_history_resp)
    close_order_row = dict(close_order_rows[0]) if close_order_rows else {}
    exit_price_exact = _safe_float(close_fill_agg.get("avg_price")) or _extract_exchange_row_price(close_order_row)

    entry_price_exact = (
        _safe_float(entry_fill_agg.get("avg_price"))
        or _safe_float(order_detail.get("priceAvg"))
        or _safe_float(order_detail.get("fillPrice"))
        or _safe_float(record.get("actual_fill_price"))
        or _safe_float(record.get("entry_price"))
    )
    entry_size_exact = (
        _safe_float(entry_fill_agg.get("total_size"))
        or _safe_float(order_detail.get("baseVolume"))
        or _safe_float(order_detail.get("size"))
        or _safe_float(record.get("size"))
        or 0.0
    )
    stop_loss = _safe_float(record.get("stop_loss"), 0.0) or 0.0
    risk_quote_value = abs((entry_price_exact or 0.0) - stop_loss) * entry_size_exact if entry_price_exact and stop_loss and entry_size_exact else None

    gross_profit_quote = _safe_float(close_fill_agg.get("gross_profit_quote"), 0.0) or 0.0
    total_fees_quote = (
        _safe_float(entry_fill_agg.get("total_fees_quote"), 0.0) or 0.0
    ) + (
        _safe_float(close_fill_agg.get("total_fees_quote"), 0.0) or 0.0
    )
    net_realized_quote = gross_profit_quote + total_fees_quote

    realized_r = None
    if risk_quote_value and abs(risk_quote_value) > 1e-12:
        realized_r = round(float(net_realized_quote / risk_quote_value), 4)

    flat_tol = float(SIGNAL_CONFIG.get("live_trade_reconciliation_flat_pnl_tolerance_quote", 0.01) or 0.01)
    if net_realized_quote > flat_tol:
        outcome_bucket = "winner"
    elif net_realized_quote < -flat_tol:
        outcome_bucket = "loser"
    else:
        outcome_bucket = "flat"

    exit_reason = _infer_exchange_exit_reason(record, close_fill_agg, close_order_row)
    exit_time = _parse_any_timestamp(close_fill_agg.get("last_fill_time")) or _parse_exchange_timestamp(close_order_row.get("uTime") or close_order_row.get("cTime"))
    resolved = dict(record)
    resolved.update(
        {
            "resolved_at": _utc_now_iso(),
            "exit_time": _json_safe_default(exit_time) if exit_time is not None else None,
            "exit_reason": exit_reason,
            "exit_price": exit_price_exact,
            "outcome_bucket": outcome_bucket,
            "realized_r": realized_r,
            "bars_until_resolution": None,
            "tp2_touched": bool(
                _safe_float(record.get("take_profit_2")) is not None
                and exit_price_exact is not None
                and (
                    (
                        str(record.get("direction") or "") == "BUY"
                        and exit_price_exact >= _safe_float(record.get("take_profit_2"), 0.0)
                    )
                    or (
                        str(record.get("direction") or "") == "SELL"
                        and exit_price_exact <= _safe_float(record.get("take_profit_2"), float("inf"))
                    )
                )
            ),
            "resolution_basis": "exchange_fills_reconciled",
            "entry_price": entry_price_exact,
            "size": entry_size_exact or record.get("size"),
            "risk_quote_value": round(float(risk_quote_value), 10) if risk_quote_value is not None else None,
            "exchange_entry_state": entry_state,
            "exchange_entry_fill_count": entry_fill_agg.get("fill_count"),
            "exchange_entry_avg_price": entry_fill_agg.get("avg_price"),
            "exchange_entry_fees_quote": entry_fill_agg.get("total_fees_quote"),
            "exchange_entry_fill_ids": entry_fill_agg.get("fill_ids"),
            "exchange_exit_order_id": close_order_id,
            "exchange_exit_fill_count": close_fill_agg.get("fill_count"),
            "exchange_exit_avg_price": exit_price_exact,
            "exchange_exit_trade_sides": close_fill_agg.get("trade_sides"),
            "exchange_exit_fill_ids": close_fill_agg.get("fill_ids"),
            "exchange_gross_profit_quote": round(float(gross_profit_quote), 10),
            "exchange_total_fees_quote": round(float(total_fees_quote), 10),
            "exchange_net_realized_quote": round(float(net_realized_quote), 10),
            "exchange_close_order_detail": close_order_row,
        }
    )
    return resolved


def _structure_alignment_relation(structure_4h, structure_15m):
    left = str(structure_4h or "").strip().lower()
    right = str(structure_15m or "").strip().lower()
    directional = {"bullish", "bearish"}
    if left in directional and right in directional:
        return "same_direction" if left == right else "opposed_direction"
    if left or right:
        return "mixed_or_ranging"
    return "unknown"


