def _build_live_swing_snapshot(
    df_15m,
    df_4h_structure,
    atr_value,
    current_price,
    *,
    trigger_type=None,
    swept_level=None,
    breakout_level=None,
    sweep_candle_idx=None,
    breakout_idx=None,
):
    snapshot = {
        "selected_level_type": "unknown",
        "selected_level_age_candles": None,
        "selected_level_distance_atr": None,
        "swing_high_count_15m": 0,
        "swing_low_count_15m": 0,
        "swing_total_count_15m": 0,
        "swing_high_count_4h": 0,
        "swing_low_count_4h": 0,
        "swing_total_count_4h": 0,
        "latest_swing_high_age_15m_candles": None,
        "latest_swing_low_age_15m_candles": None,
        "latest_swing_high_distance_15m_atr": None,
        "latest_swing_low_distance_15m_atr": None,
        "latest_swing_high_age_4h_candles": None,
        "latest_swing_low_age_4h_candles": None,
        "latest_swing_high_distance_4h_atr": None,
        "latest_swing_low_distance_4h_atr": None,
    }

    def _series_metrics(frame, column, prefix):
        if frame is None or getattr(frame, "empty", True) or column not in frame.columns:
            return
        series = frame[column].dropna()
        count = int(len(series))
        snapshot[f"{prefix}_count"] = count
        if series.empty:
            return
        last_idx = series.index[-1]
        try:
            age = int((len(frame) - 1) - frame.index.get_loc(last_idx))
        except Exception:
            age = None
        distance = None
        level = _safe_float(series.iloc[-1])
        if level is not None and atr_value and atr_value > 0 and current_price:
            distance = round(abs(float(current_price) - float(level)) / float(atr_value), 4)
        snapshot[f"latest_{column}_age_{prefix.split('_')[-1]}_candles"] = age
        snapshot[f"latest_{column}_distance_{prefix.split('_')[-1]}_atr"] = distance

    if df_15m is not None and not getattr(df_15m, "empty", True):
        highs_15m = df_15m["swing_high"].dropna() if "swing_high" in df_15m.columns else pd.Series(dtype="float64")
        lows_15m = df_15m["swing_low"].dropna() if "swing_low" in df_15m.columns else pd.Series(dtype="float64")
        snapshot["swing_high_count_15m"] = int(len(highs_15m))
        snapshot["swing_low_count_15m"] = int(len(lows_15m))
        snapshot["swing_total_count_15m"] = int(len(highs_15m) + len(lows_15m))
        _series_metrics(df_15m, "swing_high", "swing_high_15m")
        _series_metrics(df_15m, "swing_low", "swing_low_15m")

    if df_4h_structure is not None and not getattr(df_4h_structure, "empty", True):
        highs_4h = df_4h_structure["swing_high"].dropna() if "swing_high" in df_4h_structure.columns else pd.Series(dtype="float64")
        lows_4h = df_4h_structure["swing_low"].dropna() if "swing_low" in df_4h_structure.columns else pd.Series(dtype="float64")
        snapshot["swing_high_count_4h"] = int(len(highs_4h))
        snapshot["swing_low_count_4h"] = int(len(lows_4h))
        snapshot["swing_total_count_4h"] = int(len(highs_4h) + len(lows_4h))
        _series_metrics(df_4h_structure, "swing_high", "swing_high_4h")
        _series_metrics(df_4h_structure, "swing_low", "swing_low_4h")

    selected_level = None
    selected_level_age = None
    trigger_token = str(trigger_type or "").strip().lower()
    if trigger_token == "sweep" and swept_level is not None:
        snapshot["selected_level_type"] = "swept_level"
        selected_level = _safe_float(swept_level)
        selected_level_age = (
            int((len(df_15m) - 1) - sweep_candle_idx)
            if df_15m is not None and sweep_candle_idx is not None
            else None
        )
        selected_level = _safe_float(breakout_level)
        selected_level_age = (
            int((len(df_15m) - 1) - breakout_idx)
            if df_15m is not None and breakout_idx is not None
            else None
        )

    snapshot["selected_level_age_candles"] = selected_level_age
    if selected_level is not None and atr_value and atr_value > 0 and current_price:
        snapshot["selected_level_distance_atr"] = round(
            abs(float(current_price) - float(selected_level)) / float(atr_value),
            4,
        )

    return snapshot


def _clamp01(value):
    numeric = _safe_float(value)
    if numeric is None:
        return 0.0
    return max(0.0, min(1.0, float(numeric)))


def _compute_entry_distance_atr(entry_price, trigger_level, atr_value):
    entry = _safe_float(entry_price)
    trigger = _safe_float(trigger_level)
    atr = _safe_float(atr_value)
    if entry is None or trigger is None or atr is None or atr <= 0:
        return None
    return round(abs(float(entry) - float(trigger)) / float(atr), 4)


    created = _safe_float(created_at)
    if created is None:
        return 0
    resolved = _safe_float(resolved_at, time.time())
    elapsed = max(0.0, float(resolved) - float(created))
    if elapsed <= 0:
        return 0
    return int(ceil(elapsed / float(candle_seconds or 300)))


    reason = str(reason_text or "").strip().lower()
    if not reason:
        return None
    if "disabled" in reason:
        return "confirmation_disabled"
    if "no anchor level" in reason:
        return "no_anchor_level"
    if "touch tolerance" in reason or "touch-and-reverse" in reason:
        return "touch_and_reverse_not_seen"
    return (
        reason.replace("—", "-")
        .replace("–", "-")
        .replace(" ", "_")
        .replace("/", "_")
        .replace(":", "_")
    )[:80]


def _normalize_vote_breakdown(vote_breakdown):
    if not isinstance(vote_breakdown, dict):
        return {}
    normalized = {}
    for key, value in vote_breakdown.items():
        key_str = str(key or "").strip()
        if not key_str:
            continue
        normalized[key_str] = int(_safe_float(value, 0) or 0)
    return normalized


def _derive_missing_vote_types(vote_breakdown):
    normalized = _normalize_vote_breakdown(vote_breakdown)
    return sorted([key for key, value in normalized.items() if int(value) <= 0])


def _classify_retest_quality(trigger_type, valid_retest=None, retest_msg=None, er_score=None):
    trigger = str(trigger_type or "").strip().lower()
    if trigger != "breakout":
        return "not_applicable"
    if valid_retest is False:
        return "failed"
    if er_score is None:
        message = str(retest_msg or "").lower()
        if "valid retest" in message:
            return "confirmed"
        return "unknown"
    numeric = float(er_score)
    if numeric > 0.3:
        return "strong"
    if numeric >= -0.1:
        return "acceptable"
    return "weak"

def _build_quality_subscores(*, static_score=None, recent_candle_bonus=None, of_score=None, of_votes=None, microstructure_score=None, adx_score=None, final_score=None):
    return {
        "static_score": _safe_float(static_score),
        "recent_candle_bonus": _safe_float(recent_candle_bonus, 0.0),
        "orderflow_score": _safe_float(of_score, 0.0),
        "orderflow_vote_points": int((_safe_int(of_votes, 0) or 0) * 2),
        "microstructure_score": _safe_float(microstructure_score, 0.0),
        "adx_confirmation_score": _safe_float(adx_score, 0.0),
        "final_score": _safe_float(final_score),
    }


def _live_quality_subscores_from_signal(signal, *, static_score=None, recent_candle_bonus=None, of_score=None, of_votes=None, microstructure_score=None, adx_score=None, final_score=None):
    """Build quality telemetry from the same live fields used at decision time."""
    signal = signal or {}
    of_state = signal.get("order_flow_confirmation_state")
    of_state = of_state if isinstance(of_state, dict) else {}
    adx_state = signal.get("adx_confirmation_state")
    adx_state = adx_state if isinstance(adx_state, dict) else {}
    return _build_quality_subscores(
        static_score=_first_non_empty(static_score, signal.get("static_score"), signal.get("quality_score"), signal.get("confidence_score")),
        recent_candle_bonus=_first_non_empty(recent_candle_bonus, signal.get("recent_candle_confirmation_bonus")),
        of_score=_first_non_empty(of_score, signal.get("of_score"), of_state.get("of_score")),
        of_votes=_first_non_empty(of_votes, signal.get("of_votes_raw"), of_state.get("of_votes")),
        microstructure_score=_first_non_empty(
            microstructure_score,
            signal.get("microstructure_score"),
            signal.get("path_microstructure_score"),
            of_state.get("microstructure_score"),
        ),
        adx_score=_first_non_empty(adx_score, signal.get("adx_confirmation_score"), adx_state.get("score")),
        final_score=_first_non_empty(final_score, signal.get("quality_score"), signal.get("of_gate_final_score"), signal.get("confidence_score")),
    )


def _quality_field_usable(value):
    return value not in (None, "", {}, [])


