def _get_live_path_guard(signal):
    payload = _load_json_file(_LIVE_PATH_SCORECARDS_FILE, default={})
    by_path = payload.get("by_path") or []
    if not by_path:
        try:
            resolved_rows = _dedupe_trade_audit_resolved_rows(_load_jsonl_rows(_LIVE_TRADE_AUDIT_RESOLVED_FILE))
            by_path = _build_path_scorecards_payload(resolved_rows).get("by_path", [])
        except Exception as exc:
            logger.debug("Could not rebuild live path guard payload from raw audit rows: %s", exc)
            by_path = []
    trigger_type = str((signal or {}).get("trigger_type") or "unknown")
    row = next((row for row in by_path if str(row.get("trigger_type")) == trigger_type), None)
    if not row:
        return {"blocked": False, "warning": False, "reason": "", "row": None}
    return {
        "blocked": bool(row.get("quarantine_recommended")),
        "warning": bool((row.get("recent_10") or {}).get("expectancy_r", 0.0) < 0),
        "reason": row.get("quarantine_reason") or "",
        "row": row,
    }


def _get_live_symbol_guard(signal):
    payload = _load_json_file(_LIVE_SYMBOL_QUALITY_FILE, default={})
    symbol = str((signal or {}).get("symbol") or "unknown")
    row = next((row for row in payload.get("symbols", []) if str(row.get("symbol")) == symbol), None)
    if not row:
        return {"blocked": False, "warning": False, "reason": "", "row": None}
    reason = (
        f"Live symbol quality weak: expectancy={row.get('expectancy_r')}R, "
        f"failure_rate={row.get('placement_failure_rate')}"
    )
    return {
        "blocked": bool(row.get("block_recommended")),
        "warning": bool(row.get("warning")),
        "reason": reason,
        "row": row,
    }


def _append_signal_gate_observation(
    signal,
    *,
    stage,
    reason_code,
    reason_text,
    metrics=None,
    mode="audit_only",
):
    signal = signal or {}
    gate_observations = signal.setdefault("gate_observations", [])
    observation_key = (
        str(stage or "unknown"),
        str(reason_code or "unknown"),
        str(reason_text or ""),
        str(mode or "audit_only"),
    )
    for existing in gate_observations:
        existing_key = (
            str(existing.get("stage") or "unknown"),
            str(existing.get("reason_code") or "unknown"),
            str(existing.get("reason_text") or ""),
            str(existing.get("mode") or "audit_only"),
        )
        if existing_key == observation_key:
            return False

    mode_token = str(mode or "audit_only")
    observation = {
        "stage": str(stage or "unknown"),
        "reason_code": str(reason_code or "unknown"),
        "reason_text": str(reason_text or ""),
        "timestamp": _utc_now_iso(),
        "mode": mode_token,
    }
    if metrics:
        safe_metrics = {
            str(key): _json_safe_default(value)
            for key, value in dict(metrics).items()
        }
        observation["metrics"] = safe_metrics
        signal.setdefault("gate_value_observations", {})[
            str(reason_code or "unknown")
        ] = safe_metrics
    gate_observations.append(observation)
    if mode_token == "audit_only":
        prefix = "AUDIT-ONLY gate observed"
    elif mode_token == "hard_block":
        prefix = "HARD-BLOCK gate observed"
    else:
        prefix = f"{mode_token.upper()} gate observed"
    signal.setdefault("rationale", []).append(
        f"{prefix} [{reason_code}]: {reason_text}"
    )
    return True


def _build_live_context_rule_metrics(signal, live_context, matched_rule=None):
    signal = signal or {}
    live_context = live_context or {}
    matched_rule = dict(matched_rule or {})
    metrics = {
        "trigger_type": live_context.get("trigger_type"),
        "direction": live_context.get("direction"),
        "selected_level_type": live_context.get("selected_level_type"),
        "selected_level_age_bucket": live_context.get("selected_level_age_bucket"),
        "selected_level_age_candles": signal.get("selected_level_age_candles"),
        "selected_level_distance_bucket": live_context.get("selected_level_distance_bucket"),
        "selected_level_distance_atr": signal.get("selected_level_distance_atr"),
        "swing_total_count_15m_bucket": live_context.get("swing_total_count_15m_bucket"),
        "swing_total_count_15m": signal.get("swing_total_count_15m"),
        "swing_total_count_4h_bucket": live_context.get("swing_total_count_4h_bucket"),
        "swing_total_count_4h": signal.get("swing_total_count_4h"),
    }
    if matched_rule:
        metrics["matched_rule"] = {
            str(key): _json_safe_default(value)
            for key, value in matched_rule.items()
        }
        metrics["matched_context_values"] = {
            str(key): _json_safe_default(live_context.get(key))
            for key in matched_rule.keys()
            if not str(key).startswith("_")
        }
    return {
        str(key): _json_safe_default(value)
        for key, value in metrics.items()
        if value not in (None, "", {}, [])
    }


def _compute_context_risk_profile(signal):
    signal = signal or {}
    reasons = []
    fixed_multiplier = 1.0
    signal["_pre_context_risk_multiplier"] = fixed_multiplier
    live_context = _build_live_rule_context(signal)
    live_context_audit_only_matched, live_context_audit_only_reason, live_context_audit_only_rule = _evaluate_named_rule_match(
        live_context,
        _get_mode_aware_rule_list("live_context_audit_only_rules"),
        label="Live context audit-only",
    )
    if live_context_audit_only_matched:
        _append_signal_gate_observation(
            signal,
            stage="live_context",
            reason_code="live_context_audit_only_rule_matched",
            reason_text=live_context_audit_only_reason or "Live context matched audit-only rule",
            metrics=_build_live_context_rule_metrics(signal, live_context, live_context_audit_only_rule),
            mode="audit_only",
        )
    live_context_blocked, live_context_reason, live_context_block_rule = _evaluate_named_rule_match(
        live_context,
        _get_mode_aware_rule_list("live_context_hard_block_rules"),
        label="Live context hard-blocked",
    )
    if live_context_blocked:
        _append_signal_gate_observation(
            signal,
            stage="live_context",
            reason_code="live_context_blocked",
            reason_text=live_context_reason or "Blocked by live context hard-block rules",
            metrics=_build_live_context_rule_metrics(signal, live_context, live_context_block_rule),
            mode="hard_block",
        )
        return {
            "blocked": True,
            "reason_code": "live_context_blocked",
            "reason_text": live_context_reason or "Blocked by live context hard-block rules",
            "multiplier": 0.0,
            "tier": "blocked",
            "reasons": reasons + [live_context_reason],
        }

    quant_live_filter_gate = _evaluate_quant_live_filter_gate(signal, live_context)
    if quant_live_filter_gate.get("blocked"):
        return {
            "blocked": True,
            "reason_code": quant_live_filter_gate.get("reason_code") or "quant_live_filter_blocked",
            "reason_text": quant_live_filter_gate.get("reason_text") or "Blocked by quant live filter",
            "multiplier": 0.0,
            "tier": "blocked",
            "reasons": reasons + list(quant_live_filter_gate.get("reasons") or []),
        }

    path_guard = _get_live_path_guard(signal)
    if path_guard["blocked"]:
        if bool(SIGNAL_CONFIG.get("live_path_quarantine_hard_block", True)):
            return {
                "blocked": True,
                "reason_code": "path_quarantined",
                "reason_text": path_guard["reason"] or "Path quarantined by live scorecard",
                "multiplier": 0.0,
                "tier": "blocked",
                "reasons": reasons + [path_guard["reason"]],
            }
        reasons.append("Path quarantine hard-block disabled; fixed sizing retained")
        if path_guard["reason"]:
            reasons.append(path_guard["reason"])
    elif path_guard["warning"]:
        reasons.append("Path currently underperforming live; fixed sizing retained")

    symbol_guard = _get_live_symbol_guard(signal)
    if symbol_guard["blocked"] and bool(SIGNAL_CONFIG.get("enable_live_symbol_quality_hard_block", False)):
        return {
            "blocked": True,
            "reason_code": "symbol_quality_blocked",
            "reason_text": symbol_guard["reason"] or "Symbol blocked by live quality filter",
            "multiplier": 0.0,
            "tier": "blocked",
            "reasons": reasons + [symbol_guard["reason"]],
        }
    if symbol_guard["blocked"]:
        reasons.append("Symbol quality hard-block disabled; fixed sizing retained")
        if symbol_guard["reason"]:
            reasons.append(symbol_guard["reason"])
    if symbol_guard["warning"]:
        reasons.append("Symbol quality warning observed; fixed sizing retained")

    return {
        "blocked": False,
        "reason_code": "",
        "reason_text": "",
        "multiplier": fixed_multiplier,
        "tier": "fixed",
        "reasons": reasons,
    }


async def refresh_live_telemetry(symbols=None):
    global _live_telemetry_cycle_counter, _live_rejected_shadow_rotation_offset
    _live_telemetry_cycle_counter += 1
    requested_symbols = list(dict.fromkeys([str(s or "").upper() for s in (symbols or []) if s]))
    trade_audit_symbols = list(
        dict.fromkeys(
            [
                str(row.get("symbol") or "").upper()
                for row in _live_trade_audit_pending.values()
                if row.get("symbol")
            ]
        )
    )
    trade_audit_tp15_symbols = list(
        dict.fromkeys(
            [
                str(row.get("symbol") or "").upper()
                for row in _live_trade_audit_tp15_pending.values()
                if row.get("symbol")
            ]
        )
    )
    of_gate_symbols = list(
        dict.fromkeys(
            [
                str(row.get("symbol") or "").upper()
                for row in _live_of_gate_shadow_pending.values()
                if row.get("symbol")
            ]
        )
    )
    rejected_shadow_symbols = list(
        dict.fromkeys(
            [
                str(row.get("symbol") or "").upper()
                for row in _live_rejected_shadow_pending.values()
                if row.get("symbol")
            ]
        )
    )
    rejected_refresh_every = max(
        1,
        int(SIGNAL_CONFIG.get("live_rejected_shadow_refresh_every_cycles", 2) or 2),
    )
    rejected_refresh_cap = max(
        0,
        int(SIGNAL_CONFIG.get("live_rejected_shadow_refresh_max_symbols", 40) or 40),
    )
    rejected_refresh_due = (
        bool(rejected_shadow_symbols)
        and rejected_refresh_cap > 0
        and ((_live_telemetry_cycle_counter - 1) % rejected_refresh_every == 0)
    )
    selected_rejected_shadow_symbols = []
    if rejected_refresh_due:
        if rejected_refresh_cap >= len(rejected_shadow_symbols):
            selected_rejected_shadow_symbols = list(rejected_shadow_symbols)
            _live_rejected_shadow_rotation_offset = 0
        else:
            start = _live_rejected_shadow_rotation_offset % len(rejected_shadow_symbols)
            ordered = rejected_shadow_symbols[start:] + rejected_shadow_symbols[:start]
            selected_rejected_shadow_symbols = ordered[:rejected_refresh_cap]
            _live_rejected_shadow_rotation_offset = (
                start + len(selected_rejected_shadow_symbols)
            ) % len(rejected_shadow_symbols)

    # Real trade audits and OF shadow stay in the fast lane every cycle.
    # Rejected shadow runs in a slower rotating lane so it can't dominate loop time.
    pending_symbols = []
    seen = set()
    for symbol in trade_audit_symbols + trade_audit_tp15_symbols + of_gate_symbols + selected_rejected_shadow_symbols:
        if not symbol or symbol in seen:
            continue
        pending_symbols.append(symbol)
        seen.add(symbol)
    max_symbols = int(SIGNAL_CONFIG.get("live_telemetry_refresh_max_symbols", 20))
    extra_requested_symbols = []
    for symbol in requested_symbols:
        if not symbol or symbol in seen:
            continue
        extra_requested_symbols.append(symbol)
        seen.add(symbol)
    symbols = pending_symbols + extra_requested_symbols[:max_symbols]
    fast_lane_symbols = set(trade_audit_symbols) | set(trade_audit_tp15_symbols) | set(of_gate_symbols)
    rejected_lane_symbols = set(selected_rejected_shadow_symbols) | (
        set(rejected_shadow_symbols) & fast_lane_symbols
    )
    refreshed = 0
    resolved_total = 0
    rejected_resolved_total = 0
    trade_audit_resolved_total = 0
    trade_audit_tp15_resolved_total = 0
    of_gate_resolved_total = 0
    for symbol in symbols:
        try:
            df = get_operational_df_sync(
                symbol,
                SIGNAL_CONFIG.get("candlestick_interval", "15m"),
                SIGNAL_CONFIG.get("operational_15m_candle_limit", SIGNAL_CONFIG.get("candlestick_limit", 600)),
                min_candles=SIGNAL_CONFIG.get("min_required_candles", 50),
            )
            if df is None or df.empty:
                if symbol in rejected_lane_symbols:
                    rejected_updates = _update_live_rejected_shadow_outcomes(symbol, df)
                    rejected_resolved_total += rejected_updates
                    resolved_total += rejected_updates
                continue
            trade_audit_updates = _update_live_trade_audit_outcomes(symbol, df)
            trade_audit_tp15_updates = _update_live_trade_audit_tp15_outcomes(symbol, df)
            of_gate_updates = _update_live_of_gate_shadow_outcomes(symbol, df)
            rejected_updates = 0
            if symbol in rejected_lane_symbols:
                rejected_updates = _update_live_rejected_shadow_outcomes(symbol, df)
            trade_audit_resolved_total += trade_audit_updates
            trade_audit_tp15_resolved_total += trade_audit_tp15_updates
            of_gate_resolved_total += of_gate_updates
            rejected_resolved_total += rejected_updates
            resolved_total += trade_audit_updates + trade_audit_tp15_updates + of_gate_updates + rejected_updates
            refreshed += 1
        except Exception as exc:
            logger.warning(f"[{symbol}] Live telemetry refresh failed: {exc}")
    report_summary = _refresh_live_analytics_reports()
    report_summary.update(
        {
            "refreshed_symbols": refreshed,
            "resolved_updates": resolved_total,
            "resolved_trade_audits": trade_audit_resolved_total,
            "resolved_trade_audits_tp15": trade_audit_tp15_resolved_total,
            "resolved_rejected_shadow": rejected_resolved_total,
            "resolved_of_gate_shadow": of_gate_resolved_total,
            "rejected_shadow_refresh_due": bool(rejected_refresh_due),
            "rejected_shadow_total_pending_symbols": len(rejected_shadow_symbols),
            "rejected_shadow_refreshed_symbols": len(selected_rejected_shadow_symbols),
            "telemetry_cycle": _live_telemetry_cycle_counter,
        }
    )
    return report_summary


_load_live_trade_audit_pending()
_load_live_trade_audit_tp15_pending()
_load_live_rejected_shadow_pending()


def _get_signal_cache_key(symbol: str) -> str:
    return f"{symbol}_{SIGNAL_CONFIG['candlestick_interval']}"


def cache_trade_signal(signal: dict, symbol: str = None, reason: str = "trade placement") -> None:
    """
    Cache a fully confirmed/executed signal so the same setup is not re-entered
    before the configured trade-skip timeout expires.
    """
    cache_symbol = symbol or signal.get('symbol')
    if not cache_symbol:
        return

    cache_key = _get_signal_cache_key(cache_symbol)
    _signal_cache[cache_key] = (dict(signal), time.time())

    timeout_s = int(SIGNAL_CONFIG.get('signal_cache_timeout', 72000))
    timeout_min = timeout_s / 60
    logger.info(
        f"[{cache_symbol}] Signal cached after {reason} - "
        f"will skip until expiry ({timeout_s}s / {timeout_min:.1f}min)"
    )


def _interval_to_seconds(interval: str) -> int:
    mapping = {
        '1m': 60,
        '3m': 180,
        '5m': 300,
        '15m': 900,
        '30m': 1800,
        '1H': 3600,
        '4H': 14400,
        '1D': 86400,
    }
    return mapping.get(interval, 0)


def _extract_last_df_timestamp_s(df) -> float:
    """
    Best-effort extraction of the most recent candle timestamp from a DataFrame.
    Returns epoch seconds, or 0.0 if unavailable.
    """
    if df is None or getattr(df, 'empty', True):
        return 0.0

    try:
        if isinstance(df.index, pd.DatetimeIndex) and len(df.index) > 0:
            return float(df.index[-1].timestamp())
    except Exception:
        pass

    if 'timestamp' in df.columns and len(df['timestamp']) > 0:
        try:
            ts = float(df['timestamp'].iloc[-1])
            return ts / 1000.0 if ts > 1e11 else ts
        except Exception:
            return 0.0

    return 0.0


def _cache_is_fresh(
    cache_entry: dict,
    ttl_s: int,
    interval: str = None,
    refresh_on_new_candle: bool = True,
) -> bool:
    """
    Cache freshness rule:
    1. The configured TTL is still respected as the hard maximum age.
    2. If a new candle for the relevant interval should now exist, refresh early
       so structure-dependent decisions are not made on stale candles.
    """
    if not cache_entry:
        return False

    now = time.time()
    cache_ts = float(cache_entry.get('ts', 0))
    if cache_ts <= 0 or (now - cache_ts) >= ttl_s:
        return False

    if refresh_on_new_candle:
        interval_s = _interval_to_seconds(interval) if interval else 0
        last_data_ts = float(cache_entry.get('last_data_ts', 0))
        if interval_s > 0 and last_data_ts > 0 and now >= (last_data_ts + interval_s):
            return False

    return True


def _get_operational_limit(interval: str) -> int:
    if interval == SIGNAL_CONFIG.get("candlestick_interval", "15m"):
        return int(
            SIGNAL_CONFIG.get(
                "operational_15m_candle_limit",
                SIGNAL_CONFIG.get("candlestick_limit", 600),
            )
        )
    if interval in ("1H", "4H"):
        return int(SIGNAL_CONFIG.get("htf_operational_candle_limit", 100))
    return int(SIGNAL_CONFIG.get("fresh_data_limit", 100))


def _get_directional_15m_limit(default_limit: int = None) -> int:
    fallback_limit = (
        default_limit
        if default_limit is not None
        else SIGNAL_CONFIG.get(
            "operational_15m_candle_limit",
            SIGNAL_CONFIG.get("candlestick_limit", 600),
        )
    )
    return int(SIGNAL_CONFIG.get("directional_15m_candle_limit", fallback_limit))


def _get_interval_bucket(interval: str, now_s: float = None) -> int:
    interval_s = _interval_to_seconds(interval)
    if interval_s <= 0:
        return 0
    ts = time.time() if now_s is None else now_s
    return int(ts // interval_s)


def _request_timeout_value(key: str, default: float = None):
    raw = SIGNAL_CONFIG.get(key, default)
    try:
        if raw is None:
            return None
        value = float(raw)
        if value <= 0:
            return None
        return value
    except Exception:
        if default is None:
            return None
        try:
            fallback = float(default)
            return None if fallback <= 0 else fallback
        except Exception:
            return None


def _api_retry_attempts(default: int = 3) -> int:
    try:
        return max(1, int(SIGNAL_CONFIG.get("api_request_retry_attempts", default) or default))
    except Exception:
        return int(default)


def _api_retry_backoff_seconds(default: float = 1.0) -> float:
    try:
        return max(0.0, float(SIGNAL_CONFIG.get("api_request_retry_backoff_seconds", default) or default))
    except Exception:
        return float(default)


def _sleep_api_retry_backoff(base_backoff_s: float, attempt_number: int):
    if base_backoff_s <= 0:
        return
    time.sleep(base_backoff_s * max(1.0, (2 ** max(0, int(attempt_number) - 1))))


def _public_get_json_with_retry(url: str, params=None, *, timeout_key: str = "public_api_timeout_seconds", default_timeout: float = 5.0):
    timeout_s = _request_timeout_value(timeout_key, default_timeout)
    retry_attempts = _api_retry_attempts()
    backoff_s = _api_retry_backoff_seconds()
    last_payload = None
    for attempt_number in range(1, retry_attempts + 1):
        response = None
        try:
            response = requests.get(url, params=params, timeout=timeout_s)
            payload = response.json() if response.content else {}
            if response.status_code == 200:
                return response, payload
            last_payload = payload if isinstance(payload, dict) else None
            if response.status_code >= 500 and attempt_number < retry_attempts:
                logger.warning(
                    f"Public API server error [{url}] (attempt {attempt_number}/{retry_attempts}); retrying."
                )
                _sleep_api_retry_backoff(backoff_s, attempt_number)
                continue
            return response, payload
        except (requests.exceptions.Timeout, requests.exceptions.ConnectionError, requests.exceptions.RequestException) as exc:
            logger.warning(
                f"Public API request failed [{url}] (attempt {attempt_number}/{retry_attempts}): {exc}"
            )
            if attempt_number < retry_attempts:
                _sleep_api_retry_backoff(backoff_s, attempt_number)
    return None, (last_payload or {})


def _extract_first_df_timestamp_s(df) -> float:
    """
    Best-effort extraction of the earliest candle timestamp from a DataFrame.
    Returns epoch seconds, or 0.0 if unavailable.
    """
    if df is None or getattr(df, 'empty', True):
        return 0.0

    try:
        if isinstance(df.index, pd.DatetimeIndex) and len(df.index) > 0:
            return float(df.index[0].timestamp())
    except Exception:
        pass

    if 'timestamp' in df.columns and len(df['timestamp']) > 0:
        try:
            ts = float(df['timestamp'].iloc[0])
            return ts / 1000.0 if ts > 1e11 else ts
        except Exception:
            return 0.0

    return 0.0


def _get_operational_update_limit(interval: str) -> int:
    if interval == SIGNAL_CONFIG.get("candlestick_interval", "15m"):
        return int(SIGNAL_CONFIG.get("operational_update_candles", 10))
    if interval in ("1H", "4H"):
        return int(
            SIGNAL_CONFIG.get(
                "htf_operational_update_candles",
                SIGNAL_CONFIG.get("operational_update_candles", 10),
            )
        )
    return int(SIGNAL_CONFIG.get("operational_update_candles", 10))


def _merge_operational_df(cached_df, update_df, limit: int):
    merged = pd.concat([cached_df, update_df], axis=0)
    merged = merged[~merged.index.duplicated(keep='last')]
    merged = merged.sort_index()
    if len(merged) > limit:
        merged = merged.tail(limit)
    return merged


def _incremental_update_is_safe(cached_df, update_df, interval: str) -> bool:
    """
    Incremental update is safe only if the fetched update slice overlaps or is
    directly contiguous with the cached tail. Otherwise we force a full refresh.
    """
    if cached_df is None or getattr(cached_df, 'empty', True):
        return False
    if update_df is None or getattr(update_df, 'empty', True):
        return False

    interval_s = _interval_to_seconds(interval)
    if interval_s <= 0:
        return False

    cached_last_ts = _extract_last_df_timestamp_s(cached_df)
    update_first_ts = _extract_first_df_timestamp_s(update_df)
    if cached_last_ts <= 0 or update_first_ts <= 0:
        return False

    # Safe if update slice reaches back to the cached tail or at most one candle
    # beyond it. This handles overlap and simple continuity.
    return update_first_ts <= (cached_last_ts + interval_s)


def _history_cache_is_complete_enough(df, requested_limit: int, min_candles: int = None) -> bool:
    if df is None or getattr(df, "empty", True):
        return False
    requested = max(1, int(requested_limit or len(df) or 1))
    actual = int(len(df))
    if min_candles is not None and actual < int(min_candles):
        return False
    completion_ratio = actual / requested if requested > 0 else 1.0
    min_ratio = float(SIGNAL_CONFIG.get("history_cache_min_completion_ratio", 0.85) or 0.85)
    return completion_ratio >= min_ratio or actual >= requested


def _operational_cache_fallback_is_usable(symbol: str, interval: str, cached_entry, min_candles: int) -> bool:
    cached_df = (cached_entry or {}).get("df") if isinstance(cached_entry, dict) else None
    if cached_df is None or getattr(cached_df, "empty", True):
        return False
    if len(cached_df) < int(min_candles or 1):
        return False

    interval_s = _interval_to_seconds(interval)
    if interval_s <= 0:
        return True

    last_data_ts = float((cached_entry or {}).get("last_data_ts") or _extract_last_df_timestamp_s(cached_df) or 0.0)
    if last_data_ts <= 0:
        return False

    max_stale_buckets = max(1, int(SIGNAL_CONFIG.get("operational_cache_max_stale_buckets", 3) or 3))
    max_stale_seconds = interval_s * max_stale_buckets
    age_s = max(0.0, time.time() - last_data_ts)
    if age_s > max_stale_seconds:
        logger.warning(
            f"[{symbol}] Operational {interval} cache is stale "
            f"({age_s/60:.1f}min old, max {max_stale_seconds/60:.1f}min) - refusing cached fallback"
        )
        return False
    return True


def get_operational_df_sync(symbol: str, interval: str, limit: int = None, min_candles: int = None):
    """
    Return a fresh operational OHLCV slice.
    Operational candles are intentionally not cached for live decisions.
    """
    resolved_limit = int(limit or _get_operational_limit(interval))
    resolved_min_candles = int(
        min_candles
        if min_candles is not None
        else min(resolved_limit, SIGNAL_CONFIG.get("min_required_candles", 50))
    )
    if _operational_tf_cache:
        _operational_tf_cache.clear()
    df = fetch_and_prepare_data_sync(
        symbol,
        interval,
        resolved_limit,
        min_candles=resolved_min_candles,
    )
    if df is None or df.empty:
        return None
    return df.copy()


async def get_operational_df(symbol: str, interval: str, limit: int = None, min_candles: int = None):
    return get_operational_df_sync(symbol, interval, limit=limit, min_candles=min_candles)

