def _get_mode_aware_rule_list(config_key):
    if str(config_key or "") in {
        "live_context_hard_block_rules",
        "live_context_soft_allow_rules",
        "live_context_rescue_rules",
        "live_swing_tighten_rules",
        "live_swing_rescue_rules",
    }:
        return []
    rules = []
    rules.extend(SIGNAL_CONFIG.get(config_key, []) or [])
    deduped = []
    seen = set()
    for rule in rules:
        normalized = tuple(sorted(_normalize_precision_rule(rule).items()))
        if not normalized or normalized in seen:
            continue
        seen.add(normalized)
        deduped.append(rule)
    return deduped

