def _normalize_bucket_token(value) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    return str("" if value is None else value).strip().lower()


def _base_symbol(symbol: str) -> str:
    text = str(symbol or "").upper().replace("_UMCBL", "")
    return text[:-4] if text.endswith("USDT") else text


def _classify_symbol_bucket(symbol: str) -> str:
    root = _base_symbol(symbol)
    if root in INDEX_STYLE_SYMBOLS:
        return "index"
    if root in EQUITY_INDEXED_SYMBOLS:
        return "equity"
    if root in METAL_SYMBOLS:
        return "metal"
    if root in MAJOR_SYMBOLS:
        return "major"
    return "alt"


def _classify_session_bucket(ts) -> str:
    hour = pd.Timestamp(ts).hour
    if 0 <= hour < 8:
        return "asia"
    if 8 <= hour < 13:
        return "europe"
    if 13 <= hour < 21:
        return "us"
    return "late"


def _get_signal_session_timestamp(df) -> pd.Timestamp:
    default_ts = pd.Timestamp.utcnow()
    if default_ts.tzinfo is not None:
        default_ts = default_ts.tz_convert(None)

    if df is None or getattr(df, "empty", True):
        return default_ts

    interval_s = _interval_to_seconds(SIGNAL_CONFIG.get("candlestick_interval", "15m"))
    try:
        if isinstance(df.index, pd.DatetimeIndex) and len(df.index) > 0:
            ts = pd.Timestamp(df.index[-1])
            if ts.tzinfo is not None:
                ts = ts.tz_convert(None)
            return ts + pd.Timedelta(seconds=interval_s)
    except Exception:
        pass

    return default_ts


def _parse_bucket_pair(raw):
    if isinstance(raw, dict):
        return (
            _normalize_bucket_token(raw.get("symbol_bucket")),
            _normalize_bucket_token(raw.get("session_bucket")),
        )

    text = _normalize_bucket_token(raw)
    for sep in (":", "|", "/", ","):
        if sep in text:
            left, right = text.split(sep, 1)
            return left.strip(), right.strip()
    return text, ""


def _normalize_precision_rule(raw):
    if not isinstance(raw, dict):
        return {}
    normalized = {}
    for key, value in raw.items():
        norm_key = str(key or "").strip().lower()
        if norm_key.startswith("_"):
            continue
        norm_value = _normalize_bucket_token(value)
        if norm_key and norm_value:
            normalized[norm_key] = norm_value
    return normalized


def _format_precision_rule(rule):
    normalized = _normalize_precision_rule(rule)
    if not normalized:
        return ""
    return " & ".join(f"{key}={value}" for key, value in normalized.items())


def _precision_rule_matches(context, raw_rule):
    rule = _normalize_precision_rule(raw_rule)
    if not rule:
        return False
    for key, expected in rule.items():
        if _normalize_bucket_token(context.get(key)) != expected:
            return False
    return True


def _dynamic_rule_stamp():
    parts = []
    for path in (_LIVE_ASYMMETRIC_TUNING_REPORT_FILE, _LIVE_SWING_EVIDENCE_REPORT_FILE):
        try:
            parts.append((path, os.path.getmtime(path)))
        except OSError:
            parts.append((path, None))
    return tuple(parts)


def _clean_dynamic_rule_filters(raw_filters, *, drop_keys=None):
    drop_keys = set(drop_keys or [])
    cleaned = {}
    for key, value in (raw_filters or {}).items():
        key_str = str(key or "").strip()
        if not key_str or key_str in drop_keys or value is None:
            continue
        normalized_value = _normalize_bucket_token(value)
        if not normalized_value or normalized_value == "unknown":
            continue
        cleaned[key_str] = value
    return cleaned


def _rule_is_subset(candidate_rule, selected_rule):
    candidate = _normalize_precision_rule(candidate_rule)
    selected = _normalize_precision_rule(selected_rule)
    if not candidate or not selected:
        return False
    return all(selected.get(key) == value for key, value in candidate.items())


def _dedupe_dynamic_rules(rules, *, max_rules=None, prefer_specific=False):
    cleaned = []
    seen = set()
    for rule in rules or []:
        normalized = _normalize_precision_rule(rule)
        normalized_key = tuple(sorted(normalized.items()))
        if not normalized or normalized_key in seen:
            continue
        if prefer_specific and any(_rule_is_subset(rule, existing) for existing in cleaned):
            continue
        cleaned.append(rule)
        seen.add(normalized_key)
        if max_rules and len(cleaned) >= max_rules:
            break
    return cleaned


