def _extract_atr_value_for_meta(df):
    if df is None or getattr(df, "empty", True):
        return None
    atr_candidates = [
        f"ATRr_{SIGNAL_CONFIG.get('atr_period', 14)}",
        f"ATR_{SIGNAL_CONFIG.get('atr_period', 14)}",
        "ATR",
    ]
    atr_col = next((col for col in atr_candidates if col in df.columns and not df[col].isna().all()), None)
    if atr_col:
        atr_series = df[atr_col].dropna()
        if not atr_series.empty:
            if len(atr_series) >= 5:
                return float(atr_series.tail(5).mean())
            return float(atr_series.iloc[-1])
    close_value = _safe_float(df["close"].iloc[-1])
    return close_value * 0.005 if close_value else None


def _safe_pct_change_from_prices(last_price, reference_price):
    last_val = _safe_float(last_price)
    ref_val = _safe_float(reference_price)
    if not last_val or not ref_val:
        return None
    if ref_val == 0:
        return None
    return ((last_val - ref_val) / ref_val) * 100.0


def _safe_basis_bps(price_value, reference_value):
    price = _safe_float(price_value)
    reference = _safe_float(reference_value)
    if price is None or reference in (None, 0):
        return None
    return ((price - reference) / reference) * 10000.0


def _classify_sign_bucket(value, neutral_band):
    numeric = _safe_float(value)
    if numeric is None:
        return "unknown"
    if numeric > neutral_band:
        return "bullish"
    if numeric < (-neutral_band):
        return "bearish"
    return "neutral"


def _pct(numerator, denominator):
    if not denominator:
        return None
    return round((float(numerator) / float(denominator)) * 100.0, 2)


def _fetch_futures_ticker_snapshot_rows():
    response = api_client.make_request(
        "GET",
        "/api/v2/mix/market/tickers",
        params={"productType": "USDT-FUTURES"},
    )
    if not (response and response.get("code") == "00000" and response.get("data")):
        return []

    rows = []
    for raw in response.get("data") or []:
        symbol = _normalize_bitget_symbol(raw.get("symbol"))
        if not symbol:
            continue
        last_price = _safe_float(raw.get("lastPr"))
        open_24h = _safe_float(raw.get("open24h"))
        change_24h_pct = None
        if raw.get("priceChangePercent") not in (None, ""):
            change_24h_pct = _safe_float(raw.get("priceChangePercent"))
            if change_24h_pct is not None:
                change_24h_pct *= 100.0
        if change_24h_pct is None:
            change_24h_pct = _safe_pct_change_from_prices(last_price, open_24h)

        rows.append(
            {
                "symbol": symbol,
                "last_price": last_price,
                "open_24h": open_24h,
                "change_24h_pct": change_24h_pct,
                "quote_volume": _safe_float(raw.get("quoteVolume"), _safe_float(raw.get("usdtVolume"))),
                "base_volume": _safe_float(raw.get("baseVolume")),
                "funding_rate": _safe_float(raw.get("fundingRate")),
                "holding_amount": _safe_float(raw.get("holdingAmount")),
                "index_price": _safe_float(raw.get("indexPrice")),
                "mark_price": _safe_float(raw.get("markPrice")),
                "bid_price": _safe_float(raw.get("bidPr")),
                "ask_price": _safe_float(raw.get("askPr")),
                "timestamp_ms": _safe_int(raw.get("ts"), None),
                "raw": _to_json_safe(raw),
            }
        )
    return rows


def _fetch_symbol_regime_snapshot(symbol, interval, limit):
    symbol = _normalize_bitget_symbol(symbol)
    payload = {
        "symbol": symbol,
        "interval": interval,
        "available": False,
        "fetch_error": None,
        "regime": "unknown",
        "structure": "unknown",
        "last_bos": None,
        "last_choch": None,
        "close": None,
        "atr_value": None,
        "adx_value": None,
        "candle_timestamp": None,
    }
    try:
        df = fetch_data_sync(symbol, interval, limit)
        if df is None or getattr(df, "empty", True) or len(df) < 40:
            payload["fetch_error"] = "insufficient_data"
            return payload
        df = calculate_all_indicators(df.copy())
        df = identify_swing_points(df)
        structure, last_bos, last_choch, _detail = classify_market_structure(df)
        atr_value = _extract_atr_value_for_meta(df)
        regime = detect_market_regime(df, atr_value) if atr_value is not None else "unknown"
        payload.update(
            {
                "available": True,
                "regime": regime,
                "structure": structure,
                "last_bos": last_bos,
                "last_choch": last_choch,
                "close": _safe_float(df["close"].iloc[-1]),
                "atr_value": _safe_float(atr_value),
                "adx_value": _safe_float(df["adx"].iloc[-1] if "adx" in df.columns else None),
                "candle_timestamp": _json_safe_default(df.index[-1]),
            }
        )
        return payload
    except Exception as exc:
        payload["fetch_error"] = str(exc)
        return payload


def _build_structure_breadth_snapshot(symbols, *, interval, candle_limit, source):
    normalized_symbols = []
    for raw_symbol in symbols or []:
        symbol = _normalize_bitget_symbol(raw_symbol)
        if symbol and symbol not in normalized_symbols:
            normalized_symbols.append(symbol)
    snapshot = {
        "source": source,
        "interval": interval,
        "candle_limit": candle_limit,
        "symbols": {},
        "bullish_count": 0,
        "bearish_count": 0,
        "ranging_count": 0,
        "unknown_count": 0,
        "total": 0,
        "bullish_pct": None,
        "bearish_pct": None,
        "ranging_pct": None,
        "unknown_pct": None,
    }
    if not normalized_symbols:
        return snapshot

    workers = max(1, min(4, len(normalized_symbols)))
    with ThreadPoolExecutor(max_workers=workers) as pool:
        futures = {
            pool.submit(_fetch_symbol_regime_snapshot, symbol, interval, candle_limit): symbol
            for symbol in normalized_symbols
        }
        for future, symbol in futures.items():
            try:
                result = future.result()
            except Exception as exc:
                result = {"symbol": symbol, "available": False, "fetch_error": str(exc), "structure": "unknown", "regime": "unknown"}
            snapshot["symbols"][symbol] = result
            structure = str(result.get("structure") or "unknown").lower()
            if structure == "bullish":
                snapshot["bullish_count"] += 1
            elif structure == "bearish":
                snapshot["bearish_count"] += 1
            elif structure == "ranging":
                snapshot["ranging_count"] += 1
            else:
                snapshot["unknown_count"] += 1

    snapshot["total"] = len(snapshot["symbols"])
    snapshot["bullish_pct"] = _pct(snapshot["bullish_count"], snapshot["total"])
    snapshot["bearish_pct"] = _pct(snapshot["bearish_count"], snapshot["total"])
    snapshot["ranging_pct"] = _pct(snapshot["ranging_count"], snapshot["total"])
    snapshot["unknown_pct"] = _pct(snapshot["unknown_count"], snapshot["total"])
    return snapshot


