def _build_funding_breadth_snapshot(market_ticker_rows):
    threshold = float(SIGNAL_CONFIG.get("market_meta_funding_extreme_threshold", 0.0005) or 0.0005)
    funding_rates = [
        _safe_float(row.get("funding_rate"))
        for row in (market_ticker_rows or [])
        if _safe_float(row.get("funding_rate")) is not None
    ]
    positive_count = sum(1 for value in funding_rates if value > 0)
    negative_count = sum(1 for value in funding_rates if value < 0)
    flat_count = sum(1 for value in funding_rates if value == 0)
    mean_rate = (sum(funding_rates) / len(funding_rates)) if funding_rates else None
    return {
        "symbol_count": len(funding_rates),
        "positive_count": positive_count,
        "negative_count": negative_count,
        "flat_count": flat_count,
        "positive_pct": _pct(positive_count, len(funding_rates)),
        "negative_pct": _pct(negative_count, len(funding_rates)),
        "mean_funding_rate": round(mean_rate, 8) if mean_rate is not None else None,
        "mean_funding_rate_bps": round(mean_rate * 10000.0, 4) if mean_rate is not None else None,
        "extreme_count": sum(1 for value in funding_rates if abs(value) >= threshold),
        "extreme_threshold": threshold,
        "source": "fresh_scanner_universe_current_funding",
        "state": (
            "longs_paying"
            if mean_rate is not None and mean_rate > 0
            else "shorts_paying"
            if mean_rate is not None and mean_rate < 0
            else "flat"
        ),
    }


def _build_basis_snapshot(symbol_ticker_row, market_ticker_rows):
    threshold_bps = float(SIGNAL_CONFIG.get("market_meta_basis_stress_threshold_bps", 15.0) or 15.0)
    symbol_last = _safe_float((symbol_ticker_row or {}).get("last_price"))
    symbol_mark = _safe_float((symbol_ticker_row or {}).get("mark_price"))
    symbol_index = _safe_float((symbol_ticker_row or {}).get("index_price"))

    market_mark_basis = []
    market_last_basis = []
    stress_symbols = []
    for row in (market_ticker_rows or []):
        symbol = str(row.get("symbol") or "")
        last_basis = _safe_basis_bps(row.get("last_price"), row.get("index_price"))
        mark_basis = _safe_basis_bps(row.get("mark_price"), row.get("index_price"))
        if last_basis is not None:
            market_last_basis.append(last_basis)
        if mark_basis is not None:
            market_mark_basis.append(mark_basis)
            if abs(mark_basis) >= threshold_bps:
                stress_symbols.append(symbol)

    mean_mark_basis = (sum(market_mark_basis) / len(market_mark_basis)) if market_mark_basis else None
    return {
        "symbol_last_vs_index_bps": round(_safe_basis_bps(symbol_last, symbol_index), 4) if _safe_basis_bps(symbol_last, symbol_index) is not None else None,
        "symbol_mark_vs_index_bps": round(_safe_basis_bps(symbol_mark, symbol_index), 4) if _safe_basis_bps(symbol_mark, symbol_index) is not None else None,
        "market_mean_last_vs_index_bps": round(sum(market_last_basis) / len(market_last_basis), 4) if market_last_basis else None,
        "market_mean_mark_vs_index_bps": round(mean_mark_basis, 4) if mean_mark_basis is not None else None,
        "stress_symbol_count": len(stress_symbols),
        "stress_symbols": stress_symbols,
        "stress_threshold_bps": threshold_bps,
        "source": "fresh_scanner_universe_mark_index_basis",
        "state": (
            "positive_stress"
            if mean_mark_basis is not None and mean_mark_basis >= threshold_bps
            else "negative_stress"
            if mean_mark_basis is not None and mean_mark_basis <= (-threshold_bps)
            else "contained"
        ),
    }


def _build_open_interest_snapshot(symbol_oi_snapshot, symbol_ticker_row, market_ticker_rows, scanner_breadth, funding_breadth, basis_snapshot):
    oi_values = [
        _safe_float(row.get("holding_amount"))
        for row in (market_ticker_rows or [])
        if _safe_float(row.get("holding_amount")) is not None
    ]
    symbol_oi = _safe_float((symbol_oi_snapshot or {}).get("open_interest"), _safe_float((symbol_ticker_row or {}).get("holding_amount")))
    median_oi = float(pd.Series(oi_values, dtype="float64").median()) if oi_values else None
    oi_ratio = (symbol_oi / median_oi) if symbol_oi is not None and median_oi not in (None, 0) else None
    bullish_pct = _safe_float((scanner_breadth or {}).get("bullish_pct"))
    bearish_pct = _safe_float((scanner_breadth or {}).get("bearish_pct"))
    funding_mean_bps = _safe_float((funding_breadth or {}).get("mean_funding_rate_bps"))
    basis_mean_bps = _safe_float((basis_snapshot or {}).get("major_mean_mark_vs_index_bps"))

    inferred_state = "mixed_or_unconfirmed"
    if bullish_pct is not None and bearish_pct is not None and funding_mean_bps is not None and basis_mean_bps is not None:
        if bullish_pct > bearish_pct and funding_mean_bps > 0 and basis_mean_bps > 0:
            inferred_state = "long_expansion_inferred"
        elif bearish_pct > bullish_pct and funding_mean_bps < 0 and basis_mean_bps < 0:
            inferred_state = "short_expansion_inferred"
        elif abs(funding_mean_bps) < 1.0 and abs(basis_mean_bps) < 5.0:
            inferred_state = "balanced_or_contracting"

    return {
        "symbol_open_interest": symbol_oi,
        "symbol_open_interest_actual": symbol_oi,
        "symbol_snapshot": _to_json_safe(symbol_oi_snapshot),
        "market_symbol_count": len(oi_values),
        "market_median_open_interest": round(median_oi, 6) if median_oi is not None else None,
        "symbol_vs_market_median_ratio": round(oi_ratio, 4) if oi_ratio is not None else None,
        "inferred_state": inferred_state,
        "state_method": "inferred_from_current_context",
        "source": "fresh_current_oi_plus_breadth_inference",
    }


def _build_market_pressure_snapshot(scanner_breadth, major_breadth, funding_breadth, basis_snapshot, leader_snapshots):
    score = 0.0
    scanner_bull = _safe_float((scanner_breadth or {}).get("bullish_pct"), 0.0) or 0.0
    scanner_bear = _safe_float((scanner_breadth or {}).get("bearish_pct"), 0.0) or 0.0
    major_bull = _safe_float((major_breadth or {}).get("bullish_pct"), 0.0) or 0.0
    major_bear = _safe_float((major_breadth or {}).get("bearish_pct"), 0.0) or 0.0
    funding_mean = _safe_float((funding_breadth or {}).get("mean_funding_rate_bps"), 0.0) or 0.0
    basis_mean = _safe_float((basis_snapshot or {}).get("market_mean_mark_vs_index_bps"), 0.0) or 0.0

    score += (scanner_bull - scanner_bear) / 20.0
    score += (major_bull - major_bear) / 25.0
    score += max(-1.5, min(1.5, funding_mean / 2.0))
    score += max(-1.5, min(1.5, basis_mean / 5.0))

    btc_1h = ((leader_snapshots or {}).get("BTCUSDT") or {}).get("1H") or {}
    eth_1h = ((leader_snapshots or {}).get("ETHUSDT") or {}).get("1H") or {}
    for leader_snapshot in (btc_1h, eth_1h):
        structure = str(leader_snapshot.get("structure") or "unknown").lower()
        if structure == "bullish":
            score += 0.5
        elif structure == "bearish":
            score -= 0.5
        regime = str(leader_snapshot.get("regime") or "unknown").lower()
        if regime == "trending_strong":
            score += 0.25 if structure == "bullish" else -0.25 if structure == "bearish" else 0.0

    if score >= 2.5:
        state = "risk_on_bullish"
    elif score >= 1.0:
        state = "bullish"
    elif score <= -2.5:
        state = "risk_off_bearish"
    elif score <= -1.0:
        state = "bearish"
    else:
        state = "mixed"

    return {
        "state": state,
        "score": round(score, 4),
        "scanner_bullish_pct": scanner_bull,
        "scanner_bearish_pct": scanner_bear,
        "major_bullish_pct": major_bull,
        "major_bearish_pct": major_bear,
        "funding_mean_bps": funding_mean,
        "basis_mean_bps": basis_mean,
    }


def _build_liquidation_environment_snapshot(symbol_ticker_row, funding_breadth, basis_snapshot, open_interest_snapshot, scanner_breadth):
    symbol_basis = _safe_float((basis_snapshot or {}).get("symbol_mark_vs_index_bps"))
    basis_threshold = float(SIGNAL_CONFIG.get("market_meta_symbol_basis_stress_threshold_bps", 20.0) or 20.0)
    funding_extremes = _safe_int((funding_breadth or {}).get("extreme_count"), 0)
    breadth_bull = _safe_float((scanner_breadth or {}).get("bullish_pct"), 0.0) or 0.0
    breadth_bear = _safe_float((scanner_breadth or {}).get("bearish_pct"), 0.0) or 0.0
    oi_state = str((open_interest_snapshot or {}).get("inferred_state") or "mixed_or_unconfirmed")
    flags = []
    if symbol_basis is not None and abs(symbol_basis) >= basis_threshold:
        flags.append("symbol_basis_stress")
    if funding_extremes >= 2:
        flags.append("funding_extremes")
    if abs(breadth_bull - breadth_bear) >= 30.0:
        flags.append("one_way_breadth")
    if oi_state in {"long_expansion_inferred", "short_expansion_inferred"}:
        flags.append("crowded_open_interest")

    return {
        "flag": len(flags) >= 2,
        "state": "elevated" if len(flags) >= 2 else "normal",
        "reasons": flags,
        "state_method": "inferred_from_basis_funding_oi_breadth",
    }


def _fetch_market_sentiment_snapshot():
    snapshot = {
        "available": False,
        "source": "disabled",
        "value": None,
        "classification": None,
        "soft_score": None,
        "quarantine_flag": False,
        "timestamp": None,
        "fetch_error": None,
    }
    if not bool(SIGNAL_CONFIG.get("market_meta_sentiment_enabled", True)):
        return snapshot

    url = str(SIGNAL_CONFIG.get("market_meta_sentiment_url") or "").strip()
    if not url:
        snapshot["fetch_error"] = "missing_sentiment_url"
        return snapshot

    try:
        response = requests.get(url, timeout=_market_meta_timeout_seconds())
        payload = response.json()
        data = payload.get("data") or []
        item = data[0] if data else {}
        value = _safe_int(item.get("value"), None)
        classification = str(item.get("value_classification") or "").strip() or None
        if value is None:
            snapshot["fetch_error"] = f"sentiment_unavailable:{payload}"
            return snapshot
        if value <= 20:
            soft_score = -2
        elif value <= 40:
            soft_score = -1
        elif value < 60:
            soft_score = 0
        elif value < 80:
            soft_score = 1
        else:
            soft_score = 2
        snapshot.update(
            {
                "available": True,
                "source": "alternative_me_fng_live",
                "value": value,
                "classification": classification,
                "soft_score": soft_score,
                "quarantine_flag": str(classification or "").lower() in {"extreme fear", "extreme greed"},
                "timestamp": _json_safe_default(_parse_exchange_timestamp(item.get("timestamp"))),
            }
        )
        return snapshot
    except Exception as exc:
        snapshot["fetch_error"] = str(exc)
        return snapshot


