def _build_fresh_market_meta_audit_context(signal):
    symbol = _normalize_bitget_symbol((signal or {}).get("symbol"))
    snapshot = _market_meta_default_snapshot(symbol)
    try:
        ticker_rows = _fetch_futures_ticker_snapshot_rows()
        if not ticker_rows:
            raise ValueError("No futures ticker rows returned for market meta")
        ticker_by_symbol = {str(row.get("symbol")): row for row in ticker_rows}
        symbol_ticker_row = ticker_by_symbol.get(symbol) or {}
        eligible_ticker_rows = [
            row for row in ticker_rows
            if _safe_float(row.get("quote_volume")) is not None and float(row.get("quote_volume")) >= float(MIN_VOLUME_THRESHOLD)
        ]

        leader_symbols = ("BTCUSDT", "ETHUSDT")
        leader_snapshots = {leader: {} for leader in leader_symbols}
        interval_limits = {
            "15m": int(SIGNAL_CONFIG.get("market_meta_regime_candle_limit_15m", 220) or 220),
            "1H": int(SIGNAL_CONFIG.get("market_meta_regime_candle_limit_1h", 220) or 220),
            "4H": int(SIGNAL_CONFIG.get("market_meta_regime_candle_limit_4h", 220) or 220),
        }
        for leader_symbol in leader_symbols:
            for interval, limit in interval_limits.items():
                leader_snapshots[leader_symbol][interval] = _fetch_symbol_regime_snapshot(leader_symbol, interval, limit)

        major_breadth = _build_major_coin_breadth_snapshot()
        scanned_breadth = _build_scanned_symbol_breadth_snapshot(ticker_rows)
        breakout_breadth = {
            "6h": _build_recent_breakout_breadth_snapshot(SIGNAL_CONFIG.get("market_meta_breakout_breadth_short_hours", 6)),
            "24h": _build_recent_breakout_breadth_snapshot(SIGNAL_CONFIG.get("market_meta_breakout_breadth_hours", 24)),
        }

        funding_symbol = _fetch_symbol_funding_snapshot(symbol, symbol_ticker_row)
        funding_breadth = _build_funding_breadth_snapshot(eligible_ticker_rows)
        basis_snapshot = _build_basis_snapshot(symbol_ticker_row, eligible_ticker_rows)
        symbol_oi_snapshot = _fetch_symbol_open_interest_snapshot(symbol, symbol_ticker_row)
        open_interest_snapshot = _build_open_interest_snapshot(
            symbol_oi_snapshot,
            symbol_ticker_row,
            eligible_ticker_rows,
            scanned_breadth,
            funding_breadth,
            basis_snapshot,
        )
        market_pressure = _build_market_pressure_snapshot(
            scanned_breadth,
            major_breadth,
            funding_breadth,
            basis_snapshot,
            leader_snapshots,
        )
        liquidation_environment = _build_liquidation_environment_snapshot(
            symbol_ticker_row,
            funding_breadth,
            basis_snapshot,
            open_interest_snapshot,
            scanned_breadth,
        )
        sentiment_snapshot = _fetch_market_sentiment_snapshot()

        snapshot.update(
            {
                "market_meta_available": True,
                "leaders": leader_snapshots,
                "major_coin_breadth": major_breadth,
                "scanned_symbol_breadth": scanned_breadth,
                "breakout_breadth": breakout_breadth,
                "funding": {
                    "symbol": funding_symbol,
                    "breadth": funding_breadth,
                },
                "open_interest": open_interest_snapshot,
                "basis": basis_snapshot,
                "market_pressure": market_pressure,
                "liquidation_environment": liquidation_environment,
                "market_sentiment": sentiment_snapshot,
            }
        )
    except Exception as exc:
        snapshot["market_meta_fetch_error"] = str(exc)
    return _flatten_market_meta_snapshot(snapshot)


def _use_orderflow_final_score_gate() -> bool:
    return bool(SIGNAL_CONFIG.get("enable_orderflow_final_score_gate", True))


def _evaluate_live_confirmation_evidence(signal, trigger_type=None, direction=None):
    signal = signal or {}
    trigger = str(trigger_type or signal.get("trigger_type") or "").strip().lower()
    direction_token = str(direction or signal.get("direction") or "").strip().upper()
    evidence = []

    expected_divergence = "bullish" if direction_token == "BUY" else "bearish"
    momentum_type = str(signal.get("momentum_divergence_type") or signal.get("divergence_type") or "").lower()
    momentum_strength = _safe_float(signal.get("momentum_divergence_strength"), 0.0) or 0.0
    if trigger == "sweep":
        min_momentum = float(SIGNAL_CONFIG.get("live_confirmation_min_momentum_divergence_strength_sweep", 40.0) or 40.0)
        sweep_anchor_score = _safe_float(signal.get("sweep_anchor_divergence_score"), 0.0) or 0.0
        min_sweep_anchor = float(SIGNAL_CONFIG.get("live_confirmation_min_sweep_anchor_divergence_score", 68.0) or 68.0)
        if expected_divergence in momentum_type and momentum_strength >= min_momentum:
            evidence.append(f"directional_sweep_momentum_divergence_{momentum_strength:.1f}")
        if bool(signal.get("strong_sweep_anchor_divergence")) or sweep_anchor_score >= min_sweep_anchor:
            evidence.append(f"sweep_anchor_divergence_{sweep_anchor_score:.1f}")
    else:
        min_momentum = float(SIGNAL_CONFIG.get("live_confirmation_min_momentum_divergence_strength_breakout", 25.0) or 25.0)
        if expected_divergence in momentum_type and momentum_strength >= min_momentum:
            evidence.append(f"directional_breakout_momentum_divergence_{momentum_strength:.1f}")

    adx_score = _safe_int(signal.get("adx_confirmation_score"), 0)
    adx_state = signal.get("adx_confirmation_state") if isinstance(signal.get("adx_confirmation_state"), dict) else {}
    if adx_score > 0:
        adx_slope = _safe_float(adx_state.get("adx_slope_per_bar"))
        adx_delta = _safe_float(adx_state.get("adx_delta"))
        evidence.append(f"path_aware_adx_slope_score_{adx_score}_slope_{adx_slope}_delta_{adx_delta}")

    pressure_slope = _safe_float(
        signal.get("order_flow_pressure_slope"),
        _safe_float(signal.get("of_gate_directional_pressure_slope")),
    )
    imbalance_slope = _safe_float(
        signal.get("order_flow_imbalance_slope"),
        _safe_float(signal.get("of_gate_imbalance_slope")),
    )
    pressure_slope_min = float(SIGNAL_CONFIG.get("live_confirmation_min_orderflow_pressure_slope", 0.001) or 0.001)
    imbalance_slope_min = float(SIGNAL_CONFIG.get("live_confirmation_min_orderflow_imbalance_slope", 0.0001) or 0.0001)
    pressure_slope_ok = pressure_slope is not None and pressure_slope >= pressure_slope_min
    if direction_token == "SELL":
        imbalance_slope_ok = imbalance_slope is not None and imbalance_slope <= -imbalance_slope_min
    else:
        imbalance_slope_ok = imbalance_slope is not None and imbalance_slope >= imbalance_slope_min
    if pressure_slope_ok or imbalance_slope_ok:
        evidence.append(f"supportive_orderflow_slope_pressure_{pressure_slope}_imbalance_{imbalance_slope}")

    absorption_proxy = signal.get("candle_absorption_proxy")
    breakout_proxy = signal.get("breakout_candle_proxy")
    if isinstance(absorption_proxy, dict) and trigger == "sweep":
        if bool(absorption_proxy.get("available")) and bool(absorption_proxy.get("absorbed")):
            evidence.append(
                f"candlestick_sweep_absorption_{_safe_float(absorption_proxy.get('absorption_strength'), 0.0)}"
            )
    if isinstance(breakout_proxy, dict) and trigger == "breakout":
        if bool(breakout_proxy.get("available")) and bool(breakout_proxy.get("continuation_confirmed")):
            evidence.append(
                f"candlestick_breakout_continuation_{_safe_float(breakout_proxy.get('continuation_strength'), 0.0)}"
            )

    return {
        "passed": bool(evidence),
        "evidence": evidence,
        "required_any": [
            "directional_divergence",
            "path_aware_adx_slope",
            "supportive_orderflow_slope",
            "candlestick_orderflow_proxy",
        ],
    }


def _build_gate_context_from_signal(signal):
    signal = signal or {}
    micro = signal.get("microstructure") or {}
    footprint = micro.get("footprint") or {}
    momentum_strength = float(signal.get("momentum_divergence_strength") or 0.0)
    delta_strength = float(
        signal.get("delta_divergence_strength")
        or footprint.get("divergence_strength")
        or 0.0
    )
    sweep_anchor_score = float(signal.get("sweep_anchor_divergence_score") or 0.0)
    has_momentum_divergence = bool(
        signal.get("has_momentum_divergence")
        or signal.get("strong_momentum_divergence")
        or signal.get("momentum_divergence_type")
    )
    has_delta_divergence = bool(
        signal.get("has_delta_divergence")
        or signal.get("strong_delta_divergence")
        or micro.get("delta_divergence")
        or footprint.get("delta_divergence")
    )
    has_sweep_anchor_divergence = bool(
        signal.get("has_sweep_anchor_divergence")
        or signal.get("strong_sweep_anchor_divergence")
        or signal.get("sweep_anchor_divergence_confirmed")
        or sweep_anchor_score > 0
    )
    strong_momentum_divergence = bool(
        signal.get("strong_momentum_divergence")
        or (
            has_momentum_divergence
            and momentum_strength >= float(SIGNAL_CONFIG.get("live_confirmation_min_momentum_divergence_strength_breakout", 40) or 40)
        )
    )
    strong_delta_divergence = bool(
        signal.get("strong_delta_divergence")
        or (
            has_delta_divergence
            and delta_strength >= float(SIGNAL_CONFIG.get("live_confirmation_min_delta_divergence_strength", 0.15) or 0.15)
        )
    )
    strong_sweep_anchor_divergence = bool(
        signal.get("strong_sweep_anchor_divergence")
        or (
            has_sweep_anchor_divergence
            and sweep_anchor_score >= float(SIGNAL_CONFIG.get("sweep_anchor_divergence_strong_score", 68) or 68)
        )
    )
    return {
        "symbol_bucket": signal.get("symbol_bucket"),
        "session_bucket": signal.get("session_bucket"),
        "trend_regime": signal.get("research_trend_regime"),
        "vol_regime": signal.get("research_vol_regime"),
        "adx_regime": signal.get("research_adx_regime"),
        "structure_4h": signal.get("structure_4h"),
        "structure_15m": signal.get("structure_15m"),
        "liquidity_bucket": signal.get("liquidity_bucket"),
        "has_momentum_divergence": has_momentum_divergence,
        "strong_momentum_divergence": strong_momentum_divergence,
        "has_delta_divergence": has_delta_divergence,
        "strong_delta_divergence": strong_delta_divergence,
        "has_sweep_anchor_divergence": has_sweep_anchor_divergence,
        "strong_sweep_anchor_divergence": strong_sweep_anchor_divergence,
        "sweep_anchor_divergence_mode": signal.get("sweep_anchor_divergence_mode"),
    }


def _build_live_rule_context(signal):
    signal = signal or {}
    context = dict(_build_gate_context_from_signal(signal))
    structure_alignment = (
        signal.get("structure_alignment")
        or signal.get("alignment_state")
        or _structure_alignment_relation(signal.get("structure_4h"), signal.get("structure_15m"))
    )
    context.update(
        {
            "trigger_type": signal.get("trigger_type") or signal.get("primary_setup"),
            "direction": signal.get("direction"),
            "market_regime": signal.get("market_regime") or signal.get("trend_regime_at_reject") or signal.get("trend_regime"),
            "structure_alignment": structure_alignment,
            "alignment_state": signal.get("alignment_state") or structure_alignment,
            "retest_quality": signal.get("retest_quality") or "unknown",
            "audit_symbol_bucket": signal.get("audit_symbol_bucket") or signal.get("symbol_bucket"),
            "audit_session_bucket": signal.get("audit_session_bucket") or signal.get("session_bucket"),
            "audit_liquidity_bucket": signal.get("audit_liquidity_bucket") or signal.get("liquidity_bucket"),
            "context_risk_tier": signal.get("context_risk_tier"),
            "selected_level_type": signal.get("selected_level_type") or "unknown",
            "selected_level_age_bucket": _bucket_age_candles(signal.get("selected_level_age_candles")),
            "selected_level_distance_bucket": _bucket_distance_atr(signal.get("selected_level_distance_atr")),
            "swing_total_count_15m_bucket": _bucket_swing_count(signal.get("swing_total_count_15m")),
            "swing_total_count_4h_bucket": _bucket_swing_count(signal.get("swing_total_count_4h")),
            "latest_swing_high_age_15m_bucket": _bucket_age_candles(signal.get("latest_swing_high_age_15m_candles")),
            "latest_swing_low_age_15m_bucket": _bucket_age_candles(signal.get("latest_swing_low_age_15m_candles")),
        }
    )
    context.update(_build_quant_research_runtime_context(signal))
    return context


def _evaluate_named_rule_match(context, raw_rules, *, label):
    for raw_rule in raw_rules or []:
        if _precision_rule_matches(context, raw_rule):
            if isinstance(raw_rule, dict):
                display_label = str(raw_rule.get("_label") or "").strip()
                if display_label:
                    return True, f"{label}: {display_label}", dict(raw_rule)
            formatted_rule = _format_precision_rule(raw_rule)
            return True, f"{label}: {formatted_rule}", dict(raw_rule)
    return False, "", None


def _evaluate_named_rule_list(context, raw_rules, *, label):
    matched, reason_text, _matched_rule = _evaluate_named_rule_match(
        context,
        raw_rules,
        label=label,
    )
    return matched, reason_text


def _evaluate_contextual_soft_bypass(context, trigger_type, *, enabled_key, rules_key_suffix, label):
    if not bool(SIGNAL_CONFIG.get(enabled_key, False)):
        return False, ""

    trigger_token = str(trigger_type or "").strip().lower()
    if trigger_token not in ("sweep", "breakout"):
        return False, ""

    rules_key = f"{trigger_token}_{rules_key_suffix}"
    for raw_rule in SIGNAL_CONFIG.get(rules_key, []) or []:
        if _precision_rule_matches(context, raw_rule):
            return True, f"{label} soft-bypassed via {_format_precision_rule(raw_rule)}"
    return False, ""


def _evaluate_static_ensemble_soft_bypass(context, trigger_type):
    return _evaluate_contextual_soft_bypass(
        context,
        trigger_type,
        enabled_key="enable_contextual_static_ensemble_soft_bypass",
        rules_key_suffix="static_ensemble_soft_bypass_rules",
        label="Static ensemble",
    )


def _evaluate_precision_profile(context, hard_block_rules, allow_any_rules, label):
    for raw_rule in hard_block_rules:
        if _precision_rule_matches(context, raw_rule):
            formatted_rule = _format_precision_rule(raw_rule)
            return False, f"{label} precision filter blocked context rule: {formatted_rule}", {
                "precision_profile_passed": False,
                "failed_precision_checks": [f"hard_block:{formatted_rule}"],
            }

    normalized_allow_rules = [_normalize_precision_rule(raw_rule) for raw_rule in allow_any_rules]
    normalized_allow_rules = [rule for rule in normalized_allow_rules if rule]
    if normalized_allow_rules:
        for rule in normalized_allow_rules:
            if _precision_rule_matches(context, rule):
                formatted_rule = _format_precision_rule(rule)
                return True, f"Precision {label.lower()} profile passed via {formatted_rule}", {
                    "precision_profile_passed": True,
                    "failed_precision_checks": [],
                }
        allowed_text = "; ".join(_format_precision_rule(rule) for rule in normalized_allow_rules)
        return False, f"{label} precision filter blocked context: none of the allowed rules matched ({allowed_text})", {
            "precision_profile_passed": False,
            "failed_precision_checks": [f"allowed_rules_not_matched:{allowed_text}"],
        }

    return True, "", {
        "precision_profile_passed": True,
        "failed_precision_checks": [],
    }


def _evaluate_precision_sweep_profile(context):
    return _evaluate_precision_profile(
        context,
        SIGNAL_CONFIG.get("precision_sweep_hard_block_rules", []) or [],
        SIGNAL_CONFIG.get("precision_sweep_allow_any_rules", []) or [],
        "Sweep",
    )


def _evaluate_precision_breakout_profile(context):
    return _evaluate_precision_profile(
        context,
        SIGNAL_CONFIG.get("precision_breakout_hard_block_rules", []) or [],
        SIGNAL_CONFIG.get("precision_breakout_allow_any_rules", []) or [],
        "Breakout",
    )


def _evaluate_live_bucket_filter(symbol: str, df):
    symbol_bucket = _classify_symbol_bucket(symbol)
    session_bucket = _classify_session_bucket(_get_signal_session_timestamp(df))
    # Bucket/session labels are kept only as observational audit dimensions.
    # They no longer participate in live trade blocking.
    return {
        "symbol_bucket": symbol_bucket,
        "session_bucket": session_bucket,
        "filter_enabled": False,
        "blocked": False,
        "reason": "",
    }

# ─── Reusable Helpers ──────────────────────────────────────────────────────
def _derive_ma_direction_state(df, *, timeframe=""):
    """Return bullish/bearish/ranging using the configured fast/slow MA stack."""
    timeframe = str(timeframe or "").strip() or "unknown"
    if df is None or getattr(df, "empty", True) or "close" not in df.columns:
        return {
            "trend": "ranging",
            "source": "moving_average",
            "timeframe": timeframe,
            "reason": f"{timeframe} MA direction unavailable: missing candles",
        }

    try:
        close = pd.to_numeric(df["close"], errors="coerce")
    except Exception:
        close = pd.Series(dtype=float)
    close = close.dropna()
    if close.empty:
        return {
            "trend": "ranging",
            "source": "moving_average",
            "timeframe": timeframe,
            "reason": f"{timeframe} MA direction unavailable: no valid close values",
        }

    fast_len = max(1, int(SIGNAL_CONFIG.get("ma_short_period", 20) or 20))
    slow_len = max(fast_len + 1, int(SIGNAL_CONFIG.get("ma_long_period", 50) or 50))
    slope_lookback = max(1, int(SIGNAL_CONFIG.get("htf_ma_slope_lookback_candles", 5) or 5))
    price_deadband_pct = float(SIGNAL_CONFIG.get("htf_ma_price_deadband_pct", 0.001) or 0.0)
    slope_deadband_pct = float(SIGNAL_CONFIG.get("htf_ma_slope_deadband_pct", 0.0002) or 0.0)

    def _ma_series(column, length):
        if column in df.columns:
            try:
                series = pd.to_numeric(df[column], errors="coerce").dropna()
                if not series.empty:
                    return series
            except Exception:
                pass
        try:
            series = ta.ema(close, length=length)
            if series is not None:
                series = pd.to_numeric(series, errors="coerce").dropna()
                if not series.empty:
                    return series
        except Exception:
            pass
        return close.ewm(span=length, adjust=False).mean().dropna()

    fast_series = _ma_series("ema_fast", fast_len)
    slow_series = _ma_series("ema_slow", slow_len)
    if fast_series.empty or slow_series.empty:
        return {
            "trend": "ranging",
            "source": "moving_average",
            "timeframe": timeframe,
            "reason": f"{timeframe} MA direction unavailable: missing MA values",
        }

    price = _safe_float(close.iloc[-1])
    ema_fast = _safe_float(fast_series.iloc[-1])
    ema_slow = _safe_float(slow_series.iloc[-1])
    ref_price = max(abs(price or 0.0), 1e-12)
    price_deadband = ref_price * price_deadband_pct
    slope_deadband = ref_price * slope_deadband_pct

    def _slope(series):
        if len(series) < 2:
            return None
        bars = min(slope_lookback, len(series) - 1)
        return _safe_float((float(series.iloc[-1]) - float(series.iloc[-1 - bars])) / max(bars, 1))

    ema_fast_slope = _slope(fast_series)
    ema_slow_slope = _slope(slow_series)
    bullish_stack = ema_fast is not None and ema_slow is not None and ema_fast >= (ema_slow - price_deadband)
    bearish_stack = ema_fast is not None and ema_slow is not None and ema_fast <= (ema_slow + price_deadband)
    bullish_price = price is not None and ema_slow is not None and price >= (ema_slow - price_deadband)
    bearish_price = price is not None and ema_slow is not None and price <= (ema_slow + price_deadband)
    fast_up = ema_fast_slope is not None and ema_fast_slope >= -slope_deadband
    fast_down = ema_fast_slope is not None and ema_fast_slope <= slope_deadband
    slow_up = ema_slow_slope is not None and ema_slow_slope >= -slope_deadband
    slow_down = ema_slow_slope is not None and ema_slow_slope <= slope_deadband

    if bullish_stack and bullish_price and fast_up:
        trend = "bullish"
    elif bearish_stack and bearish_price and fast_down:
        trend = "bearish"
    else:
        trend = "ranging"

    quality = "strong" if trend in {"bullish", "bearish"} and (
        (trend == "bullish" and slow_up) or (trend == "bearish" and slow_down)
    ) else ("weak" if trend in {"bullish", "bearish"} else "ranging")
    reason = (
        f"{timeframe} MA direction={trend}: price={price}, ema_fast={ema_fast}, "
        f"ema_slow={ema_slow}, fast_slope={ema_fast_slope}, slow_slope={ema_slow_slope}"
    )
    return {
        "trend": trend,
        "quality": quality,
        "source": "moving_average",
        "timeframe": timeframe,
        "reason": reason,
        "price": price,
        "ema_fast": ema_fast,
        "ema_slow": ema_slow,
        "ema_fast_slope_per_bar": ema_fast_slope,
        "ema_slow_slope_per_bar": ema_slow_slope,
        "price_vs_slow_ma_bullish": bool(bullish_price),
        "price_vs_slow_ma_bearish": bool(bearish_price),
        "ma_stack_bullish": bool(bullish_stack),
        "ma_stack_bearish": bool(bearish_stack),
        "fast_slope_up": bool(fast_up),
        "fast_slope_down": bool(fast_down),
        "slow_slope_up": bool(slow_up),
        "slow_slope_down": bool(slow_down),
    }


def check_htf_alignment(htf_data, direction, min_confluence=1, trigger_type='breakout'):
    """
    Path-aware higher-timeframe alignment using MA-derived direction.

    4H MA direction is the authority: if it aligns, alignment passes. 1H and
    ADX strength adjust confidence only; they no longer hard-block MA alignment.
    """
    direction = str(direction or "").strip().upper()
    trigger_type = str(trigger_type or "breakout").strip().lower()
    if direction not in {"BUY", "SELL"} or not htf_data:
        return 0

    tf_4h = htf_data.get("4H") or {}
    tf_1h = htf_data.get("1H") or {}
    trend_4h = str(tf_4h.get("trend") or "ranging").strip().lower()
    strength_4h = str(tf_4h.get("strength") or "weak").strip().lower()
    trend_1h = str(tf_1h.get("trend") or "ranging").strip().lower()
    strength_1h = str(tf_1h.get("strength") or "weak").strip().lower()

    aligned_4h = (
        (direction == "BUY" and trend_4h == "bullish")
        or (direction == "SELL" and trend_4h == "bearish")
    )
    opposed_1h = (
        (direction == "BUY" and trend_1h == "bearish")
        or (direction == "SELL" and trend_1h == "bullish")
    )
    aligned_1h = (
        (direction == "BUY" and trend_1h == "bullish")
        or (direction == "SELL" and trend_1h == "bearish")
    )

    if not aligned_4h:
        return 0

    score = 1.25 if strength_4h == "strong" else 1.0
    if strength_4h == "ranging":
        score = 1.0

    if aligned_1h:
        score += 1.0 if strength_1h == "strong" else 0.5
    elif opposed_1h:
        score -= 0.25

    if trigger_type == "sweep":
        rsi_4h = _safe_float(tf_4h.get("rsi"), 50.0) or 50.0
        rsi_supports_liquidity_run = (
            (direction == "BUY" and rsi_4h <= 45)
            or (direction == "SELL" and rsi_4h >= 55)
        )
        if rsi_supports_liquidity_run:
            score += 0.25

    return max(float(score), 1.0)


def _evaluate_htf_ma_macd_confirmation(htf_data, direction, *, trigger_type='breakout'):
    """Validate 4H trend with MA stack/slope while keeping MACD as timing telemetry."""
    direction = str(direction or "").strip().upper()
    trigger_type = str(trigger_type or "breakout").strip().lower()
    tf_key = str(SIGNAL_CONFIG.get("htf_ma_confirmation_timeframe", "4H") or "4H").strip() or "4H"
    tf_data = (htf_data or {}).get(tf_key) or {}
    if direction not in {"BUY", "SELL"}:
        return {
            "passed": False,
            "reason_code": "invalid_direction",
            "reason_text": "HTF MA confirmation failed: invalid trade direction",
            "timeframe": tf_key,
        }
    if not tf_data:
        return {
            "passed": False,
            "reason_code": "missing_htf_data",
            "reason_text": f"HTF MA confirmation failed: missing {tf_key} data",
            "timeframe": tf_key,
        }

    price = _safe_float(tf_data.get("price"))
    ema_fast = _safe_float(tf_data.get("ema_fast"))
    ema_slow = _safe_float(tf_data.get("ema_slow"))
    ema_fast_slope = _safe_float(tf_data.get("ema_fast_slope_per_bar"))
    ema_slow_slope = _safe_float(tf_data.get("ema_slow_slope_per_bar"))
    macd_hist = _safe_float(tf_data.get("macd_hist"))
    macd_hist_slope = _safe_float(tf_data.get("macd_hist_slope_per_bar"))

    require_price_side = bool(SIGNAL_CONFIG.get("htf_ma_require_price_side", True))
    require_stack = bool(SIGNAL_CONFIG.get("htf_ma_require_stack", True))
    require_fast_slope = bool(SIGNAL_CONFIG.get("htf_ma_require_fast_slope", True))
    require_slow_slope = bool(SIGNAL_CONFIG.get("htf_ma_require_slow_slope", False))
    slope_deadband_pct = float(SIGNAL_CONFIG.get("htf_ma_slope_deadband_pct", 0.0) or 0.0)
    price_deadband_pct = float(SIGNAL_CONFIG.get("htf_ma_price_deadband_pct", 0.0) or 0.0)
    ref_price = max(abs(price or 0.0), 1e-12)
    slope_deadband = ref_price * slope_deadband_pct
    price_deadband = ref_price * price_deadband_pct

    checks = []
    failures = []

    if direction == "BUY":
        price_ok = price is not None and ema_slow is not None and price >= (ema_slow - price_deadband)
        stack_ok = ema_fast is not None and ema_slow is not None and ema_fast >= ema_slow
        fast_slope_ok = ema_fast_slope is not None and ema_fast_slope >= -slope_deadband
        slow_slope_ok = ema_slow_slope is not None and ema_slow_slope >= -slope_deadband
        macd_support = (
            "supportive"
            if (macd_hist is not None and (macd_hist >= 0 or (macd_hist_slope or 0.0) > 0))
            else "opposing"
        )
    else:
        price_ok = price is not None and ema_slow is not None and price <= (ema_slow + price_deadband)
        stack_ok = ema_fast is not None and ema_slow is not None and ema_fast <= ema_slow
        fast_slope_ok = ema_fast_slope is not None and ema_fast_slope <= slope_deadband
        slow_slope_ok = ema_slow_slope is not None and ema_slow_slope <= slope_deadband
        macd_support = (
            "supportive"
            if (macd_hist is not None and (macd_hist <= 0 or (macd_hist_slope or 0.0) < 0))
            else "opposing"
        )

    checks.append(("price_vs_slow_ma", price_ok, require_price_side))
    checks.append(("ma_stack", stack_ok, require_stack))
    checks.append(("fast_ma_slope", fast_slope_ok, require_fast_slope))
    checks.append(("slow_ma_slope", slow_slope_ok, require_slow_slope))
    for label, ok, required in checks:
        if required and not ok:
            failures.append(label)

    passed = not failures
    if passed:
        reason_text = (
            f"HTF MA confirmation passed ({tf_key}): price={price}, "
            f"ema_fast={ema_fast}, ema_slow={ema_slow}, fast_slope={ema_fast_slope}, "
            f"slow_slope={ema_slow_slope}, macd={macd_support}"
        )
    else:
        reason_text = (
            f"HTF MA confirmation failed ({tf_key}, {trigger_type}): "
            f"{', '.join(failures)} | price={price}, ema_fast={ema_fast}, "
            f"ema_slow={ema_slow}, fast_slope={ema_fast_slope}, slow_slope={ema_slow_slope}, "
            f"macd={macd_support}"
        )

    return {
        "passed": passed,
        "reason_code": "passed" if passed else "htf_ma_confirmation_failed",
        "reason_text": reason_text,
        "timeframe": tf_key,
        "trigger_type": trigger_type,
        "direction": direction,
        "price": price,
        "ema_fast": ema_fast,
        "ema_slow": ema_slow,
        "ema_fast_slope_per_bar": ema_fast_slope,
        "ema_slow_slope_per_bar": ema_slow_slope,
        "price_vs_slow_ma_passed": bool(price_ok),
        "ma_stack_passed": bool(stack_ok),
        "fast_ma_slope_passed": bool(fast_slope_ok),
        "slow_ma_slope_passed": bool(slow_slope_ok),
        "macd_hist": macd_hist,
        "macd_hist_slope_per_bar": macd_hist_slope,
        "macd_support": macd_support,
        "failures": failures,
    }


def check_effort_result_divergence(candle_subset, direction):
    """
    Returns float in [-1.0, 1.0]: directional candle effort vs full-subset average.
    > 0 = directional candles have above-average volume and range.
    < 0 = directional candles are weak relative to subset.

    Fixes vs original:
    - Return clamped to [-1.0, 1.0] (previously unbounded below -1.0).
    - Opposing candle strength subtracted — a mixed cluster scores lower.
    - avg_vol uses max(mean, 1e-9) for clean zero-volume protection.
    """
    if len(candle_subset) < 2:
        return 0.0

    avg_vol   = max(candle_subset["volume"].mean(), 1e-9)
    has_range = "range" in candle_subset.columns
    avg_range = max(
        candle_subset["range"].mean() if has_range
        else (candle_subset["high"] - candle_subset["low"]).mean(),
        1e-9
    )

    if direction == "BUY":
        dir_candles = candle_subset[candle_subset["close"] > candle_subset["open"]]
        opp_candles = candle_subset[candle_subset["close"] < candle_subset["open"]]
    else:
        dir_candles = candle_subset[candle_subset["close"] < candle_subset["open"]]
        opp_candles = candle_subset[candle_subset["close"] > candle_subset["open"]]

    if dir_candles.empty:
        return -1.0

    dir_rng = dir_candles["range"] if has_range else (dir_candles["high"] - dir_candles["low"])
    effort  = dir_candles["volume"].mean() / avg_vol
    result  = dir_rng.mean() / avg_range
    raw     = (effort + result) / 2 - 1.0

    if not opp_candles.empty:
        opp_rng = opp_candles["range"] if has_range else (opp_candles["high"] - opp_candles["low"])
        opp_effort = opp_candles["volume"].mean() / avg_vol
        opp_result = opp_rng.mean() / avg_range
        opposition = max(0.0, (opp_effort + opp_result) / 2 - 1.0) * 0.4
        raw -= opposition

    return float(max(-1.0, min(1.0, raw)))

# ─── Advanced Order Flow Analyzer ──────────────────────────────────────────
class OrderFlowAnalyzer:
    def __init__(self, symbol: str, tick_size: float = None):
        self.symbol = symbol.upper().replace('_UMCBL', '')
        self.bids = SortedDict(lambda k: -float(k))
        self.asks = SortedDict()
        self.trade_history = deque(maxlen=int(SIGNAL_CONFIG.get("of_trade_history_maxlen", 20000) or 20000))
        self.book_history = deque(maxlen=int(SIGNAL_CONFIG.get("of_book_history_maxlen", 5000) or 5000))
        self.level_events = defaultdict(list)
        self.bid_levels_raw = SortedDict(lambda k: -float(k))
        self.ask_levels_raw = SortedDict()
        self.seq = None
        self.logger = logging.getLogger(__name__)
        self.needs_resync = False
        self.checksum_depth = ORDER_FLOW_CHECKSUM_DEPTH
        self.checksum_depth_detected = None
        self.ws_diag = {
            'snapshots': 0,
            'updates': 0,
            'checksum_failures': 0,
            'sequence_gaps': 0,
            'stale_updates': 0,
            'resync_requests': 0,
            'reconnect_attempts': 0,
            'duplicate_trades': 0
        }
        # Recently ingested exchange trade ids. Reconnects and overlapping
        # subscriptions replay trades that were already counted, which would
        # otherwise inflate CVD, delta and aggression ratio.
        dedupe_window = max(0, _safe_int(SIGNAL_CONFIG.get("of_trade_dedupe_window"), 20000) or 0)
        self._recent_trade_ids = deque(maxlen=dedupe_window) if dedupe_window else None
        self._recent_trade_id_set = set()
        # ── Microstructure additions ─────────────────────────────────────────
        # Footprint delta: net aggressor volume per price level
        self.level_delta     = defaultdict(float)   # price → net delta (buy+ sell-)
        self.level_vol       = defaultdict(float)   # price → total volume traded
        # Depth history: per-level snapshots for heatmap + migration detection
        # Each entry: (ts_ms, [(price, size), ...] bids, [(price, size), ...] asks)

        self.depth_history   = deque(maxlen=int(SIGNAL_CONFIG.get("of_book_history_maxlen", 5000) or 5000))
        self.total_bid_vol = 0.0
        self.total_ask_vol = 0.0
        # Queue dynamics: persistent event history keyed by price level
        # Survives across analyze() calls — NOT reset between calls so
        # the statistical baseline accumulates over the full session.
        self.level_event_history = defaultdict(list)  # price → [(ts, action, size), ...]
        # Tick size for absorption ratio (injected from symbol config at analyze() time)
        self.tick_size       = tick_size

    def _is_duplicate_trade(self, trade_id):
        if self._recent_trade_ids is None or trade_id is None:
            return False
        key = str(trade_id)
        if key in self._recent_trade_id_set:
            return True
        if len(self._recent_trade_ids) == self._recent_trade_ids.maxlen:
            self._recent_trade_id_set.discard(self._recent_trade_ids[0])
        self._recent_trade_ids.append(key)
        self._recent_trade_id_set.add(key)
        return False

    @staticmethod
    def _to_signed_int32(value: int) -> int:
        value &= 0xffffffff
        if value >= 0x80000000:
            value -= 0x100000000
        return value

    async def connect_and_subscribe(self):
        for attempt in range(1, WS_RECONNECT_ATTEMPTS + 1):
            try:
                ws = await websockets.connect(
                    WS_URL,
                    ping_interval=None,
                    ping_timeout=None,
                    open_timeout=float(SIGNAL_CONFIG.get('websocket_open_timeout_seconds', 10.0) or 10.0),
                    close_timeout=float(SIGNAL_CONFIG.get('websocket_open_timeout_seconds', 10.0) or 10.0),
                )
                sub_msg = {
                    "op": "subscribe",
                    "args": [
                        {
                            "instType": "USDT-FUTURES",
                            "channel": str(SIGNAL_CONFIG.get("of_book_channel", "books15") or "books15"),
                            "instId": self.symbol,
                        },
                        {"instType": "USDT-FUTURES", "channel": "trade", "instId": self.symbol}
                    ]
                }
                await ws.send(json.dumps(sub_msg))
                self.logger.debug(f"[{self.symbol}] Subscribed (attempt {attempt})")
                return ws
            except Exception as e:
                self.logger.warning(f"WS connect failed (attempt {attempt}/{WS_RECONNECT_ATTEMPTS}): {e}")
                if attempt == WS_RECONNECT_ATTEMPTS:
                    raise
                await asyncio.sleep(1.5 * attempt)

    @staticmethod
    def _parse_book_levels(levels):
        parsed = {}
        raw = {}
        for level in levels or []:
            try:
                price_raw, size_raw = level[0], level[1]
                price = float(price_raw)
                size = float(size_raw)
            except Exception:
                continue
            if size <= 0:
                continue
            parsed[price] = size
            raw[price] = (str(price_raw), str(size_raw))
        return parsed, raw

    def _track_snapshot_side_diff(self, ts, old_book, new_book):
        for price in set(old_book.keys()) | set(new_book.keys()):
            old_size = float(old_book.get(price, 0.0) or 0.0)
            new_size = float(new_book.get(price, 0.0) or 0.0)
            delta = new_size - old_size
            if abs(delta) <= 1e-12:
                continue
            if new_size <= 0:
                self.track_event(price, ts, 'remove', -old_size)
            else:
                self.track_event(price, ts, 'add' if old_size <= 0 else 'update', delta)

    def _replace_book_from_snapshot(self, book_data, ts):
        new_bids, new_bid_raw = self._parse_book_levels(book_data.get('bids', []))
        new_asks, new_ask_raw = self._parse_book_levels(book_data.get('asks', []))
        self._track_snapshot_side_diff(ts, self.bids, new_bids)
        self._track_snapshot_side_diff(ts, self.asks, new_asks)

        self.bids.clear()
        self.asks.clear()
        self.bid_levels_raw.clear()
        self.ask_levels_raw.clear()
        self.bids.update(new_bids)
        self.asks.update(new_asks)
        self.bid_levels_raw.update(new_bid_raw)
        self.ask_levels_raw.update(new_ask_raw)
        self.total_bid_vol = float(sum(new_bids.values()))
        self.total_ask_vol = float(sum(new_asks.values()))

    def reset_live_book_state(self, reason=None):
        """Clear only the mutable live book after a continuity break; keep historical buffers intact."""
        self.bids.clear()
        self.asks.clear()
        self.bid_levels_raw.clear()
        self.ask_levels_raw.clear()
        self.total_bid_vol = 0.0
        self.total_ask_vol = 0.0
        self.seq = None
        self.needs_resync = False
        self.ws_diag["resync_requests"] = self.ws_diag.get("resync_requests", 0) + 1
        if reason:
            self.ws_diag["last_resync_reason"] = str(reason)

    async def handle_message(self, data):
        try:
            if not isinstance(data, dict):
                return
            if data.get('event') == 'subscribe':
                return
            payload = data.get('data')

            if not isinstance(payload, list) or not payload:
                return
            arg = data.get('arg', {})
            channel = str(arg.get('channel') or "")
            book_channels = {'books', 'books1', 'books5', 'books15'}
            action = str(data.get('action') or "").strip().lower()

            if channel == 'trade':
                for trade in payload:
                    if not isinstance(trade, dict):
                        continue
                    try:
                        ts = int(trade.get('ts') or trade.get('T') or 0)
                        side = str(trade.get('side') or trade.get('S') or "").strip().lower()
                        price = float(trade.get('price', trade.get('px', trade.get('p', 0))) or 0)
                        size = float(trade.get('size', trade.get('sz', trade.get('v', 0))) or 0)
                    except (TypeError, ValueError):
                        continue
                    if size > 0 and price > 0:
                        trade_id = trade.get('tradeId', trade.get('tradeid', trade.get('i')))
                        if self._is_duplicate_trade(trade_id):
                            self.ws_diag['duplicate_trades'] += 1
                            continue
                        self.trade_history.append((ts, price, size, side))
                        self.level_delta[price] += size if side == 'buy' else -size
                        self.level_vol[price] += size
                return

            if not action:
                action = 'snapshot' if channel in book_channels else ''
            if not action:
                return

            if channel in book_channels:
                book_data = payload[0]
                if not isinstance(book_data, dict):
                    return
                ts = int(book_data.get('ts', 0))
                if action == 'snapshot':
                    self.ws_diag['snapshots'] += 1
                    self._replace_book_from_snapshot(book_data, ts)
                    seq = book_data.get('seq')
                    self.seq = int(seq) if seq is not None else None
                elif action == 'update':
                    self.ws_diag['updates'] += 1
                    prev_seq_raw = book_data.get('prevSeq', book_data.get('pseq'))
                    prev_seq = int(prev_seq_raw) if prev_seq_raw is not None else None
                    next_seq_raw = book_data.get('seq')
                    next_seq = int(next_seq_raw) if next_seq_raw is not None else None
                    apply_incremental = True
                    if prev_seq == 0:
                        # Snapshot-style depth channels (books1/books5/books15) send pseq=0.
                        # Treat as a full replace instead of a group-killing gap.
                        self.ws_diag['snapshots'] += 1
                        self._replace_book_from_snapshot(book_data, ts)
                        if next_seq is not None:
                            self.seq = next_seq
                        apply_incremental = False
                    elif self.seq is not None:
                        if prev_seq is not None:
                            if prev_seq != self.seq:
                                self.ws_diag['sequence_gaps'] += 1
                                self.logger.warning(
                                    "[%s] sequence gap: expected prevSeq=%s got %s",
                                    self.symbol, self.seq, prev_seq,
                                )
                                if ORDER_FLOW_SEQUENCE_MODE == "off":
                                    # Apply anyway; the book may drift until the
                                    # next snapshot-style push repairs it.
                                    pass
                                else:
                                    # A gap means the local book no longer matches the
                                    # exchange. Request a real resync (unsubscribe +
                                    # resubscribe) instead of silently dropping updates.
                                    self.needs_resync = True
                                    return
                        elif next_seq is not None:
                            # Some feeds don't provide prevSeq. In that case, reject only stale/non-increasing updates.
                            if next_seq <= self.seq:
                                self.ws_diag['stale_updates'] += 1
                                return
                    if apply_incremental:
                        if next_seq is not None:
                            self.seq = next_seq
                        for side_key, book_dict in [('bids', self.bids), ('asks', self.asks)]:
                            raw_dict = self.bid_levels_raw if side_key == 'bids' else self.ask_levels_raw
                            updates = book_data.get(side_key, [])
                            for price_str, size_str in updates:
                                price = float(price_str)
                                size = float(size_str)
                                old_size = book_dict.get(price, 0.0)
                                delta = size - old_size
                                if size == 0:
                                    if price in book_dict:
                                        self.track_event(price, ts, 'remove', -book_dict[price])
                                        if side_key == 'bids':
                                            self.total_bid_vol -= book_dict[price]
                                        else:
                                            self.total_ask_vol -= book_dict[price]
                                        del book_dict[price]
                                        if price in raw_dict:
                                            del raw_dict[price]
                                else:
                                    action_type = 'add' if old_size == 0 else 'update'
                                    self.track_event(price, ts, action_type, delta)
                                    if side_key == 'bids':
                                        self.total_bid_vol += delta
                                    else:
                                        self.total_ask_vol += delta
                                    book_dict[price] = size
                                    raw_dict[price] = (str(price_str), str(size_str))
                checksum_raw = book_data.get('checksum')
                checksum = int(checksum_raw) if checksum_raw is not None else None
                if checksum is not None and ORDER_FLOW_CHECKSUM_MODE != 'off':
                    if not self.validate_checksum(checksum):
                        self.ws_diag['checksum_failures'] += 1
                        self.logger.warning("Checksum validation failed")
                        if ORDER_FLOW_CHECKSUM_MODE == 'strict':
                            self.needs_resync = True
                            return
                total_bid_vol = self.total_bid_vol
                total_ask_vol = self.total_ask_vol
                self.book_history.append((ts, total_bid_vol, total_ask_vol))

                # ── Depth snapshot: top-N levels per side for heatmap + migration ──
                # Stored in parallel to book_history — does not replace it.
                # SortedDict with negated key sorts bids descending (best bid first).
                # SortedDict without negation sorts asks ascending (best ask first).
                top_n = max(1, _safe_int(SIGNAL_CONFIG.get("of_depth_snapshot_levels"), DEPTH_SNAPSHOT_LEVELS))
                bid_snap = list(self.bids.items())[:top_n]
                ask_snap = list(self.asks.items())[:top_n]
                self.depth_history.append((ts, bid_snap, ask_snap))

                # level_event_history is written directly in track_event().
                # Pruning is deferred to compute time (_prune_event_history)
                # to keep the hot WS receive loop O(1) per update.
                return
        except Exception as e:
            self.logger.error(f"Message handling error: {e}")

    def _compute_checksum_for_depth(self, depth: int) -> int:
        bid_levels = list(self.bid_levels_raw.values())[:depth]
        ask_levels = list(self.ask_levels_raw.values())[:depth]
        parts = []
        for i in range(max(len(bid_levels), len(ask_levels))):
            if i < len(bid_levels):
                p, s = bid_levels[i]
                parts.append(f"{p}:{s}")
            if i < len(ask_levels):
                p, s = ask_levels[i]
                parts.append(f"{p}:{s}")
        checksum_str = ':'.join(parts)
        return self._to_signed_int32(zlib.crc32(checksum_str.encode()))

    def validate_checksum(self, received_checksum: int) -> bool:
        received = self._to_signed_int32(int(received_checksum))

        if self.checksum_depth_detected:
            return self._compute_checksum_for_depth(self.checksum_depth_detected) == received

        if self.checksum_depth > 0:
            return self._compute_checksum_for_depth(self.checksum_depth) == received

        # Auto-detect once per symbol/session to match exchange checksum depth.
        candidates = [25, 20, 15, 10, 5, 50, 100, DEFAULT_DEPTH_LEVELS]
        seen = set()
        for depth in candidates:
            if depth <= 0 or depth in seen:
                continue
            seen.add(depth)
            if self._compute_checksum_for_depth(depth) == received:
                self.checksum_depth_detected = depth
                self.logger.debug(f"[{self.symbol}] Checksum depth auto-detected: {depth}")
                return True
        return False

    def track_event(self, price: float, ts: int, action: str, delta_size: float):
        self.level_events[price].append((ts, action, delta_size))
        # Also write to persistent history for queue dynamics z-test.
        # Pruning is intentionally NOT done here — this is in the hot WS receive
        # loop. Pruning is deferred to _prune_event_history() called once at
        # compute time, keeping this path O(1).
        self.level_event_history[price].append((ts, action, delta_size))

    def _prune_event_history(self, current_ts_ms: int):
        """
        Remove events older than QUEUE_ACCUMULATE_SECONDS from level_event_history.
        Called ONCE per analyze() cycle at compute time — never inside the WS loop.

        This replaces the previous O(n) per-update pruning that ran inside
        handle_message on every book tick, which was expensive on active symbols
        with hundreds of price levels each accumulating events in parallel.

        Complexity: O(total events across all levels) — acceptable at compute time,
        not acceptable inside a sub-millisecond WS receive callback.
        """
        cutoff_ms = current_ts_ms - (QUEUE_ACCUMULATE_SECONDS * 1000)
        # Iterate over a snapshot of keys to allow safe deletion
        for price in list(self.level_event_history.keys()):
            events = self.level_event_history[price]
            if not events:
                del self.level_event_history[price]
                continue
            # Binary search for cutoff — events are appended in timestamp order
            # so the list is monotonically increasing. Use bisect for O(log n).
            lo, hi = 0, len(events)
            while lo < hi:
                mid = (lo + hi) // 2
                if events[mid][0] < cutoff_ms:
                    lo = mid + 1
                else:
                    hi = mid
            if lo == len(events):
                # All events are stale — remove the level entirely
                del self.level_event_history[price]
            elif lo > 0:
                # Slice off stale prefix in one operation
                self.level_event_history[price] = events[lo:]

    def _log_ws_diagnostics(self, status: str, elapsed_seconds: float):
        self.logger.info(
            "[%s] WS diagnostics (%s): snapshots=%d updates=%d checksum_failures=%d "
            "sequence_gaps=%d stale_updates=%d resync_requests=%d reconnect_attempts=%d "
            "duplicate_trades=%d elapsed=%.1fs",
            self.symbol,
            status,
            self.ws_diag['snapshots'],
            self.ws_diag['updates'],
            self.ws_diag['checksum_failures'],
            self.ws_diag['sequence_gaps'],
            self.ws_diag['stale_updates'],
            self.ws_diag['resync_requests'],
            self.ws_diag['reconnect_attempts'],
            self.ws_diag.get('duplicate_trades', 0),
            elapsed_seconds
        )

    def detect_icebergs_and_spoofs(self):
        """
        Detect iceberg orders and determine their direction by tracking both
        event count AND notional volume (price * size) per side.

        Direction logic:
        - Bid-side refills = hidden buyers accumulating = bullish
        - Ask-side refills = hidden sellers distributing = bearish
        - Direction is only called if ONE side dominates both by count (>=60%)
          AND by notional volume (>=60%). Requiring BOTH prevents a few large
          orders on one side from overriding many small orders on the other.
        - If neither side dominates both metrics, direction = None (mixed).
        """
        bid_icebergs = 0        # event count on bid side
        ask_icebergs = 0        # event count on ask side
        bid_notional = 0.0      # total notional volume of bid-side iceberg refills
        ask_notional = 0.0      # total notional volume of ask-side iceberg refills
        spoofs = 0
        all_sizes = [s for d in [self.bids.values(), self.asks.values()] for s in d]
        avg_level_size = np.mean(all_sizes) if all_sizes else 1.0
        spoof_threshold = avg_level_size * SPOOF_SIZE_THRESHOLD_MULT

        for price, events in self.level_events.items():
            is_bid = price in self.bids
            events = sorted(events, key=lambda x: x[0])
            for i in range(1, len(events)):
                prev_ts, prev_act, prev_delta = events[i-1]
                curr_ts, curr_act, curr_delta = events[i]
                dt = curr_ts - prev_ts

                # Iceberg: a level was consumed (prev_delta < 0) and quickly
                # refilled (curr_delta > 0) within the refill window
                if (prev_delta < 0 and curr_act in ['add', 'update']
                        and curr_delta > 0 and dt <= ICEBERG_REFILL_WINDOW_MS):
                    if abs(curr_delta) >= abs(prev_delta) * 0.75:
                        # Weight by notional value: price * refill size
                        notional = price * abs(curr_delta)
                        if is_bid:
                            bid_icebergs += 1
                            bid_notional += notional
                        else:
                            ask_icebergs += 1
                            ask_notional += notional

                # Spoof: large order added then removed quickly with no trades
                if (prev_act == 'add' and abs(prev_delta) > spoof_threshold
                        and curr_act == 'remove' and dt <= SPOOF_REMOVE_WINDOW_MS):
                    trades_in_window = [
                        t for t in self.trade_history
                        if prev_ts <= t[0] <= curr_ts and abs(t[1] - price) < 0.0001
                    ]
                    if not trades_in_window:
                        spoofs += 1

        total_icebergs = bid_icebergs + ask_icebergs
        total_notional = bid_notional + ask_notional

        # Determine direction: require dominance on BOTH count and notional
        # to avoid false direction calls from mixed activity
        iceberg_direction = None
        if total_icebergs > 0 and total_notional > 0:
            bid_count_pct = bid_icebergs / total_icebergs
            bid_notional_pct = bid_notional / total_notional
            ask_count_pct = ask_icebergs / total_icebergs
            ask_notional_pct = ask_notional / total_notional

            DOMINANCE_THRESHOLD = 0.60  # must own 60%+ of both count and notional

            if bid_count_pct >= DOMINANCE_THRESHOLD and bid_notional_pct >= DOMINANCE_THRESHOLD:
                iceberg_direction = 'BUY'
            elif ask_count_pct >= DOMINANCE_THRESHOLD and ask_notional_pct >= DOMINANCE_THRESHOLD:
                iceberg_direction = 'SELL'
            # else: mixed — direction stays None

        return {
            'icebergs': total_icebergs,
            'bid_icebergs': bid_icebergs,
            'ask_icebergs': ask_icebergs,
            'bid_notional': round(bid_notional, 2),
            'ask_notional': round(ask_notional, 2),
            'iceberg_direction': iceberg_direction,  # 'BUY', 'SELL', or None
            'spoofs': spoofs
        }

    def compute_metrics(self):
        if not self.book_history or len(self.book_history) < MIN_SNAPSHOTS_REQUIRED:
            return {'error': f'Insufficient data (snapshots: {len(self.book_history)} < {MIN_SNAPSHOTS_REQUIRED})'}
        # Normalize activity to quote-notional so thresholds are consistent across symbols.
        # trade_history is a deque, so convert once to a list before any slicing.
        trades = list(self.trade_history)
        buy_notional = sum((p * s) for _, p, s, side in trades if side == 'buy')
        sell_notional = sum((p * s) for _, p, s, side in trades if side == 'sell')
        total_trade_notional = buy_notional + sell_notional
        if total_trade_notional < MIN_TRADE_VOLUME_THRESHOLD:
            return {'error': f'Trade volume too low ({total_trade_notional:.2f} < {MIN_TRADE_VOLUME_THRESHOLD})'}
        imbalances = []
        for _, bid_vol, ask_vol in self.book_history:
            total = bid_vol + ask_vol
            if total > 0:
                imbalances.append((bid_vol - ask_vol) / total)
        avg_imbalance = np.mean(imbalances) if imbalances else 0.0
        if len(imbalances) >= 2:
            imbalance_slope = float(imbalances[-1] - imbalances[0]) / float(len(imbalances) - 1)
        else:
            imbalance_slope = 0.0
        cvd = buy_notional - sell_notional
        aggression_ratio = (buy_notional - sell_notional) / total_trade_notional if total_trade_notional > 0 else 0.0
        trade_count = len(trades)
        cvd_slope_per_trade = float(cvd / trade_count) if trade_count > 0 else 0.0
        half_idx = max(1, trade_count // 2)
        first_half = trades[:half_idx]
        second_half = trades[half_idx:]

        def _half_flow_stats(trades):
            if not trades:
                return 0.0, 0.0
            buy_half = sum((p * s) for _, p, s, side in trades if side == 'buy')
            sell_half = sum((p * s) for _, p, s, side in trades if side == 'sell')
            total_half = buy_half + sell_half
            cvd_half = buy_half - sell_half
            aggression_half = (cvd_half / total_half) if total_half > 0 else 0.0
            return float(cvd_half), float(aggression_half)

        first_half_cvd, first_half_aggr = _half_flow_stats(first_half)
        second_half_cvd, second_half_aggr = _half_flow_stats(second_half)
        cvd_intensity_shift = (
            (second_half_cvd / max(len(second_half), 1)) -
            (first_half_cvd / max(len(first_half), 1))
        ) if first_half and second_half else 0.0
        aggression_ratio_delta_halves = (
            second_half_aggr - first_half_aggr
        ) if first_half and second_half else 0.0
        anomalies = self.detect_icebergs_and_spoofs()
        # Pressure is a directional split of trade notional, not a transformed
        # imbalance score. The two sides must be complementary and must be
        # derived from the same base so they never drift apart.
        if total_trade_notional > 0:
            buy_pressure = float((buy_notional / total_trade_notional) * 100.0)
        else:
            buy_pressure = 50.0
        buy_pressure = max(0.0, min(100.0, float(buy_pressure)))
        sell_pressure = 100.0 - buy_pressure
        start_imbalance = float(imbalances[0]) if imbalances else 0.0
        end_imbalance = float(imbalances[-1]) if imbalances else 0.0
        buy_pressure_slope = imbalance_slope * 50.0
        sell_pressure_slope = -buy_pressure_slope
        signal = None
        if (buy_pressure >= ORDER_FLOW_MIN_PRESSURE and
            avg_imbalance >= ORDER_FLOW_MIN_IMBALANCE and
            cvd > 0 and aggression_ratio >= 0.28):
            signal = 'BUY'
        elif (sell_pressure >= ORDER_FLOW_MIN_PRESSURE and
              -avg_imbalance >= ORDER_FLOW_MIN_IMBALANCE and
              cvd < 0 and aggression_ratio <= -0.28):
            signal = 'SELL'
        reject_reason = None
        # Direction already computed inside detect_icebergs_and_spoofs using
        # dual-metric dominance (both count % and notional % must be >= 60%)
        iceberg_direction = anomalies.get('iceberg_direction')  # 'BUY', 'SELL', or None
        bid_icebergs = anomalies.get('bid_icebergs', 0)
        ask_icebergs = anomalies.get('ask_icebergs', 0)
        bid_notional = anomalies.get('bid_notional', 0.0)
        ask_notional = anomalies.get('ask_notional', 0.0)
        total_icebergs = anomalies['icebergs']

        if anomalies['spoofs'] > HIGH_SPOOF_THRESHOLD:
            reject_reason = f"High spoofing ({anomalies['spoofs']} events) [anomaly basis=bitget_books5]"
        elif total_icebergs > HIGH_ICEBERG_THRESHOLD:
            if iceberg_direction is None:
                # Both count and notional are mixed — no confident direction
                reject_reason = (
                    f"High iceberg activity — mixed direction "
                    f"(bid={bid_icebergs} events/${bid_notional:.0f}, "
                    f"ask={ask_icebergs} events/${ask_notional:.0f}) [anomaly basis=bitget_books5]"
                )
            elif signal is not None and iceberg_direction != signal:
                # Icebergs have a clear direction AND it explicitly opposes the
                # internal order flow signal — institutional flow is against us
                reject_reason = (
                    f"Iceberg direction opposes signal: "
                    f"whale {'buying' if iceberg_direction == 'BUY' else 'selling'} "
                    f"(${max(bid_notional, ask_notional):.0f} notional) vs {signal} signal [anomaly basis=bitget_books5]"
                )
            # If signal is None (pressure not yet strong enough on its own),
            # aligned icebergs can still act as confluence — no rejection
        elif total_trade_notional < MIN_TRADE_VOLUME_THRESHOLD * 1.5:
            reject_reason = f"Low trade activity ({total_trade_notional:.1f}) [anomaly basis=bitget_books5]"

        # Iceberg confluence bonus: when icebergs are directional and not rejected,
        # boost the matching pressure to help it clear the order flow gate
        if iceberg_direction and total_icebergs > HIGH_ICEBERG_THRESHOLD and not reject_reason:
            if iceberg_direction == 'BUY' and buy_pressure < 72:
                buy_pressure = min(100, buy_pressure + 8)
            elif iceberg_direction == 'SELL' and sell_pressure < 72:
                sell_pressure = min(100, sell_pressure + 8)

        return {
            'orderflow_basis': 'bitget_only',
            'buy_pressure': buy_pressure,
            'sell_pressure': sell_pressure,
            'imbalance': round(avg_imbalance, 4),
            'start_imbalance': round(start_imbalance, 4),
            'end_imbalance': round(end_imbalance, 4),
            'imbalance_slope_per_snapshot': round(imbalance_slope, 6),
            'buy_pressure_slope_per_snapshot': round(buy_pressure_slope, 6),
            'sell_pressure_slope_per_snapshot': round(sell_pressure_slope, 6),
            'cvd': round(cvd, 2),
            'cvd_slope_per_trade': round(cvd_slope_per_trade, 6),
            'cvd_intensity_delta_halves': round(cvd_intensity_shift, 6),
            'aggression_ratio': round(aggression_ratio, 3),
            'aggression_ratio_delta_halves': round(aggression_ratio_delta_halves, 6),
            'total_trade_vol': round(total_trade_notional, 2),
            'icebergs_detected': total_icebergs,
            'iceberg_direction': iceberg_direction,
            'bid_icebergs': bid_icebergs,
            'ask_icebergs': ask_icebergs,
            'bid_notional': bid_notional,
            'ask_notional': ask_notional,
            'spoofs_detected': anomalies['spoofs'],
            'signal': signal,
            'reject_reason': reject_reason
        }

    # ── FEATURE 1: Footprint Delta + Delta Divergence ───────────────────────
    def compute_footprint_delta(self) -> dict:
        """
        Per-price-level net aggressor volume and session-level delta divergence.

        Delta divergence: price moved in one direction over the observation window,
        but net delta moved in the opposite direction. This is the canonical sign
        that the dominant participant was absorbing, not initiating the move.

        Returns:
            delta_divergence      : bool   — price and delta disagree in direction
            divergence_strength   : float  — |net_delta| / total_vol (0–1), 0 if no divergence
            net_delta             : float  — session net delta (positive = net buying aggression)
            total_vol             : float  — total volume traded in window
            top_opposed_levels    : list   — top-5 price levels with most opposing delta
              each entry: {'price': float, 'delta': float, 'vol': float, 'notional': float}
            delta_at_sweep_level  : float  — net delta at the level closest to swept_level
              (populated in compute_absorption; None here, set externally if needed)
        """
        if not self.trade_history:
            return {
                'delta_divergence': False, 'divergence_strength': 0.0,
                'net_delta': 0.0, 'total_vol': 0.0,
                'top_opposed_levels': [], 'sufficient_data': False
            }

        total_vol = sum(self.level_vol.values())
        net_delta = sum(self.level_delta.values())
        n_trades  = len(self.trade_history)

        # Need minimum trades for statistical reliability
        if n_trades < DELTA_DIVERGENCE_MIN_TRADES or total_vol == 0:
            return {
                'delta_divergence': False, 'divergence_strength': 0.0,
                'net_delta': round(net_delta, 4), 'total_vol': round(total_vol, 4),
                'top_opposed_levels': [], 'sufficient_data': False
            }

        # Establish price direction over observation window
        first_price = self.trade_history[0][1]
        last_price  = self.trade_history[-1][1]
        price_move  = last_price - first_price

        # Divergence: price up but net delta negative (sellers absorbing uptick)
        #             price down but net delta positive (buyers absorbing downtick)
        # Also require delta magnitude to exceed noise floor
        delta_ratio = abs(net_delta) / total_vol
        divergence = (
            price_move > 0 and net_delta < 0 and delta_ratio >= DELTA_DIVERGENCE_RATIO
        ) or (
            price_move < 0 and net_delta > 0 and delta_ratio >= DELTA_DIVERGENCE_RATIO
        )

        divergence_strength = delta_ratio if divergence else 0.0

        # Top-5 levels with most opposing delta (relative to price direction)
        # For an upward price move, opposing levels are those with negative delta (sellers)
        # For a downward price move, opposing levels are those with positive delta (buyers)
        if price_move >= 0:
            # Opposing = negative delta levels (sellers dominated at these ticks)
            sorted_levels = sorted(
                [(p, d) for p, d in self.level_delta.items() if d < 0],
                key=lambda x: x[1]  # most negative first
            )[:5]
        else:
            # Opposing = positive delta levels (buyers dominated at these ticks)
            sorted_levels = sorted(
                [(p, d) for p, d in self.level_delta.items() if d > 0],
                key=lambda x: -x[1]  # most positive first
            )[:5]

        top_opposed = [
            {
                'price':    round(p, 8),
                'delta':    round(d, 4),
                'vol':      round(self.level_vol.get(p, 0.0), 4),
                'notional': round(p * self.level_vol.get(p, 0.0), 2)
            }
            for p, d in sorted_levels
        ]

        return {
            'delta_divergence':    divergence,
            'divergence_strength': round(divergence_strength, 4),
            'net_delta':           round(net_delta, 4),
            'total_vol':           round(total_vol, 4),
            'price_move':          round(price_move, 8),
            'top_opposed_levels':  top_opposed,
            'sufficient_data':     True
        }

    # ── FEATURE 2: Absorption Detection ─────────────────────────────────────
    def compute_absorption(self, key_levels: list = None) -> dict:
        """
        Detect institutional absorption: large volume traded at a price zone
        with minimal resulting price movement, implying a hidden counterparty.

        The baseline is volume-per-tick across the full observation window.
        A level absorbs if the volume-at-level is >> VPT-baseline but price
        did not move through it (the level is still present in the book, OR
        the move through it was less than 1× tick_size).

        Args:
            key_levels: list of SMC price levels (OB, EQH/EQL, swept_level)
                        to specifically check for absorption. If None, uses
                        all levels from level_delta.

        Returns:
            absorption_detected   : bool
            max_absorption_ratio  : float — peak volume-at-level / expected
            absorbed_levels       : list — levels with absorption details
            ob_level_absorbed     : bool — True if any key_level shows absorption
              (highest-value flag for signal scoring)
        """
        if not self.trade_history or not self.level_vol:
            return {
                'absorption_detected': False, 'max_absorption_ratio': 0.0,
                'absorbed_levels': [], 'ob_level_absorbed': False,
                'sufficient_data': False
            }

        # Volume-per-tick baseline for this observation window
        all_prices = [t[1] for t in self.trade_history]
        price_range = max(all_prices) - min(all_prices) if len(all_prices) > 1 else 0.0

        # Derive tick size: use injected value, else fall back to smallest price
        # difference between consecutive sorted unique prices in trade history
        tick_size = self.tick_size
        if not tick_size or tick_size <= 0:
            sorted_px = sorted(set(round(p, 8) for p in all_prices))
            if len(sorted_px) >= 2:
                diffs = [sorted_px[i+1] - sorted_px[i]
                         for i in range(len(sorted_px)-1) if sorted_px[i+1] > sorted_px[i]]
                tick_size = min(diffs) if diffs else 0.0001
            else:
                tick_size = 0.0001

        price_range_ticks = max(price_range / tick_size, 1.0)
        total_vol = sum(self.level_vol.values())
        vpt_baseline = total_vol / price_range_ticks  # expected vol per tick

        absorbed_levels = []
        max_ratio = 0.0

        # Current book prices (levels still in book = not moved through)
        current_bid_prices = set(self.bids.keys())
        current_ask_prices = set(self.asks.keys())
        all_book_prices    = current_bid_prices | current_ask_prices

        levels_to_check = list(self.level_vol.keys())

        for price in levels_to_check:
            vol_at_level = self.level_vol[price]
            notional     = price * vol_at_level

            # Skip levels with insufficient notional to be institutional
            if notional < ABSORPTION_MIN_NOTIONAL:
                continue

            # Compute expected volume based on VPT baseline (one tick worth)
            expected_vol = vpt_baseline * 1.0  # one tick worth of expected vol
            if expected_vol <= 0:
                continue

            ratio = vol_at_level / expected_vol

            # A level absorbed if:
            # (a) ratio significantly above baseline AND
            # (b) level is still in book (price did not move cleanly through it) OR
            #     level was in book within the last tick (still nearby)
            still_in_book = (
                price in all_book_prices or
                any(abs(p - price) <= tick_size for p in all_book_prices)
            )

            if ratio >= ABSORPTION_RATIO_MODERATE and still_in_book:
                net_delta_at_level = self.level_delta.get(price, 0.0)
                absorbed_levels.append({
                    'price':      round(price, 8),
                    'vol':        round(vol_at_level, 4),
                    'notional':   round(notional, 2),
                    'ratio':      round(ratio, 2),
                    'net_delta':  round(net_delta_at_level, 4),
                    'strength':   'strong' if ratio >= ABSORPTION_RATIO_STRONG else 'moderate',
                    'is_key_level': False  # updated below
                })
                max_ratio = max(max_ratio, ratio)

        # Cross-reference with SMC key levels (OB, EQH/EQL, swept_level)
        ob_level_absorbed = False
        if key_levels and absorbed_levels:
            for ab in absorbed_levels:
                for kl in key_levels:
                    if kl and abs(ab['price'] - kl) <= tick_size * 3:
                        ab['is_key_level'] = True
                        ob_level_absorbed  = True
                        break

        # Sort by ratio descending
        absorbed_levels.sort(key=lambda x: -x['ratio'])

        return {
            'absorption_detected': len(absorbed_levels) > 0,
            'max_absorption_ratio': round(max_ratio, 2),
            'absorbed_levels':      absorbed_levels[:8],  # top 8
            'ob_level_absorbed':    ob_level_absorbed,
            'vpt_baseline':         round(vpt_baseline, 4),
            'sufficient_data':      True
        }

    # ── FEATURE 3: Liquidity Heatmap + Migration Detection ──────────────────
    def compute_liquidity_structure(self) -> dict:
        """
        Liquidity walls, voids, and migration detection from depth_history.

        Data covers top-10 bid/ask levels — i.e. a few ticks around the current
        touch. This is ENTRY EXECUTION QUALITY data, not path-to-TP data.

        Walls   : price levels with persistently large resting size (>= LIQUIDITY_WALL_MULT
                  × average level size across snapshots). Scored by which side relative
                  to current price and trigger type (sweep vs breakout).
        Voids   : price zones where resting size is consistently thin (<= LIQUIDITY_VOID_PCTS
                  × average). Scored only if queue_drain has not already captured this.
        Migration: a large resting order disappears at price P and reappears within
                  MIGRATION_WINDOW_MS at an adjacent price level, same approximate size.
                  Migrating toward current price = informed participant positioning
                  before execution.

        Path-to-TP friction is NOT assessed here — that requires S/R density
        analysis at ATR scale, handled separately in generate_trade_signal.
        """
        empty = {
            'liquidity_walls': [], 'liquidity_voids': [],
            'migration_events': [], 'sufficient_data': False
        }

        if len(self.depth_history) < 5:
            return empty

        # ── Build level-size time series ────────────────────────────────────
        # Aggregate size at each price level across all snapshots
        level_size_series = defaultdict(list)   # price → [size per snapshot]
        level_side        = {}                  # price → 'bid' or 'ask'

        for ts, bid_snap, ask_snap in self.depth_history:
            for price, size in bid_snap:
                level_size_series[price].append(size)
                level_side[price] = 'bid'
            for price, size in ask_snap:
                level_size_series[price].append(size)
                level_side[price] = 'ask'

        if not level_size_series:
            return empty

        # Compute average size per level and overall average
        level_avg    = {p: np.mean(sizes) for p, sizes in level_size_series.items()}
        overall_avg  = np.mean(list(level_avg.values())) if level_avg else 1.0

        if overall_avg <= 0:
            return empty

        # ── Liquidity walls ─────────────────────────────────────────────────
        walls = []
        for price, avg_size in level_avg.items():
            mult = avg_size / overall_avg
            if mult >= LIQUIDITY_WALL_MULT:
                walls.append({
                    'price':    round(price, 8),
                    'avg_size': round(avg_size, 4),
                    'mult':     round(mult, 2),
                    'side':     level_side.get(price, 'unknown')
                })
        walls.sort(key=lambda x: -x['mult'])

        # ── Liquidity voids ─────────────────────────────────────────────────
        # A void = consecutive price levels all below LIQUIDITY_VOID_PCTS × avg
        # Only report on the top-10 bid and top-10 ask levels we track
        all_prices_sorted = sorted(level_avg.keys())
        voids = []
        void_start = None
        void_side  = None

        for i, price in enumerate(all_prices_sorted):
            if level_avg[price] / overall_avg <= LIQUIDITY_VOID_PCTS:
                if void_start is None:
                    void_start = price
                    void_side  = level_side.get(price, 'unknown')
            else:
                if void_start is not None and price > void_start:
                    voids.append({
                        'price_low':  round(void_start, 8),
                        'price_high': round(price, 8),
                        'side':       void_side
                    })
                void_start = None
                void_side  = None

        # ── Migration detection ──────────────────────────────────────────────
        # Identify large orders that moved across price levels within MIGRATION_WINDOW_MS.
        # Requires level_event_history to have accumulated removes and adds.
        migrations = []

        # Only consider events on significant orders (>= MIGRATION_MIN_SIZE_MULT × avg)
        min_migration_size = overall_avg * MIGRATION_MIN_SIZE_MULT

        remove_events = []
        add_events    = []

        for price_level, events in self.level_event_history.items():
            for ts, action, size in events:
                notional = price_level * abs(size)
                if abs(size) >= min_migration_size:
                    if action == 'remove':
                        remove_events.append((ts, price_level, abs(size), notional))
                    elif action in ('add', 'update') and size > 0:
                        add_events.append((ts, price_level, abs(size), notional))

        # Match removes to adds within MIGRATION_WINDOW_MS at a different price
        for rem_ts, rem_price, rem_size, rem_notional in remove_events:
            for add_ts, add_price, add_size, add_notional in add_events:
                if add_price == rem_price:
                    continue  # same level = refill, not migration (iceberg handles this)
                dt = add_ts - rem_ts
                if dt < 0 or dt > MIGRATION_WINDOW_MS:
                    continue
                # Size must be within tolerance
                size_ratio = add_size / max(rem_size, 1e-9)
                if not (1.0 - MIGRATION_SIZE_TOLERANCE <= size_ratio <= 1.0 + MIGRATION_SIZE_TOLERANCE):
                    continue

                # Determine direction relative to price movement
                # 'toward_bid' = order moved to lower price = potential buyer building
                # 'toward_ask' = order moved to higher price = potential seller building
                direction = 'toward_bid' if add_price < rem_price else 'toward_ask'

                migrations.append({
                    'from_price':  round(rem_price, 8),
                    'to_price':    round(add_price, 8),
                    'size':        round(add_size, 4),
                    'notional':    round(add_notional, 2),
                    'ts':          add_ts,
                    'direction':   direction,
                    'delta_price': round(add_price - rem_price, 8)
                })

        # Deduplicate migrations by (from_price, to_price) — keep highest notional
        seen_migrations = {}
        for m in migrations:
            key = (m['from_price'], m['to_price'])
            if key not in seen_migrations or m['notional'] > seen_migrations[key]['notional']:
                seen_migrations[key] = m
        migrations = sorted(seen_migrations.values(), key=lambda x: -x['notional'])

        return {
            'liquidity_walls':       walls[:10],
            'liquidity_voids':       voids[:10],
            'migration_events':      migrations[:10],
            'sufficient_data':       True
        }

    # ── FEATURE 4: Queue Dynamics Statistical Validation ────────────────────
    def compute_queue_dynamics(self) -> dict:
        """
        Statistical analysis of queue behaviour at the best bid/ask (touch levels).

        Queue drain detection: the time-weighted average size at touch dropped
        significantly below the session baseline — the book was thinned before
        the sweep, indicating the "support" was withdrawn (bait, not genuine defence).

        z-test: |z| >= QUEUE_Z_SCORE_SIGNIFICANT → statistically meaningful departure
        from session mean. p-value reported for logging. Requires MIN_EVENTS.

        Queue stability: touch-level size is consistently above baseline — a genuine
        large participant is defending the level.

        Returns:
            best_bid_price        : float
            best_ask_price        : float
            bid_touch_tw_size     : float — time-weighted average size at best bid
            ask_touch_tw_size     : float — time-weighted average size at best ask
            bid_session_mean      : float — session baseline for best bid touch
            ask_session_mean      : float — session baseline for best ask touch
            bid_z_score           : float — z-score of current bid touch size vs session
            ask_z_score           : float — z-score of current ask touch size vs session
            queue_drain_bid       : bool  — bid queue significantly below baseline (z < -THRESH)
            queue_drain_ask       : bool  — ask queue significantly below baseline (z > THRESH)
            queue_stable_bid      : bool  — bid queue significantly above baseline
            queue_stable_ask      : bool  — ask queue significantly above baseline
            bid_n                 : int   — number of events used for bid test
            ask_n                 : int   — number of events used for ask test
            sufficient_data       : bool
        """
        empty = {
            'best_bid_price': None, 'best_ask_price': None,
            'bid_touch_tw_size': 0.0, 'ask_touch_tw_size': 0.0,
            'bid_session_mean': 0.0, 'ask_session_mean': 0.0,
            'bid_z_score': 0.0, 'ask_z_score': 0.0,
            'queue_drain_bid': False, 'queue_drain_ask': False,
            'queue_stable_bid': False, 'queue_stable_ask': False,
            'bid_n': 0, 'ask_n': 0, 'sufficient_data': False
        }

        if not self.bids or not self.asks or not self.level_event_history:
            return empty

        # Current touch levels
        best_bid = max(self.bids.keys()) if self.bids else None
        best_ask = min(self.asks.keys()) if self.asks else None

        if best_bid is None or best_ask is None:
            return empty

        def _time_weighted_size(price: float) -> tuple:
            """
            Compute time-weighted average size at a price level from persistent
            event history, and extract the per-snapshot size series for z-test.
            """
            events = self.level_event_history.get(price, [])
            if len(events) < 2:
                return 0.0, []

            events_sorted = sorted(events, key=lambda e: e[0])
            tw_sizes  = []
            size_vals = []
            current_size = 0.0

            for i in range(len(events_sorted) - 1):
                ts, action, delta = events_sorted[i]
                next_ts = events_sorted[i + 1][0]
                dt_ms = max(next_ts - ts, 0)

                if action in ('add', 'update'):
                    current_size = max(0.0, current_size + delta)
                elif action == 'remove':
                    current_size = max(0.0, current_size - abs(delta))

                if current_size > 0 and dt_ms > 0:
                    tw_sizes.append(current_size * dt_ms)
                    size_vals.append(current_size)

            total_time = sum(
                max(events_sorted[i+1][0] - events_sorted[i][0], 0)
                for i in range(len(events_sorted)-1)
            )
            tw_mean = sum(tw_sizes) / max(total_time, 1) if tw_sizes else 0.0
            return tw_mean, size_vals

        bid_tw_size, bid_series = _time_weighted_size(best_bid)
        ask_tw_size, ask_series = _time_weighted_size(best_ask)

        # z-test: is the current TW size a significant departure from the
        # series mean? Use t-test (handles small n better than z-test)
        def _z_score(series: list, current: float) -> tuple:
            n = len(series)
            if n < QUEUE_STABILITY_MIN_EVENTS:
                return 0.0, 1.0, n  # insufficient data
            mean = np.mean(series)
            std  = np.std(series, ddof=1)
            if std == 0:
                return 0.0, 1.0, n
            z = (current - mean) / std
            # Two-tailed p-value via t-distribution (more honest at small n)
            p = float(2 * (1 - stats.t.cdf(abs(z), df=n-1)))
            return float(z), p, n

        bid_z, bid_p, bid_n = _z_score(bid_series, bid_tw_size)
        ask_z, ask_p, ask_n = _z_score(ask_series, ask_tw_size)

        bid_session_mean = float(np.mean(bid_series)) if bid_series else 0.0
        ask_session_mean = float(np.mean(ask_series)) if ask_series else 0.0

        # Queue drain: touch-level size significantly BELOW session baseline
        # This is the leading indicator — the "support" was withdrawn before sweep
        queue_drain_bid  = bid_z < -QUEUE_Z_SCORE_SIGNIFICANT and bid_n >= QUEUE_STABILITY_MIN_EVENTS
        queue_drain_ask  = ask_z >  QUEUE_Z_SCORE_SIGNIFICANT and ask_n >= QUEUE_STABILITY_MIN_EVENTS

        # Queue stability: size significantly ABOVE baseline — genuine defender
        queue_stable_bid = bid_z >  QUEUE_Z_SCORE_SIGNIFICANT and bid_n >= QUEUE_STABILITY_MIN_EVENTS
        queue_stable_ask = ask_z < -QUEUE_Z_SCORE_SIGNIFICANT and ask_n >= QUEUE_STABILITY_MIN_EVENTS

        sufficient = (bid_n >= QUEUE_STABILITY_MIN_EVENTS or
                      ask_n >= QUEUE_STABILITY_MIN_EVENTS)

        return {
            'best_bid_price':    best_bid,
            'best_ask_price':    best_ask,
            'bid_touch_tw_size': round(bid_tw_size, 4),
            'ask_touch_tw_size': round(ask_tw_size, 4),
            'bid_session_mean':  round(bid_session_mean, 4),
            'ask_session_mean':  round(ask_session_mean, 4),
            'bid_z_score':       round(bid_z, 3),
            'ask_z_score':       round(ask_z, 3),
            'queue_drain_bid':   queue_drain_bid,
            'queue_drain_ask':   queue_drain_ask,
            'queue_stable_bid':  queue_stable_bid,
            'queue_stable_ask':  queue_stable_ask,
            'bid_n':             bid_n,
            'ask_n':             ask_n,
            'sufficient_data':   sufficient
        }
    # put below 2f
    def _snapshot_clone(self, *, lookback_seconds=None, event_lookback_seconds=None):
        """
        Build a private clone of this analyzer's rolling buffers for a requested
        window. MUST run on the event loop (serialized with handle_message) so the
        copy is race-free. Returns a context dict consumed by compute_from_clone.
        """
        now_ms = int(time.time() * 1000)
        lookback_ms = int(max(1, _safe_int(lookback_seconds, ORDER_FLOW_WINDOW_SECONDS)) * 1000)
        event_ms = int(max(lookback_ms, _safe_int(event_lookback_seconds, lookback_seconds or ORDER_FLOW_WINDOW_SECONDS) * 1000))
        data_cutoff = now_ms - lookback_ms
        event_cutoff = now_ms - event_ms

        snapshot = OrderFlowAnalyzer(self.symbol, tick_size=self.tick_size)
        snapshot.bids.update(self.bids)
        snapshot.asks.update(self.asks)
        snapshot.bid_levels_raw.update(self.bid_levels_raw)
        snapshot.ask_levels_raw.update(self.ask_levels_raw)
        snapshot.seq = self.seq
        snapshot.ws_diag = dict(self.ws_diag)
        snapshot.checksum_depth_detected = self.checksum_depth_detected

        trades = [trade for trade in list(self.trade_history) if _safe_int(trade[0], 0) >= data_cutoff]
        books = [row for row in list(self.book_history) if _safe_int(row[0], 0) >= data_cutoff]
        depth_rows = [row for row in list(self.depth_history) if _safe_int(row[0], 0) >= data_cutoff]
        snapshot.trade_history = deque(trades, maxlen=max(len(trades), 1))
        snapshot.book_history = deque(books, maxlen=max(len(books), 1))
        snapshot.depth_history = deque(depth_rows, maxlen=max(len(depth_rows), 1))

        snapshot.level_delta = defaultdict(float)
        snapshot.level_vol = defaultdict(float)
        for _, price, size, side in trades:
            snapshot.level_delta[price] += size if side == 'buy' else -size
            snapshot.level_vol[price] += size

        snapshot.level_events = defaultdict(list)
        snapshot.level_event_history = defaultdict(list)
        for price, events in list(self.level_events.items()):
            filtered = [event for event in events if _safe_int(event[0], 0) >= event_cutoff]
            if filtered:
                snapshot.level_events[price] = filtered
        for price, events in list(self.level_event_history.items()):
            filtered = [event for event in events if _safe_int(event[0], 0) >= event_cutoff]
            if filtered:
                snapshot.level_event_history[price] = filtered

        return {
            "snapshot": snapshot,
            "trades": trades,
            "books": books,
            "depth_rows": depth_rows,
            "now_ms": now_ms,
            "lookback_ms": lookback_ms,
            "event_ms": event_ms,
        }

    def compute_from_clone(self, ctx, *, key_levels=None):
        """
        Heavy CPU work over a private clone (safe to run in a worker thread).
        ctx is produced by _snapshot_clone.
        """
        snapshot = ctx["snapshot"]
        trades = ctx["trades"]
        books = ctx["books"]
        depth_rows = ctx["depth_rows"]
        now_ms = ctx["now_ms"]
        lookback_ms = ctx["lookback_ms"]
        event_ms = ctx["event_ms"]

        result = snapshot.compute_metrics()
        if isinstance(result, dict):
            result['ws_diagnostics'] = dict(snapshot.ws_diag)
            result['coverage'] = {
                'lookback_seconds': int(lookback_ms // 1000),
                'event_lookback_seconds': int(event_ms // 1000),
                'trade_count': len(trades),
                'book_snapshot_count': len(books),
                'depth_snapshot_count': len(depth_rows),
                'oldest_trade_age_seconds': (
                    round((now_ms - min(_safe_int(row[0], now_ms) for row in trades)) / 1000.0, 3)
                    if trades else None
                ),
                'latest_trade_age_seconds': (
                    round((now_ms - max(_safe_int(row[0], now_ms) for row in trades)) / 1000.0, 3)
                    if trades else None
                ),
                'latest_book_age_seconds': (
                    round((now_ms - max(_safe_int(row[0], now_ms) for row in books)) / 1000.0, 3)
                    if books else None
                ),
            }
            if not result.get('error'):
                try:
                    result['footprint'] = snapshot.compute_footprint_delta()
                except Exception as exc:
                    self.logger.warning(f"[{self.symbol}] Cached footprint delta failed: {exc}")
                    result['footprint'] = {'delta_divergence': False, 'sufficient_data': False}
                try:
                    result['absorption'] = snapshot.compute_absorption(key_levels=key_levels)
                except Exception as exc:
                    self.logger.warning(f"[{self.symbol}] Cached absorption failed: {exc}")
                    result['absorption'] = {'absorption_detected': False, 'sufficient_data': False}
                try:
                    result['liquidity'] = snapshot.compute_liquidity_structure()
                except Exception as exc:
                    self.logger.warning(f"[{self.symbol}] Cached liquidity structure failed: {exc}")
                    result['liquidity'] = {
                        'liquidity_walls': [],
                        'liquidity_voids': [],
                        'migration_events': [],
                        'sufficient_data': False,
                    }
                try:
                    result['queue'] = snapshot.compute_queue_dynamics()
                except Exception as exc:
                    self.logger.warning(f"[{self.symbol}] Cached queue dynamics failed: {exc}")
                    result['queue'] = {'queue_drain_bid': False, 'queue_drain_ask': False, 'sufficient_data': False}
        return result

    def compute_cached_snapshot(self, *, lookback_seconds=None, event_lookback_seconds=None, key_levels=None):
        """
        Backward-compatible sync path: clone + compute in one call.
        Hot paths (snapshot(), maintenance) use _snapshot_clone + compute_from_clone
        separately so the clone runs on the loop and compute runs in a thread.
        """
        ctx = self._snapshot_clone(lookback_seconds=lookback_seconds, event_lookback_seconds=event_lookback_seconds)
        return self.compute_from_clone(ctx, key_levels=key_levels)

    #stop here
    async def analyze(self, window_seconds: int = ORDER_FLOW_WINDOW_SECONDS, key_levels=None):
        ws = None
        started_at = time.time()
        for attempt in range(1, WS_RECONNECT_ATTEMPTS + 1):
            self.ws_diag['reconnect_attempts'] = attempt
            collection_completed = False
            try:
                ws = await self.connect_and_subscribe()
                start = time.time()
                next_ping_at = time.time() + 30
                while time.time() - start < window_seconds:
                    try:
                        msg = await asyncio.wait_for(
                            ws.recv(),
                            timeout=float(SIGNAL_CONFIG.get('websocket_recv_timeout_seconds', 2.0) or 2.0),
                        )
                        await self.handle_message(msg)
                        if self.needs_resync:
                            self.ws_diag['resync_requests'] += 1
                            self.logger.warning(f"[{self.symbol}] Resync requested after gap/checksum failure")
                            break
                    except asyncio.TimeoutError:
                        if time.time() >= next_ping_at:
                            await ws.send("ping")
                            next_ping_at = time.time() + 30
                        continue
                    except websockets.exceptions.ConnectionClosed:
                        self.logger.warning(f"WS closed during collection (attempt {attempt})")
                        break
                    except Exception as e:
                        self.logger.error(f"WS receive error (attempt {attempt}): {e}")
                        break
                if not self.needs_resync and (time.time() - start) >= window_seconds:
                    collection_completed = True
            except Exception as e:
                self.logger.error(f"WS connection failed (attempt {attempt}): {e}")
            finally:
                if ws:
                    try:
                        await ws.close()
                    except:
                        pass
                    ws = None
            if collection_completed:
                break
            self.needs_resync = False
            if attempt < WS_RECONNECT_ATTEMPTS:
                await asyncio.sleep(2 ** attempt)
            else:
                self._log_ws_diagnostics("failed", time.time() - started_at)
                return None
        result = self.compute_metrics()
        if isinstance(result, dict):
            result['ws_diagnostics'] = dict(self.ws_diag)

            # ── Prune stale event history ONCE before all compute methods ────
            # Deferred from the hot WS loop — safe to do O(total events) here.
            # Use the latest book snapshot timestamp as the current time reference
            # so pruning is consistent with the data we just collected.
            _prune_ts = self.book_history[-1][0] if self.book_history else int(time.time() * 1000)
            self._prune_event_history(_prune_ts)

            # ── Microstructure layer: always run after core metrics ───────────
            # These methods use data accumulated during the WS window.
            # They do not open additional connections.
            try:
                footprint = self.compute_footprint_delta()
                result['footprint'] = footprint
            except Exception as _e:
                self.logger.warning(f"[{self.symbol}] Footprint delta failed: {_e}")
                result['footprint'] = {'delta_divergence': False, 'sufficient_data': False}

            try:
                absorption = self.compute_absorption(key_levels=key_levels)
                result['absorption'] = absorption
            except Exception as _e:
                self.logger.warning(f"[{self.symbol}] Absorption detection failed: {_e}")
                result['absorption'] = {'absorption_detected': False, 'sufficient_data': False}

            try:
                liquidity = self.compute_liquidity_structure()
                result['liquidity'] = liquidity
            except Exception as _e:
                self.logger.warning(f"[{self.symbol}] Liquidity structure failed: {_e}")
                result['liquidity'] = {'liquidity_walls': [], 'liquidity_voids': [],
                                       'migration_events': [], 'sufficient_data': False}

            try:
                queue = self.compute_queue_dynamics()
                result['queue'] = queue
            except Exception as _e:
                self.logger.warning(f"[{self.symbol}] Queue dynamics failed: {_e}")
                result['queue'] = {'queue_drain_bid': False, 'queue_drain_ask': False,
                                   'sufficient_data': False}

        status = "ok"
        if isinstance(result, dict) and result.get('error'):
            status = "error"
        self._log_ws_diagnostics(status, time.time() - started_at)
        return result


class OrderFlowManager:
    """
    Process-wide continuous WebSocket orderflow collector.

    The scanner provides the symbol universe. This manager keeps rolling trade
    and book buffers warm, then signal generation reads snapshots from cache.
    """
    #put below 2b
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.analyzers = {}
        self.symbol_meta = {}
        self.symbol_gaps = defaultdict(lambda: deque(maxlen=50))
        self.groups = {}
        self.symbol_to_group = {}
        self._lock = asyncio.Lock()
        self._next_group_id = 1
        self._ever_prepared = False
        # Bitget-only reference decisions (thread-safe cache). Written ONLY
        # by the main thread's confirmation path; read by the cross-exchange
        # layer. Never call analyzer.compute_metrics() from another thread.
        self._reference_signals = {}
        self._reference_signals_lock = threading.Lock()
        # Bounded executor for heavy snapshot compute (offloaded off the WS loop).
        self._compute_executor = ThreadPoolExecutor(
            max_workers=max(1, _safe_int(SIGNAL_CONFIG.get("of_snapshot_worker_threads"), 4) or 4),
            thread_name_prefix="of-snapshot",
        )
        # Per-symbol inflight futures to prevent overlapping snapshot computes.
        self._inflight = {}
        self._maintenance = None
        # Focus tier: symbols served by the incremental `books` channel.
        self._focus_symbols = set()
        self._focus_promoted_at = {}
        self._focus_last_seen = {}

    #stop  here
    @staticmethod
    def _norm(symbol):
        return _normalize_bitget_symbol(symbol)

    def _enabled(self):
        return bool(SIGNAL_CONFIG.get("enable_websocket_orderflow_confirmation", False)) and bool(
            SIGNAL_CONFIG.get("enable_continuous_orderflow_manager", True)
        )

    def _book_channel(self):
        """Depth channel for the wide scan universe."""
        return str(SIGNAL_CONFIG.get("of_book_channel", "books15") or "books15").strip() or "books15"

    def _focus_book_channel(self):
        """Depth channel for focus symbols: incremental `books` carries seq + checksum."""
        if not bool(SIGNAL_CONFIG.get("of_enable_focus_book_upgrade", True)):
            return self._book_channel()
        return str(SIGNAL_CONFIG.get("of_focus_book_channel", "books") or "books").strip() or "books"

    @staticmethod
    def _channel_weight(channel):
        """Relative bandwidth cost of a depth channel, used to size connections."""
        weights = SIGNAL_CONFIG.get("of_book_channel_weights")
        if isinstance(weights, dict) and channel in weights:
            return max(1, _safe_int(weights.get(channel), 2) or 2)
        return {"books1": 1, "books5": 1, "books15": 2, "books": 6}.get(channel, 2)

    def desired_book_channel(self, symbol):
        return self._focus_book_channel() if symbol in self._focus_symbols else self._book_channel()

    def _symbols_per_connection(self, book_channel=None):
        target_channels = max(2, _safe_int(SIGNAL_CONFIG.get("of_target_channels_per_connection"), 40))
        if not bool(SIGNAL_CONFIG.get("of_subscribe_book_channel", True)):
            return max(1, target_channels)
        channel = book_channel or self._book_channel()
        # 1 unit for the trade channel plus the depth channel's weight.
        return max(1, target_channels // (1 + self._channel_weight(channel)))

    def mark_focus(self, symbol):
        """
        Promote a symbol to the focus tier (full incremental depth).

        Called whenever signal generation actually reads a symbol, so the
        expensive channel is only paid for on trade candidates. Capped and
        dwell-limited so the set does not churn between connections.
        """
        if not bool(SIGNAL_CONFIG.get("of_enable_focus_book_upgrade", True)):
            return
        now = time.time()
        self._focus_last_seen[symbol] = now
        if symbol in self._focus_symbols:
            return
        max_focus = max(0, _safe_int(SIGNAL_CONFIG.get("of_focus_symbols_max"), 40) or 0)
        if max_focus <= 0:
            return
        if len(self._focus_symbols) >= max_focus:
            dwell = max(0.0, _safe_float(SIGNAL_CONFIG.get("of_focus_min_dwell_seconds"), 300.0) or 0.0)
            evictable = [
                (self._focus_last_seen.get(other, 0.0), other)
                for other in self._focus_symbols
                if now - self._focus_promoted_at.get(other, 0.0) >= dwell
            ]
            if not evictable:
                return
            _, victim = min(evictable)
            self._demote_focus(victim)
        self._focus_symbols.add(symbol)
        self._focus_promoted_at[symbol] = now

    def _demote_focus(self, symbol):
        self._focus_symbols.discard(symbol)
        self._focus_promoted_at.pop(symbol, None)

    def _expire_focus_symbols(self):
        idle = max(0.0, _safe_float(SIGNAL_CONFIG.get("of_focus_idle_seconds"), 900.0) or 0.0)
        if idle <= 0:
            return
        dwell = max(0.0, _safe_float(SIGNAL_CONFIG.get("of_focus_min_dwell_seconds"), 300.0) or 0.0)
        now = time.time()
        for symbol in list(self._focus_symbols):
            if now - self._focus_promoted_at.get(symbol, 0.0) < dwell:
                continue
            if now - self._focus_last_seen.get(symbol, 0.0) >= idle:
                self._demote_focus(symbol)

    def _active_group_count(self):
        return sum(1 for group in self.groups.values() if self._group_alive(group))

    def _group_alive(self, group):
        if not isinstance(group, dict):
            group = self.groups.get(group) or {}
        if not group or group.get("task_done"):
            return False
        task = group.get("task")
        if task is None:
            return True
        return not task.done()

    def _group_book_channel(self, group):
        if isinstance(group, dict):
            return str(group.get("book_channel") or self._book_channel())
        return self._book_channel()

    def _bind_symbol_to_live_group(self, symbol):
        desired_channel = self.desired_book_channel(symbol)
        gid = self.symbol_to_group.get(symbol)
        group = self.groups.get(gid) if gid is not None else None
        if (
            gid is not None
            and self._group_alive(group)
            and symbol in (group.get("symbols") or set())
            and self._group_book_channel(group) == desired_channel
        ):
            meta = self.symbol_meta.setdefault(symbol, {})
            meta["group_id"] = gid
            if group.get("connected") and not meta.get("subscribe_error"):
                meta["subscribed"] = True
            return gid
        for other_id, other in self.groups.items():
            if not self._group_alive(other):
                continue
            if symbol not in (other.get("symbols") or set()):
                continue
            if self._group_book_channel(other) != desired_channel:
                continue
            self.symbol_to_group[symbol] = other_id
            meta = self.symbol_meta.setdefault(symbol, {})
            meta["group_id"] = other_id
            if other.get("connected") and not meta.get("subscribe_error"):
                meta["subscribed"] = True
            return other_id
        return None

    def _ownership_rank(self, symbol, gid):
        """Higher is better: right depth channel first, then connected, then oldest."""
        group = self.groups.get(gid) or {}
        return (
            1 if self._group_book_channel(group) == self.desired_book_channel(symbol) else 0,
            1 if group.get("connected") else 0,
            -(_safe_int(group.get("created_at_ms"), gid) or 0),
        )

    def _dedupe_overlapping_groups(self):
        overlaps = 0
        live = {gid: group for gid, group in self.groups.items() if self._group_alive(group)}
        original = {gid: set(group.get("symbols") or set()) for gid, group in live.items()}

        claimed = {}
        for gid, symbols in original.items():
            for symbol in symbols:
                owner = claimed.get(symbol)
                if owner is None:
                    claimed[symbol] = gid
                    continue
                overlaps += 1
                if self._ownership_rank(symbol, gid) > self._ownership_rank(symbol, owner):
                    claimed[symbol] = gid

        for gid, group in live.items():
            keep = {symbol for symbol in original[gid] if claimed.get(symbol) == gid}
            # The duplicate is unsubscribed from this socket immediately when
            # it is still connected, otherwise on its next frame; either way
            # the other symbols on that connection are never disturbed.
            for symbol in original[gid] - keep:
                group.setdefault("pending_release", set()).add(symbol)
                ws = group.get("ws")
                if ws is not None:
                    asyncio.create_task(self._release_symbol(ws, gid, symbol))
                self.logger.warning(
                    "OrderFlowManager releasing duplicate subscription for %s from group %s (owner group %s)",
                    symbol, gid, claimed.get(symbol),
                )
            group["symbols"] = keep
            for symbol in keep:
                self.symbol_to_group[symbol] = gid
                meta = self.symbol_meta.setdefault(symbol, {})
                meta["group_id"] = gid
            if not keep:
                task = group.get("task")
                if task is not None and not task.done():
                    task.cancel()
                group["task_done"] = True
        return overlaps

    def _chunks(self, symbols, size):
        for idx in range(0, len(symbols), max(1, size)):
            yield symbols[idx: idx + max(1, size)]

    def _empty_payload(self, symbol, reason, *, lookback_seconds=0, event_lookback_seconds=0, coverage=None):
        coverage = coverage or {}

        # Preserve actual WS source identity when possible. Do not manufacture 'unavailable' if the transport is live.
        ws_available = bool(coverage.get('ws_available'))
        coverage_sufficient = bool(coverage.get('coverage_sufficient'))
        if ws_available:
            # Transport exists but coverage may be insufficient
            source_state = 'live_ws_continuous'
            ws_status = 'coverage_insufficient' if not coverage_sufficient else 'continuous_ws_ready'
        else:
            source_state = 'live_ws_continuous_unavailable'
            ws_status = 'continuous_ws_not_ready'

        return {
            'buy_pressure': 50,
            'sell_pressure': 50,
            'signal': None,
            'imbalance': 0.0,
            'start_imbalance': 0.0,
            'end_imbalance': 0.0,
            'imbalance_slope_per_snapshot': 0.0,
            'buy_pressure_slope_per_snapshot': 0.0,
            'sell_pressure_slope_per_snapshot': 0.0,
            'cvd_slope_per_trade': 0.0,
            'cvd_intensity_delta_halves': 0.0,
            'aggression_ratio_delta_halves': 0.0,
            'live_orderflow_source': source_state,
            'live_orderflow_window_seconds': int(lookback_seconds or 0),
            'orderflow_metrics_available': False,
            'coverage_sufficient': coverage_sufficient,
            'confirmation_eligible': False,
            'ws_diagnostics': {
                'enabled': True,
                'status': ws_status,
                'source': source_state,
                'error': reason,
                'coverage': coverage,
            },
            'coverage': coverage,
            'reject_reason': reason,
            'websocket_orderflow_optional': False,
            'fail_closed': True,
            'event_lookback_seconds': int(event_lookback_seconds or 0),
            'symbol': symbol,
        }

    def _coverage_block_payload(self, symbol, reason, *, lookback_seconds=0, event_lookback_seconds=0, coverage=None):
        coverage = coverage or {}
        source = str(coverage.get("source_state") or "live_ws_continuous")
        return {
            'buy_pressure': 50,
            'sell_pressure': 50,
            'signal': None,
            'imbalance': 0.0,
            'start_imbalance': 0.0,
            'end_imbalance': 0.0,
            'imbalance_slope_per_snapshot': 0.0,
            'buy_pressure_slope_per_snapshot': 0.0,
            'sell_pressure_slope_per_snapshot': 0.0,
            'cvd_slope_per_trade': 0.0,
            'cvd_intensity_delta_halves': 0.0,
            'aggression_ratio_delta_halves': 0.0,
            'live_orderflow_source': source,
            'live_orderflow_window_seconds': int(lookback_seconds or 0),
            'orderflow_metrics_available': False,
            'coverage_sufficient': False,
            'confirmation_eligible': False,
            'coverage': coverage,
            'ws_diagnostics': {
                'enabled': True,
                'status': 'coverage_insufficient',
                'source': source,
                'error': reason,
                'coverage': coverage,
            },
            'reject_reason': reason,
            'websocket_orderflow_optional': False,
            'fail_closed': True,
            'event_lookback_seconds': int(event_lookback_seconds or 0),
            'symbol': symbol,
        }

    async def prepare_symbols(self, symbols, *, wait_for_warmup=True):
        if not self._enabled():
            return {"enabled": False, "reason": "continuous orderflow manager disabled"}
        symbols = [self._norm(symbol) for symbol in symbols or []]
        symbols = [symbol for symbol in dict.fromkeys(symbols) if symbol]
        if not symbols:
            return {"enabled": True, "prepared": 0, "warm_count": 0, "reason": "no symbols"}
        await self.ensure_symbols(symbols)
        if wait_for_warmup:
            return await self.warmup(symbols)
        summary = self.coverage_summary(
            symbols,
            required_stream_age_seconds=SIGNAL_CONFIG.get("of_min_stream_age_seconds", 60),
        )
        summary["warmup_elapsed_seconds"] = 0.0
        summary["target_age_seconds"] = _safe_int(SIGNAL_CONFIG.get("of_min_stream_age_seconds"), 60)
        summary["warmup_skipped"] = True
        return summary
    #put below 2c



    def _fetch_valid_usdt_futures_inst_ids(self):
        """Return the set of valid USDT-FUTURES instIds from Bitget, or None on failure."""
        try:
            url = "https://api.bitget.com/api/v2/mix/market/contracts?productType=USDT-FUTURES"
            resp = requests.get(url, timeout=10)
            resp.raise_for_status()
            data = resp.json() or {}
            valid = set()
            for item in (data.get("data") or []):
                inst = item.get("symbol") or item.get("instId")
                if inst:
                    valid.add(str(inst).upper())
            return valid or None
        except Exception as exc:
            self.logger.warning("OrderFlowManager could not fetch valid USDT-FUTURES instrument list: %s", exc)
            return None

    async def ensure_symbols(self, symbols):
        if not self._enabled():
            return {"enabled": False}
        symbols = [self._norm(symbol) for symbol in symbols or []]
        symbols = [symbol for symbol in dict.fromkeys(symbols) if symbol]




        if symbols and not getattr(self, "_symbol_universe_validated", False):
            self._symbol_universe_validated = True
            try:
                valid = await asyncio.to_thread(self._fetch_valid_usdt_futures_inst_ids)
                if valid is not None:
                    self._valid_inst_ids = valid
                    invalid = [s for s in symbols if s not in valid]
                    if invalid:
                        self.logger.warning(
                            "OrderFlowManager symbol universe validation: %d/%d requested symbols are NOT valid USDT-FUTURES contracts on Bitget: %s",
                            len(invalid), len(symbols),
                            ", ".join(invalid[:50]) + (" ..." if len(invalid) > 50 else ""),
                        )
                    else:
                        self.logger.info(
                            "OrderFlowManager symbol universe validation: all %d requested symbols are valid USDT-FUTURES contracts",
                            len(symbols),
                        )
            except Exception as exc:
                self.logger.warning("OrderFlowManager symbol universe validation failed: %s", exc)


        # ── Fast path: every symbol already assigned to a live group.
        now_ms = int(time.time() * 1000)
        if symbols and all(self._bind_symbol_to_live_group(symbol) is not None for symbol in symbols):
            for symbol in symbols:
                if symbol not in self.analyzers:
                    break
                meta = self.symbol_meta.get(symbol)
                if meta:
                    meta["scanner_seen_ms"] = now_ms
            else:
                return {"enabled": True, "tracked": len(self.analyzers)}

        async with self._lock:
            self._dedupe_overlapping_groups()
            valid_ids = getattr(self, "_valid_inst_ids", None)
            for symbol in symbols:
                if valid_ids is not None and symbol not in valid_ids:
                    meta = self.symbol_meta.setdefault(symbol, {})
                    meta["subscribe_error"] = meta.get("subscribe_error") or "invalid_usdt_futures_contract"
                    continue
                if symbol not in self.analyzers:
                    self.analyzers[symbol] = OrderFlowAnalyzer(symbol)
                self.symbol_meta.setdefault(
                    symbol,
                    {
                        "stream_start_ms": None,
                        "last_message_ms": None,
                        "last_trade_ms": None,
                        "last_book_ms": None,
                        "group_id": None,
                        "scanner_seen_ms": now_ms,
                        "subscribed": False,
                        "subscription_requested_ms": None,
                    },
                )
                self.symbol_meta[symbol]["scanner_seen_ms"] = now_ms

            missing = []
            for symbol in symbols:
                if valid_ids is not None and symbol not in valid_ids:
                    continue
                if self._bind_symbol_to_live_group(symbol) is None:
                    missing.append(symbol)
            if missing:
                attached = await self._attach_to_existing_groups(missing, now_ms)
                if attached:
                    missing = [symbol for symbol in missing if symbol not in attached]
            if missing:
                max_connections = max(1, _safe_int(SIGNAL_CONFIG.get("of_max_connections"), 50))
                capacity = max_connections - self._active_group_count()
                started = 0
                # Group by depth channel: focus symbols ride the heavier
                # incremental `books` feed with fewer symbols per socket.
                by_channel = defaultdict(list)
                for symbol in missing:
                    by_channel[self.desired_book_channel(symbol)].append(symbol)
                chunks = [
                    (channel, chunk)
                    for channel, channel_symbols in by_channel.items()
                    for chunk in self._chunks(channel_symbols, self._symbols_per_connection(channel))
                ]
                for channel, chunk in chunks:
                    if capacity <= 0:
                        self.logger.warning(
                            "OrderFlowManager connection cap reached; %d symbols will fail closed until capacity frees",
                            len(missing) - started,
                        )
                        break
                    already = [symbol for symbol in chunk if self._bind_symbol_to_live_group(symbol) is not None]
                    group_symbols = [symbol for symbol in chunk if symbol not in already]
                    if not group_symbols:
                        continue
                    group_id = self._next_group_id
                    self._next_group_id += 1
                    task = asyncio.create_task(self._connection_loop(group_id, group_symbols, channel))
                    self.groups[group_id] = {
                        "symbols": set(group_symbols),
                        "task": task,
                        "created_at_ms": now_ms,
                        "task_done": False,
                        "connected": False,
                        "book_channel": channel,
                    }
                    for symbol in group_symbols:
                        self.symbol_to_group[symbol] = group_id
                        self.symbol_meta[symbol]["group_id"] = group_id
                        self.symbol_meta[symbol]["subscription_requested_ms"] = now_ms
                    capacity -= 1
                    started += len(group_symbols)
                if started:
                    self.logger.info(
                        "OrderFlowManager started %d new symbol streams across %d active groups",
                        started,
                        self._active_group_count(),
                    )
        return {"enabled": True, "tracked": len(self.analyzers)}

    #stop here
    async def warmup(self, symbols):
        symbols = [self._norm(symbol) for symbol in symbols or []]
        symbols = [symbol for symbol in dict.fromkeys(symbols) if symbol]
        if not symbols:
            return {"enabled": True, "prepared": 0, "warm_count": 0}

        initial_warmup = not self._ever_prepared
        full_warmup = max(0, _safe_int(SIGNAL_CONFIG.get("of_warmup_seconds"), 60))
        incremental_warmup = max(
            0,
            _safe_int(SIGNAL_CONFIG.get("of_incremental_warmup_seconds"), SIGNAL_CONFIG.get("of_min_stream_age_seconds", 60)),
        )
        target_age = full_warmup if initial_warmup else incremental_warmup
        max_wait = max(0, _safe_int(SIGNAL_CONFIG.get("of_warmup_max_wait_seconds"), target_age))
        ready_ratio = min(1.0, max(0.0, _safe_float(SIGNAL_CONFIG.get("of_warmup_ready_ratio"), 0.6) or 0.6))
        min_ready = min(len(symbols), max(1, int(ceil(len(symbols) * ready_ratio))))

        started = time.time()
        if target_age > 0:
            self.logger.info(
                "OrderFlowManager warm-up: target_age=%ss, max_wait=%ss, symbols=%d, ready_ratio=%.2f",
                target_age,
                max_wait,
                len(symbols),
                ready_ratio,
            )
        while True:
            self.prune()
            summary = self.coverage_summary(symbols, required_stream_age_seconds=target_age)
            if summary.get("warm_count", 0) >= min_ready:
                self._ever_prepared = True
                summary["warmup_elapsed_seconds"] = round(time.time() - started, 2)
                summary["target_age_seconds"] = target_age
                return summary
            if max_wait <= 0 or (time.time() - started) >= max_wait:
                self._ever_prepared = True
                summary["warmup_elapsed_seconds"] = round(time.time() - started, 2)
                summary["target_age_seconds"] = target_age
                summary["warning"] = "warmup_timeout_some_symbols_not_ready"
                self.logger.warning(
                    "OrderFlowManager warm-up incomplete: warm=%d/%d after %.1fs; unready symbols fail closed",
                    summary.get("warm_count", 0),
                    len(symbols),
                    time.time() - started,
                )
                return summary
            await asyncio.sleep(float(SIGNAL_CONFIG.get("of_warmup_poll_seconds", 2.0) or 2.0))

    def coverage_summary(self, symbols, *, required_stream_age_seconds=None):
        rows = []
        warm_count = 0
        for symbol in symbols or []:
            coverage = self._coverage(self._norm(symbol), required_stream_age_seconds=required_stream_age_seconds)
            rows.append(coverage)
            # Warm should reflect ws_warm (stream warmed according to of_warmup_seconds), not combined ready
            if coverage.get("ws_warm"):
                warm_count += 1
        return {
            "enabled": True,
            "prepared": len(rows),
            "warm_count": warm_count,
            "not_ready_count": max(0, len(rows) - warm_count),
            "active_groups": self._active_group_count(),
            # Report symbols that are not ws_warm (not warmed) rather than legacy ready
            "sample_not_ready": [row.get("symbol") for row in rows if not row.get("ws_warm")][:10],
        }

    def record_reference_signal(self, native_symbol, signal):
        """Cache the latest Bitget-only reference decision (main thread only)."""
        try:
            with self._reference_signals_lock:
                self._reference_signals[str(native_symbol)] = {
                    "signal": signal,
                    "ts": time.time(),
                }
        except Exception:
            pass

    def get_reference_signals_snapshot(self):
        """Thread-safe shallow copy of the reference-decision cache."""
        try:
            with self._reference_signals_lock:
                return dict(self._reference_signals)
        except Exception:
            return {}

    def health_report(self, symbols=None, *, required_stream_age_seconds=None, persist=True):
        symbols = [self._norm(symbol) for symbol in (symbols or self.analyzers.keys())]
        symbols = [symbol for symbol in dict.fromkeys(symbols) if symbol]
        rows = [
            self._coverage(symbol, required_stream_age_seconds=required_stream_age_seconds)
            for symbol in symbols
        ]
        failure_counts = Counter()
        stale_trade_count = 0
        stale_book_count = 0
        latest_trade_ages = []
        latest_book_ages = []
        for row in rows:
            for reason in row.get("failures") or []:
                failure_counts[str(reason).split(":", 1)[0]] += 1
            trade_age = _safe_float(row.get("latest_trade_age_seconds"))
            book_age = _safe_float(row.get("latest_book_age_seconds"))
            if trade_age is not None:
                latest_trade_ages.append(trade_age)
                if trade_age > _safe_float(SIGNAL_CONFIG.get("of_max_data_staleness_seconds"), 45.0):
                    stale_trade_count += 1
            if book_age is not None:
                latest_book_ages.append(book_age)
                if book_age > _safe_float(SIGNAL_CONFIG.get("of_max_data_staleness_seconds"), 45.0):
                    stale_book_count += 1

        group_rows = []
        membership_counts = Counter()
        for group_id, group in sorted(self.groups.items(), key=lambda item: item[0]):
            task = group.get("task")
            live = self._group_alive(group)
            for symbol in (group.get("symbols") or []):
                if live:
                    membership_counts[symbol] += 1
            group_rows.append(
                {
                    "group_id": group_id,
                    "symbol_count": len(group.get("symbols") or []),
                    "connected": bool(group.get("connected")),
                    "task_done": bool(group.get("task_done")),
                    "task_cancelled": bool(task.cancelled()) if task is not None and task.done() else False,
                    "task_failed": bool(task.exception()) if task is not None and task.done() and not task.cancelled() else False,
                }
            )
        duplicate_assignments = sum(1 for count in membership_counts.values() if count > 1)

        payload = {
            "updated_at": _utc_now_iso(),
            "enabled": self._enabled(),
            "background_thread_enabled": bool(SIGNAL_CONFIG.get("enable_orderflow_background_thread", True)),
            "prepared": len(rows),
            "warm_count": sum(1 for row in rows if row.get("ws_warm")),
            "not_ready_count": sum(1 for row in rows if not row.get("ws_warm")),
            "subscribed_count": sum(1 for row in rows if row.get("ws_available")),
            "coverage_ok_count": sum(1 for row in rows if row.get("coverage_sufficient")),
            "active_groups": self._active_group_count(),
            "duplicate_symbol_assignments": duplicate_assignments,
            "book_channel": self._book_channel(),
            "focus_book_channel": self._focus_book_channel(),
            "focus_symbol_count": len(self._focus_symbols),
            "failure_counts": dict(sorted(failure_counts.items())),
            "stale_trade_count": stale_trade_count,
            "stale_book_count": stale_book_count,
            "avg_latest_trade_age_seconds": round(float(np.mean(latest_trade_ages)), 3) if latest_trade_ages else None,
            "avg_latest_book_age_seconds": round(float(np.mean(latest_book_ages)), 3) if latest_book_ages else None,
            "median_latest_trade_age_seconds": round(float(np.median(latest_trade_ages)), 3) if latest_trade_ages else None,
            "median_latest_book_age_seconds": round(float(np.median(latest_book_ages)), 3) if latest_book_ages else None,
            "sample_not_ready": [row.get("symbol") for row in rows if not row.get("ws_warm")][:20],
            "top_not_ready": [
                {
                    "symbol": row.get("symbol"),
                    "failures": row.get("failures") or [],
                    "trade_count": row.get("trade_count"),
                    "book_snapshot_count": row.get("book_snapshot_count"),
                    "latest_trade_age_seconds": row.get("latest_trade_age_seconds"),
                    "latest_book_age_seconds": row.get("latest_book_age_seconds"),
                }
                for row in rows
                if not row.get("ws_warm")
            ][:25],
            "groups": group_rows,
        }
        if persist:
            _save_json_file(_ORDERFLOW_HEALTH_FILE, payload)
        return payload

    def _coverage(self, symbol, *, lookback_seconds=None, event_lookback_seconds=None, required_stream_age_seconds=None):
        now_ms = int(time.time() * 1000)
        symbol = self._norm(symbol)
        analyzer = self.analyzers.get(symbol)
        meta = self.symbol_meta.get(symbol, {})
        lookback_s = max(1, _safe_int(lookback_seconds, SIGNAL_CONFIG.get("of_breakout_lookback_seconds", 180)))
        event_s = max(lookback_s, _safe_int(event_lookback_seconds, lookback_s))
        required_age = _safe_int(required_stream_age_seconds, SIGNAL_CONFIG.get("of_min_stream_age_seconds", 60))

        stream_start_ms = _safe_int(meta.get("stream_start_ms"), None)
        stream_age_s = (now_ms - stream_start_ms) / 1000.0 if stream_start_ms else 0.0
        trades = list(analyzer.trade_history) if analyzer is not None else []
        books = list(analyzer.book_history) if analyzer is not None else []
        trade_cutoff = now_ms - (lookback_s * 1000)
        event_cutoff = now_ms - (event_s * 1000)
        window_trades = [row for row in trades if _safe_int(row[0], 0) >= trade_cutoff]
        window_books = [row for row in books if _safe_int(row[0], 0) >= trade_cutoff]
        trade_notional = sum(float(row[1]) * float(row[2]) for row in window_trades)
        latest_trade_ms = max((_safe_int(row[0], 0) for row in trades), default=None)
        latest_book_ms = max((_safe_int(row[0], 0) for row in books), default=None)
        latest_trade_age_s = (now_ms - latest_trade_ms) / 1000.0 if latest_trade_ms else None
        latest_book_age_s = (now_ms - latest_book_ms) / 1000.0 if latest_book_ms else None

        max_data_age = float(SIGNAL_CONFIG.get("of_max_data_staleness_seconds", 10.0) or 10.0)
        min_trades = max(1, _safe_int(SIGNAL_CONFIG.get("of_min_trades_per_snapshot"), 8))
        min_notional = _safe_float(SIGNAL_CONFIG.get("of_min_trade_notional"), MIN_TRADE_VOLUME_THRESHOLD)
        min_books = max(MIN_SNAPSHOTS_REQUIRED, _safe_int(SIGNAL_CONFIG.get("of_min_book_snapshots"), MIN_SNAPSHOTS_REQUIRED))
        fail_closed_on_thin_tape = bool(SIGNAL_CONFIG.get("of_fail_closed_on_thin_tape", True))

        # Semantic separation of transport vs coverage failures
        ws_failures = []
        book_failures = []
        trade_failures = []

        # Transport / subscription state
        live_gid = self._bind_symbol_to_live_group(symbol)
        ws_available = (
            analyzer is not None
            and not meta.get("subscribe_error")
            and (live_gid is not None or bool(meta.get("subscribed")))
        )
        if not ws_available:
            ws_failures.append("symbol_not_subscribed")

        # Warmth (operating time on current stream)
        ws_warm = False
        if ws_available:
            if stream_age_s < required_age:
                ws_failures.append(f"stream_not_warm:{stream_age_s:.1f}s<{required_age}s")
            else:
                ws_warm = True

        # Coverage checks (do not conflate with transport availability)
        if fail_closed_on_thin_tape and len(window_trades) < min_trades:
            trade_failures.append(f"thin_tape_trades:{len(window_trades)}<{min_trades}")
        if fail_closed_on_thin_tape and trade_notional < min_notional:
            trade_failures.append(f"thin_tape_notional:{trade_notional:.2f}<{min_notional:.2f}")
        if len(window_books) < min_books:
            book_failures.append(f"book_coverage:{len(window_books)}<{min_books}")
        if latest_trade_age_s is None or latest_trade_age_s > max_data_age:
            trade_failures.append(
                f"stale_trade_stream:{latest_trade_age_s:.1f}s>{max_data_age:.1f}s"
                if latest_trade_age_s is not None else "missing_trade_stream"
            )
        if latest_book_age_s is None or latest_book_age_s > max_data_age:
            book_failures.append(
                f"stale_book_stream:{latest_book_age_s:.1f}s>{max_data_age:.1f}s"
                if latest_book_age_s is not None else "missing_book_stream"
            )

        gap_hits = []
        if bool(SIGNAL_CONFIG.get("of_fail_closed_on_gap", True)):
            for gap_start, gap_end in list(self.symbol_gaps.get(symbol, [])):
                if gap_end >= event_cutoff and gap_start <= now_ms:
                    gap_hits.append({"start_ms": gap_start, "end_ms": gap_end})
            if gap_hits:
                trade_failures.append("reconnect_gap_intersects_required_window")

        # Aggregate coverage result but keep transport semantics explicit
        coverage_failures = list(trade_failures) + list(book_failures)
        coverage_sufficient = not coverage_failures

        # For backward compatibility, keep 'ready' but do NOT treat it as transport availability in callers
        combined_failures = list(ws_failures) + coverage_failures

        coverage_payload = {
            "symbol": symbol,
            "ready": not combined_failures,
            "failures": combined_failures,

            "stream_age_seconds": round(float(stream_age_s), 3),
            "required_stream_age_seconds": int(required_age),
            "lookback_seconds": int(lookback_s),
            "event_lookback_seconds": int(event_s),

            "trade_count": len(window_trades),
            "trade_notional": round(float(trade_notional), 4),
            "book_snapshot_count": len(window_books),
            "latest_trade_age_seconds": round(float(latest_trade_age_s), 3) if latest_trade_age_s is not None else None,
            "latest_book_age_seconds": round(float(latest_book_age_s), 3) if latest_book_age_s is not None else None,

            "gap_hits": gap_hits,
            "group_id": meta.get("group_id"),
            "subscribed": bool(meta.get("subscribed")),

            # Explicit, separate semantic fields
            "ws_available": ws_available,
            "ws_warm": ws_warm,
            "book_available": latest_book_ms is not None,
            "book_fresh": (latest_book_ms is not None) and (latest_book_age_s is not None and latest_book_age_s <= max_data_age),
            "trade_available": latest_trade_ms is not None,
            "trade_fresh": (latest_trade_ms is not None) and (latest_trade_age_s is not None and latest_trade_age_s <= max_data_age),

            "coverage_sufficient": coverage_sufficient,
            "ws_failures": ws_failures,
            "book_failures": book_failures,
            "trade_failures": trade_failures,
            "basis": "bitget_only",
        }

        # ── Cross-exchange LIVE basis (fail-safe) ──────────────────────────
        # When the cross-exchange layer is running, warmness/coverage are
        # re-derived from the CONSOLIDATED multi-venue book+tape (Bitget +
        # Binance + OKX + Bybit). Any failure here leaves the venue-only
        # coverage payload untouched.
        try:
            coverage_payload = self._cx_augment_coverage(symbol, coverage_payload, lookback_s)
        except Exception:
            self.logger.exception("cross-exchange coverage augmentation failed (non-fatal)")

        return coverage_payload

    # ── Cross-exchange live integration hooks ─────────────────────────────
    def _cx_provider(self):
        """Lazily bind the cross-exchange live provider (fail-safe: returns
        None when the layer is unavailable, leaving the venue-only basis)."""
        provider = getattr(self, "cx_live_provider", None)
        if provider is not None:
            if provider.is_layer_running():
                return provider
            # Stale provider (e.g. the layer was restarted by the supervisor
            # after a loop stall) — drop the cache and re-bind below.
            self.cx_live_provider = None
        if not _CROSS_EXCHANGE_LIVE_AVAILABLE:
            return None
        try:
            provider = _cx_get_live_provider()
        except Exception:
            provider = None
        self.cx_live_provider = provider
        if provider is None or not provider.is_layer_running():
            return None
        return provider

    def _cx_augment_coverage(self, symbol, coverage, lookback_seconds):
        """Re-derive orderflow warm/coverage on the CONSOLIDATED multi-venue
        basis when the cross-exchange layer is running.

        Threshold semantics with the richer book:
          * absolute-USD thresholds (min trade notional, min trades per
            snapshot, consolidated coverage depth) are scaled by the number
            of venues currently CONTRIBUTING data (venue_scale, capped) so
            the richer book does not silently loosen the gates;
          * ratio/percentage thresholds are scale-invariant and untouched;
          * execution-venue (Bitget) transport/freshness failures still apply
            — stale venue streams still block, but single-venue thin-tape
            checks are superseded by the consolidated tape checks.
        """
        provider = self._cx_provider()
        if provider is None:
            return coverage
        cx = provider.get_live_consolidated(symbol, lookback_seconds=lookback_seconds)
        if not isinstance(cx, dict) or not cx.get("active"):
            # Surface WHY the consolidated basis was unavailable so the
            # Bitget-only fallback is visible in rejection reasons.
            if isinstance(cx, dict):
                try:
                    coverage["cx_inactive_reason"] = str(cx.get("reason") or "cx_unavailable")
                    if cx.get("venue_detail"):
                        coverage["cx_inactive_venue_detail"] = cx.get("venue_detail")
                except Exception:
                    pass
            return coverage

        venue_scale = max(1.0, float(cx.get("venue_scale") or 1.0))

        # Warm basis: execution-venue stream warm AND consolidated book warm.
        ws_warm = bool(coverage.get("ws_warm")) and bool(cx.get("warm"))

        # Consolidated tape checks with venue-scaled absolute thresholds.
        min_notional = _safe_float(SIGNAL_CONFIG.get("of_min_trade_notional"), 25.0) * venue_scale
        min_trades = max(1, _safe_int(SIGNAL_CONFIG.get("of_min_trades_per_snapshot"), 4) * int(round(venue_scale)))
        cx_notional = float(cx.get("buy_notional_usd") or 0.0) + float(cx.get("sell_notional_usd") or 0.0)
        cx_trades = int(cx.get("trade_count") or 0)

        cx_tape_failures = []
        if cx_trades < min_trades:
            cx_tape_failures.append(f"cx_thin_tape_trades:{cx_trades}<{min_trades}")
        if cx_notional < min_notional:
            cx_tape_failures.append(f"cx_thin_tape_notional:{cx_notional:.2f}<{min_notional:.2f}")

        cx_book_failures = []
        if not bool(cx.get("coverage")):
            cx_book_failures.append(str(cx.get("coverage_reason") or "cx_coverage_insufficient"))

        cx_ws_failures = []
        if not bool(cx.get("warm")):
            cx_ws_failures.append(str(cx.get("warm_reason") or "cx_book_not_warm"))

        # Venue transport/freshness failures carry over; venue thin-tape
        # entries are superseded by the consolidated tape checks above.
        prior_ws = [str(f) for f in (coverage.get("ws_failures") or [])]
        prior_trade = [str(f) for f in (coverage.get("trade_failures") or []) if not str(f).startswith("thin_tape")]
        prior_book = [str(f) for f in (coverage.get("book_failures") or [])]

        ws_failures = prior_ws + cx_ws_failures
        trade_failures = prior_trade + cx_tape_failures
        book_failures = prior_book + cx_book_failures
        coverage_failures = trade_failures + book_failures
        combined_failures = ws_failures + coverage_failures

        out = dict(coverage)
        out["basis"] = "consolidated"
        out["ws_warm"] = ws_warm
        out["ready"] = not combined_failures
        out["failures"] = combined_failures
        out["coverage_sufficient"] = not coverage_failures
        out["confirmation_eligible"] = not coverage_failures
        out["ws_failures"] = ws_failures
        out["trade_failures"] = trade_failures
        out["book_failures"] = book_failures
        out["cx_venue_scale"] = venue_scale
        out["cross_exchange"] = {
            "active": True,
            "contributing_venues": cx.get("contributing_venues"),
            "excluded_venues": cx.get("excluded_venues"),
            "venue_scale": venue_scale,
            "depth_usd": cx.get("depth_usd"),
            "bid_depth_usd": cx.get("bid_depth_usd"),
            "ask_depth_usd": cx.get("ask_depth_usd"),
            "imbalance": cx.get("imbalance"),
            "cvd_usd": cx.get("cvd_usd"),
            "aggression_ratio": cx.get("aggression_ratio"),
            "trade_count": cx.get("trade_count"),
            "warm": cx.get("warm"),
            "coverage": cx.get("coverage"),
            "confirmation": cx.get("confirmation"),
            "consolidated_signal": cx.get("consolidated_signal"),
        }
        return out

    def _cx_apply_consolidated_metrics(self, result, symbol, lookback_seconds):
        """Overlay the CONSOLIDATED multi-venue confirmation metrics (pressure,
        imbalance, window CVD, aggression) onto the snapshot payload so the
        entry gates operate on the rich book. Venue-local (Bitget) values are
        preserved under 'bitget_local' for telemetry."""
        # Record the PRE-overlay (Bitget-only) signal in the manager's
        # thread-safe reference cache — the cross-exchange layer reads this
        # cache instead of ever calling compute_metrics() cross-thread (v8).
        if isinstance(result, dict) and not result.get("error"):
            try:
                _mgr = get_orderflow_manager()
                if _mgr is not None:
                    _mgr.record_reference_signal(symbol, result.get("signal"))
            except Exception:
                pass
        provider = self._cx_provider()
        if provider is None or not isinstance(result, dict) or result.get("error"):
            return
        cx = provider.get_live_consolidated(symbol, lookback_seconds=lookback_seconds)
        if not isinstance(cx, dict) or not cx.get("active"):
            return

        local = {}
        for key in ("buy_pressure", "sell_pressure", "imbalance", "cvd",
                    "aggression_ratio", "total_trade_vol", "signal"):
            if key in result:
                local[key] = result[key]
        if local:
            result["bitget_local"] = local

        _contributing = cx.get("contributing_venues") or []
        result["orderflow_basis"] = (
            f"consolidated_{len(_contributing)}venues" if _contributing else "consolidated"
        )
        result["buy_pressure"] = float(cx.get("buy_pressure") or 50.0)
        result["sell_pressure"] = float(cx.get("sell_pressure") or 50.0)
        result["imbalance"] = float(cx.get("imbalance") or 0.0)
        # Window CVD across all contributing venues — same semantics as the
        # venue-local payload 'cvd' (NOT the engine's cumulative accumulator).
        result["cvd"] = float(cx.get("cvd_usd") or 0.0)
        result["aggression_ratio"] = float(cx.get("aggression_ratio") or 0.0)
        result["total_trade_vol"] = round(
            float(cx.get("buy_notional_usd") or 0.0) + float(cx.get("sell_notional_usd") or 0.0), 2
        )
        result["cx_venue_scale"] = max(1.0, float(cx.get("venue_scale") or 1.0))
        result["cross_exchange"] = {
            "active": True,
            "contributing_venues": cx.get("contributing_venues"),
            "excluded_venues": cx.get("excluded_venues"),
            "depth_usd": cx.get("depth_usd"),
            "bid_depth_usd": cx.get("bid_depth_usd"),
            "ask_depth_usd": cx.get("ask_depth_usd"),
            "imbalance": cx.get("imbalance"),
            "cvd_usd": cx.get("cvd_usd"),
            "aggression_ratio": cx.get("aggression_ratio"),
            "trade_count": cx.get("trade_count"),
            "warm": cx.get("warm"),
            "coverage": cx.get("coverage"),
            "confirmation": cx.get("confirmation"),
            "consolidated_signal": cx.get("consolidated_signal"),
            "venue_scale": cx.get("venue_scale"),
        }
        # The snapshot's internal OF signal follows the consolidated decision.
        # Fix signal & metrics consistency (F-5): if consolidated signal is None (unconfirmed),
        # do not retain Bitget-only signal with consolidated metrics.
        if cx.get("consolidated_signal") is not None:
            result["signal"] = cx["consolidated_signal"]
        elif cx.get("active") and cx.get("orderflow_basis") != "bitget_fallback":
            result["signal"] = None

        # ── Consolidated anomaly gate (v8.1) ────────────────────────────
        # With the consolidated book available, the anomaly rejections
        # (spoofing / icebergs / low activity) are re-derived from the
        # CONSOLIDATED anomaly detector — the same criteria, on the merged
        # multi-venue book. The Bitget-books5 verdict is preserved only as
        # telemetry under 'bitget_local'. If no consolidated history exists
        # yet (layer just started), the venue-only verdict stands.
        anomalies = cx.get("anomalies") if isinstance(cx.get("anomalies"), dict) else {}
        if anomalies:
            result["consolidated_anomalies"] = dict(anomalies)
            prev_reject = str(result.get("reject_reason") or "")
            cx_tag = f"[anomaly basis={result.get('orderflow_basis') or 'consolidated'}]"
            _c_spoofs = int(anomalies.get("spoofs") or 0)
            _c_total_icebergs = int(anomalies.get("icebergs") or 0)
            _c_direction = anomalies.get("iceberg_direction")
            _c_bid_ice = int(anomalies.get("bid_icebergs") or 0)
            _c_ask_ice = int(anomalies.get("ask_icebergs") or 0)
            _c_bid_usd = float(anomalies.get("bid_notional") or 0.0)
            _c_ask_usd = float(anomalies.get("ask_notional") or 0.0)
            _c_vol = float(result.get("total_trade_vol") or 0.0)
            _c_signal = result.get("signal")
            new_reject = None
            if _c_spoofs > HIGH_SPOOF_THRESHOLD:
                new_reject = f"High spoofing ({_c_spoofs} events) {cx_tag}"
            elif _c_total_icebergs > HIGH_ICEBERG_THRESHOLD:
                if _c_direction is None:
                    new_reject = (
                        f"High iceberg activity — mixed direction "
                        f"(bid={_c_bid_ice} events/${_c_bid_usd:.0f}, "
                        f"ask={_c_ask_ice} events/${_c_ask_usd:.0f}) {cx_tag}"
                    )
                elif _c_signal is not None and _c_direction != _c_signal:
                    new_reject = (
                        f"Iceberg direction opposes signal: "
                        f"whale {'buying' if _c_direction == 'BUY' else 'selling'} "
                        f"(${max(_c_bid_usd, _c_ask_usd):.0f} notional) vs {_c_signal} signal {cx_tag}"
                    )
            elif _c_vol < MIN_TRADE_VOLUME_THRESHOLD * 1.5:
                new_reject = f"Low trade activity ({_c_vol:.1f}) {cx_tag}"
            if new_reject:
                result["reject_reason"] = new_reject
            elif "anomaly basis=bitget_books5" in prev_reject:
                # Consolidated re-check PASSED — the venue-only anomaly
                # rejection is superseded by the consolidated verdict.
                result["reject_reason"] = None

    #put below 2d
    async def snapshot(self, symbol, *, trigger_type="breakout", lookback_seconds=None, event_lookback_seconds=None, key_levels=None):
        if not self._enabled():
            return None
        symbol = self._norm(symbol)
        # Symbols the signal layer actually reads get the incremental depth feed.
        self.mark_focus(symbol)
        trigger = str(trigger_type or "breakout").strip().lower()
        if lookback_seconds is None:
            lookback_seconds = SIGNAL_CONFIG.get("of_sweep_lookback_seconds", 180) if trigger == "sweep" else SIGNAL_CONFIG.get("of_breakout_lookback_seconds", 45)
        if event_lookback_seconds is None:
            event_lookback_seconds = SIGNAL_CONFIG.get("of_sweep_event_lookback_seconds", 300) if trigger == "sweep" else SIGNAL_CONFIG.get("of_breakout_event_lookback_seconds", 180)

        t0 = time.perf_counter()

        # ── Inflight dedup: reuse a running snapshot for this symbol+window.
        inflight_key = (symbol, trigger)
        existing = self._inflight.get(inflight_key)
        if existing is not None and not existing.done():
            return await asyncio.shield(existing)

        loop = asyncio.get_running_loop()
        fut = loop.create_future()
        self._inflight[inflight_key] = fut

        try:
            if self._bind_symbol_to_live_group(symbol) is None:
                await self.ensure_symbols([symbol])
            t1 = time.perf_counter()

            # NOTE: prune() is intentionally NOT called here. It runs periodically
            # in the orderflow maintenance worker.
            coverage = self._coverage(symbol, lookback_seconds=lookback_seconds, event_lookback_seconds=event_lookback_seconds)
            t2 = time.perf_counter()

            if not coverage.get("coverage_sufficient"):
                fail_reasons = []
                if coverage.get("trade_failures"):
                    fail_reasons.extend(coverage.get("trade_failures") or [])
                if coverage.get("book_failures"):
                    fail_reasons.extend(coverage.get("book_failures") or [])
                _basis = str(coverage.get("basis") or "bitget_only")
                reason = f"Continuous orderflow coverage insufficient [basis={_basis}]: " + "; ".join(fail_reasons or [])
                _cx_inactive = str(coverage.get("cx_inactive_reason") or "")
                if _cx_inactive:
                    reason += f" (cross-exchange inactive: {_cx_inactive})"
                """
                try:
                    self.logger.debug("OrderFlowManager snapshot coverage insufficient: symbol=%s coverage=%s", symbol, fail_reasons)
                except Exception:
                    pass
                """
                result = self._empty_payload(symbol, reason, lookback_seconds=lookback_seconds, event_lookback_seconds=event_lookback_seconds, coverage=coverage)
                if not fut.done():
                    fut.set_result(result)
                return result

            analyzer = self.analyzers.get(symbol)
            if analyzer is None:
                result = self._empty_payload(symbol, "Continuous orderflow analyzer missing", lookback_seconds=lookback_seconds, event_lookback_seconds=event_lookback_seconds, coverage=coverage)
                if not fut.done():
                    fut.set_result(result)
                return result

            # Clone buffers ON THE LOOP (serialized with handle_message -> no race),
            # then run heavy compute IN A THREAD over the private clone (non-blocking).
            ctx = analyzer._snapshot_clone(
                lookback_seconds=lookback_seconds,
                event_lookback_seconds=event_lookback_seconds,
            )
            result = await loop.run_in_executor(
                self._compute_executor,
                lambda: analyzer.compute_from_clone(ctx, key_levels=key_levels),
            )
            t3 = time.perf_counter()

            if not isinstance(result, dict):
                result = self._empty_payload(symbol, "Continuous orderflow snapshot returned no usable payload", lookback_seconds=lookback_seconds, event_lookback_seconds=event_lookback_seconds, coverage=coverage)
            elif result.get("error"):
                result = self._empty_payload(symbol, f"Continuous orderflow snapshot failed: {result.get('error')}", lookback_seconds=lookback_seconds, event_lookback_seconds=event_lookback_seconds, coverage=coverage)
            else:
                result = dict(result)
                result["live_orderflow_source"] = "live_ws_continuous"
                result["live_orderflow_window_seconds"] = int(lookback_seconds or 0)
                result["event_lookback_seconds"] = int(event_lookback_seconds or 0)
                result["coverage"] = coverage
                result["fail_closed"] = True
                result["websocket_orderflow_optional"] = False
                ws_diag = result.get("ws_diagnostics") if isinstance(result.get("ws_diagnostics"), dict) else {}
                ws_diag.update({"enabled": True, "status": "live_ws_continuous", "source": "live_ws_continuous", "coverage": coverage})
                result["ws_diagnostics"] = ws_diag

                # ── Cross-exchange LIVE confirmation basis (fail-safe) ────
                # Pressure / imbalance / CVD / aggression handed to the entry
                # gates become the CONSOLIDATED multi-venue values. Venue-local
                # Bitget values are preserved under result['bitget_local'].
                try:
                    if self._cx_provider() is not None:
                        self._cx_apply_consolidated_metrics(result, symbol, lookback_seconds)
                except Exception:
                    self.logger.exception("cross-exchange metric overlay failed (non-fatal)")

            # Timing instrumentation — log only slow snapshots.
            total = t3 - t0
            if total > 1.0:
                self.logger.info(
                    "[%s] snapshot slow: ensure=%.3f coverage=%.3f compute=%.3f total=%.3f",
                    symbol, t1 - t0, t2 - t1, t3 - t2, total,
                )

            if not fut.done():
                fut.set_result(result)
            return result
        except Exception as exc:
            if not fut.done():
                fut.set_exception(exc)
            raise
        finally:
            self._inflight.pop(inflight_key, None)

    #stop here
    def _reconcile_stale_subscription_state(self):
        now_ms = int(time.time() * 1000)
        try:
            disconnect_window = max(0.0, _safe_float(SIGNAL_CONFIG.get("of_disconnect_mark_unavailable_after_seconds"), 45.0) or 45.0)
        except Exception:
            disconnect_window = 45.0
        disconnect_deadline_ms = now_ms - int(max(0.0, disconnect_window) * 1000.0)

        for symbol, meta in list(self.symbol_meta.items()):
            if not isinstance(meta, dict):
                continue
            live_gid = self._bind_symbol_to_live_group(symbol)
            if live_gid is not None:
                group = self.groups.get(live_gid) or {}
                # Quiet tape is a coverage issue, not an unsubscribed socket.
                if group.get("connected") and not meta.get("subscribe_error"):
                    meta["subscribed"] = True
                    meta["group_id"] = live_gid
                continue
            last_book_ms = _safe_int(meta.get("last_book_ms"), None)
            last_trade_ms = _safe_int(meta.get("last_trade_ms"), None)
            last_message_ms = _safe_int(meta.get("last_message_ms"), None)
            last_disconnect_ms = _safe_int(meta.get("last_disconnect_ms"), None)
            last_seen_ms = max(
                [ts for ts in (last_book_ms, last_trade_ms, last_message_ms) if ts is not None] + [0],
                default=0,
            )
            disconnected = last_disconnect_ms is not None and last_disconnect_ms <= disconnect_deadline_ms
            if disconnected and last_seen_ms <= disconnect_deadline_ms:
                meta["subscribed"] = False
                gid = meta.get("group_id")
                if gid and not self._group_alive(self.groups.get(gid)):
                    self.groups.pop(gid, None)
                meta["group_id"] = None
                self.symbol_to_group.pop(symbol, None)

    def prune(self):
        self._expire_focus_symbols()
        self._dedupe_overlapping_groups()
        # Dead-group sweep (orphans that finished while symbols were still flagged)
        for gid, g in list(self.groups.items()):
            if g.get("task_done") or (g.get("task") is not None and g.get("task").done()):
                g["task_done"] = True
                g["connected"] = False
                for s in g.get("symbols", []):
                    if self.symbol_to_group.get(s) == gid:
                        self.symbol_to_group.pop(s, None)
                    meta = self.symbol_meta.get(s)
                    if isinstance(meta, dict) and meta.get("group_id") == gid:
                        meta["group_id"] = None
                        meta["subscribed"] = False
                self.groups.pop(gid, None)

        # Reap only groups whose socket itself is silent. Per-symbol quiet
        # markets must not cancel a live multiplexed connection.
        try:
            reap_s = max(30.0, _safe_float(SIGNAL_CONFIG.get("of_group_reap_seconds"), 120.0) or 120.0)
        except Exception:
            reap_s = 120.0
        reap_deadline_ms = int(time.time() * 1000) - int(reap_s * 1000)
        for gid, g in list(self.groups.items()):
            if not self._group_alive(g):
                continue
            created_ms = _safe_int(g.get("created_at_ms"), None)
            if created_ms is None or created_ms > reap_deadline_ms:
                continue
            last_recv_ms = _safe_int(g.get("last_recv_at_ms"), None)
            if last_recv_ms is not None and last_recv_ms >= reap_deadline_ms:
                continue
            if last_recv_ms is None and g.get("connected"):
                continue
            task = g.get("task")
            if task is not None and not task.done():
                task.cancel()
            g["task_done"] = True
            g["connected"] = False
            self.logger.warning(
                "OrderFlowManager group %s reaped after %.0fs without socket frames; slot freed",
                gid, reap_s,
            )

        self._reconcile_stale_subscription_state()

        now_ms = int(time.time() * 1000)
        trade_cutoff = now_ms - (max(1, _safe_int(SIGNAL_CONFIG.get("of_trade_retention_seconds"), 900)) * 1000)
        book_cutoff  = now_ms - (max(1, _safe_int(SIGNAL_CONFIG.get("of_book_retention_seconds"), 600)) * 1000)
        event_cutoff = now_ms - (max(1, _safe_int(SIGNAL_CONFIG.get("of_event_retention_seconds"), 900)) * 1000)

        for analyzer in list(self.analyzers.values()):
            analyzer.trade_history = deque(
                [row for row in list(analyzer.trade_history) if _safe_int(row[0], 0) >= trade_cutoff],
                maxlen=analyzer.trade_history.maxlen,
            )
            analyzer.book_history = deque(
                [row for row in list(analyzer.book_history) if _safe_int(row[0], 0) >= book_cutoff],
                maxlen=analyzer.book_history.maxlen,
            )
            analyzer.depth_history = deque(
                [row for row in list(analyzer.depth_history) if _safe_int(row[0], 0) >= book_cutoff],
                maxlen=analyzer.depth_history.maxlen,
            )
            for price in list(analyzer.level_events.keys()):
                events = [event for event in analyzer.level_events[price] if _safe_int(event[0], 0) >= event_cutoff]
                if events:
                    analyzer.level_events[price] = events
                else:
                    del analyzer.level_events[price]
            for price in list(analyzer.level_event_history.keys()):
                events = [event for event in analyzer.level_event_history[price] if _safe_int(event[0], 0) >= event_cutoff]
                if events:
                    analyzer.level_event_history[price] = events
                else:
                    del analyzer.level_event_history[price]
    #put below: 2e
    async def shutdown(self):
        for group in list(self.groups.values()):
            task = group.get("task")
            if task and not task.done():
                task.cancel()
        self._inflight.clear()
        try:
            self._compute_executor.shutdown(wait=False, cancel_futures=True)
        except Exception:
            pass
        await asyncio.sleep(0)
    #stop here
    async def _connection_loop(self, group_id, symbols, book_channel=None):
        symbols = [self._norm(symbol) for symbol in symbols if self._norm(symbol)]
        book_channel = book_channel or self._book_channel()
        reconnect_attempt = 0
        while True:
            group = self.groups.get(group_id)
            if group is not None:
                live_symbols = [self._norm(s) for s in (group.get("symbols") or symbols) if self._norm(s)]
                if live_symbols:
                    symbols = live_symbols
            if not symbols:
                break
            ws = None
            reconnect_attempt += 1
            connected_at_ms = int(time.time() * 1000)
            try:
                ws = await websockets.connect(
                    WS_URL,
                    ping_interval=None,
                    ping_timeout=None,
                    open_timeout=float(SIGNAL_CONFIG.get('websocket_open_timeout_seconds', 10.0) or 10.0),
                    close_timeout=float(SIGNAL_CONFIG.get('websocket_open_timeout_seconds', 10.0) or 10.0),
                )
                group = self.groups.setdefault(
                    group_id,
                    {"symbols": set(symbols), "task_done": False, "book_channel": book_channel},
                )
                group["connected"] = True
                group["last_recv_at_ms"] = connected_at_ms
                group["released"] = set()
                group["book_channel"] = book_channel
                # Exposed so late joiners can be subscribed onto this socket
                # instead of burning a whole new connection each.
                group["ws"] = ws
                for symbol in symbols:
                    meta = self.symbol_meta.setdefault(symbol, {})
                    if not meta.get("stream_start_ms"):
                        meta["stream_start_ms"] = connected_at_ms
                    meta["last_connect_ms"] = connected_at_ms
                    meta["subscribed"] = True
                    meta["subscribe_error"] = None
                    self.symbol_to_group[symbol] = group_id
                    meta["group_id"] = group_id
                await self._subscribe_group(ws, symbols, book_channel=book_channel)
                group["subscribed_at_ms"] = int(time.time() * 1000)
                self.logger.info(
                    "OrderFlowManager group %s subscribed %d symbols (%s channel)",
                    group_id,
                    len(symbols),
                    book_channel,
                )
                reconnect_attempt = 0
                ping_interval_s = max(
                    5.0,
                    _safe_float(SIGNAL_CONFIG.get("of_ws_ping_interval_seconds"), 20.0) or 20.0,
                )
                recv_poll_s = max(
                    0.5,
                    _safe_float(SIGNAL_CONFIG.get("of_ws_recv_poll_seconds"), 1.0) or 1.0,
                )
                stale_reconnect_s = max(
                    5.0,
                    _safe_float(SIGNAL_CONFIG.get("of_ws_stale_reconnect_seconds"), 30.0) or 30.0,
                )
                last_recv_at = time.time()
                next_ping_at = time.time() + ping_interval_s
                while True:
                    if time.time() >= next_ping_at:
                        try:
                            await ws.send("ping")
                        except Exception:
                            raise RuntimeError(f"group {group_id} ping send failed")
                        next_ping_at = time.time() + ping_interval_s
                    try:
                        msg = await asyncio.wait_for(
                            ws.recv(),
                            timeout=recv_poll_s,
                        )
                    except asyncio.TimeoutError:
                        if (time.time() - last_recv_at) >= stale_reconnect_s:
                            raise RuntimeError(
                                f"group {group_id} stale: no frames in {time.time() - last_recv_at:.1f}s; reconnecting"
                            )
                        continue
                    last_recv_at = time.time()
                    group = self.groups.get(group_id)
                    if group is not None:
                        group["last_recv_at_ms"] = int(last_recv_at * 1000)
                        group["connected"] = True
                    if msg == "ping":
                        try:
                            await ws.send("pong")
                        except Exception:
                            pass
                        continue
                    if msg == "pong":
                        continue
                    try:
                        payload = json.loads(msg)
                    except Exception:
                        continue
                    if not isinstance(payload, dict):
                        continue

                    evt = payload.get("event")
                    if evt == "subscribe":
                        s_arg = payload.get("arg") or {}
                        self.logger.debug(
                            "OrderFlowManager group %s subscribe ack: channel=%s instId=%s",
                            group_id, s_arg.get("channel"), s_arg.get("instId"),
                        )
                        s_sym = self._norm(s_arg.get("instId"))
                        if s_sym:
                            s_meta = self.symbol_meta.setdefault(s_sym, {})
                            s_meta["subscribe_acked"] = True
                            s_meta["subscribed"] = True
                            s_meta["subscribe_error"] = None
                        continue
                    if evt == "error":
                        code = payload.get("code")
                        err_text = payload.get("msg") or payload.get("message") or ""
                        self.logger.warning(
                            "OrderFlowManager group %s subscribe REJECTED by exchange: code=%s msg=%s",
                            group_id, code, err_text,
                        )
                        err_arg = payload.get("arg") or {}
                        err_sym = self._norm(err_arg.get("instId"))
                        if not err_sym:
                            import re as _re
                            m = _re.search(r"([A-Z0-9]{2,20}USDT)", str(err_text))
                            if m:
                                err_sym = m.group(1)
                        if err_sym:
                            e_meta = self.symbol_meta.setdefault(err_sym, {})
                            e_meta["subscribe_error"] = f"code={code} msg={err_text}"
                            e_meta["subscribed"] = False
                        continue

                    arg = payload.get("arg") or {}
                    symbol = self._norm(arg.get("instId"))
                    channel = str(arg.get("channel") or "")
                    # A symbol owned by another group would be ingested twice
                    # into the shared analyzer, double-counting trades and
                    # replaying book deltas. Drop it from this socket instead.
                    group = self.groups.get(group_id) or {}
                    if symbol and (
                        self.symbol_to_group.get(symbol, group_id) != group_id
                        or symbol in (group.get("pending_release") or ())
                    ):
                        await self._release_symbol(ws, group_id, symbol)
                        continue
                    analyzer = self.analyzers.get(symbol)
                    if not analyzer:
                        continue
                    await analyzer.handle_message(payload)
                    now_ms = int(time.time() * 1000)
                    meta = self.symbol_meta.setdefault(symbol, {})
                    meta["last_message_ms"] = now_ms
                    meta["subscribed"] = True
                    meta["subscribe_error"] = None
                    if channel == "trade":
                        meta["last_trade_ms"] = now_ms
                    elif channel in {"books", "books1", "books5", "books15"}:
                        meta["last_book_ms"] = now_ms
                    if analyzer.needs_resync:
                        analyzer.needs_resync = False
                        analyzer.reset_live_book_state("checksum_or_sequence_resync")
                        self.logger.warning(
                            "OrderFlowManager resyncing %s on group %s without dropping sibling symbols",
                            symbol, group_id,
                        )
                        await self._resync_symbol(ws, group_id, symbol)
            except asyncio.CancelledError:
                break
            except Exception as exc:
                self.logger.warning(
                    "OrderFlowManager group %s reconnecting after WS error: %s",
                    group_id,
                    exc,
                )
                group = self.groups.get(group_id)
                if group is not None:
                    group["connected"] = False
                self._record_gap_for_symbols(symbols)
                for symbol in symbols:
                    meta = self.symbol_meta.setdefault(symbol, {})
                    meta["last_disconnect_ms"] = int(time.time() * 1000)
                await asyncio.sleep(min(30.0, 2.0 * reconnect_attempt))
            finally:
                if ws is not None:
                    try:
                        await ws.close()
                    except Exception:
                        pass
                group = self.groups.get(group_id)
                if group is not None:
                    group["connected"] = False
                    group["ws"] = None
                    group["subscribed_at_ms"] = None
                for symbol in symbols:
                    meta = self.symbol_meta.setdefault(symbol, {})
                    if not meta.get("subscribed"):
                        meta["last_disconnect_ms"] = int(time.time() * 1000)
        group = self.groups.get(group_id)
        if group is not None:
            group["task_done"] = True
            group["connected"] = False

    async def _attach_to_existing_groups(self, symbols, now_ms):
        """
        Subscribe symbols onto live sockets that already carry their depth
        channel and still have room.

        Without this, promoting symbols to the focus tier one at a time opens
        one connection per symbol and exhausts `of_max_connections`.
        """
        attached = set()
        for symbol in symbols:
            channel = self.desired_book_channel(symbol)
            capacity = self._symbols_per_connection(channel)
            for gid, group in self.groups.items():
                if not self._group_alive(group) or self._group_book_channel(group) != channel:
                    continue
                ws = group.get("ws")
                # A group that has not sent its subscribe yet picks the symbol
                # up when it connects; otherwise subscribe on the live socket.
                pre_connect = ws is None and not group.get("subscribed_at_ms")
                if ws is None and not pre_connect:
                    continue
                current = group.setdefault("symbols", set())
                if len(current) >= capacity:
                    continue
                if ws is not None:
                    try:
                        await self._subscribe_group(ws, [symbol], book_channel=channel)
                    except Exception as exc:
                        self.logger.warning(
                            "OrderFlowManager could not attach %s to group %s: %s", symbol, gid, exc
                        )
                        continue
                current.add(symbol)
                (group.get("pending_release") or set()).discard(symbol)
                (group.get("released") or set()).discard(symbol)
                self.symbol_to_group[symbol] = gid
                meta = self.symbol_meta.setdefault(symbol, {})
                meta["group_id"] = gid
                meta["subscription_requested_ms"] = now_ms
                meta["subscribed"] = True
                meta["subscribe_error"] = None
                if not meta.get("stream_start_ms"):
                    meta["stream_start_ms"] = now_ms
                attached.add(symbol)
                self.logger.info(
                    "OrderFlowManager attached %s to existing group %s (%s channel, %d/%d symbols)",
                    symbol, gid, channel, len(current), capacity,
                )
                break
        return attached

    def _symbol_args(self, symbol, book_channel, *, book_only=False):
        args = [] if book_only else [{"instType": "USDT-FUTURES", "channel": "trade", "instId": symbol}]
        if bool(SIGNAL_CONFIG.get("of_subscribe_book_channel", True)):
            args.append({"instType": "USDT-FUTURES", "channel": book_channel, "instId": symbol})
        return args

    async def _resync_symbol(self, ws, group_id, symbol):
        """
        Force the exchange to resend a depth snapshot for one symbol.

        Re-sending `subscribe` for a channel that is already subscribed is a
        no-op, so the book would stay broken after a sequence gap. Unsubscribe
        first, then resubscribe; sibling symbols on the socket are untouched.
        """
        group = self.groups.get(group_id) or {}
        book_channel = self._group_book_channel(group)
        args = self._symbol_args(symbol, book_channel, book_only=True)
        if not args:
            return
        try:
            await ws.send(json.dumps({"op": "unsubscribe", "args": args}))
            await asyncio.sleep(1.0 / max(1.0, _safe_float(SIGNAL_CONFIG.get("of_subscribe_messages_per_second"), 5.0) or 5.0))
            await ws.send(json.dumps({"op": "subscribe", "args": args}))
        except Exception as exc:
            self.logger.warning(
                "OrderFlowManager group %s failed to resync %s: %s", group_id, symbol, exc,
            )

    async def _release_symbol(self, ws, group_id, symbol):
        """Unsubscribe a symbol this group no longer owns, keeping the socket alive."""
        group = self.groups.setdefault(group_id, {"symbols": set(), "task_done": False})
        released = group.setdefault("released", set())
        group.get("symbols", set()).discard(symbol)
        group.get("pending_release", set()).discard(symbol)
        if symbol in released:
            return
        released.add(symbol)
        args = self._symbol_args(symbol, self._group_book_channel(group))
        try:
            await ws.send(json.dumps({"op": "unsubscribe", "args": args}))
        except Exception as exc:
            self.logger.warning(
                "OrderFlowManager group %s failed to unsubscribe duplicate %s: %s",
                group_id, symbol, exc,
            )
            return
        self.logger.info(
            "OrderFlowManager group %s released duplicate subscription for %s",
            group_id, symbol,
        )

    async def _subscribe_group(self, ws, symbols, book_channel=None):
        include_books = bool(SIGNAL_CONFIG.get("of_subscribe_book_channel", True))
        book_channel = book_channel or self._book_channel()
        max_payload_bytes = max(512, _safe_int(SIGNAL_CONFIG.get("of_subscribe_payload_max_bytes"), 3800))
        max_messages_per_second = max(1.0, _safe_float(SIGNAL_CONFIG.get("of_subscribe_messages_per_second"), 5.0) or 5.0)
        min_delay = 1.0 / max_messages_per_second
        current = []

        async def flush():
            nonlocal current
            if not current:
                return
            await ws.send(json.dumps({"op": "subscribe", "args": current}))
            current = []
            await asyncio.sleep(min_delay)

        for symbol in symbols:
            args = [{"instType": "USDT-FUTURES", "channel": "trade", "instId": symbol}]
            if include_books:
                args.append({"instType": "USDT-FUTURES", "channel": book_channel, "instId": symbol})
            for arg in args:
                tentative = current + [arg]
                payload_size = len(json.dumps({"op": "subscribe", "args": tentative}))
                if payload_size > max_payload_bytes or len(tentative) > 40:
                    await flush()
                current.append(arg)
        await flush()

    def _record_gap_for_symbols(self, symbols):
        now_ms = int(time.time() * 1000)
        for symbol in symbols:
            meta = self.symbol_meta.get(symbol, {})
            last_msg = _safe_int(meta.get("last_message_ms"), None)
            if last_msg is not None and now_ms > last_msg:
                self.symbol_gaps[symbol].append((last_msg, now_ms))
            meta["last_disconnect_ms"] = now_ms
            meta["connection_lost_ms"] = now_ms


_ORDERFLOW_MANAGER = None
_ORDERFLOW_BACKGROUND_LOOP = None
_ORDERFLOW_BACKGROUND_THREAD = None #put below a
_ORDERFLOW_MAINTENANCE = None   # <-- ADD THIS LINE
_ORDERFLOW_BACKGROUND_READY = threading.Event()
_ORDERFLOW_BACKGROUND_LOCK = threading.Lock()


def get_orderflow_manager():
    global _ORDERFLOW_MANAGER
    if _ORDERFLOW_MANAGER is None:
        _ORDERFLOW_MANAGER = OrderFlowManager()
    return _ORDERFLOW_MANAGER


def _orderflow_background_enabled():
    return bool(SIGNAL_CONFIG.get("enable_orderflow_background_thread", True))


def _orderflow_background_thread_main(loop):
    asyncio.set_event_loop(loop)
    _ORDERFLOW_BACKGROUND_READY.set()
    loop.run_forever()

#put below: 2h
def start_orderflow_background_manager():
    global _ORDERFLOW_BACKGROUND_LOOP, _ORDERFLOW_BACKGROUND_THREAD, _ORDERFLOW_MAINTENANCE
    if not _orderflow_background_enabled():
        return {"enabled": False, "reason": "orderflow background thread disabled"}
    manager = get_orderflow_manager()
    if not manager._enabled():
        return {"enabled": False, "reason": "continuous orderflow manager disabled"}
    with _ORDERFLOW_BACKGROUND_LOCK:
        if (
            _ORDERFLOW_BACKGROUND_LOOP is not None
            and _ORDERFLOW_BACKGROUND_THREAD is not None
            and _ORDERFLOW_BACKGROUND_THREAD.is_alive()
        ):
            return {"enabled": True, "already_running": True}
        _ORDERFLOW_BACKGROUND_READY.clear()
        _ORDERFLOW_BACKGROUND_LOOP = asyncio.new_event_loop()
        _ORDERFLOW_BACKGROUND_THREAD = threading.Thread(
            target=_orderflow_background_thread_main,
            args=(_ORDERFLOW_BACKGROUND_LOOP,),
            name="OrderFlowManagerLoop",
            daemon=True,
        )
        _ORDERFLOW_BACKGROUND_THREAD.start()
    if not _ORDERFLOW_BACKGROUND_READY.wait(timeout=5.0):
        return {"enabled": False, "reason": "orderflow background loop did not start"}

    # Start the continuously-refreshed snapshot cache + periodic prune worker.
    if _ORDERFLOW_MAINTENANCE is None:
        try:
            from orderflow_maintenance import start_orderflow_maintenance
            _ORDERFLOW_MAINTENANCE = start_orderflow_maintenance(
                manager,
                loop=_ORDERFLOW_BACKGROUND_LOOP,
                snapshot_interval=_safe_float(SIGNAL_CONFIG.get("of_snapshot_refresh_interval_seconds"), 1.0) or 1.0,
                prune_interval=_safe_float(SIGNAL_CONFIG.get("of_prune_interval_seconds"), 30.0) or 30.0,
                worker_threads=_safe_int(SIGNAL_CONFIG.get("of_snapshot_worker_threads"), 4) or 4,
            )
        except Exception as exc:
            logger.warning(f"OrderFlow maintenance could not start: {exc}")
    return {"enabled": True, "started": True}
