#put below 2g
def _run_orderflow_background(factory, *, timeout=None, raise_on_timeout=False):
    """
    Run factory() on the OrderFlow background loop.
    factory may return a plain value (dict) or a coroutine.

    On timeout we do NOT cancel the running coroutine: it may be inside
    synchronous CPU work that cannot respond to cancellation, and cancelling
    would leave an orphan hogging the loop. The inflight dedup in snapshot()
    ensures the running job's result is reused by the next request.
    """
    state = start_orderflow_background_manager()
    if not state.get("enabled"):
        if raise_on_timeout:
            raise RuntimeError(state.get("reason", "orderflow background disabled"))
        return state
    loop = _ORDERFLOW_BACKGROUND_LOOP
    if loop is None or not loop.is_running():
        if raise_on_timeout:
            raise RuntimeError("orderflow background loop unavailable")
        return {"enabled": False, "reason": "orderflow background loop unavailable"}

    async def _runner():
        result = factory()
        if asyncio.iscoroutine(result):
            return await result
        return result

    future = asyncio.run_coroutine_threadsafe(_runner(), loop)
    try:
        return future.result(timeout=timeout)
    except FutureTimeoutError:
        # Let the job finish in the background; do not cancel it.
        if raise_on_timeout:
            raise asyncio.TimeoutError("orderflow background command timed out")
        return {"enabled": False, "reason": "orderflow background command timed out"}
    except Exception as exc:
        if raise_on_timeout:
            raise
        return {"enabled": False, "reason": f"orderflow background command failed: {exc}"}
