async def get_orderflow_snapshot(symbol, *, trigger_type="breakout", lookback_seconds=None, event_lookback_seconds=None, key_levels=None):
    symbol = _normalize_bitget_symbol(symbol)

    # 1) Read the continuously-refreshed cache first — no wait on the WS manager.
    try:
        from orderflow_maintenance import get_cached_snapshot
        cached = get_cached_snapshot(symbol, trigger_type)
        max_age = _safe_float(SIGNAL_CONFIG.get("of_snapshot_cache_max_age_seconds"), 2.0) or 2.0
        if cached and (time.time() - cached.get("ts", 0)) <= max_age:
            snap = cached.get("snapshot")
            if isinstance(snap, dict) and not snap.get("error"):
                return snap
    except Exception:
        pass

    if _orderflow_background_enabled():
        timeout = _safe_float(SIGNAL_CONFIG.get("of_snapshot_timeout_seconds"), 5.0) or 5.0
        try:
            return await asyncio.to_thread(
                _run_orderflow_background,
                lambda: get_orderflow_manager().snapshot(
                    symbol,
                    trigger_type=trigger_type,
                    lookback_seconds=lookback_seconds,
                    event_lookback_seconds=event_lookback_seconds,
                    key_levels=key_levels,
                ),
                timeout=timeout,
                raise_on_timeout=True,
            )
        except Exception:
            # Timeout / failure: a slow snapshot must NOT read as "source unknown /
            # books unavailable". Reuse a stale-but-valid cache if present, else
            # return a source-preserving payload and skip confirmation this cycle.
            try:
                cached = get_cached_snapshot(symbol, trigger_type)
                if cached and cached.get("snapshot") and not cached["snapshot"].get("error"):
                    return cached["snapshot"]
            except Exception:
                pass
            return get_orderflow_manager()._empty_payload(
                symbol,
                "snapshot compute timed out; confirmation skipped this cycle",
                lookback_seconds=lookback_seconds or 0,
                event_lookback_seconds=event_lookback_seconds or 0,
                coverage={"ws_available": True, "ws_warm": True, "coverage_sufficient": False, "timeout": True},
            )

    return await get_orderflow_manager().snapshot(
        symbol,
        trigger_type=trigger_type,
        lookback_seconds=lookback_seconds,
        event_lookback_seconds=event_lookback_seconds,
        key_levels=key_levels,
    )
