#put below: 2j
async def shutdown_orderflow_manager():
    global _ORDERFLOW_BACKGROUND_LOOP, _ORDERFLOW_BACKGROUND_THREAD, _ORDERFLOW_MAINTENANCE
    if _orderflow_background_enabled() and _ORDERFLOW_BACKGROUND_LOOP is not None:
        loop = _ORDERFLOW_BACKGROUND_LOOP
        thread = _ORDERFLOW_BACKGROUND_THREAD
        if _ORDERFLOW_MAINTENANCE is not None:
            try:
                _ORDERFLOW_MAINTENANCE.stop()
            except Exception:
                pass
            _ORDERFLOW_MAINTENANCE = None
        timeout = _safe_float(SIGNAL_CONFIG.get("of_background_command_timeout_seconds"), 15.0) or 15.0
        try:
            future = asyncio.run_coroutine_threadsafe(get_orderflow_manager().shutdown(), loop)
            await asyncio.to_thread(future.result, timeout=timeout)
        except Exception as exc:
            logger.warning(f"Orderflow background shutdown warning: {exc}")
        try:
            loop.call_soon_threadsafe(loop.stop)
        except Exception:
            pass
        if thread is not None:
            await asyncio.to_thread(thread.join, timeout=5.0)
        try:
            loop.close()
        except Exception:
            pass
        _ORDERFLOW_BACKGROUND_LOOP = None
        _ORDERFLOW_BACKGROUND_THREAD = None
        return
    await get_orderflow_manager().shutdown()
