def _normalize_bitget_base_url(base_url=None):
    base = str(base_url or os.getenv("BITGET_API_URL", "https://api.bitget.com")).strip().rstrip("/")
    for suffix in ("/api/v2/mix", "/api/v1/mix"):
        if base.endswith(suffix):
            base = base[: -len(suffix)]
            break
    return base.rstrip("/")


def _sync_bitget_time_offset(base_url=None, *, force=False):
    global _BITGET_TIME_OFFSET_MS, _BITGET_TIME_SYNCED_AT
    now = time.time()
    if not force and _BITGET_TIME_SYNCED_AT and (now - _BITGET_TIME_SYNCED_AT) < _BITGET_TIME_SYNC_TTL_S:
        return _BITGET_TIME_OFFSET_MS
    base = _normalize_bitget_base_url(base_url)
    server_time = None
    try:
        response, payload = _public_get_json_with_retry(
            f"{base}/api/v2/public/time",
            timeout_key='public_api_timeout_seconds',
            default_timeout=5.0,
        )
        if response is not None and response.status_code == 200 and isinstance(payload, dict) and str(payload.get("code")) == "00000":
            server_time = _safe_int(((payload.get("data") or {}).get("serverTime")), None)
    except Exception as exc:
        logger.warning(f"Bitget time sync failed: {exc}")
    if server_time is not None:
        local_ms = int(time.time() * 1000)
        _BITGET_TIME_OFFSET_MS = int(server_time - local_ms)
        _BITGET_TIME_SYNCED_AT = now
    return _BITGET_TIME_OFFSET_MS


def _get_bitget_timestamp_ms(base_url=None, *, force_sync=False):
    offset = _sync_bitget_time_offset(base_url=base_url, force=force_sync)
    return int(time.time() * 1000) + int(offset or 0)


def make_signed_request(method, endpoint, params=None, body=None):
    timeout_s = _request_timeout_value('signed_api_timeout_seconds', 10.0)
    retry_attempts = _api_retry_attempts()
    backoff_s = _api_retry_backoff_seconds()
    try:
        api_key = os.getenv("BITGET_API_KEY")
        secret_key = os.getenv("BITGET_SECRET_KEY")
        passphrase = os.getenv("BITGET_PASSPHRASE")
        base_url = _normalize_bitget_base_url(os.getenv("BITGET_API_URL", "https://api.bitget.com"))
        if not all([api_key, secret_key, passphrase]):
            logger.error("Missing API credentials in .env file")
            return None
        normalized_params = None
        if params:
            if isinstance(params, dict):
                normalized_params = sorted(params.items())
            else:
                normalized_params = params
        timestamp = str(_get_bitget_timestamp_ms(base_url))
        query_string = urlencode(normalized_params, doseq=True) if normalized_params else ""
        body_str = json.dumps(body, separators=(",", ":"), ensure_ascii=False) if body else ""
        request_path = endpoint
        if query_string:
            request_path = f"{endpoint}?{query_string}"
        sign_string = f"{timestamp}{method.upper()}{request_path}{body_str}"
        sign = base64.b64encode(
            hmac.new(secret_key.encode('utf-8'), sign_string.encode('utf-8'), hashlib.sha256).digest()
        ).decode('utf-8')
        headers = {
            "ACCESS-KEY": api_key,
            "ACCESS-SIGN": sign,
            "ACCESS-TIMESTAMP": timestamp,
            "ACCESS-PASSPHRASE": passphrase,
            "Content-Type": "application/json",
            "locale": "en-US"
        }
        url = f"{base_url}{request_path}"
        if method.upper() not in {"GET", "POST"}:
            logger.error(f"Unsupported HTTP method: {method}")
            return None

        last_payload = None
        for attempt_number in range(1, retry_attempts + 1):
            response = None
            if method.upper() == "GET":
                request_call = lambda: requests.get(url, headers=headers, timeout=timeout_s)
            else:
                request_call = lambda: requests.post(url, headers=headers, data=body_str or None, timeout=timeout_s)

            try:
                response = request_call()
                response_data = response.json()
                if response_data.get('code') == "40008":
                    timestamp = str(_get_bitget_timestamp_ms(base_url, force_sync=True))
                    sign_string = f"{timestamp}{method.upper()}{request_path}{body_str}"
                    headers["ACCESS-SIGN"] = base64.b64encode(
                        hmac.new(secret_key.encode('utf-8'), sign_string.encode('utf-8'), hashlib.sha256).digest()
                    ).decode('utf-8')
                    headers["ACCESS-TIMESTAMP"] = timestamp
                    response = request_call()
                    response_data = response.json()

                if response.status_code == 200 and response_data.get('code') == "00000":
                    return response_data

                last_payload = response_data
                if response.status_code >= 500 and attempt_number < retry_attempts:
                    logger.warning(
                        f"Signed API server error [{method.upper()} {request_path}] "
                        f"(attempt {attempt_number}/{retry_attempts}); retrying."
                    )
                    _sleep_api_retry_backoff(backoff_s, attempt_number)
                    continue

                logger.error(f"API request failed [{method.upper()} {request_path}]: {response_data}")
                return response_data
            except requests.exceptions.Timeout as e:
                logger.warning(
                    f"Signed API request timeout [{method.upper()} {request_path}] "
                    f"(attempt {attempt_number}/{retry_attempts}): {e}"
                )
            except requests.exceptions.ConnectionError as e:
                logger.warning(
                    f"Signed API connection error [{method.upper()} {request_path}] "
                    f"(attempt {attempt_number}/{retry_attempts}): {e}"
                )
            except requests.exceptions.RequestException as e:
                logger.warning(
                    f"Signed API request error [{method.upper()} {request_path}] "
                    f"(attempt {attempt_number}/{retry_attempts}): {e}"
                )
            if attempt_number < retry_attempts:
                _sleep_api_retry_backoff(backoff_s, attempt_number)
        return last_payload
    except Exception as e:
        logger.error(f"Error in make_signed_request: {str(e)}")
        return None

def make_post_request(request_path, body):
    return make_signed_request('POST', request_path, body=body)

def make_get_request(request_path, params=None):
    return make_signed_request('GET', request_path, params=params)

def clear_symbol_config_cache():
    global SYMBOL_CONFIG_CACHE
    SYMBOL_CONFIG_CACHE = {}
    logger.info("Cleared symbol config cache")

def get_symbol_config(symbol):
    global SYMBOL_CONFIG_CACHE
    if symbol in SYMBOL_CONFIG_CACHE:
        return SYMBOL_CONFIG_CACHE[symbol]
    try:
        params = {'symbol': symbol, 'productType': 'USDT-FUTURES'}
        resp = make_get_request('/api/v2/mix/market/contracts', params=params)
        if resp and resp.get('code') == "00000":
            contract = resp.get('data', [{}])[0]
            config = {
                'price_place': int(contract.get('pricePlace', 4)),
                'volume_place': int(contract.get('volumePlace', 3)),
                'min_trade_num': float(contract.get('minTradeNum', 0.001)),
                'size_multiplier': float(contract.get('sizeMultiplier', 0.001)),
                'min_trade_usdt': _safe_float(
                    contract.get('minTradeUSDT')
                    or contract.get('minTradeUsdt')
                    or contract.get('minTradeValue')
                    or contract.get('minOrderValue'),
                    0.0,
                ) or 0.0,
            }
            SYMBOL_CONFIG_CACHE[symbol] = config
            return config
        logger.error(f"Failed to fetch symbol config for {symbol}: {resp}")
        return {'price_place': 4, 'volume_place': 3, 'min_trade_num': 0.001, 'size_multiplier': 0.001, 'min_trade_usdt': 0.0}
    except Exception as e:
        logger.error(f"Error fetching symbol config for {symbol}: {str(e)}")
        return {'price_place': 4, 'volume_place': 3, 'min_trade_num': 0.001, 'size_multiplier': 0.001, 'min_trade_usdt': 0.0}


def _ceil_to_step(value, step, precision):
    value = _safe_float(value, 0.0) or 0.0
    step = _safe_float(step, 0.0) or 0.0
    if step <= 0:
        return round(value, int(precision or 0))
    return round(ceil(value / step) * step, int(precision or 0))


def _estimate_exchange_min_trade_value(symbol_config, entry_price):
    symbol_config = symbol_config or {}
    entry = _safe_float(entry_price, 0.0) or 0.0
    if entry <= 0:
        return 0.0, 0.0
    volume_place = _safe_int(symbol_config.get('volume_place'), 3)
    min_trade_num = _safe_float(symbol_config.get('min_trade_num'), 0.001) or 0.001
    size_multiplier = _safe_float(symbol_config.get('size_multiplier'), min_trade_num) or min_trade_num
    min_size = _ceil_to_step(min_trade_num, size_multiplier, volume_place)
    min_trade_usdt = _safe_float(symbol_config.get('min_trade_usdt'), 0.0) or 0.0
    min_trade_value = max(min_size * entry, min_trade_usdt)
    return round(float(min_trade_value), 6), min_size

@sleep_and_retry
@limits(calls=20, period=1)
def get_candlestick_data_sync(symbol, interval, limit):
    # No caching — always fetch fresh candles every cycle so analysis
    # reflects the current market structure, not stale data from a previous run.
    retry_attempts = _api_retry_attempts()
    backoff_s = _api_retry_backoff_seconds()
    for attempt_number in range(1, retry_attempts + 1):
        try:
            data = get_candlestick_data(symbol, interval, limit)
            if data:
                return data
            logger.warning(
                f"[{symbol}] {interval} candle fetch returned no data "
                f"(attempt {attempt_number}/{retry_attempts})."
            )
        except Exception as e:
            logger.warning(
                f"[{symbol}] {interval} candle fetch failed "
                f"(attempt {attempt_number}/{retry_attempts}): {e}"
            )
        if attempt_number < retry_attempts:
            _sleep_api_retry_backoff(backoff_s, attempt_number)
    return None


def get_batch_candlestick_data_sync(symbols, interval, limit):
    batch_data = {}
    for symbol in list(dict.fromkeys(symbols or [])):
        result = get_candlestick_data_sync(symbol, interval, limit)
        if result:
            batch_data[symbol] = result
        else:
            logger.warning(f"Failed to fetch candlestick data for {symbol}")
    return batch_data


def fetch_data_sync(symbol, interval, limit):
    """
    Fetch raw OHLCV candles and return a clean DataFrame.
    Synchronous on purpose so first-run API flakiness is not amplified by async wrappers.
    """
    candles_data = get_candlestick_data_sync(symbol, interval, limit)
    if not candles_data:
        logger.error(f"Could not fetch candlestick data for {symbol} on {interval} timeframe.")
        return None
    required_columns = ['timestamp', 'open', 'high', 'low', 'close', 'volume']
    if not all(col in candles_data[0] for col in required_columns):
        logger.error(f"Missing required columns in candlestick data for {symbol}: {list(candles_data[0].keys())}")
        return None
    df = pd.DataFrame(candles_data)
    df['datetime'] = pd.to_datetime(df['timestamp'], unit='ms').dt.tz_localize(None)
    df = df.set_index('datetime')
    df = df.drop(columns=['timestamp'], errors='ignore')
    df[['open', 'high', 'low', 'close', 'volume']] = df[['open', 'high', 'low', 'close', 'volume']].apply(pd.to_numeric, errors='coerce')
    initial_rows = len(df)
    df.dropna(subset=['open', 'high', 'low', 'close', 'volume'], inplace=True)
    if len(df) < initial_rows:
        logger.warning(f"Dropped {initial_rows - len(df)} rows with NaN OHLCV data for {symbol} on {interval}.")
    if df.empty:
        logger.error(f"DataFrame for {symbol} on {interval} is empty after dropping NaNs.")
        return None
    if not isinstance(df.index, pd.DatetimeIndex):
        logger.error(f"DataFrame index for {symbol} on {interval} is not a DatetimeIndex.")
        return None
    df = df.sort_index()
    return df


def fetch_and_prepare_data_sync(symbol, interval, limit, batch_mode=False, symbols=None, min_candles=None):
    df = fetch_data_sync(symbol, interval, limit)
    if df is None:
        logger.error(f"Failed to fetch {interval} data for {symbol}.")
        return None
    time_span = (df.index[-1] - df.index[0]).total_seconds() / 3600 if len(df) > 1 else 0
    _min_candles = min_candles if min_candles is not None else SIGNAL_CONFIG.get('min_required_candles', 50)
    _min_hours = SIGNAL_CONFIG.get('time_span_hours', 12) if min_candles is None else 0
    if time_span >= _min_hours and len(df) >= _min_candles:
        return df
    logger.error(f"Insufficient {interval} data for {symbol} ({len(df)} candles, {time_span:.2f} hours).")
    return None


def fetch_higher_tf_data_sync(symbol, intervals=['1H', '4H'], limit=None):
    tf_data = {}
    _limit = limit or SIGNAL_CONFIG.get('candlestick_limit', 400)
    for interval in intervals:
        df = fetch_and_prepare_data_sync(symbol, interval, _limit)
        if df is not None and not df.empty:
            if len(df) >= SIGNAL_CONFIG.get('macd_slow_period', 26) + SIGNAL_CONFIG.get('macd_signal_period', 9) - 1:
                df = calculate_all_indicators(df)
            tf_data[interval] = df
    return tf_data


