def _compute_path_adx_state(df):
    state = {
        "available": False,
        "timeframe": None,
        "current_adx": None,
        "prior_adx": None,
        "adx_delta": None,
        "adx_slope_per_bar": None,
        "adx_lookback_candles": None,
        "adx_net_change": None,
        "adx_positive_step_ratio": None,
    }
    if df is None or getattr(df, "empty", True) or "adx" not in df.columns:
        return state
    adx_series = pd.to_numeric(df["adx"], errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
    lookback = max(4, int(SIGNAL_CONFIG.get("path_adx_slope_lookback_candles", 10) or 10))
    if len(adx_series) < max(6, lookback):
        return state
    smooth = max(2, int(SIGNAL_CONFIG.get("adx_smooth_period", 3) or 3))
    current_window = adx_series.tail(smooth)
    prior_window = adx_series.iloc[-(smooth * 2):-smooth] if len(adx_series) >= (smooth * 2) else adx_series.iloc[:-smooth]
    if prior_window.empty:
        return state
    current_adx = float(current_window.mean())
    prior_adx = float(prior_window.mean())
    adx_delta = float(current_adx - prior_adx)
    slope_window = adx_series.tail(lookback).astype(float).to_numpy()
    x_axis = np.arange(len(slope_window), dtype=float)
    try:
        adx_slope = float(np.polyfit(x_axis, slope_window, 1)[0])
    except Exception:
        adx_slope = float(slope_window[-1] - slope_window[0]) / max(len(slope_window) - 1, 1)
    step_deltas = np.diff(slope_window)
    positive_step_ratio = (
        float(np.sum(step_deltas > 0) / len(step_deltas))
        if len(step_deltas) > 0
        else 0.0
    )
    net_change = float(slope_window[-1] - slope_window[0])
    state.update(
        {
            "available": True,
            "timeframe": "15m",
            "current_adx": round(current_adx, 4),
            "prior_adx": round(prior_adx, 4),
            "adx_delta": round(adx_delta, 4),
            "adx_slope_per_bar": round(adx_slope, 4),
            "adx_lookback_candles": int(lookback),
            "adx_net_change": round(net_change, 4),
            "adx_positive_step_ratio": round(positive_step_ratio, 4),
        }
    )
    return state


def _get_path_adx_timeframe() -> str:
    raw = str(SIGNAL_CONFIG.get("path_adx_confirmation_timeframe", "15m") or "15m").strip()
    return _normalize_path_adx_timeframe(raw)


def _get_path_adx_limit() -> int:
    return int(
        SIGNAL_CONFIG.get(
            "path_adx_confirmation_candle_limit",
            SIGNAL_CONFIG.get("structure_candles_1h", 100),
        ) or 100
    )


def _normalize_path_adx_timeframe(raw_value) -> str:
    raw = str(raw_value or "").strip()
    if not raw:
        return "1H"
    if raw.lower().endswith("m"):
        return raw.lower()
    if raw.lower().endswith("h"):
        return f"{raw[:-1]}H"
    return raw


def _get_path_adx_audit_timeframes() -> list[str]:
    configured = SIGNAL_CONFIG.get("path_adx_audit_timeframes", ["3m", "5m", "15m", "1H"]) or []
    unique = []
    for item in configured:
        token = _normalize_path_adx_timeframe(item)
        if token and token not in unique:
            unique.append(token)
    selected = _get_path_adx_timeframe()
    if selected not in unique:
        unique.append(selected)
    return unique


def _flatten_adx_audit_states(states) -> dict:
    flat = {}
    if not isinstance(states, dict):
        return flat
    for timeframe, state in states.items():
        if not isinstance(state, dict):
            continue
        token = str(timeframe or "").strip().lower().replace(" ", "_").replace("/", "_")
        if not token:
            continue
        flat[f"audit_adx_{token}_available"] = bool(state.get("available"))
        flat[f"audit_adx_{token}_current"] = _safe_float(state.get("current_adx"))
        flat[f"audit_adx_{token}_prior"] = _safe_float(state.get("prior_adx"))
        flat[f"audit_adx_{token}_delta"] = _safe_float(state.get("adx_delta"))
        flat[f"audit_adx_{token}_slope_per_bar"] = _safe_float(state.get("adx_slope_per_bar"))
        flat[f"audit_adx_{token}_lookback_candles"] = _safe_int(state.get("adx_lookback_candles"))
        flat[f"audit_adx_{token}_net_change"] = _safe_float(state.get("adx_net_change"))
        flat[f"audit_adx_{token}_positive_step_ratio"] = _safe_float(state.get("adx_positive_step_ratio"))
    return flat


def _compute_path_adx_state_for_symbol(symbol, timeframe=None, fallback_df=None):
    timeframe = _normalize_path_adx_timeframe(timeframe or _get_path_adx_timeframe())
    limit = _get_path_adx_limit()
    df_source = None
    if timeframe == "15m" and fallback_df is not None and not getattr(fallback_df, "empty", True):
        state = _compute_path_adx_state(fallback_df)
        state["timeframe"] = timeframe
        state["source"] = "signal_frame"
        state["candle_count"] = int(len(fallback_df))
        return state
    if symbol:
        try:
            df_source = get_operational_df_sync(
                symbol,
                timeframe,
                limit=limit,
                min_candles=max(40, min(limit, 80)),
            )
            if df_source is not None and not getattr(df_source, "empty", True):
                df_source = calculate_all_indicators(df_source.copy())
        except Exception as exc:
            logger.warning(f"[{symbol}] Could not compute {timeframe} ADX confirmation frame: {exc}")
            df_source = None
    if df_source is None or getattr(df_source, "empty", True):
        state = _compute_path_adx_state(fallback_df)
        state["timeframe"] = str(state.get("timeframe") or timeframe)
        state["source"] = "fallback_signal_frame"
        return state
    state = _compute_path_adx_state(df_source)
    state["timeframe"] = timeframe
    state["source"] = "operational_htf"
    state["candle_count"] = int(len(df_source))
    return state


def _collect_path_adx_audit_states(symbol, fallback_df=None):
    states = {}
    for timeframe in _get_path_adx_audit_timeframes():
        states[timeframe] = _compute_path_adx_state_for_symbol(symbol, timeframe=timeframe, fallback_df=fallback_df)
    return states


def _evaluate_path_adx_confirmation(symbol, trigger_type, fallback_df=None, adx_states=None):
    trigger = str(trigger_type or "").strip().lower()
    selected_tf = _get_path_adx_timeframe()
    states = adx_states if isinstance(adx_states, dict) else _collect_path_adx_audit_states(symbol, fallback_df=fallback_df)
    state = dict(states.get(selected_tf) or _compute_path_adx_state_for_symbol(symbol, timeframe=selected_tf, fallback_df=fallback_df))
    rationale = []
    if not state["available"]:
        return False, 0, ["ADX confirmation unavailable"], state

    current_adx = float(state["current_adx"])
    prior_adx = float(state["prior_adx"])
    adx_delta = float(state["adx_delta"])
    adx_slope = float(state["adx_slope_per_bar"])
    adx_net_change = _safe_float(state.get("adx_net_change"), adx_delta) or 0.0
    adx_positive_step_ratio = _safe_float(state.get("adx_positive_step_ratio"), 0.0) or 0.0
    adx_lookback = _safe_int(state.get("adx_lookback_candles"), 0)
    adx_tf = str(state.get("timeframe") or "unknown")

    if trigger == "sweep":
        prior_min = float(SIGNAL_CONFIG.get("sweep_adx_prior_strength_min", 22.0) or 22.0)
        current_min = float(SIGNAL_CONFIG.get("sweep_adx_current_min", 16.0) or 16.0)
        delta_max = float(SIGNAL_CONFIG.get("sweep_adx_delta_max", -0.25) or -0.25)
        prior_ok = prior_adx >= prior_min
        current_ok = current_adx >= current_min
        decay_ok = adx_delta <= delta_max and adx_slope < 0
        rationale.append(
            f"Sweep {adx_tf} ADX state: current={current_adx:.2f}, prior={prior_adx:.2f}, "
            f"delta={adx_delta:+.2f}, slope={adx_slope:+.2f}/bar"
        )
        if prior_ok and current_ok and decay_ok:
            bonus = 8 if prior_adx >= (prior_min + 5.0) and adx_delta <= min(delta_max * 2.0, -0.60) else 5
            rationale.append(
                f"{adx_tf} ADX confirms sweep exhaustion: prior trend strength is fading "
                "without collapsing into dead low ADX."
            )
            return True, bonus, rationale, state
        if not prior_ok:
            rationale.append(
                f"Sweep ADX failed: prior {adx_tf} ADX {prior_adx:.2f} < required prior-strength floor {prior_min:.2f}."
            )
        elif not current_ok:
            rationale.append(
                f"Sweep ADX failed: current {adx_tf} ADX {current_adx:.2f} is too weak; reversal looks dead rather than exhausted."
            )
        else:
            rationale.append(
                f"Sweep ADX failed: {adx_tf} ADX is not decaying enough now (delta {adx_delta:+.2f}, slope {adx_slope:+.2f}/bar)."
            )
        return False, 0, rationale, state

    breakout_min = float(SIGNAL_CONFIG.get("breakout_adx_current_min", 20.0) or 20.0)
    breakout_delta_min = float(SIGNAL_CONFIG.get("breakout_adx_delta_min", 0.15) or 0.15)
    breakout_positive_ratio_min = float(
        SIGNAL_CONFIG.get("breakout_adx_expansion_positive_ratio_min", 0.60) or 0.60
    )
    current_ok = current_adx >= breakout_min
    retest_cooldown_max_drop = float(
        SIGNAL_CONFIG.get("breakout_adx_retest_cooldown_max_drop", 1.25) or 1.25
    )
    retest_cooldown_positive_ratio_min = float(
        SIGNAL_CONFIG.get("breakout_adx_retest_cooldown_positive_ratio_min", 0.45) or 0.45
    )
    expansion_ok = (
        adx_net_change >= breakout_delta_min
        and adx_positive_step_ratio >= breakout_positive_ratio_min
    )
    retest_cooldown_ok = (
        current_ok
        and prior_adx >= breakout_min
        and adx_delta >= -abs(retest_cooldown_max_drop)
        and (
            adx_net_change >= 0
            or adx_positive_step_ratio >= retest_cooldown_positive_ratio_min
        )
    )
    rationale.append(
        f"Breakout {adx_tf} ADX state: current={current_adx:.2f}, prior={prior_adx:.2f}, "
        f"delta={adx_delta:+.2f}, slope={adx_slope:+.2f}/bar, "
        f"net{adx_lookback}={adx_net_change:+.2f}, up_ratio={adx_positive_step_ratio:.2f}"
    )
    if current_ok and expansion_ok:
        bonus = 8 if adx_net_change >= max(breakout_delta_min * 2.0, 0.50) and adx_slope > 0.10 else 5
        rationale.append(
            f"{adx_tf} ADX confirms breakout expansion across the recent {adx_lookback}-bar profile."
        )
        return True, bonus, rationale, state
    if retest_cooldown_ok:
        rationale.append(
            f"{adx_tf} ADX remains valid for breakout retest: current strength is above {breakout_min:.2f} "
            f"and any pullback cooldown is controlled (delta {adx_delta:+.2f}, "
            f"net {adx_net_change:+.2f}, up_ratio {adx_positive_step_ratio:.2f})."
        )
        return True, 3, rationale, state
    if not current_ok:
        rationale.append(
            f"Breakout ADX failed: current {adx_tf} ADX {current_adx:.2f} < required expansion floor {breakout_min:.2f}."
        )
    else:
        rationale.append(
            f"Breakout ADX failed: {adx_tf} ADX lacks expansion or controlled retest strength "
            f"(delta {adx_delta:+.2f}, net {adx_net_change:+.2f}, "
            f"slope {adx_slope:+.2f}/bar, up_ratio {adx_positive_step_ratio:.2f})."
        )
    return False, 0, rationale, state


def _evaluate_path_orderflow_confirmation(*, trigger_type, direction, fresh_of, mode_profile, price_place, entry_price=None, tp1=None):
    trigger = str(trigger_type or "").strip().lower()
    direction_token = str(direction or "").strip().upper()
    pressure_min = float(mode_profile.get("orderflow_gate_pressure_min", 60) or 60)
    imbalance_min = float(mode_profile.get("orderflow_gate_imbalance_min", 0.20) or 0.20)

    buy_pressure = float(_safe_float((fresh_of or {}).get("buy_pressure"), 50.0) or 50.0)
    sell_pressure = float(_safe_float((fresh_of or {}).get("sell_pressure"), 50.0) or 50.0)
    imbalance = float(_safe_float((fresh_of or {}).get("imbalance"), 0.0) or 0.0)
    imbalance_slope = float(_safe_float((fresh_of or {}).get("imbalance_slope_per_snapshot"), 0.0) or 0.0)
    buy_pressure_slope = float(_safe_float((fresh_of or {}).get("buy_pressure_slope_per_snapshot"), 0.0) or 0.0)
    sell_pressure_slope = float(_safe_float((fresh_of or {}).get("sell_pressure_slope_per_snapshot"), 0.0) or 0.0)
    rel_pressure = buy_pressure if direction_token == "BUY" else sell_pressure
    opp_pressure = sell_pressure if direction_token == "BUY" else buy_pressure
    rel_pressure_slope = buy_pressure_slope if direction_token == "BUY" else sell_pressure_slope
    opp_pressure_slope = sell_pressure_slope if direction_token == "BUY" else buy_pressure_slope
    aligned_imbalance = imbalance >= imbalance_min if direction_token == "BUY" else imbalance <= -imbalance_min
    adverse_imbalance = imbalance <= -imbalance_min if direction_token == "BUY" else imbalance >= imbalance_min

    rationale = []
    of_score = 0
    of_votes = 0
    ms_score = 0
    hard_block_reason = None

    footprint = (fresh_of or {}).get("footprint", {}) or {}
    absorption = (fresh_of or {}).get("absorption", {}) or {}
    queue = (fresh_of or {}).get("queue", {}) or {}
    liquidity = (fresh_of or {}).get("liquidity", {}) or {}

    delta_divergence = bool(footprint.get("delta_divergence", False))
    delta_strength = float(_safe_float(footprint.get("divergence_strength"), 0.0) or 0.0)
    clean_delta = bool(footprint.get("clean_delta", False))
    absorption_strength = _extract_absorption_strength(absorption)
    absorbed_key_level = bool(absorption.get("ob_level_absorbed", False))
    strong_absorption = absorbed_key_level and absorption_strength >= 0.70
    moderate_absorption = absorbed_key_level and absorption_strength >= 0.40
    queue_key = "queue_drain_bid" if direction_token == "BUY" else "queue_drain_ask"
    queue_drain = bool(queue.get(queue_key, False))
    same_side_iceberg = str((fresh_of or {}).get("iceberg_direction") or "").strip().upper() == direction_token

    rationale.append(
        f"OF snapshot: pressure={rel_pressure:.0f}% in-trade, opp_pressure={opp_pressure:.0f}%, "
        f"imbalance={imbalance:.3f}, pressure_slope={rel_pressure_slope:+.3f}/snap, imbalance_slope={imbalance_slope:+.4f}/snap"
    )

    if trigger == "sweep":
        if opp_pressure >= 60 and adverse_imbalance and not (delta_divergence or moderate_absorption or queue_drain):
            hard_block_reason = (
                f"Sweep OF failed: continuation pressure still dominant "
                f"(opp_pressure={opp_pressure:.0f}%, imbalance={imbalance:.3f}) without absorption/divergence."
            )
            rationale.append(hard_block_reason)
        else:
            if strong_absorption:
                ms_score += 16
                rationale.append(
                    f"Strong sweep absorption at defended level (strength={absorption_strength:.2f}) +16pts"
                )
            elif moderate_absorption:
                ms_score += 10
                rationale.append(
                    f"Moderate sweep absorption at defended level (strength={absorption_strength:.2f}) +10pts"
                )
            elif absorption_strength > 0:
                ms_score += 4
                rationale.append(f"Mild sweep absorption present (strength={absorption_strength:.2f}) +4pts")

            if delta_divergence:
                delta_bonus = 16 if delta_strength >= 0.30 else 12
                ms_score += delta_bonus
                rationale.append(
                    f"Sweep delta divergence confirms reversal (strength={delta_strength:.2%}) +{delta_bonus}pts"
                )
            if queue_drain:
                ms_score += 8
                rationale.append("Queue drain confirms reversal-side liquidity vacuum +8pts")
            if same_side_iceberg:
                of_score += 4
                rationale.append("Aligned iceberg support detected on reversal side +4pts")

            if rel_pressure >= pressure_min and aligned_imbalance:
                of_score += 6
                of_votes = 2
                rationale.append("Sweep OF has already flipped into supportive pressure +6pts")
            elif rel_pressure >= 50 or aligned_imbalance:
                of_score += 2
                of_votes = 1
                rationale.append("Sweep OF partially supportive; reversal is starting but not fully expanded yet +2pts")
            else:
                rationale.append(
                    "Sweep OF not yet directionally flipped — tolerated because sweep confirmation comes from absorption/divergence."
                )

            if adverse_imbalance and opp_pressure >= 60 and not strong_absorption:
                rationale.append(
                    f"Residual continuation pressure still present (opp_pressure={opp_pressure:.0f}%, imbalance={imbalance:.3f}) - logged for audit"
                )

            if not (strong_absorption or moderate_absorption or delta_divergence or queue_drain):
                if not (rel_pressure >= pressure_min and aligned_imbalance):
                    hard_block_reason = (
                        "Sweep OF failed: no live reversal confirmation "
                        "(no absorption, no delta divergence, no queue drain, and no supportive pressure flip)."
                    )
                    rationale.append(hard_block_reason)
    else:
        adversarial_pressure = float(SIGNAL_CONFIG.get("adversarial_flow_pressure_max", 35) or 35)
        if rel_pressure < adversarial_pressure and adverse_imbalance:
            hard_block_reason = (
                f"Breakout OF failed: adversarial continuation pressure opposes entry "
                f"(pressure={rel_pressure:.0f}%, imbalance={imbalance:.3f})."
            )
            rationale.append(hard_block_reason)
        else:
            if rel_pressure >= 82:
                of_score += 10
                rationale.append(f"Very strong breakout pressure ({rel_pressure:.0f}%) +10pts")
            elif rel_pressure >= 75:
                of_score += 6
                rationale.append(f"Solid breakout pressure ({rel_pressure:.0f}%) +6pts")

            if aligned_imbalance and abs(imbalance) > 0.38:
                of_score += 7
                rationale.append(f"Strong aligned book imbalance ({imbalance:.3f}) +7pts")

            if rel_pressure >= pressure_min and aligned_imbalance:
                of_score += 10
                of_votes = 3
                rationale.append(
                    f"Strong breakout continuation OF (pressure={rel_pressure:.0f}%, imbalance={imbalance:.3f}) +10pts"
                )
            elif rel_pressure >= pressure_min or aligned_imbalance:
                of_score += 6
                of_votes = 2
                rationale.append(
                    f"Meaningful breakout OF support (pressure={rel_pressure:.0f}% or imbalance={imbalance:.3f}) +6pts"
                )
            elif rel_pressure >= 50:
                of_votes = 1
                rationale.append(f"Breakout OF neutral ({rel_pressure:.0f}%)")
            else:
                miss_penalty = float(SIGNAL_CONFIG.get("orderflow_miss_penalty", 8) or 8)
                rationale.append(f"Weak breakout OF ({rel_pressure:.0f}%) - logged for audit")

            if same_side_iceberg:
                of_score += 4
                rationale.append("Aligned iceberg continuation support detected +4pts")

            if delta_divergence:
                rationale.append(
                    f"Delta divergence at breakout retest opposes continuation (strength={delta_strength:.2%}) - logged for audit"
                )
            elif clean_delta:
                ms_score += 4
                rationale.append("Clean delta alignment supports breakout continuation +4pts")

            if strong_absorption:
                ms_score += 14
                rationale.append(
                    f"Strong defended absorption at breakout retest (strength={absorption_strength:.2f}) +14pts"
                )
            elif moderate_absorption:
                ms_score += 8
                rationale.append(
                    f"Moderate defended absorption at breakout retest (strength={absorption_strength:.2f}) +8pts"
                )
            elif absorption_strength > 0:
                ms_score += 3
                rationale.append(f"Mild defended absorption at breakout retest (strength={absorption_strength:.2f}) +3pts")

            if queue_drain:
                ms_score += 8
                rationale.append("Queue drain confirms thin opposing liquidity at entry +8pts")

    if (fresh_of or {}).get("cvd") is not None:
        rationale.append(
            f"CVD={float(_safe_float(fresh_of.get('cvd'), 0.0) or 0.0):.1f}, "
            f"aggression={float(_safe_float(fresh_of.get('aggression_ratio'), 0.0) or 0.0):.3f}, "
            f"vol={float(_safe_float(fresh_of.get('total_trade_vol'), 0.0) or 0.0):.1f}"
        )

    migration_events = liquidity.get("migration_events", []) if isinstance(liquidity, dict) else []
    if isinstance(migration_events, list):
        aligned_migrations = [
            event for event in migration_events
            if (
                direction_token == "BUY"
                and event.get("direction") == "toward_bid"
                and event.get("to_price", 0) > event.get("from_price", 0)
            ) or (
                direction_token == "SELL"
                and event.get("direction") == "toward_ask"
                and event.get("to_price", 0) < event.get("from_price", 0)
            )
        ]
        if len(aligned_migrations) >= 3:
            ms_score += 10
            rationale.append(f"Liquidity migration toward entry ({len(aligned_migrations)} events) +10pts")
        elif len(aligned_migrations) >= 1:
            ms_score += 5
            rationale.append(f"Liquidity migration toward entry ({len(aligned_migrations)} events) +5pts")

    walls = liquidity.get("walls", []) if isinstance(liquidity, dict) else []
    if isinstance(walls, list) and entry_price is not None and tp1 is not None:
        opposing_walls = [
            wall for wall in walls
            if wall.get("side") == ("ask" if direction_token == "BUY" else "bid")
            and (
                (direction_token == "BUY" and float(entry_price) < wall.get("price", 0) < float(tp1))
                or (direction_token == "SELL" and float(tp1) < wall.get("price", 0) < float(entry_price))
            )
        ]
        if opposing_walls:
            rationale.append(
                f"Opposing wall in path to TP1 ({opposing_walls[0].get('price', 0):.{price_place}f}) - logged for audit"
            )

    return {
        "hard_block_reason": hard_block_reason,
        "of_score": int(round(of_score)),
        "of_votes": int(of_votes),
        "microstructure_score": int(round(ms_score)),
        "rationale": rationale,
        "directional_pressure": round(rel_pressure, 4),
        "opposing_pressure": round(opp_pressure, 4),
        "imbalance": round(imbalance, 4),
        "directional_pressure_slope": round(rel_pressure_slope, 6),
        "opposing_pressure_slope": round(opp_pressure_slope, 6),
        "imbalance_slope": round(imbalance_slope, 6),
        "buy_pressure": round(buy_pressure, 4),
        "sell_pressure": round(sell_pressure, 4),
        "buy_pressure_slope": round(buy_pressure_slope, 6),
        "sell_pressure_slope": round(sell_pressure_slope, 6),
        "cvd": round(float(_safe_float((fresh_of or {}).get("cvd"), 0.0) or 0.0), 4),
        "cvd_slope_per_trade": round(float(_safe_float((fresh_of or {}).get("cvd_slope_per_trade"), 0.0) or 0.0), 6),
        "cvd_intensity_delta_halves": round(float(_safe_float((fresh_of or {}).get("cvd_intensity_delta_halves"), 0.0) or 0.0), 6),
        "aggression_ratio": round(float(_safe_float((fresh_of or {}).get("aggression_ratio"), 0.0) or 0.0), 6),
        "aggression_ratio_delta_halves": round(float(_safe_float((fresh_of or {}).get("aggression_ratio_delta_halves"), 0.0) or 0.0), 6),
        "icebergs_detected": int(_safe_int((fresh_of or {}).get("icebergs_detected"), 0) or 0),
        "iceberg_direction": (fresh_of or {}).get("iceberg_direction"),
        "bid_icebergs": int(_safe_int((fresh_of or {}).get("bid_icebergs"), 0) or 0),
        "ask_icebergs": int(_safe_int((fresh_of or {}).get("ask_icebergs"), 0) or 0),
        "bid_notional": round(float(_safe_float((fresh_of or {}).get("bid_notional"), 0.0) or 0.0), 4),
        "ask_notional": round(float(_safe_float((fresh_of or {}).get("ask_notional"), 0.0) or 0.0), 4),
        "spoofs_detected": int(_safe_int((fresh_of or {}).get("spoofs_detected"), 0) or 0),
        "footprint": _to_json_safe((fresh_of or {}).get("footprint", {})),
        "absorption": _to_json_safe((fresh_of or {}).get("absorption", {})),
        "liquidity": _to_json_safe((fresh_of or {}).get("liquidity", {})),
        "queue": _to_json_safe((fresh_of or {}).get("queue", {})),
        "ws_diagnostics": _to_json_safe((fresh_of or {}).get("ws_diagnostics", {})),
    }


def _evaluate_live_ws_orderflow_entry_confirmation(
    *,
    trigger_type,
    direction,
    fresh_of,
    mode_profile,
    price_place,
    entry_price=None,
    tp1=None,
):
    """Use the existing OF analyzer for telemetry, then make entry pass/fail live-WS only."""
    fresh_of = fresh_of or {}
    base = _evaluate_path_orderflow_confirmation(
        trigger_type=trigger_type,
        direction=direction,
        fresh_of=fresh_of,
        mode_profile=mode_profile,
        price_place=price_place,
        entry_price=entry_price,
        tp1=tp1,
    )

    trigger = str(trigger_type or "").strip().lower()
    direction_token = str(direction or "").strip().upper()
    source = str(fresh_of.get("live_orderflow_source") or "").strip().lower()
    # Per user requirement: treat WS live only when books are warm and fresh.
    ws_live = _orderflow_payload_has_live_book(fresh_of)
    ws_required = bool(SIGNAL_CONFIG.get("require_live_ws_orderflow_for_entry", True))

    pressure = _safe_float(base.get("directional_pressure"), 0.0) or 0.0
    opposing_pressure = _safe_float(base.get("opposing_pressure"), 0.0) or 0.0
    imbalance = _safe_float(base.get("imbalance"), 0.0) or 0.0
    pressure_min = float(SIGNAL_CONFIG.get("live_ws_directional_pressure_min", 52.0) or 52.0)
    pressure_edge_min = float(SIGNAL_CONFIG.get("live_ws_pressure_edge_min", 2.0) or 2.0)
    imbalance_min = float(SIGNAL_CONFIG.get("live_ws_imbalance_min_abs", 0.03) or 0.03)

    failures = []
    evidence = []

    if ws_required and not ws_live:
        cov = _orderflow_coverage_from_payload(fresh_of)
        if isinstance(cov, dict) and "ws_available" in cov:
            if bool(cov.get("ws_available")):
                coverage_failures = cov.get("failures") or []
                if coverage_failures:
                    failures.append("live WS orderflow coverage insufficient: " + "; ".join(str(item) for item in coverage_failures))
                else:
                    failures.append("live WS orderflow coverage insufficient: books not warm or stale")
            else:
                failures.append("live WS orderflow unavailable/source=live_ws_continuous_unavailable")
        elif _orderflow_source_is_live_ws(source):
            failures.append("live WS orderflow coverage incomplete/source=live_ws_continuous")
        else:
            source_label = source or "unknown"
            failures.append(f"live WS orderflow unavailable/source={source_label}")
    elif ws_live:
        evidence.append("live_ws_orderflow_available")

    pressure_ok = pressure >= pressure_min and (pressure - opposing_pressure) >= pressure_edge_min
    if pressure_ok:
        evidence.append(f"ws_pressure_aligned_{pressure:.1f}_edge_{pressure - opposing_pressure:.1f}")
    else:
        failures.append(
            f"WS pressure not aligned enough: pressure={pressure:.1f}, "
            f"opposing={opposing_pressure:.1f}, min={pressure_min:.1f}, edge_min={pressure_edge_min:.1f}"
        )

    if direction_token == "BUY":
        imbalance_ok = imbalance >= imbalance_min
    else:
        imbalance_ok = imbalance <= -imbalance_min
    if imbalance_ok:
        evidence.append(f"ws_imbalance_aligned_{imbalance:.4f}")
    else:
        failures.append(
            f"WS imbalance not aligned enough: imbalance={imbalance:.4f}, min_abs={imbalance_min:.4f}"
        )

    cvd = _safe_float(fresh_of.get("cvd"))
    aggression_ratio = _safe_float(fresh_of.get("aggression_ratio"))
    if cvd is not None:
        if (direction_token == "BUY" and cvd > 0) or (direction_token == "SELL" and cvd < 0):
            evidence.append(f"cvd_aligned_{cvd:.1f}")
        else:
            cvd_opposition_min = float(SIGNAL_CONFIG.get("live_ws_cvd_strong_opposition_abs", 2500.0) or 2500.0)
            cx_venue_scale = max(1.0, float(_safe_float((fresh_of or {}).get("cx_venue_scale"), 1.0) or 1.0))
            if cx_venue_scale > 1.0:
                # Consolidated multi-venue tape: scale the absolute-USD opposition
                # threshold by the contributing-venue count so the richer book
                # does not loosen this gate. Ratio gates are scale-invariant.
                cvd_opposition_min *= cx_venue_scale
            if abs(float(cvd)) > cvd_opposition_min:
                failures.append(f"CVD strongly opposes {direction_token}: cvd={cvd:.1f}")
    if aggression_ratio is not None:
        aggr_block = (
            (direction_token == "BUY" and aggression_ratio <= -0.35)
            or (direction_token == "SELL" and aggression_ratio >= 0.35)
        )
        if aggr_block:
            failures.append(f"Aggression ratio strongly opposes {direction_token}: {aggression_ratio:.3f}")
        elif aggression_ratio != 0:
            evidence.append(f"aggression_ratio_logged_{aggression_ratio:.3f}")

    footprint = fresh_of.get("footprint", {}) if isinstance(fresh_of, dict) else {}
    absorption = fresh_of.get("absorption", {}) if isinstance(fresh_of, dict) else {}
    queue = fresh_of.get("queue", {}) if isinstance(fresh_of, dict) else {}
    liquidity = fresh_of.get("liquidity", {}) if isinstance(fresh_of, dict) else {}
    if not isinstance(footprint, dict):
        footprint = {}
    if not isinstance(absorption, dict):
        absorption = {}
    if not isinstance(queue, dict):
        queue = {}
    if not isinstance(liquidity, dict):
        liquidity = {}

    absorption_strength = _extract_absorption_strength(absorption)
    absorption_min = float(SIGNAL_CONFIG.get("live_ws_sweep_absorption_min_strength", 0.40) or 0.40)
    delta_strength = float(_safe_float(footprint.get("divergence_strength"), 0.0) or 0.0)
    delta_min = float(SIGNAL_CONFIG.get("live_ws_sweep_delta_divergence_min_strength", 0.15) or 0.15)
    queue_key = "queue_drain_bid" if direction_token == "BUY" else "queue_drain_ask"
    sweep_event_evidence = bool(
        (absorption_strength >= absorption_min)
        or (bool(footprint.get("delta_divergence")) and delta_strength >= delta_min)
        or bool(queue.get(queue_key))
        or bool(footprint.get("delta_reclaim"))
    )
    if trigger == "sweep":
        if sweep_event_evidence:
            evidence.append("sweep_micro_event_confirmed")
        elif bool(SIGNAL_CONFIG.get("live_ws_sweep_require_event_evidence", False)):
            failures.append(
                "Sweep OF lacks micro event evidence: no absorption, delta divergence/reclaim, or queue drain"
            )

    walls = liquidity.get("walls", []) if isinstance(liquidity, dict) else []
    if trigger == "breakout" and isinstance(walls, list) and entry_price is not None and tp1 is not None:
        opposing_side = "ask" if direction_token == "BUY" else "bid"
        wall_between_entry_and_tp = [
            wall for wall in walls
            if isinstance(wall, dict)
            and wall.get("side") == opposing_side
            and (
                (direction_token == "BUY" and float(entry_price) < _safe_float(wall.get("price"), 0.0) < float(tp1))
                or (direction_token == "SELL" and float(tp1) < _safe_float(wall.get("price"), 0.0) < float(entry_price))
            )
        ]
        if wall_between_entry_and_tp:
            evidence.append("opposing_wall_between_entry_and_tp_logged")

    passed = not failures
    decision_reason = (
        f"Live WS OF confirmation passed ({trigger or 'path'}): "
        f"pressure={pressure:.1f}, opposing={opposing_pressure:.1f}, imbalance={imbalance:.4f}"
        if passed
        else "Live WS OF confirmation failed: " + "; ".join(failures)
    )
    rationale = list(base.get("rationale", []))
    rationale.append(decision_reason)

    base.update(
        {
            "passed": passed,
            "hard_block_reason": None if passed else "; ".join(failures),
            "confirmation_model": "live_ws_orderflow_only",
            "live_orderflow_source": source,
            "ws_live": ws_live,
            "ws_required": ws_required,
            "confirmation_evidence": evidence,
            "confirmation_failures": failures,
            "rationale": rationale,
            "sweep_event_evidence": sweep_event_evidence,
            "sweep_absorption_strength": round(float(absorption_strength), 4),
            "sweep_delta_divergence_strength": round(float(delta_strength), 4),
        }
    )
    return base


def _evaluate_last_candle_directional_body(df, direction, atr_value=None):
    direction_token = str(direction or "").strip().upper()
    if df is None or getattr(df, "empty", True) or direction_token not in {"BUY", "SELL"}:
        return {"passed": False, "reason": "Last-candle confirmation unavailable"}

    candle = df.iloc[-1]
    open_price = _safe_float(candle.get("open"))
    high_price = _safe_float(candle.get("high"))
    low_price = _safe_float(candle.get("low"))
    close_price = _safe_float(candle.get("close"))
    if None in (open_price, high_price, low_price, close_price):
        return {"passed": False, "reason": "Last-candle OHLC incomplete"}

    candle_range = max(float(high_price) - float(low_price), 0.0)
    body = abs(float(close_price) - float(open_price))
    body_ratio = body / candle_range if candle_range > 0 else 0.0
    atr_safe = _safe_float(atr_value, 0.0) or 0.0
    body_atr = body / atr_safe if atr_safe > 0 else None

    min_body_ratio = float(SIGNAL_CONFIG.get("last_candle_confirm_min_body_ratio", 0.35) or 0.35)
    min_body_atr = float(SIGNAL_CONFIG.get("last_candle_confirm_min_body_atr", 0.10) or 0.0)
    require_close_location = bool(SIGNAL_CONFIG.get("last_candle_confirm_require_close_location", True))

    directional = close_price > open_price if direction_token == "BUY" else close_price < open_price
    if direction_token == "BUY":
        close_location_ok = close_price >= low_price + (candle_range * 0.55) if candle_range > 0 else False
    else:
        close_location_ok = close_price <= high_price - (candle_range * 0.55) if candle_range > 0 else False

    body_ok = body_ratio >= min_body_ratio and (body_atr is None or body_atr >= min_body_atr)
    passed = bool(directional and body_ok and (close_location_ok or not require_close_location))
    return {
        "passed": passed,
        "reason": (
            f"Last candle {'confirms' if passed else 'does not confirm'} {direction_token}: "
            f"body={body_ratio:.2f}, body_atr={body_atr if body_atr is not None else 'n/a'}, "
            f"close_location_ok={close_location_ok}"
        ),
        "direction": direction_token,
        "open": float(open_price),
        "high": float(high_price),
        "low": float(low_price),
        "close": float(close_price),
        "body_ratio": round(float(body_ratio), 4),
        "body_atr": round(float(body_atr), 4) if body_atr is not None else None,
        "min_body_ratio": min_body_ratio,
        "min_body_atr": min_body_atr,
        "close_location_ok": bool(close_location_ok),
    }


def _evaluate_confirmation_aware_entry_proximity(
    *,
    df,
    direction,
    trigger_type,
    trigger_level,
    entry_price,
    atr_value,
    price_place=4,
    stage="initial",
    last_candle_state=None,
):
    """Keep anti-chase protection, but allow stronger confirmed entry candles."""
    trigger_token = str(trigger_type or "").strip().lower()
    direction_token = str(direction or "").strip().upper()
    trigger = _safe_float(trigger_level)
    entry = _safe_float(entry_price)
    atr = _safe_float(atr_value)
    if trigger is None or entry is None or atr is None or atr <= 0:
        return {
            "stage": stage,
            "passed": False,
            "status": "failed",
            "reason": "Entry proximity unavailable: missing trigger, entry, or ATR",
            "trigger_type": trigger_token,
            "direction": direction_token,
        }

    if trigger_token == "sweep":
        zone = "swept level"
        base_max = _safe_float(SIGNAL_CONFIG.get("max_sweep_entry_atr"), 1.0)
        confirmed_max = _safe_float(SIGNAL_CONFIG.get("max_sweep_confirmed_entry_atr"), 1.5)
        absolute_max = _safe_float(SIGNAL_CONFIG.get("max_sweep_absolute_entry_atr"), 2.0)
    else:
        zone = "retest zone"
        base_max = _safe_float(SIGNAL_CONFIG.get("max_breakout_entry_atr"), 1.0)
        confirmed_max = _safe_float(SIGNAL_CONFIG.get("max_breakout_confirmed_entry_atr"), 1.75)
        absolute_max = _safe_float(SIGNAL_CONFIG.get("max_breakout_absolute_entry_atr"), 2.25)

    base_max = max(0.0, float(base_max or 0.0))
    confirmed_max = max(base_max, float(confirmed_max or base_max))
    absolute_max = max(confirmed_max, float(absolute_max or confirmed_max))
    confirmation_aware = bool(SIGNAL_CONFIG.get("confirmation_aware_entry_proximity", True))

    if not isinstance(last_candle_state, dict):
        last_candle_state = _evaluate_last_candle_directional_body(df, direction_token, atr)
    last_candle_confirmed = bool((last_candle_state or {}).get("passed"))

    max_entry_atr = base_max
    mode = "base"
    if confirmation_aware and last_candle_confirmed:
        body_atr = _safe_float((last_candle_state or {}).get("body_atr"), 0.0) or 0.0
        min_body_atr = _safe_float(
            (last_candle_state or {}).get("min_body_atr"),
            SIGNAL_CONFIG.get("last_candle_confirm_min_body_atr", 0.10),
        ) or 0.0
        body_extension_cap = max(
            0.0,
            _safe_float(SIGNAL_CONFIG.get("confirmed_entry_body_extension_cap_atr"), 0.25) or 0.0,
        )
        body_extension = min(body_extension_cap, max(0.0, float(body_atr) - float(min_body_atr)))
        max_entry_atr = min(absolute_max, confirmed_max + body_extension)
        mode = "confirmed_candle"
    elif confirmation_aware:
        mode = "base_unconfirmed_candle"

    entry_distance_atr = abs(entry - trigger) / atr
    passed = bool(entry_distance_atr <= max_entry_atr)
    decimals = max(0, min(_safe_int(price_place, 4), 10))
    level_text = f"{trigger:.{decimals}f}"
    if passed:
        reason = (
            f"Entry proximity OK: {entry_distance_atr:.2f}xATR from {zone} "
            f"(max {max_entry_atr:.2f}xATR, mode={mode})"
        )
    else:
        reason = (
            f"Late {trigger_token or 'trade'} entry: price {entry_distance_atr:.2f}xATR "
            f"from {zone} {level_text} (max {max_entry_atr:.2f}xATR, mode={mode})"
        )

    return {
        "stage": stage,
        "status": "passed" if passed else "failed",
        "passed": passed,
        "reason": reason,
        "trigger_type": trigger_token,
        "direction": direction_token,
        "zone": zone,
        "trigger_level": trigger,
        "entry_price": entry,
        "entry_distance_atr": round(float(entry_distance_atr), 4),
        "max_entry_atr": round(float(max_entry_atr), 4),
        "base_entry_atr": round(float(base_max), 4),
        "confirmed_entry_atr": round(float(confirmed_max), 4),
        "absolute_entry_atr": round(float(absolute_max), 4),
        "mode": mode,
        "confirmation_aware": confirmation_aware,
        "last_candle_confirmed": last_candle_confirmed,
        "last_candle_state": _to_json_safe(last_candle_state or {}),
    }


def _evaluate_simplified_live_entry_gate(
    *,
    trigger_type,
    direction,
    fresh_of,
    of_eval,
    adx_passed,
    adx_state,
    last_candle_state,
):
    """Final compact live-entry gate: live WS pressure and imbalance only."""
    direction_token = str(direction or "").strip().upper()
    fresh_of = fresh_of or {}
    of_eval = of_eval or {}
    failures = []
    evidence = []

    source = str(fresh_of.get("live_orderflow_source") or "").strip().lower()
    ws_required = bool(SIGNAL_CONFIG.get("require_live_ws_orderflow_for_entry", True))
    # Per user requirement: only consider WS unavailable/source=unknown when
    # books are not warm (stream_age < of_warmup_seconds) or book staleness > threshold.
    ws_live = _orderflow_payload_has_live_book(fresh_of)
    if ws_required and not ws_live:
        cov = _orderflow_coverage_from_payload(fresh_of)
        if isinstance(cov, dict) and "ws_available" in cov:
            if bool(cov.get("ws_available")):
                coverage_failures = cov.get("failures") or []
                if coverage_failures:
                    failures.append("live WS orderflow coverage insufficient: " + "; ".join(str(item) for item in coverage_failures))
                else:
                    failures.append("live WS orderflow coverage insufficient: books not warm or stale")
            else:
                failures.append("live WS orderflow unavailable/source=live_ws_continuous_unavailable")
        elif _orderflow_source_is_live_ws(source):
            failures.append("live WS orderflow coverage incomplete/source=live_ws_continuous")
        else:
            source_label = source or "unknown"
            failures.append(f"live WS orderflow unavailable/source={source_label}")
    elif ws_live:
        evidence.append("live_ws_orderflow_available")

    pressure = _safe_float(of_eval.get("directional_pressure"), 0.0) or 0.0
    opposing_pressure = _safe_float(of_eval.get("opposing_pressure"), 0.0) or 0.0
    imbalance = _safe_float(of_eval.get("imbalance"), 0.0) or 0.0
    pressure_slope = _safe_float(of_eval.get("directional_pressure_slope"), 0.0) or 0.0
    imbalance_slope = _safe_float(of_eval.get("imbalance_slope"), 0.0) or 0.0

    pressure_min = float(SIGNAL_CONFIG.get("live_ws_directional_pressure_min", 52.0) or 52.0)
    pressure_edge_min = float(SIGNAL_CONFIG.get("live_ws_pressure_edge_min", 2.0) or 2.0)
    imbalance_min = float(SIGNAL_CONFIG.get("live_ws_imbalance_min_abs", 0.03) or 0.03)

    pressure_ok = pressure >= pressure_min and (pressure - opposing_pressure) >= pressure_edge_min
    if direction_token == "BUY":
        imbalance_ok = imbalance >= imbalance_min
    else:
        imbalance_ok = imbalance <= -imbalance_min

    if pressure_ok:
        evidence.append(f"ws_pressure_aligned_{pressure:.1f}")
    else:
        failures.append(
            f"WS pressure not aligned enough: pressure={pressure:.1f}, "
            f"opposing={opposing_pressure:.1f}, min={pressure_min:.1f}, edge_min={pressure_edge_min:.1f}"
        )
    if imbalance_ok:
        evidence.append(f"ws_imbalance_aligned_{imbalance:.4f}")
    else:
        failures.append(f"WS imbalance not aligned enough: imbalance={imbalance:.4f}, min_abs={imbalance_min:.4f}")

    return {
        "passed": not failures,
        "trigger_type": str(trigger_type or "").strip().lower(),
        "direction": direction_token,
        "evidence": evidence,
        "failures": failures,
        "live_orderflow_source": source,
        "ws_required": ws_required,
        "directional_pressure": round(float(pressure), 4),
        "opposing_pressure": round(float(opposing_pressure), 4),
        "imbalance": round(float(imbalance), 6),
        "directional_pressure_slope": round(float(pressure_slope), 6),
        "imbalance_slope": round(float(imbalance_slope), 6),
        "confirmation_model": "live_ws_orderflow_only",
        "adx_logged_only": _to_json_safe(adx_state),
        "last_candle_logged_only": _to_json_safe(last_candle_state),
        "adx_state": _to_json_safe(adx_state),
        "last_candle_state": _to_json_safe(last_candle_state),
    }


def detect_volume_structure(df, direction, atr_value, original_direction=None):
    """
    Replaces Wyckoff as the 15m-appropriate gatekeeper.
    Captures the same underlying concepts Wyckoff represents
    (climactic volume, absorption, effort vs result) but at a
    timeframe where they are actually meaningful.

    Returns: (passed: bool, score: int, reason: str)

    Parameters:
        direction          : The direction to check climactic volume for.
                             this direction for RSI extreme check instead of direction.
                             Prevents incorrect rejection when flip direction RSI
                             is neutral but breakout direction RSI is extreme.

    Three components are checked:
    1. Climactic volume event — was there a vol spike recently that
       suggests institutional activity (stop hunt, capitulation)?
    2. Absorption — after the climax, did volume dry up while price held?
    3. Effort vs result — are recent candles showing strong volume but small
       range (effort without result)? This signals exhaustion.
    """
    if len(df) < 20:
        return False, 0, "Insufficient data for volume structure"

    recent = df.tail(30).copy()
    vol_mean = recent['volume'].mean()
    vol_std = recent['volume'].std()
    if vol_std == 0:
        return False, 0, "Zero volume std"

    score = 0
    reasons = []

    # ── Component 1: Climactic volume event in last 10 candles ──────────
    # A real move needs a triggering event — high-volume candle that
    # swept stops or caused capitulation. Z-score > 1.5 = significant.
    last_10 = recent.tail(10)
    vol_zscores = (last_10['volume'] - vol_mean) / vol_std
    climax_candles = last_10[vol_zscores > 1.5]

    if not climax_candles.empty:
        # direction = event direction being checked (original breakout on flip path)
        # BUY direction = looking for bearish climax (reversal) or bullish (continuation)
        if direction == "BUY":
            valid_climax   = climax_candles[climax_candles["close"] <= climax_candles["open"]]
            valid_climax_b = climax_candles[climax_candles["close"] >  climax_candles["open"]]
        else:
            valid_climax   = climax_candles[climax_candles["close"] >= climax_candles["open"]]
            valid_climax_b = climax_candles[climax_candles["close"] <  climax_candles["open"]]

        # ── Fix 10: Path-aware continuation climax handling ──────────────────
        # Reversal/flip: a continuation-direction climax means price is still
        # running — wrong time to fade it unless on breakout path.
        # Accept continuation fallback ONLY when original_direction is None
        # direction, so valid_climax already looks for the correct reversal candle.
        if valid_climax.empty and not valid_climax_b.empty:
            if original_direction is None:
                # Breakout path: continuation climax confirms momentum — accept
                valid_climax = valid_climax_b
            # Sweep / flip path: absence of reversal climax is meaningful — do not reassign

        if not valid_climax.empty:
            max_zscore = vol_zscores[valid_climax.index].max()
            if max_zscore > 2.5:
                score += 30
                reasons.append(f"Strong climactic volume event (z={max_zscore:.1f})")
            else:
                score += 15
                reasons.append(f"Moderate climactic volume event (z={max_zscore:.1f})")
        else:
            score += 5
            reasons.append("Volume spike but wrong direction candle")
    else:
        reasons.append("No climactic volume event in last 10 candles")

    # ── Component 2: Post-climax absorption ─────────────────────────────
    if not climax_candles.empty:
        climax_end = climax_candles.index[-1]
        try:
            climax_pos  = recent.index.get_loc(climax_end)
            post_climax = recent.iloc[climax_pos + 1:]
            if len(post_climax) >= 3:
                post_vol_mean = post_climax['volume'].mean()
                climax_vol = climax_candles['volume'].max()
                absorption_ratio = post_vol_mean / climax_vol if climax_vol > 0 else 1.0
                if absorption_ratio < 0.5:
                    score += 25
                    reasons.append(f"Strong absorption: post-climax vol {absorption_ratio:.1%} of climax")
                elif absorption_ratio < 0.75:
                    score += 12
                    reasons.append(f"Mild absorption: post-climax vol {absorption_ratio:.1%} of climax")
                else:
                    reasons.append(f"Weak absorption: vol not contracting ({absorption_ratio:.1%})")
        except Exception:
            pass

    # ── Component 3: Effort vs Result on last 5 candles ─────────────────
    # High volume + small candle range = effort without result = exhaustion.
    # the RSI extreme that matters is in the BREAKOUT direction, not the flip.
    last_5 = recent.tail(5)
    avg_range = recent['range'].mean() if 'range' in recent.columns else (recent['high'] - recent['low']).mean()
    avg_vol_recent = recent['volume'].mean()
    rsi_direction = original_direction if original_direction is not None else direction

    if avg_range > 0 and avg_vol_recent > 0:
        effort_without_result = last_5[
            (last_5['volume'] > avg_vol_recent * 1.1) &
            ((last_5['high'] - last_5['low']) < avg_range * 0.8)
        ]

        # ── Fix 3: Hard reject on exhaustion candle clusters ─────────────────
        if len(effort_without_result) >= 3 and original_direction is None:
            return False, 0, (
                f"Hard reject: {len(effort_without_result)}/5 recent candles are exhaustion candles "
                f"(high volume, no range expansion) — momentum spent, entry would be into dead move"
            )

        rsi_col = f"RSI_{SIGNAL_CONFIG.get('rsi_period', 14)}"
        if len(effort_without_result) >= 2 and rsi_col in df.columns:
            rsi_last = df[rsi_col].iloc[-1]
            rsi_extreme = (rsi_direction == 'BUY' and rsi_last > 65) or (rsi_direction == 'SELL' and rsi_last < 35)
            if rsi_extreme and original_direction is None:
                return False, 0, (
                    f"Hard reject: 2 exhaustion candles + RSI extreme ({rsi_last:.1f}) "
                    f"= spent momentum at extended price — SL hit on retracement before resumption"
                )

        if len(effort_without_result) >= 2:
            score += 20
            reasons.append(f"Effort-result divergence: {len(effort_without_result)} exhaustion candles")
        elif len(effort_without_result) == 1:
            score += 10
            reasons.append("Mild effort-result divergence")

    # ── Gate: minimum score to pass (configurable) ─────────────────────────
    min_score = SIGNAL_CONFIG.get("vol_structure_min_score", 15)
    passed = score >= min_score
    reason_str = " | ".join(reasons) if reasons else "No volume structure"
    return passed, score, reason_str

def detect_momentum_divergence(df, price_col='close', is_bullish=True):
    """
    Detect RSI divergence using swing-anchored comparison.

    Fixes vs original:
    - Uses swing highs/lows to anchor divergence rather than arbitrary 2-bar
      point comparison. Requires two swing lows (bullish) or highs (bearish).
    - RSI column derived from config period — not hardcoded to RSI_14.
    - Minimum 3-bar separation between comparison points enforced.
    - Strength = RSI delta * 4, clamped 0-100.
    - Fix 11: Minimum RSI delta raised from 1.0 to 5.0 — a 1-point RSI delta
      on a 15m chart is indistinguishable from noise. Genuine divergence requires
      a meaningful momentum-price disconnect of at least 5 RSI points.
    - Fix 6: Loop now scans ALL valid pairs across the lookback window and
      returns the STRONGEST divergence found, not just the first from the most
      recent bar. Previous logic broke out of both loops immediately after finding
      any divergence at j=n-1, missing stronger divergence at earlier bars.
    """
    rsi_period = SIGNAL_CONFIG.get("rsi_period", 14)
    rsi_col    = f"RSI_{rsi_period}"
    if len(df) < 10 or rsi_col not in df.columns:
        return None, 0

    rsi   = df[rsi_col]
    price = df[price_col]
    lookback = min(len(df), 30)

    sub_price = price.iloc[-lookback:].values
    sub_rsi   = rsi.iloc[-lookback:].values
    n = len(sub_price)

    MIN_DELTA = 5.0   # minimum RSI delta to qualify as genuine divergence

    best_delta = 0.0

    if is_bullish:
        # Bullish divergence: price makes lower low, RSI makes higher low
        for j in range(n - 1, 2, -1):
            for i in range(j - 3, -1, -1):
                if sub_price[j] < sub_price[i] and sub_rsi[j] > sub_rsi[i]:
                    delta = sub_rsi[j] - sub_rsi[i]
                    if delta > best_delta:
                        best_delta = delta
        if best_delta >= MIN_DELTA:
            return "bullish_divergence", int(min(100, best_delta * 4))
    else:
        # Bearish divergence: price makes higher high, RSI makes lower high
        for j in range(n - 1, 2, -1):
            for i in range(j - 3, -1, -1):
                if sub_price[j] > sub_price[i] and sub_rsi[j] < sub_rsi[i]:
                    delta = sub_rsi[i] - sub_rsi[j]
                    if delta > best_delta:
                        best_delta = delta
        if best_delta >= MIN_DELTA:
            return "bearish_divergence", int(min(100, best_delta * 4))

    return None, 0

def fetch_order_book_depth(symbol, product_type='usdt-futures', limit=100):
    norm_symbol = symbol.replace('_UMCBL', '').upper()
    url = f"https://api.bitget.com/api/v2/mix/market/merge-depth"
    params = {
        'productType': product_type,
        'symbol': norm_symbol,
        'limit': limit
    }
    try:
        resp, data = _public_get_json_with_retry(
            url,
            params=params,
            timeout_key='public_api_timeout_seconds',
            default_timeout=5.0,
        )
        if resp is not None and data.get('code') == '00000' and data.get('data'):
            book = data['data']
            return {
                'bids': [[float(p), float(q)] for p, q in book['bids'][:50]],
                'asks': [[float(p), float(q)] for p, q in book['asks'][:50]]
            }
        return None
    except Exception as e:
        logger.error(f"Depth request error for {symbol}: {e}")
        return None

def compute_candle_absorption(df: pd.DataFrame, sweep_candle_idx: int,
                              atr_value: float, is_bullish: bool) -> dict:
    """
    Derive absorption evidence from OHLCV data of the sweep candle and the
    candle immediately after it. Used when the sweep is older than
    CANDLE_ABSORPTION_MAX_AGE candles — the live WS window no longer captures
    the absorption event, but the candle already recorded it permanently.

    Absorption signatures in OHLCV:
    1. High volume at the sweep candle with a long rejection wick.
       Price moved aggressively through the level (sweep) but closed back
       inside — the seller (for bullish sweep) was absorbed.
    2. The candle immediately after the sweep has significantly lower volume
       than the sweep candle — absorption is complete, aggressive selling stopped.
    3. The body/range ratio of the sweep candle is low — wicked hard, closed soft.
       This is the textbook "effort without result" signature.

    Returns:
        absorbed           : bool   — absorption evidence found
        absorption_strength: float  — 0.0–1.0 composite score
        wick_ratio         : float  — rejection wick as fraction of candle range
        vol_ratio          : float  — sweep candle vol / vol_ma (how climactic)
        post_vol_decay     : float  — next candle vol / sweep candle vol (decay = absorbed)
        body_ratio         : float  — body size / range (low = wick-dominant = absorbed)
        source             : str    — 'candle_historical'
    """
    empty = {
        'absorbed': False, 'absorption_strength': 0.0,
        'wick_ratio': 0.0, 'vol_ratio': 0.0,
        'post_vol_decay': 1.0, 'body_ratio': 1.0,
        'source': 'candle_historical', 'sufficient_data': False
    }

    if df is None or sweep_candle_idx is None:
        return empty

    n = len(df)
    if sweep_candle_idx < 0 or sweep_candle_idx >= n:
        return empty

    sweep_candle = df.iloc[sweep_candle_idx]
    candle_range = sweep_candle['high'] - sweep_candle['low']
    if candle_range <= 0:
        return empty

    # ── Wick ratio ────────────────────────────────────────────────────────
    # Bullish sweep: swept lows, expect lower wick (rejection of the downside)
    # Bearish sweep: swept highs, expect upper wick (rejection of the upside)
    if is_bullish:
        wick = min(sweep_candle['open'], sweep_candle['close']) - sweep_candle['low']
    else:
        wick = sweep_candle['high'] - max(sweep_candle['open'], sweep_candle['close'])
    wick_ratio = max(wick, 0.0) / candle_range

    # ── Body ratio ────────────────────────────────────────────────────────
    body      = abs(sweep_candle['close'] - sweep_candle['open'])
    body_ratio = body / candle_range  # low body = wick-dominant = absorbed

    # ── Volume climax ratio ───────────────────────────────────────────────
    vol_ma = sweep_candle.get('volume_ma', None)
    if vol_ma is None or vol_ma <= 0:
        # Compute a local vol_ma from surrounding candles
        start = max(0, sweep_candle_idx - 10)
        local_vols = df.iloc[start:sweep_candle_idx]['volume']
        vol_ma = float(local_vols.mean()) if len(local_vols) > 0 else float(sweep_candle['volume'])
    vol_ratio = float(sweep_candle['volume']) / max(vol_ma, 1e-9)

    # ── Post-candle volume decay ──────────────────────────────────────────
    # If the next candle exists, its volume should be significantly lower
    # than the sweep candle — the aggressive participant is done.
    post_vol_decay = 1.0
    if sweep_candle_idx + 1 < n:
        next_vol = float(df.iloc[sweep_candle_idx + 1]['volume'])
        post_vol_decay = next_vol / max(float(sweep_candle['volume']), 1e-9)
        # Values < 0.6 mean next-candle volume is less than 60% of sweep — good decay

    # ── Composite absorption strength ─────────────────────────────────────
    # Each component contributes to a 0–1 score:
    # - wick_ratio >= 0.40 → strong rejection wick (0.4 = config min_sweep_wick_pct)
    # - body_ratio <= 0.30 → wick-dominant candle
    # - vol_ratio >= 1.5   → climactic volume spike (sweep was institutionally sized)
    # - post_vol_decay <= 0.60 → absorption complete, aggression stopped
    score_components = []

    wick_score = min(wick_ratio / 0.60, 1.0)        # saturates at 60% wick
    score_components.append(wick_score * 0.35)       # 35% weight

    body_score = max(0.0, 1.0 - (body_ratio / 0.40))  # 0 body = 1.0, 40%+ body = 0
    score_components.append(body_score * 0.20)        # 20% weight

    vol_score = min(max(vol_ratio - 1.0, 0.0) / 2.0, 1.0)  # saturates at 3× vol_ma
    score_components.append(vol_score * 0.25)         # 25% weight

    decay_score = max(0.0, 1.0 - post_vol_decay / 0.8)  # saturates when decay <= 0
    score_components.append(decay_score * 0.20)       # 20% weight

    absorption_strength = float(sum(score_components))

    # Absorbed = wick present AND either climactic volume or clear body suppression
    absorbed = (
        wick_ratio >= SIGNAL_CONFIG.get('min_sweep_wick_pct', 0.40) and
        (vol_ratio >= 1.3 or body_ratio <= 0.35) and
        absorption_strength >= 0.35
    )

    return {
        'absorbed':            absorbed,
        'absorption_strength': round(absorption_strength, 3),
        'wick_ratio':          round(wick_ratio, 3),
        'vol_ratio':           round(vol_ratio, 3),
        'post_vol_decay':      round(post_vol_decay, 3),
        'body_ratio':          round(body_ratio, 3),
        'source':              'candle_historical',
        'sufficient_data':     True
    }


def compute_breakout_candle_proxy(df: pd.DataFrame, breakout_idx: int,
                                 breakout_level: float, atr_value: float,
                                 is_bullish: bool) -> dict:
    """
    Derive breakout-continuation evidence from 15m candles separately from live
    websocket order flow. This is not a replacement for live order flow; it is a
    parallel audit track so we can compare whether the candle-side breakout tape
    is more informative than the live WS microstructure.
    """
    empty = {
        'available': False,
        'source': 'candle_breakout_proxy',
        'breakout_age_candles': None,
        'continuation_confirmed': False,
        'continuation_strength': 0.0,
        'body_ratio': 0.0,
        'vol_ratio': 0.0,
        'close_through_atr': 0.0,
        'breakout_range_atr': 0.0,
        'post_breakout_progress_atr': 0.0,
        'post_breakout_progress_slope_atr_per_candle': 0.0,
        'post_breakout_volume_decay': None,
        'future_candles_used': 0,
    }

    if df is None or breakout_idx is None or breakout_level is None:
        return empty

    n = len(df)
    if breakout_idx < 0 or breakout_idx >= n:
        return empty

    breakout_candle = df.iloc[breakout_idx]
    candle_range = float(breakout_candle['high']) - float(breakout_candle['low'])
    if candle_range <= 0:
        updated = dict(empty)
        updated['breakout_age_candles'] = max(0, (n - 1) - int(breakout_idx))
        return updated

    breakout_age = max(0, (n - 1) - int(breakout_idx))
    atr = float(atr_value or 0.0)
    if atr <= 0:
        atr = max(float(breakout_candle['close']) * 0.005, 1e-9)

    body = abs(float(breakout_candle['close']) - float(breakout_candle['open']))
    body_ratio = body / candle_range
    breakout_range_atr = candle_range / max(atr, 1e-9)

    vol_ma = breakout_candle.get('volume_ma', None)
    if vol_ma is None or float(vol_ma) <= 0:
        start = max(0, breakout_idx - 10)
        local_vols = df.iloc[start:breakout_idx]['volume']
        vol_ma = float(local_vols.mean()) if len(local_vols) > 0 else float(breakout_candle['volume'])
    vol_ratio = float(breakout_candle['volume']) / max(float(vol_ma), 1e-9)

    close_value = float(breakout_candle['close'])
    breakout_level = float(breakout_level)
    if is_bullish:
        close_through_atr = max((close_value - breakout_level) / max(atr, 1e-9), 0.0)
    else:
        close_through_atr = max((breakout_level - close_value) / max(atr, 1e-9), 0.0)

    future = df.iloc[breakout_idx + 1: breakout_idx + 1 + 3]
    future_candles_used = int(len(future))
    post_breakout_progress_atr = close_through_atr
    post_breakout_progress_slope = 0.0
    post_breakout_volume_decay = None
    if future_candles_used:
        if is_bullish:
            peak_progress = max((float(future['high'].max()) - breakout_level) / max(atr, 1e-9), 0.0)
        else:
            peak_progress = max((breakout_level - float(future['low'].min())) / max(atr, 1e-9), 0.0)
        post_breakout_progress_atr = max(close_through_atr, peak_progress)
        post_breakout_progress_slope = post_breakout_progress_atr / max(future_candles_used, 1)
        post_breakout_volume_decay = float(future['volume'].mean()) / max(float(breakout_candle['volume']), 1e-9)

    body_score = min(body_ratio / 0.65, 1.0)
    vol_score = min(max(vol_ratio - 1.0, 0.0) / 1.5, 1.0)
    close_score = min(close_through_atr / 0.50, 1.0)
    progress_score = min(post_breakout_progress_atr / 0.75, 1.0)
    decay_score = 0.0
    if post_breakout_volume_decay is not None:
        decay_score = max(0.0, 1.0 - abs(post_breakout_volume_decay - 0.75) / 0.75)

    continuation_strength = float(
        (body_score * 0.25)
        + (vol_score * 0.20)
        + (close_score * 0.25)
        + (progress_score * 0.20)
        + (decay_score * 0.10)
    )
    continuation_confirmed = bool(
        close_through_atr >= 0.05
        and body_ratio >= 0.35
        and vol_ratio >= 1.0
        and continuation_strength >= 0.40
    )

    return {
        'available': True,
        'source': 'candle_breakout_proxy',
        'breakout_age_candles': breakout_age,
        'continuation_confirmed': continuation_confirmed,
        'continuation_strength': round(continuation_strength, 3),
        'body_ratio': round(body_ratio, 3),
        'vol_ratio': round(vol_ratio, 3),
        'close_through_atr': round(close_through_atr, 3),
        'breakout_range_atr': round(breakout_range_atr, 3),
        'post_breakout_progress_atr': round(post_breakout_progress_atr, 3),
        'post_breakout_progress_slope_atr_per_candle': round(post_breakout_progress_slope, 3),
        'post_breakout_volume_decay': round(post_breakout_volume_decay, 3) if post_breakout_volume_decay is not None else None,
        'future_candles_used': future_candles_used,
    }


async def calculate_book_order_flow_imbalance(symbol, trigger_type: str = 'breakout',
                                              tick_size: float = None,
                                              sweep_age_candles: int = 0,
                                              df=None,
                                              sweep_candle_idx: int = None,
                                              breakout_idx: int = None,
                                              breakout_level: float = None,
                                              key_levels: list = None,
                                              atr_value: float = None,
                                              is_bullish: bool = True):
    """
    Wrapper around OrderFlowAnalyzer.analyze() with:

    1. Sweep-age-aware WS window:
       The fundamental problem with a fixed window after sweep detection is
       that the WS captures post-absorption calm, not the absorption event.
       Window selection is now based on how fresh the sweep is:

       sweep_age == 0  → sweep candle is CURRENT (still forming or just closed)
                         WS window = ORDER_FLOW_WINDOW_SWEEP (20s)
                         Live absorption is happening right now.

       sweep_age == 1  → sweep closed 1 candle ago (up to 15 minutes ago on 15m)
                         WS window = ORDER_FLOW_WINDOW_SWEEP (20s)
                         Tail of absorption may still be visible.

       sweep_age >= 2  → sweep is historical. Live WS will show post-absorption calm.
                         WS window = ORDER_FLOW_WINDOW_BREAKOUT (5s) — enough for
                         pressure/imbalance/CVD. Footprint and absorption are stale.
                         Candle-historical absorption fills the gap instead.

       breakout path   → ORDER_FLOW_WINDOW_BREAKOUT (5s) always — momentum
                         confirmation is immediate.

    2. Candle-historical absorption injection:
       For sweep_age >= CANDLE_ABSORPTION_MAX_AGE (2 candles), the live WS
       footprint/absorption data is replaced with evidence derived from the
       sweep candle's OHLCV — wick ratio, volume climax, post-candle decay.
       This is the correct data source for a historical sweep.

    Args:
        sweep_age_candles : int   — how many closed candles since the sweep candle
        df                : DataFrame — needed for candle absorption derivation
        sweep_candle_idx  : int   — position of sweep candle in df
        atr_value         : float — for absorption ratio scaling
        is_bullish        : bool  — sweep direction
    """
    CANDLE_ABSORPTION_MAX_AGE = 2  # candles; beyond this, use candle-historical

    # ── Select WS window based on sweep age ──────────────────────────────
    if trigger_type == 'sweep':
        if sweep_age_candles <= 1:
            window = ORDER_FLOW_WINDOW_SWEEP      # fresh — live absorption visible
        else:
            window = ORDER_FLOW_WINDOW_BREAKOUT   # stale — minimal window, use candle data
    else:
        window = ORDER_FLOW_WINDOW_BREAKOUT

    candle_absorption_proxy = None
    candle_divergence_proxy = None
    breakout_candle_proxy = None
    if trigger_type == 'sweep':
        candle_absorption = compute_candle_absorption(
            df,
            sweep_candle_idx,
            atr_value or 0.0,
            is_bullish,
        ) if df is not None and sweep_candle_idx is not None else {
            'absorbed': False,
            'absorption_strength': 0.0,
            'wick_ratio': 0.0,
            'vol_ratio': 0.0,
            'post_vol_decay': 1.0,
            'body_ratio': 1.0,
            'source': 'candle_historical',
            'sufficient_data': False,
        }
        candle_absorption_proxy = {
            'available': bool(candle_absorption.get('sufficient_data', False)),
            'source': 'candle_historical',
            'sweep_age_candles': int(sweep_age_candles or 0),
            'absorbed': bool(candle_absorption.get('absorbed', False)),
            'absorption_strength': _safe_float(candle_absorption.get('absorption_strength')),
            'wick_ratio': _safe_float(candle_absorption.get('wick_ratio')),
            'vol_ratio': _safe_float(candle_absorption.get('vol_ratio')),
            'post_vol_decay': _safe_float(candle_absorption.get('post_vol_decay')),
            'body_ratio': _safe_float(candle_absorption.get('body_ratio')),
        }
        candle_divergence_proxy = {
            'available': bool(candle_absorption.get('sufficient_data', False)),
            'source': 'candle_historical',
            'sweep_age_candles': int(sweep_age_candles or 0),
            'delta_divergence': bool(candle_absorption.get('absorbed', False)),
            'divergence_strength': _safe_float(candle_absorption.get('absorption_strength')),
            'wick_ratio': _safe_float(candle_absorption.get('wick_ratio')),
            'vol_ratio': _safe_float(candle_absorption.get('vol_ratio')),
            'post_vol_decay': _safe_float(candle_absorption.get('post_vol_decay')),
            'body_ratio': _safe_float(candle_absorption.get('body_ratio')),
        }
        if candle_absorption_proxy.get('available'):
            logger.info(
                f"[{symbol}] Candle-historical sweep proxy recorded separately "
                f"(sweep_age={sweep_age_candles} candles, "
                f"absorbed={candle_absorption_proxy['absorbed']}, "
                f"strength={float(candle_absorption_proxy.get('absorption_strength') or 0.0):.3f}, "
                f"wick={float(candle_absorption_proxy.get('wick_ratio') or 0.0):.2f}, "
                f"vol_ratio={float(candle_absorption_proxy.get('vol_ratio') or 0.0):.2f}, "
                f"post_decay={float(candle_absorption_proxy.get('post_vol_decay') or 0.0):.2f})"
            )

    if trigger_type == 'breakout' and df is not None and breakout_idx is not None and breakout_level is not None:
        breakout_candle_proxy = compute_breakout_candle_proxy(
            df,
            breakout_idx,
            breakout_level,
            atr_value or 0.0,
            is_bullish,
        )
        if breakout_candle_proxy.get('available'):
            logger.info(
                f"[{symbol}] Candle breakout proxy recorded separately "
                f"(age={int(breakout_candle_proxy.get('breakout_age_candles') or 0)} candles, "
                f"confirmed={breakout_candle_proxy.get('continuation_confirmed')}, "
                f"strength={float(breakout_candle_proxy.get('continuation_strength') or 0.0):.3f}, "
                f"body={float(breakout_candle_proxy.get('body_ratio') or 0.0):.2f}, "
                f"vol_ratio={float(breakout_candle_proxy.get('vol_ratio') or 0.0):.2f}, "
                f"close_through_atr={float(breakout_candle_proxy.get('close_through_atr') or 0.0):.2f}, "
                f"progress_atr={float(breakout_candle_proxy.get('post_breakout_progress_atr') or 0.0):.2f})"
            )

    if bool(SIGNAL_CONFIG.get('enable_websocket_orderflow_confirmation', False)) and bool(
        SIGNAL_CONFIG.get("enable_continuous_orderflow_manager", True)
    ):
        lookback_seconds = (
            SIGNAL_CONFIG.get("of_sweep_lookback_seconds", ORDER_FLOW_WINDOW_SWEEP)
            if trigger_type == "sweep"
            else SIGNAL_CONFIG.get("of_breakout_lookback_seconds", ORDER_FLOW_WINDOW_BREAKOUT)
        )
        event_lookback_seconds = (
            SIGNAL_CONFIG.get("of_sweep_event_lookback_seconds", max(ORDER_FLOW_WINDOW_SWEEP, 300))
            if trigger_type == "sweep"
            else SIGNAL_CONFIG.get("of_breakout_event_lookback_seconds", max(ORDER_FLOW_WINDOW_BREAKOUT, 180))
        )
        try:
            cached_result = await get_orderflow_snapshot(
                symbol,
                trigger_type=trigger_type,
                lookback_seconds=lookback_seconds,
                event_lookback_seconds=event_lookback_seconds,
                key_levels=key_levels,
            )
            if isinstance(cached_result, dict):
                cached_result = dict(cached_result)
                cached_result['sweep_age_candles'] = int(sweep_age_candles or 0)
                cached_result['candle_absorption_proxy'] = candle_absorption_proxy
                cached_result['candle_divergence_proxy'] = candle_divergence_proxy
                cached_result['breakout_candle_proxy'] = breakout_candle_proxy

                # Ensure the payload used for confirmation is enriched with canonical coverage
                # and a clear live_orderflow_source if possible. This avoids cases where callers
                # build partial fresh_of payloads (books present) but lack coverage/source and
                # confirmation logs 'source=unknown'. Prefer explicit coverage from the snapshot
                # when available, otherwise compute coverage from the manager.
                try:
                    cov = _orderflow_coverage_from_payload(cached_result)
                    if not isinstance(cov, dict) or not cov:
                        # Query manager for canonical coverage as fallback
                        try:
                            mgr = get_orderflow_manager()
                            cov = mgr._coverage(symbol, lookback_seconds=lookback_seconds, event_lookback_seconds=event_lookback_seconds)
                        except Exception:
                            cov = {}
                    if isinstance(cov, dict) and cov:
                        cached_result['coverage'] = cov
                        if not cached_result.get('live_orderflow_source'):
                            cached_result['live_orderflow_source'] = 'live_ws_continuous' if cov.get('ws_available') else 'live_ws_continuous_unavailable'
                except Exception:
                    # Best-effort enrichment — do not fail signal generation on errors here
                    pass

                return cached_result
        except Exception as exc:
            logger.warning(f"[{symbol}] Continuous orderflow snapshot failed: {exc}")
            if not bool(SIGNAL_CONFIG.get("of_allow_point_in_time_fallback", False)):
                return {
                    'buy_pressure': 50, 'sell_pressure': 50,
                    'signal': None, 'imbalance': 0.0,
                    'start_imbalance': 0.0, 'end_imbalance': 0.0,
                    'imbalance_slope_per_snapshot': 0.0,
                    'buy_pressure_slope_per_snapshot': 0.0,
                    'sell_pressure_slope_per_snapshot': 0.0,
                    'cvd_slope_per_trade': 0.0,
                    'cvd_intensity_delta_halves': 0.0,
                    'aggression_ratio_delta_halves': 0.0,
                    'live_orderflow_source': 'live_ws_continuous_exception',
                    'live_orderflow_window_seconds': int(lookback_seconds or 0),
                    'event_lookback_seconds': int(event_lookback_seconds or 0),
                    'sweep_age_candles': int(sweep_age_candles or 0),
                    'candle_absorption_proxy': candle_absorption_proxy,
                    'candle_divergence_proxy': candle_divergence_proxy,
                    'breakout_candle_proxy': breakout_candle_proxy,
                    'ws_diagnostics': {
                        'enabled': True,
                        'status': 'live_ws_continuous_exception',
                        'source': 'live_ws_continuous',
                        'error': str(exc),
                    },
                    'reject_reason': 'Continuous orderflow unavailable',
                    'websocket_orderflow_optional': False,
                    'fail_closed': True,
                }
        if not bool(SIGNAL_CONFIG.get("of_allow_point_in_time_fallback", False)):
            return {
                'buy_pressure': 50, 'sell_pressure': 50,
                'signal': None, 'imbalance': 0.0,
                'start_imbalance': 0.0, 'end_imbalance': 0.0,
                'imbalance_slope_per_snapshot': 0.0,
                'buy_pressure_slope_per_snapshot': 0.0,
                'sell_pressure_slope_per_snapshot': 0.0,
                'cvd_slope_per_trade': 0.0,
                'cvd_intensity_delta_halves': 0.0,
                'aggression_ratio_delta_halves': 0.0,
                'live_orderflow_source': 'live_ws_continuous_unavailable',
                'live_orderflow_window_seconds': int(lookback_seconds or 0),
                'event_lookback_seconds': int(event_lookback_seconds or 0),
                'sweep_age_candles': int(sweep_age_candles or 0),
                'candle_absorption_proxy': candle_absorption_proxy,
                'candle_divergence_proxy': candle_divergence_proxy,
                'breakout_candle_proxy': breakout_candle_proxy,
                'ws_diagnostics': {
                    'enabled': True,
                    'status': 'live_ws_continuous_unavailable',
                    'source': 'live_ws_continuous',
                },
                'reject_reason': 'Continuous orderflow unavailable',
                'websocket_orderflow_optional': False,
                'fail_closed': True,
            }

    if not bool(SIGNAL_CONFIG.get('enable_websocket_orderflow_confirmation', False)):
        return {
            'buy_pressure': 50, 'sell_pressure': 50,
            'signal': None, 'imbalance': 0.0,
            'start_imbalance': 0.0, 'end_imbalance': 0.0,
            'imbalance_slope_per_snapshot': 0.0,
            'buy_pressure_slope_per_snapshot': 0.0,
            'sell_pressure_slope_per_snapshot': 0.0,
            'cvd_slope_per_trade': 0.0,
            'cvd_intensity_delta_halves': 0.0,
            'aggression_ratio_delta_halves': 0.0,
            'live_orderflow_source': 'candle_proxy_only_ws_disabled',
            'live_orderflow_window_seconds': 0,
            'sweep_age_candles': int(sweep_age_candles or 0),
            'candle_absorption_proxy': candle_absorption_proxy,
            'candle_divergence_proxy': candle_divergence_proxy,
            'breakout_candle_proxy': breakout_candle_proxy,
            'ws_diagnostics': {
                'enabled': False,
                'status': 'disabled_by_config',
                'source': 'candle_proxy_only_ws_disabled',
                'window_seconds': 0,
            },
            'websocket_orderflow_optional': True,
            'fail_closed': False,
        }

    try:
        analyzer = OrderFlowAnalyzer(symbol, tick_size=tick_size)
        result = await analyzer.analyze(window_seconds=window, key_levels=key_levels)

        if result and not result.get('error'):
            result = dict(result)
            result['live_orderflow_source'] = 'live_ws'
            result['live_orderflow_window_seconds'] = int(window)
            result['sweep_age_candles'] = int(sweep_age_candles or 0)
            result['candle_absorption_proxy'] = candle_absorption_proxy
            result['candle_divergence_proxy'] = candle_divergence_proxy
            result['breakout_candle_proxy'] = breakout_candle_proxy
            ws_diag = result.get('ws_diagnostics') if isinstance(result.get('ws_diagnostics'), dict) else {}
            ws_diag.update({
                'enabled': True,
                'status': 'live_ws',
                'source': 'live_ws',
                'window_seconds': int(window),
            })
            result['ws_diagnostics'] = ws_diag
            result['websocket_orderflow_optional'] = True
            result['fail_closed'] = False
            return result

        error_reason = (result or {}).get('error', 'unknown')
        ws_diag = (result or {}).get('ws_diagnostics')
        if ws_diag:
            logger.warning(
                f"Advanced order flow failed for {symbol} - optional audit only | "
                f"reason={error_reason} | ws_diag={ws_diag}"
            )
        else:
            logger.warning(
                f"Advanced order flow failed for {symbol} - optional audit only | "
                f"reason={error_reason}"
            )
        return {
            'buy_pressure': 50, 'sell_pressure': 50,
            'signal': None, 'imbalance': 0.0,
            'start_imbalance': 0.0, 'end_imbalance': 0.0,
            'imbalance_slope_per_snapshot': 0.0,
            'buy_pressure_slope_per_snapshot': 0.0,
            'sell_pressure_slope_per_snapshot': 0.0,
            'cvd_slope_per_trade': 0.0,
            'cvd_intensity_delta_halves': 0.0,
            'aggression_ratio_delta_halves': 0.0,
            'live_orderflow_source': 'live_ws_unavailable_optional',
            'live_orderflow_window_seconds': int(window),
            'sweep_age_candles': int(sweep_age_candles or 0),
            'candle_absorption_proxy': candle_absorption_proxy,
            'candle_divergence_proxy': candle_divergence_proxy,
            'breakout_candle_proxy': breakout_candle_proxy,
            'ws_diagnostics': ws_diag or {
                'enabled': True,
                'status': 'live_ws_failed',
                'source': 'live_ws',
                'error': error_reason,
                'window_seconds': int(window),
            },
            'reject_reason': 'Order flow unavailable (WS optional)',
            'websocket_orderflow_optional': True,
            'fail_closed': False
        }
    except Exception as e:
        logger.error(f"Order flow analyzer exception: {e}")
        return {
            'buy_pressure': 50, 'sell_pressure': 50,
            'signal': None, 'imbalance': 0.0,
            'start_imbalance': 0.0, 'end_imbalance': 0.0,
            'imbalance_slope_per_snapshot': 0.0,
            'buy_pressure_slope_per_snapshot': 0.0,
            'sell_pressure_slope_per_snapshot': 0.0,
            'cvd_slope_per_trade': 0.0,
            'cvd_intensity_delta_halves': 0.0,
            'aggression_ratio_delta_halves': 0.0,
            'live_orderflow_source': 'live_ws_exception',
            'live_orderflow_window_seconds': int(window),
            'sweep_age_candles': int(sweep_age_candles or 0),
            'candle_absorption_proxy': candle_absorption_proxy,
            'candle_divergence_proxy': candle_divergence_proxy,
            'breakout_candle_proxy': breakout_candle_proxy,
            'ws_diagnostics': {
                'enabled': True,
                'status': 'live_ws_exception',
                'source': 'live_ws',
                'error': str(e),
                'window_seconds': int(window),
            },
            'reject_reason': 'Order flow unavailable (WS exception optional)',
            'websocket_orderflow_optional': True,
            'fail_closed': False
        }

async def fallback_book_imbalance(symbol):
    book1 = fetch_order_book_depth(symbol)
    if not book1:
        return {'buy_pressure': 50, 'sell_pressure': 50, 'signal': None, 'imbalance': 0.0, 'start_imbalance': 0.0, 'end_imbalance': 0.0, 'imbalance_slope_per_snapshot': 0.0, 'buy_pressure_slope_per_snapshot': 0.0, 'sell_pressure_slope_per_snapshot': 0.0, 'cvd_slope_per_trade': 0.0, 'cvd_intensity_delta_halves': 0.0, 'aggression_ratio_delta_halves': 0.0, 'fallback': True, 'fallback_source': 'snapshot_depth'}
    await asyncio.sleep(1.2)
    book2 = fetch_order_book_depth(symbol)
    if not book2:
        return {'buy_pressure': 50, 'sell_pressure': 50, 'signal': None, 'imbalance': 0.0, 'start_imbalance': 0.0, 'end_imbalance': 0.0, 'imbalance_slope_per_snapshot': 0.0, 'buy_pressure_slope_per_snapshot': 0.0, 'sell_pressure_slope_per_snapshot': 0.0, 'cvd_slope_per_trade': 0.0, 'cvd_intensity_delta_halves': 0.0, 'aggression_ratio_delta_halves': 0.0, 'fallback': True, 'fallback_source': 'snapshot_depth'}
    def compute_imbalance(book):
        bid_vol = sum(q for _, q in book['bids'])
        ask_vol = sum(q for _, q in book['asks'])
        total = bid_vol + ask_vol
        return (bid_vol - ask_vol) / total if total > 0 else 0.0
    imb1 = compute_imbalance(book1)
    imb2 = compute_imbalance(book2)
    if abs(imb1 - imb2) > 0.18:
        return {'buy_pressure': 50, 'sell_pressure': 50, 'signal': None, 'imbalance': 0.0, 'start_imbalance': 0.0, 'end_imbalance': 0.0, 'imbalance_slope_per_snapshot': 0.0, 'buy_pressure_slope_per_snapshot': 0.0, 'sell_pressure_slope_per_snapshot': 0.0, 'cvd_slope_per_trade': 0.0, 'cvd_intensity_delta_halves': 0.0, 'aggression_ratio_delta_halves': 0.0, 'fallback': True, 'fallback_source': 'snapshot_depth'}
    imbalance = (imb1 + imb2) / 2
    buy_pressure = round((imbalance + 1) / 2 * 100)
    sell_pressure = 100 - buy_pressure
    signal = 'BUY' if buy_pressure >= 40 else ('SELL' if sell_pressure >= 40 else None)
    imbalance_slope = float(imb2 - imb1)
    buy_pressure_slope = imbalance_slope * 50.0
    return {
        'buy_pressure': buy_pressure,
        'sell_pressure': sell_pressure,
        'signal': signal,
        'imbalance': imbalance,
        'start_imbalance': round(float(imb1), 4),
        'end_imbalance': round(float(imb2), 4),
        'imbalance_slope_per_snapshot': round(imbalance_slope, 6),
        'buy_pressure_slope_per_snapshot': round(buy_pressure_slope, 6),
        'sell_pressure_slope_per_snapshot': round(-buy_pressure_slope, 6),
        'cvd_slope_per_trade': 0.0,
        'cvd_intensity_delta_halves': 0.0,
        'aggression_ratio_delta_halves': 0.0,
        'fallback': True,
        'fallback_source': 'snapshot_depth'
    }

def detect_wyckoff_pattern(df, higher_tf_data=None, is_bullish=True, lookback=50, min_phase_conf=20,
                           vol_mult_climax=1.5, vol_mult_sos=1.3, range_mult_ar=1.5, min_tests=2,
                           schematic_bonus=10, effort_result_threshold=0.5):
    def _safe_zscore(series: pd.Series) -> pd.Series:
        numeric = pd.to_numeric(series, errors='coerce').replace([np.inf, -np.inf], np.nan).fillna(0.0)
        if len(numeric) < 3:
            return pd.Series(np.zeros(len(numeric)), index=series.index, dtype=float)
        std = float(numeric.std(ddof=0))
        if std <= 1e-12:
            return pd.Series(np.zeros(len(numeric)), index=series.index, dtype=float)
        mean = float(numeric.mean())
        return (numeric - mean) / std

    if len(df) < lookback:
        return None, 0, {'error': 'Insufficient data'}
    recent = df.tail(lookback).copy()
    recent['volume'] = pd.to_numeric(recent['volume'], errors='coerce').replace([np.inf, -np.inf], np.nan).fillna(0.0)
    recent['vol_ma'] = recent['volume'].rolling(5).mean().fillna(1)
    recent['range'] = recent['high'] - recent['low']
    recent['vol_zscore'] = _safe_zscore(recent['volume'])
    prices = np.linspace(recent['low'].min(), recent['high'].max(), 50)
    vol_hist, _ = np.histogram(recent['close'], bins=prices, weights=recent['volume'])
    poc_level = prices[np.argmax(vol_hist)]
    atr_mean = recent.get('ATR', recent['range']).mean()
    adj_lookback = min(len(df), int(lookback * (1 + (atr_mean / recent['close'].mean() if recent['close'].mean() > 0 else 0))))
    recent = df.tail(adj_lookback).copy()
    recent['volume'] = pd.to_numeric(recent['volume'], errors='coerce').replace([np.inf, -np.inf], np.nan).fillna(0.0)
    recent['vol_ma'] = recent['volume'].rolling(5).mean().fillna(1)
    recent['range'] = recent['high'] - recent['low']
    recent['vol_zscore'] = _safe_zscore(recent['volume'])
    phase_breakdown = {}
    pattern_type = None
    total_conf = 0
    schematic_type = 'Core'
    htf_alignment_bonus = 0
    if higher_tf_data:
        htf_trends = [info['trend'] for info in higher_tf_data.values()]
        htf_strengths = [info['strength'] for info in higher_tf_data.values()]
        if is_bullish:
            if 'bearish' in htf_trends or all(s == 'ranging' for s in htf_strengths):
                htf_alignment_bonus = 15
            else:
                return None, 0, {'error': 'HTF misalignment for accumulation'}
        else:
            if 'bullish' in htf_trends or all(s == 'ranging' for s in htf_strengths):
                htf_alignment_bonus = 15
            else:
                return None, 0, {'error': 'HTF misalignment for distribution'}
        phase_breakdown['HTF Alignment'] = htf_alignment_bonus
    if is_bullish:
        sc_candidates = recent[
            (recent['low'] == recent['low'].min()) &
            (recent['vol_zscore'] > vol_mult_climax) &
            (recent['range'] > recent['range'].mean() * 1.2)
        ]
        if sc_candidates.empty:
            return None, 0, phase_breakdown
        sc_idx = sc_candidates.index[0]
        phase_a_conf = 25 if recent.loc[sc_idx, 'volume'] > recent['vol_ma'].mean() * vol_mult_climax else 10
        eff_res_a = recent.loc[sc_idx, 'range'] / recent['range'].mean()
        if eff_res_a < effort_result_threshold:
            phase_a_conf -= 10
        ar_df = recent.loc[sc_idx:]
        ar_high_idx = ar_df['high'].idxmax()
        ar_range = ar_df.loc[ar_high_idx, 'high'] - recent.loc[sc_idx, 'low']
        if ar_range >= recent['range'].mean() * range_mult_ar:
            phase_a_conf += 10
        st_df = ar_df.loc[ar_high_idx:]
        st_lows = st_df['low'].rolling(min_tests).min().dropna()
        if len(st_lows) >= min_tests and (st_lows > recent.loc[sc_idx, 'low']).all():
            phase_a_conf += 10
            if st_df['volume'].mean() < recent.loc[sc_idx, 'volume'] * 0.8:
                phase_a_conf += 5
        phase_breakdown['Phase A (SC+AR+ST)'] = phase_a_conf
        consol_start = ar_high_idx
        consol_df = recent.loc[consol_start:]
        avg_vol_consol = consol_df['vol_ma'].mean()
        lows_series = consol_df['low'].rolling(min_tests).min().dropna()
        if len(lows_series) >= min_tests and lows_series.is_monotonic_increasing:
            phase_b_conf = 30
            up_candles = consol_df[consol_df['close'] > consol_df['open']]
            eff_res_b = up_candles['range'].mean() / consol_df['range'].mean()
            if eff_res_b > effort_result_threshold and up_candles['vol_zscore'].mean() > consol_df['vol_zscore'].mean() * 0.8:
                phase_b_conf += 10
            else:
                phase_b_conf -= 5
        else:
            phase_b_conf = 0
        if avg_vol_consol < recent['vol_ma'].mean() * 0.85:
            phase_b_conf += 10
        if abs(consol_df['close'].mean() - poc_level) / poc_level < 0.02:
            phase_b_conf += 5
        phase_breakdown['Phase B'] = phase_b_conf
        support = consol_df['low'].min()
        springs = consol_df[
            (consol_df['low'] < support) &
            (consol_df['vol_zscore'] < 1.0) &
            (consol_df['close'] > support)
        ]
        phase_c_conf = 0
        if not springs.empty:
            phase_c_conf = 25
            schematic_type = 'Schematic 1'
            phase_c_conf += schematic_bonus
            if len(springs) > 1:
                phase_c_conf += 10
            recovery_strength = (consol_df['close'] - springs['low']) / springs['range']
            eff_res_c = recovery_strength.mean()
            if eff_res_c > effort_result_threshold:
                phase_c_conf += 10
            else:
                phase_c_conf -= 5
            post_spring = consol_df.loc[springs.index[-1]:]
            if post_spring['low'].min() >= support:
                phase_c_conf += 10
        else:
            schematic_type = 'Schematic 2'
        phase_breakdown['Phase C (Spring)'] = phase_c_conf
        resistance = consol_df['high'].max()
        breakout_candles = consol_df.tail(10)
        sos = breakout_candles[
            (breakout_candles['close'] > resistance) &
            (breakout_candles['vol_zscore'] > vol_mult_sos)
        ]
        phase_d_conf = 0
        if not sos.empty:
            phase_d_conf = 20
            if breakout_candles['range'].mean() > consol_df['range'].mean() * 1.25:
                phase_d_conf += 10
            eff_res_d = sos['range'].mean() / breakout_candles['range'].mean()
            if eff_res_d > effort_result_threshold:
                phase_d_conf += 10
            else:
                phase_d_conf -= 5
            lps = breakout_candles[
                (breakout_candles['low'] <= resistance) &
                (breakout_candles['volume'] < breakout_candles['vol_ma'].mean() * 0.9)
            ]
            if not lps.empty:
                phase_d_conf += 10
        phase_breakdown['Phase D (SOS/LPS)'] = phase_d_conf
        total_conf = sum(phase_breakdown.values()) + htf_alignment_bonus
        pattern_type = f'wyckoff_accumulation ({schematic_type})'
    else:
        bc_candidates = recent[
            (recent['high'] == recent['high'].max()) &
            (recent['vol_zscore'] > vol_mult_climax) &
            (recent['range'] > recent['range'].mean() * 1.2)
        ]
        if bc_candidates.empty:
            return None, 0, phase_breakdown
        bc_idx = bc_candidates.index[0]
        phase_a_conf = 25 if recent.loc[bc_idx, 'volume'] > recent['vol_ma'].mean() * vol_mult_climax else 10
        eff_res_a = recent.loc[bc_idx, 'range'] / recent['range'].mean()
        if eff_res_a < effort_result_threshold:
            phase_a_conf -= 10
        ar_df = recent.loc[bc_idx:]
        ar_low_idx = ar_df['low'].idxmin()
        ar_range = recent.loc[bc_idx, 'high'] - ar_df.loc[ar_low_idx, 'low']
        if ar_range >= recent['range'].mean() * range_mult_ar:
            phase_a_conf += 10
        st_df = ar_df.loc[ar_low_idx:]
        st_highs = st_df['high'].rolling(min_tests).max().dropna()
        if len(st_highs) >= min_tests and (st_highs < recent.loc[bc_idx, 'high']).all():
            phase_a_conf += 10
            if st_df['volume'].mean() < recent.loc[bc_idx, 'volume'] * 0.8:
                phase_a_conf += 5
        phase_breakdown['Phase A (BC+AR+ST)'] = phase_a_conf
        consol_start = ar_low_idx
        consol_df = recent.loc[consol_start:]
        avg_vol_consol = consol_df['vol_ma'].mean()
        highs_series = consol_df['high'].rolling(min_tests).max().dropna()
        if len(highs_series) >= min_tests and highs_series.is_monotonic_decreasing:
            phase_b_conf = 30
            down_candles = consol_df[consol_df['close'] < consol_df['open']]
            eff_res_b = down_candles['range'].mean() / consol_df['range'].mean()
            if eff_res_b > effort_result_threshold and down_candles['vol_zscore'].mean() > consol_df['vol_zscore'].mean() * 0.8:
                phase_b_conf += 10
            else:
                phase_b_conf -= 5
        else:
            phase_b_conf = 0
        if avg_vol_consol < recent['vol_ma'].mean() * 0.85:
            phase_b_conf += 10
        if abs(consol_df['close'].mean() - poc_level) / poc_level < 0.02:
            phase_b_conf += 5
        phase_breakdown['Phase B'] = phase_b_conf
        resistance = consol_df['high'].max()
        utads = consol_df[
            (consol_df['high'] > resistance) &
            (consol_df['vol_zscore'] < 1.0) &
            (consol_df['close'] < resistance)
        ]
        phase_c_conf = 0
        if not utads.empty:
            phase_c_conf = 25
            schematic_type = 'Schematic 1'
            phase_c_conf += schematic_bonus
            if len(utads) > 1:
                phase_c_conf += 10
            recovery_strength = (utads['high'] - consol_df['close']) / utads['range']
            eff_res_c = recovery_strength.mean()
            if eff_res_c < effort_result_threshold:
                phase_c_conf += 10
            else:
                phase_c_conf -= 5
            post_utad = consol_df.loc[utads.index[-1]:]
            if post_utad['high'].max() <= resistance:
                phase_c_conf += 10
        else:
            schematic_type = 'Schematic 2'
        phase_breakdown['Phase C (UTAD)'] = phase_c_conf
        support = consol_df['low'].min()
        breakdown_candles = consol_df.tail(10)
        sow = breakdown_candles[
            (breakdown_candles['close'] < support) &
            (breakdown_candles['vol_zscore'] > vol_mult_sos)
        ]
        phase_d_conf = 0
        if not sow.empty:
            phase_d_conf = 20
            if breakdown_candles['range'].mean() > consol_df['range'].mean() * 1.25:
                phase_d_conf += 10
            eff_res_d = sow['range'].mean() / breakdown_candles['range'].mean()
            if eff_res_d > effort_result_threshold:
                phase_d_conf += 10
            else:
                phase_d_conf -= 5
            lpsy = breakdown_candles[
                (breakdown_candles['high'] >= support) &
                (breakdown_candles['volume'] < breakdown_candles['vol_ma'].mean() * 0.9)
            ]
            if not lpsy.empty:
                phase_d_conf += 10
        phase_breakdown['Phase D (SOW/LPSY)'] = phase_d_conf
        total_conf = sum(phase_breakdown.values()) + htf_alignment_bonus
        pattern_type = f'wyckoff_distribution ({schematic_type})'
    if total_conf < 70 or phase_breakdown.get('Phase C', 0) < min_phase_conf or phase_breakdown.get('Phase D', 0) < min_phase_conf:
        return None, 0, phase_breakdown
    max_possible = 200
    total_conf = int((total_conf / max_possible) * 100)
    total_conf = min(100, max(0, total_conf))
    phase_breakdown['Schematic'] = schematic_type
    return pattern_type, total_conf, phase_breakdown

def detect_consolidation_break(df, is_bullish=True, symbol_config=None):
    """
    Detect a consolidation zone and confirm its breakout.

    Fixes vs original:
    - Scan window configurable (consolidation_scan_candles, default 20).
    - Rounding uses symbol price_place or ATR-derived precision, not hardcoded 2dp.
    - Zone detection uses swing lows/highs as genuine tested levels, not Counter
      on raw prices which found trend bottoms not consolidation zones.
    - vol_ma uses existing column if available.
    """
    import math
    scan_n = SIGNAL_CONFIG.get("consolidation_scan_candles", 40)  # Fix 8: 40 candles (~10h on 15m) for meaningful zone
    if len(df) < scan_n:
        return None, None, 0

    if symbol_config and "price_place" in symbol_config:
        decimals = int(symbol_config["price_place"])
    else:
        atr_col = next((c for c in [f"ATRr_{SIGNAL_CONFIG.get('atr_period',14)}",
                                     f"ATR_{SIGNAL_CONFIG.get('atr_period',14)}", "ATR"]
                        if c in df.columns and not pd.isna(df[c].iloc[-1])), None)
        atr_val = df[atr_col].iloc[-1] if atr_col else df["close"].iloc[-1] * 0.005
        decimals = max(0, min(8, -int(math.floor(math.log10(max(atr_val, 1e-10)))) + 1))

    recent_df = df.tail(scan_n).copy()

    if is_bullish:
        zone_candidates = recent_df[pd.notna(recent_df["swing_low"])]["swing_low"]
    else:
        zone_candidates = recent_df[pd.notna(recent_df["swing_high"])]["swing_high"]

    if len(zone_candidates) >= 2:
        atr_col = next((c for c in [f"ATRr_{SIGNAL_CONFIG.get('atr_period',14)}",
                                     f"ATR_{SIGNAL_CONFIG.get('atr_period',14)}", "ATR"]
                        if c in df.columns and not pd.isna(df[c].iloc[-1])), None)
        atr_val = df[atr_col].iloc[-1] if atr_col else df["close"].iloc[-1] * 0.005
        tol = atr_val * SIGNAL_CONFIG.get("eq_tolerance_atr_multiple", 0.15)
        levels = sorted(zone_candidates.values)
        clusters, cur = [], [levels[0]]
        for lv in levels[1:]:
            if abs(lv - float(np.mean(cur))) <= tol:
                cur.append(lv)
            else:
                clusters.append(cur)
                cur = [lv]
        clusters.append(cur)
        best       = max(clusters, key=len)
        zone_price = float(np.mean(best))
        num_touches = len(best)
    else:
        col = "low" if is_bullish else "high"
        price_levels = recent_df[col].round(decimals=decimals).values
        price_counts = Counter(price_levels)
        if not price_counts:
            return None, None, 0
        zone_price, num_touches = price_counts.most_common(1)[0]

    last_close = df["close"].iloc[-1]
    vol_ma = df["volume_ma"].iloc[-1] if "volume_ma" in df.columns              else df["volume"].rolling(10).mean().iloc[-1]

    if num_touches >= 2:
        if is_bullish and last_close > zone_price and df["volume"].iloc[-1] > vol_ma * 1.2:
            return "consolidation_breakout_up", zone_price, num_touches
        elif not is_bullish and last_close < zone_price and df["volume"].iloc[-1] > vol_ma * 1.2:
            return "consolidation_breakout_down", zone_price, num_touches

    return None, None, 0

def detect_internal_bar_breakout(df, is_bullish=True, anchor_idx=None):
    """
    Detect an Inside Bar Breakout (IBO).

    Fix 10: anchor_idx parameter added. IBO now examines the 3 candles centered
    on the actual breakout index rather than always df.iloc[-1/-2/-3].
    When breakout was 2 candles ago, the old code checked the wrong 3 candles.

    Pattern: parent = anchor_idx-1, inside = anchor_idx, breakout = anchor_idx+1.
    Falls back to df.iloc[-3/-2/-1] if anchor_idx is None.
    """
    if len(df) < 3:
        return None, None

    if anchor_idx is not None and anchor_idx >= 1 and anchor_idx + 1 < len(df):
        parent   = df.iloc[anchor_idx - 1]
        inside   = df.iloc[anchor_idx]
        breakout = df.iloc[anchor_idx + 1]
    else:
        breakout = df.iloc[-1]
        inside   = df.iloc[-2]
        parent   = df.iloc[-3]

    is_inside = (inside["low"] >= parent["low"] and inside["high"] <= parent["high"])
    if not is_inside:
        return None, None

    vol_mult = SIGNAL_CONFIG.get("bo_volume_multiplier", 1.3)

    if is_bullish and breakout["close"] > parent["high"] and breakout["volume"] > inside["volume"] * vol_mult:
        return "ibo_breakout_up", float(parent["high"])

    if not is_bullish and breakout["close"] < parent["low"] and breakout["volume"] > inside["volume"] * vol_mult:
        return "ibo_breakout_down", float(parent["low"])

    return None, None

def fetch_and_analyze_higher_tf_sync(
    symbol,
    base_interval='15m',
    df_4h_cached=None,
    canonical_4h_trend=None,
    canonical_4h_detail=None,
    canonical_4h_last_bos=None,
    canonical_4h_last_choch=None,
):
    """
    Fetch 1H and 4H MA-direction context plus live HTF indicators.

    Direction is derived from the configured moving-average state on the HTF
    window. Legacy structure/BOS fields are retained only where callers still
    expect those keys for audit compatibility.

    For 4H: reuses df_4h_cached from the level context if provided, avoiding a
    redundant API call. If canonical_4h_trend is supplied, that caller-provided
    MA direction is reused and this function only adds live indicator context.
    For 1H: reuses the optional HTF context cache when enabled; otherwise
    fetches the configured 1H window on demand.

    Returns dict with keys '1H' and '4H', each containing:
        trend    : 'bullish' | 'bearish' | 'ranging'
        strength : 'strong' | 'weak' | 'ranging'
        quality  : 'strong' | 'weak' | 'ranging' (MA direction quality)
        rsi      : float
        rsi_state: 'overbought' | 'oversold' | 'neutral'
        adx      : float
        price    : float
    """
    intervals = ['1H', '4H']
    htf_data  = {}
    limit     = int(SIGNAL_CONFIG.get('htf_candle_limit', 200) or 200)
    op_limit  = int(SIGNAL_CONFIG.get('htf_operational_candle_limit', 200) or 200)
    htf_min_candles = int(SIGNAL_CONFIG.get("htf_min_required_candles", 100) or 100)
    use_full_1h = bool(SIGNAL_CONFIG.get('structure_use_full_history_1h', False))
    use_full_4h = bool(SIGNAL_CONFIG.get('structure_use_full_history_4h', False))
    now = time.time()

    for interval in intervals:
        try:
            # Reuse cached 4H df if available - avoids redundant fetch
            if interval == '4H' and df_4h_cached is not None:
                df_struct = df_4h_cached.copy()
            elif interval == '1H' and use_full_1h:
                ttl_s = SIGNAL_CONFIG.get('htf_1h_cache_ttl_s', 3600)
                deep_limit = SIGNAL_CONFIG.get('htf_1h_deep_candle_limit', limit)
                _cached_1h = _htf_1h_cache.get(symbol)
                if _cache_is_fresh(
                    _cached_1h,
                    ttl_s,
                    interval='1H',
                    refresh_on_new_candle=False,
                ):
                    df_struct = _cached_1h.get('df')
                else:
                    df_struct = fetch_and_prepare_data_sync(symbol, interval, deep_limit, min_candles=htf_min_candles)
                    if (
                        df_struct is not None
                        and not df_struct.empty
                        and _history_cache_is_complete_enough(df_struct, deep_limit, min_candles=htf_min_candles)
                    ):
                        _htf_1h_cache[symbol] = {
                            'df': df_struct,
                            'ts': time.time(),
                            'last_data_ts': _extract_last_df_timestamp_s(df_struct),
                        }
                    elif df_struct is not None and not df_struct.empty:
                        logger.debug(
                            f"[{symbol}] Skipping 1H HTF context cache write: incomplete history "
                            f"({len(df_struct)}/{deep_limit} candles)."
                        )
            else:
                df_struct = fetch_and_prepare_data_sync(symbol, interval, limit, min_candles=htf_min_candles)

            if df_struct is None or df_struct.empty:
                continue

            # Operational candles: fetch a fresh HTF tail for live indicators.
            # If that fetch fails, fall back to the structural dataframe tail so
            # analysis stays resilient.
            df_op = get_operational_df_sync(
                symbol,
                interval,
                op_limit,
                min_candles=min(op_limit, htf_min_candles),
            )
            if df_op is None or df_op.empty:
                if len(df_struct) > op_limit:
                    df_op = df_struct.tail(op_limit).copy()
                else:
                    df_op = df_struct.copy()

            df_op = calculate_all_indicators(df_op)

            # ── Structure classification — clean pivot sequence ───────────────
            # identify_swing_points must run first to populate swing_high/swing_low columns.
            # For 4H: if the caller already computed the canonical structure,
            # reuse it instead of paying for a second identical classification pass.
            if interval == '4H' and canonical_4h_trend is not None:
                structure = canonical_4h_trend
                last_bos = canonical_4h_last_bos
                last_choch = canonical_4h_last_choch
                struct_detail = canonical_4h_detail or {}
            else:
                if interval == '4H':
                    if use_full_4h:
                        _df_cls = df_struct.copy()
                    else:
                        _sc = SIGNAL_CONFIG.get('structure_candles_4h', 100)
                        _df_cls = df_struct.iloc[-_sc:].copy()
                    _df_cls = identify_swing_points(_df_cls)
                else:
                    if use_full_1h:
                        _df_cls = df_struct.copy()
                    else:
                        _sc = SIGNAL_CONFIG.get('structure_candles_1h', 100)
                        _df_cls = df_struct.iloc[-_sc:].copy()
                    _df_cls = identify_swing_points(_df_cls)
                _cms_lookback = (
                    10**9 if ((interval == '4H' and use_full_4h) or (interval == '1H' and use_full_1h))
                    else (SIGNAL_CONFIG.get('structure_lookback_4h', 16) if interval == '4H'
                          else SIGNAL_CONFIG.get('structure_lookback_1h', 20))
                )
                structure, last_bos, last_choch, struct_detail = classify_market_structure(
                    _df_cls,
                    lookback=_cms_lookback,
                )

            # Structure quality from Layer 2
            quality = struct_detail.get(
                'structure_quality',
                'strong' if structure in ('bullish', 'bearish') else 'ranging',
            )

            # Direction authority is the MA stack. Legacy structure remains
            # telemetry only so research can compare the old and new regimes.
            trend = "ranging"

            # ── Supporting indicators ────────────────────────────────────────
            last      = df_op.iloc[-1]
            rsi       = float(last.get('RSI_14', 50))
            adx       = float(last.get('adx', 20))
            strength  = 'strong' if adx > 30 else ('weak' if adx > 20 else 'ranging')
            rsi_state = 'overbought' if rsi > 70 else ('oversold' if rsi < 30 else 'neutral')
            ma_slope_lookback = max(1, int(SIGNAL_CONFIG.get("htf_ma_slope_lookback_candles", 5) or 5))

            def _indicator_slope_per_bar(column):
                if column not in df_op.columns:
                    return None
                series = df_op[column].dropna()
                if len(series) < 2:
                    return None
                bars = min(ma_slope_lookback, len(series) - 1)
                return _safe_float((float(series.iloc[-1]) - float(series.iloc[-1 - bars])) / max(bars, 1))

            macd_fast = SIGNAL_CONFIG.get("macd_fast_period", 12)
            macd_slow = SIGNAL_CONFIG.get("macd_slow_period", 26)
            macd_signal = SIGNAL_CONFIG.get("macd_signal_period", 9)
            macd_line_col = f"MACD_{macd_fast}_{macd_slow}_{macd_signal}"
            macd_signal_col = f"MACDs_{macd_fast}_{macd_slow}_{macd_signal}"
            macd_hist_col = f"MACDh_{macd_fast}_{macd_slow}_{macd_signal}"
            ema_fast = _safe_float(last.get("ema_fast"))
            ema_slow = _safe_float(last.get("ema_slow"))
            ema_fast_slope = _indicator_slope_per_bar("ema_fast")
            ema_slow_slope = _indicator_slope_per_bar("ema_slow")
            macd_line = _safe_float(last.get(macd_line_col))
            macd_signal_value = _safe_float(last.get(macd_signal_col))
            macd_hist = _safe_float(last.get(macd_hist_col))
            macd_hist_slope = _indicator_slope_per_bar(macd_hist_col)
            ma_direction_state = _derive_ma_direction_state(df_op, timeframe=interval)
            trend = str(ma_direction_state.get("trend") or "ranging")
            quality = str(ma_direction_state.get("quality") or quality or "ranging")

            htf_data[interval] = {
                'trend'    : trend,
                'trend_source': 'moving_average',
                'strength' : strength,
                'quality'  : quality,
                'rsi_state': rsi_state,
                'rsi'      : rsi,
                'adx'      : adx,
                'price'    : float(last['close']),
                'ema_fast' : ema_fast,
                'ema_slow' : ema_slow,
                'ema_fast_slope_per_bar': ema_fast_slope,
                'ema_slow_slope_per_bar': ema_slow_slope,
                'macd_line': macd_line,
                'macd_signal': macd_signal_value,
                'macd_hist': macd_hist,
                'macd_hist_slope_per_bar': macd_hist_slope,
                'last_bos' : last_bos,
                'last_choch': last_choch,
                'struct_detail': struct_detail.get('reason', ''),
                'legacy_structure': structure,
                'legacy_structure_quality': struct_detail.get('structure_quality', quality),
                'ma_direction_state': ma_direction_state,
            }
        except Exception as e:
            logger.warning(f"Failed to fetch {interval} data for {symbol}: {str(e)}")
    return htf_data


async def fetch_and_analyze_higher_tf(
    symbol,
    base_interval='15m',
    df_4h_cached=None,
    canonical_4h_trend=None,
    canonical_4h_detail=None,
    canonical_4h_last_bos=None,
    canonical_4h_last_choch=None,
):
    return fetch_and_analyze_higher_tf_sync(
        symbol,
        base_interval=base_interval,
        df_4h_cached=df_4h_cached,
        canonical_4h_trend=canonical_4h_trend,
        canonical_4h_detail=canonical_4h_detail,
        canonical_4h_last_bos=canonical_4h_last_bos,
        canonical_4h_last_choch=canonical_4h_last_choch,
    )

def analyze_volatility_clusters(df, window=10):
    if len(df) < window:
        return {'current': 'normal', 'trend': 'stable', 'score': 50}
    df['range'] = df['high'] - df['low']
    volatility_window = df['range'].tail(window)
    current_vol = df['range'].iloc[-1]
    avg_vol = volatility_window.mean()
    prev_avg_vol = df['range'].iloc[-window-5:-5].mean()
    current_state = 'high' if current_vol > avg_vol * 1.2 else ('low' if current_vol < avg_vol * 0.8 else 'normal')
    trend = 'increasing' if avg_vol > prev_avg_vol else 'decreasing'
    score = int((current_vol / avg_vol) * 100) if avg_vol > 0 else 50
    return {'current': current_state, 'trend': trend, 'score': min(100, score)}

def confirm_with_indicators(df, signal_direction):
    last_candle = df.iloc[-1]
    confluence_points = 0
    rationale_list = []
    rsi_col = f'RSI_{SIGNAL_CONFIG.get("rsi_period")}'
    macd_line_col = f'MACD_{SIGNAL_CONFIG["macd_fast_period"]}_{SIGNAL_CONFIG["macd_slow_period"]}_{SIGNAL_CONFIG["macd_signal_period"]}'
    macd_signal_col = f'MACDs_{SIGNAL_CONFIG["macd_fast_period"]}_{SIGNAL_CONFIG["macd_slow_period"]}_{SIGNAL_CONFIG["macd_signal_period"]}'
    bbu_col, bbl_col = get_bb_column_names(df, SIGNAL_CONFIG["bb_period"], SIGNAL_CONFIG["bb_std_dev"])
    if bbu_col is None or bbl_col is None:
        return 0, []
    volatility = df['ATR'].iloc[-1] / last_candle['close']
    is_trending = df['adx'].iloc[-1] > SIGNAL_CONFIG['adx_threshold']
    rsi_threshold_oversold = SIGNAL_CONFIG.get("rsi_threshold_oversold", 35)
    rsi_threshold_overbought = SIGNAL_CONFIG.get("rsi_threshold_overbought", 65)
    macd_threshold = 0.5 * volatility
    bb_threshold = 1.0 if is_trending else 1.5
    if pd.notna(last_candle.get(rsi_col)):
        if signal_direction == "BUY" and last_candle[rsi_col] < rsi_threshold_oversold:
            confluence_points += 1
            rationale_list.append(f"RSI oversold ({last_candle[rsi_col]:.2f})")
        elif signal_direction == "SELL" and last_candle[rsi_col] > rsi_threshold_overbought:
            confluence_points += 1
            rationale_list.append(f"RSI overbought ({last_candle[rsi_col]:.2f})")
    if pd.notna(last_candle.get(macd_line_col)) and pd.notna(last_candle.get(macd_signal_col)):
        # Accept crossover within last 3 candles (not just the last candle)
        mw = df[[macd_line_col, macd_signal_col]].iloc[-4:].dropna()
        bull_cross = any(
            mw[macd_line_col].iloc[i] <= mw[macd_signal_col].iloc[i] and
            mw[macd_line_col].iloc[i+1] > mw[macd_signal_col].iloc[i+1]
            for i in range(len(mw) - 1)
        )
        bear_cross = any(
            mw[macd_line_col].iloc[i] >= mw[macd_signal_col].iloc[i] and
            mw[macd_line_col].iloc[i+1] < mw[macd_signal_col].iloc[i+1]
            for i in range(len(mw) - 1)
        )
        if signal_direction == "BUY" and bull_cross and            last_candle[macd_line_col] > last_candle[macd_signal_col] + macd_threshold:
            confluence_points += 1
            rationale_list.append("MACD bullish crossover (last 3 bars)")
        elif signal_direction == "SELL" and bear_cross and              last_candle[macd_line_col] < last_candle[macd_signal_col] - macd_threshold:
            confluence_points += 1
            rationale_list.append("MACD bearish crossover (last 3 bars)")
    if 'volume_ma' in df.columns and last_candle['volume_ma'] > 0:
        if last_candle['volume'] > last_candle['volume_ma'] * SIGNAL_CONFIG.get("volume_confirmation_multiplier"):
            confluence_points += 2
            rationale_list.append("Volume spike detected")
    if bbu_col and bbl_col:
        # BUY: price near LOWER band (was wrongly checking upper band)
        # SELL: price near UPPER band (correct)
        if signal_direction == "BUY" and last_candle["low"] <= df[bbl_col].iloc[-1] * bb_threshold:
            confluence_points += 1
            rationale_list.append("Price at/near lower BB")
        elif signal_direction == "SELL" and last_candle["high"] >= df[bbu_col].iloc[-1] * bb_threshold:
            confluence_points += 1
            rationale_list.append("Price at/near upper BB")
    if "vwap" in df.columns and pd.notna(last_candle["vwap"]):
        vwap = last_candle["vwap"]
        # Accept both: price on correct side (reversal) or crossing in direction (breakout)
        if signal_direction == "BUY" and last_candle["close"] <= vwap:
            confluence_points += 1
            rationale_list.append("Price at/below VWAP (mean-reversion support)")
        elif signal_direction == "BUY" and last_candle["close"] > vwap              and "vwap" in df.columns and df["close"].iloc[-2] <= df["vwap"].iloc[-2]:
            confluence_points += 1
            rationale_list.append("Price crossed above VWAP (breakout momentum)")
        elif signal_direction == "SELL" and last_candle["close"] >= vwap:
            confluence_points += 1
            rationale_list.append("Price at/above VWAP (mean-reversion resistance)")
        elif signal_direction == "SELL" and last_candle["close"] < vwap              and "vwap" in df.columns and df["close"].iloc[-2] >= df["vwap"].iloc[-2]:
            confluence_points += 1
            rationale_list.append("Price crossed below VWAP (breakout momentum)")
    fib_levels = calculate_fibonacci_levels(df)
    current_price = last_candle['close']
    if any(abs(current_price - level) / level < SIGNAL_CONFIG['fib_tolerance'] for level in fib_levels.values()):
        confluence_points += 1
        rationale_list.append("Near Fibonacci level")
    return confluence_points, rationale_list

def confirm_with_candlesticks(df, is_bullish):
    """
    Confirm signal direction via candlestick pattern.

    Fixes vs original:
    - Engulfing uses abs() consistently on both candle bodies.
    - Scans last 2 candles so a valid pattern 1 bar ago is not missed.
    - Morning Star / Evening Star three-candle patterns added.
    """
    if len(df) < 3:
        return None

    pin_bar_body_ratio = SIGNAL_CONFIG.get("pin_bar_body_ratio", 0.1)
    pin_bar_wick_ratio = SIGNAL_CONFIG.get("pin_bar_wick_ratio", 0.5)

    for offset in [0, 1]:
        if len(df) < 3 + offset:
            continue
        c0 = df.iloc[-(1 + offset)]
        c1 = df.iloc[-(2 + offset)]
        c2 = df.iloc[-(3 + offset)]

        rng      = c0["high"] - c0["low"]
        body     = abs(c0["close"] - c0["open"])
        c1_body  = abs(c1["close"] - c1["open"])
        c2_body  = abs(c2["close"] - c2["open"])

        if is_bullish:
            if (c0["open"] < c1["close"] and c0["close"] > c1["open"] and
                c0["close"] > c0["open"] and body > c1_body):
                return "Bullish Engulfing"
            if (rng > 0 and body < rng * pin_bar_body_ratio and
                (min(c0["open"], c0["close"]) - c0["low"]) > rng * pin_bar_wick_ratio):
                return "Bullish Pin Bar"
            if (c2["close"] < c2["open"] and c1_body < c2_body * 0.5 and
                c0["close"] > c0["open"] and body > c2_body * 0.5):
                return "Morning Star"
        else:
            if (c0["open"] > c1["close"] and c0["close"] < c1["open"] and
                c0["close"] < c0["open"] and body > c1_body):
                return "Bearish Engulfing"
            if (rng > 0 and body < rng * pin_bar_body_ratio and
                (c0["high"] - max(c0["open"], c0["close"])) > rng * pin_bar_wick_ratio):
                return "Bearish Pin Bar"
            if (c2["close"] > c2["open"] and c1_body < c2_body * 0.5 and
                c0["close"] < c0["open"] and body > c2_body * 0.5):
                return "Evening Star"

    return None

def calculate_sl_tp(entry_price, signal_direction, atr_value, df, price_place,
                    swept_level=None,
                    trigger_type='breakout',
                    acceptance_low=None,
                    acceptance_high=None):
    """Calculate trigger-aware stop-loss, take-profits, and trailing activation."""
    if not isinstance(entry_price, (int, float)) or entry_price <= 0:
        return None, None, None, None
    if not isinstance(atr_value, (int, float)) or atr_value <= 0:
        return None, None, None, None

    fallback_sl_percent = SIGNAL_CONFIG.get("fallback_sl_percent", 0.01)
    structure_lookback = int(SIGNAL_CONFIG.get("sl_breakout_structure_lookback", 10) or 10)
    buffer_percent = SIGNAL_CONFIG.get("fallback_buffer_percent", 0.005)
    max_risk_pct = _safe_float(SIGNAL_CONFIG.get("max_risk_percent", 0.02), 0.02) or 0.02
    sweep_atr_buffer = SIGNAL_CONFIG.get("sl_sweep_atr_buffer", 0.6)
    atr_sl_multiplier = SIGNAL_CONFIG.get("atr_sl_multiplier", 1.5)
    breakout_atr_buffer = SIGNAL_CONFIG.get("sl_breakout_atr_buffer", 0.6)
    breakout_min_risk_atr = SIGNAL_CONFIG.get("sl_breakout_min_risk_atr", 1.5)
    is_sweep = trigger_type == 'sweep' and swept_level is not None

    def _valid_price(value):
        numeric = _safe_float(value)
        return numeric if numeric is not None and numeric > 0 else None

    def _recent_structure_extreme(column, reducer):
        if df is None or column not in getattr(df, "columns", []):
            return None
        try:
            series = df[column].dropna().tail(structure_lookback)
            if series.empty:
                return None
            return _valid_price(reducer(series))
        except Exception:
            return None

    if signal_direction == "BUY":
        if is_sweep:
            invalidation_anchor = _valid_price(swept_level)
            if invalidation_anchor is None:
                return None, None, None, None
            buffer = max(invalidation_anchor * buffer_percent, atr_value * sweep_atr_buffer)
            sl = invalidation_anchor - buffer
            min_risk = max(entry_price * fallback_sl_percent, atr_value * atr_sl_multiplier)
            sl = min(sl, entry_price - min_risk)
        else:
            acceptance_low = _safe_float(acceptance_low)
            if acceptance_low is not None and acceptance_low > 0:
                buffer = max(acceptance_low * buffer_percent, atr_value * breakout_atr_buffer)
                sl = acceptance_low - buffer
            elif df is not None:
                structure_low = df["low"].tail(structure_lookback).min()
                buffer = max(structure_low * buffer_percent, atr_value * breakout_atr_buffer)
                sl = structure_low - buffer
            else:
                sl = entry_price * (1 - fallback_sl_percent * 1.5)
            min_risk = max(entry_price * fallback_sl_percent, atr_value * breakout_min_risk_atr)
            sl = min(sl, entry_price - min_risk)

        risk = abs(entry_price - sl)
        if risk <= 0:
            sl = entry_price * (1 - fallback_sl_percent)
            risk = entry_price - sl
        max_risk = entry_price * max_risk_pct
        if max_risk > 0 and risk > max_risk:
            sl = entry_price - max_risk
            risk = max_risk
        tp1 = entry_price + (risk * SIGNAL_CONFIG.get("tp1_rr_multiplier", 1.0))
        tp2 = entry_price + (risk * SIGNAL_CONFIG.get("tp2_rr_multiplier", 1.0))

    else:
        if is_sweep:
            invalidation_anchor = _valid_price(swept_level)
            if invalidation_anchor is None:
                return None, None, None, None
            buffer = max(invalidation_anchor * buffer_percent, atr_value * sweep_atr_buffer)
            sl = invalidation_anchor + buffer
            min_risk = max(entry_price * fallback_sl_percent, atr_value * atr_sl_multiplier)
            sl = max(sl, entry_price + min_risk)
        else:
            acceptance_high = _safe_float(acceptance_high)
            if acceptance_high is not None and acceptance_high > 0:
                buffer = max(acceptance_high * buffer_percent, atr_value * breakout_atr_buffer)
                sl = acceptance_high + buffer
            elif df is not None:
                structure_high = df["high"].tail(structure_lookback).max()
                buffer = max(structure_high * buffer_percent, atr_value * breakout_atr_buffer)
                sl = structure_high + buffer
            else:
                sl = entry_price * (1 + fallback_sl_percent * 1.5)
            min_risk = max(entry_price * fallback_sl_percent, atr_value * breakout_min_risk_atr)
            sl = max(sl, entry_price + min_risk)

        risk = abs(sl - entry_price)
        if risk <= 0:
            sl = entry_price * (1 + fallback_sl_percent)
            risk = sl - entry_price
        max_risk = entry_price * max_risk_pct
        if max_risk > 0 and risk > max_risk:
            sl = entry_price + max_risk
            risk = max_risk
        tp1 = entry_price - (risk * SIGNAL_CONFIG.get("tp1_rr_multiplier", 1.0))
        tp2 = entry_price - (risk * SIGNAL_CONFIG.get("tp2_rr_multiplier", 1.0))

    trailing_sl = tp1
    return (
        round(sl, price_place),
        round(tp1, price_place),
        round(tp2, price_place),
        round(trailing_sl, price_place),
    )

def validate_confluence(confluence_points, rationale_list, min_confluence_points):
    if len(rationale_list) != confluence_points:
        logger.warning(f"Confluence mismatch: {confluence_points} vs {len(rationale_list)} items")
    return confluence_points >= min_confluence_points

async def place_trade(signal):
    """Place a market order, then attach TP/SL from the actual Bitget fill price."""
    global last_cache_clear
    logger.debug(f"Value of last_cache_clear before check: {last_cache_clear}")
    signal = signal or {}
    raw_symbol = str(signal.get('symbol') or '')
    if not raw_symbol:
        return {
            'placed': False,
            'reason_code': 'missing_symbol',
            'reason_text': 'Signal missing symbol',
        }

    placement_time = _utc_now_dt()
    base_trade_value = float(TRADE_CONFIG.get('fixed_trade_amount', 10.0))
    initial_entry_price = float(signal.get('entry_price') or 0.0)
    initial_leverage = int(TRADE_CONFIG.get('leverage', 20))

    def _result(placed, reason_code, reason_text, **extra):
        payload = {
            'placed': bool(placed),
            'reason_code': reason_code,
            'reason_text': reason_text,
            'symbol': raw_symbol,
        }
        payload.update(extra)
        return payload

    try:
        symbol = raw_symbol
        symbol = symbol.replace('_UMCBL', '').lower()
        product_type = 'USDT-FUTURES'
        margin_coin = 'USDT'
        original_direction = str(signal.get('direction', '')).strip().upper()
        direction = 'BUY' if original_direction == 'BUY' else 'SELL'
        # direction = signal['direction']
        logger.info(f"[{symbol}] SIGNAL INVERTED: generated={original_direction} → trading={direction}")
        entry_price = initial_entry_price
        leverage = initial_leverage
        require_market_meta = bool(SIGNAL_CONFIG.get("require_fresh_market_meta_before_trade", True))
        if (
            require_market_meta
            or _quant_live_filter_enabled()
            or bool(SIGNAL_CONFIG.get("enable_quant_hard_block_recommendations", False))
        ):
            try:
                market_meta_audit_fields = _build_fresh_market_meta_audit_context(signal)
            except Exception as market_meta_exc:
                logger.warning(f"[{symbol}] Market meta fetch failed before placement safety checks: {market_meta_exc}")
                market_meta_audit_fields = {
                    "market_meta_available": False,
                    "market_meta_source": "fresh_before_placement_safety_checks",
                    "market_meta_fetched_at": _utc_now_iso(),
                    "market_meta_fetch_error": str(market_meta_exc),
                    "market_meta_snapshot": _to_json_safe(_market_meta_default_snapshot(symbol)),
                }
            if isinstance(market_meta_audit_fields, dict):
                signal.update(market_meta_audit_fields)
                signal["_market_meta_audit_fields"] = dict(market_meta_audit_fields)
            if require_market_meta and not bool((market_meta_audit_fields or {}).get("market_meta_available")):
                reason_text = (
                    "Fresh market-meta context unavailable before placement; "
                    "trade blocked so outer-context gates do not run on blanks"
                )
                return _result(
                    False,
                    "market_meta_unavailable",
                    reason_text,
                    market_meta_fetch_error=(market_meta_audit_fields or {}).get("market_meta_fetch_error"),
                )
        context_risk = _compute_context_risk_profile(signal)
        signal['context_risk_multiplier'] = context_risk.get('multiplier', 1.0)
        signal['context_risk_tier'] = context_risk.get('tier')
        signal['context_risk_reasons'] = list(context_risk.get('reasons', []))
        if context_risk.get('blocked'):
            _record_live_execution_quality(
                signal,
                event_type='risk_control',
                event_status='blocked',
                event_reason=context_risk.get('reason_code'),
                reason_text=context_risk.get('reason_text'),
                base_trade_value=base_trade_value,
                context_trade_value=0.0,
                context_risk_multiplier=context_risk.get('multiplier'),
                context_risk_tier=context_risk.get('tier'),
            )
            _record_live_rejected_shadow(
                signal,
                rejection_stage='live_risk_control',
                rejection_reason_code=context_risk.get('reason_code') or 'risk_control_blocked',
                rejection_reason_text=context_risk.get('reason_text') or 'Blocked by live risk controls',
                decision_candle_time=placement_time,
                entry_price_override=entry_price or signal.get('entry_price'),
                atr_value=signal.get('atr_value'),
                price_place=signal.get('price_place'),
            )
            _record_live_trade_audit(
                signal,
                audit_status='blocked_risk_control',
                audit_reason_code=context_risk.get('reason_code') or 'risk_control_blocked',
                audit_reason_text=context_risk.get('reason_text') or 'Blocked by live risk controls',
                requested_entry_price=entry_price or signal.get('entry_price'),
                placement_time=placement_time,
                trade_value=0.0,
                leverage=leverage,
                extra_fields={
                    'base_trade_value': base_trade_value,
                    'context_trade_value': 0.0,
                },
            )
            return _result(
                False,
                context_risk.get('reason_code') or 'risk_control_blocked',
                context_risk.get('reason_text') or 'Blocked by live risk controls',
            )

        trade_value = round(base_trade_value, 4)
        _record_live_execution_quality(
            signal,
            event_type='risk_control',
            event_status='applied',
            event_reason='fixed_sizing',
            base_trade_value=base_trade_value,
            context_trade_value=trade_value,
            context_risk_multiplier=context_risk.get('multiplier'),
            context_risk_tier=context_risk.get('tier'),
        )

        def _log_failure(reason_code, reason_text, *, event_type='placement', event_status='failed', extra_fields=None):
            details = dict(extra_fields or {})
            _record_live_execution_quality(
                signal,
                event_type=event_type,
                event_status=event_status,
                event_reason=reason_code,
                reason_text=reason_text,
                **details,
            )
            _record_live_trade_audit(
                signal,
                audit_status='placement_failed',
                audit_reason_code=reason_code,
                audit_reason_text=reason_text,
                requested_entry_price=entry_price or signal.get('entry_price'),
                placement_time=placement_time,
                trade_value=details.get('trade_value', trade_value),
                leverage=details.get('leverage', leverage),
                extra_fields={
                    'base_trade_value': base_trade_value,
                    'context_trade_value': trade_value,
                    **details,
                },
            )
            return _result(False, reason_code, reason_text, **details)

        logger.debug(f"Processing trade for {symbol}, direction: {direction}, entry: {entry_price:.5f}")
        if time.time() - last_cache_clear > 24 * 3600:
            clear_symbol_config_cache()
            last_cache_clear = time.time()
        symbol_config = get_symbol_config(symbol)
        price_place = symbol_config['price_place']
        volume_place = symbol_config['volume_place']
        min_trade_num = symbol_config['min_trade_num']
        size_multiplier = symbol_config['size_multiplier']
        if bool(SIGNAL_CONFIG.get("use_exchange_min_order_size", True)):
            sizing_price = entry_price or initial_entry_price or get_current_price(symbol) or 0.0
            min_trade_value, min_trade_size = _estimate_exchange_min_trade_value(symbol_config, sizing_price)
            if min_trade_value > 0 and min_trade_size > 0:
                trade_value = round(float(min_trade_value), 6)
                signal['sizing_mode'] = 'exchange_minimum'
                signal['exchange_min_trade_value'] = trade_value
                signal['exchange_min_trade_size'] = min_trade_size
                logger.info(
                    f"[{symbol}] Exchange-minimum sizing selected: "
                    f"size={min_trade_size:.{volume_place}f}, notional={trade_value:.6f} USDT "
                    f"at reference price {float(sizing_price):.{price_place}f}"
                )
        account_params = {
            'symbol': symbol,
            'productType': product_type,
            'marginCoin': margin_coin
        }
        resp = make_get_request('/api/v2/mix/account/account', params=account_params)
        logger.debug(f"Account balance response: {resp}")
        if not resp or resp.get('code') != "00000":
            logger.error(f"Failed to get account balance: {resp}")
            return _log_failure(
                'account_balance_fetch_failed',
                'Failed to fetch account balance before placement',
                event_type='account_check',
                extra_fields={'api_response': resp},
            )
        account = resp.get('data', {})
        available = float(account.get('available', 0))
        margin_needed = trade_value / leverage if leverage > 0 else trade_value
        logger.debug(f"Available balance: {available:.2f} USDT, Required: {margin_needed:.2f} USDT")
        if available < margin_needed:
            auto_resize_enabled = bool(SIGNAL_CONFIG.get("enable_balance_auto_resize", False))
            utilization = float(SIGNAL_CONFIG.get("balance_auto_resize_utilization", 0.98) or 0.98)
            resized_trade_value = round(max(0.0, available * leverage * utilization), 4)
            if auto_resize_enabled and resized_trade_value > 0 and resized_trade_value < trade_value:
                logger.info(
                    f"[{symbol}] Auto-resizing trade value from {trade_value:.2f} to {resized_trade_value:.2f} "
                    f"because available balance is {available:.2f} USDT"
                )
                trade_value = resized_trade_value
                margin_needed = trade_value / leverage if leverage > 0 else trade_value
                _record_live_execution_quality(
                    signal,
                    event_type='account_check',
                    event_status='adjusted',
                    event_reason='balance_auto_resize',
                    reason_text='Trade value auto-resized to fit available balance',
                    available_balance=available,
                    margin_needed=margin_needed,
                    resized_trade_value=trade_value,
                    leverage=leverage,
                )
            if available < margin_needed:
                logger.warning(f"Insufficient balance: {available:.2f} USDT < {margin_needed:.2f} USDT required")
                return _log_failure(
                    'insufficient_balance',
                    f"Insufficient balance: {available:.2f} < {margin_needed:.2f}",
                    event_type='account_check',
                    event_status='blocked',
                    extra_fields={
                        'available_balance': available,
                        'margin_needed': margin_needed,
                        'trade_value': trade_value,
                    },
                )
        position_params = {
            'productType': product_type,
            'marginCoin': margin_coin
        }
        resp = make_get_request('/api/v2/mix/position/all-position', params=position_params)
        logger.debug(f"Position check response: {resp}")
        if not resp or resp.get('code') != "00000":
            logger.error(f"Failed to check positions: {resp}")
            return _log_failure(
                'position_check_failed',
                'Failed to inspect open positions before placement',
                event_type='position_check',
                extra_fields={'api_response': resp},
            )
        positions = resp.get('data', [])
        open_positions = [pos for pos in positions if float(pos.get('total', 0)) > 0 and pos.get('symbol').lower() == symbol]
        if open_positions:
            logger.warning(f"Open position already exists for {symbol}: {open_positions}. Skipping new trade.")
            _record_live_execution_quality(
                signal,
                event_type='position_check',
                event_status='blocked',
                event_reason='existing_position',
                existing_positions=open_positions,
            )
            _record_live_trade_audit(
                signal,
                audit_status='skipped_existing_position',
                audit_reason_code='existing_position',
                audit_reason_text='Open position already exists for symbol',
                requested_entry_price=entry_price or signal.get('entry_price'),
                placement_time=placement_time,
                trade_value=trade_value,
                leverage=leverage,
                extra_fields={
                    'base_trade_value': base_trade_value,
                    'context_trade_value': trade_value,
                    'existing_positions': open_positions,
                },
            )
            return _result(False, 'existing_position', 'Open position already exists')
        mode_params = {
            'symbol': symbol,
            'productType': product_type,
            'marginCoin': margin_coin,
            'marginMode': 'isolated'
        }
        resp = make_post_request('/api/v2/mix/account/set-margin-mode', body=mode_params)
        logger.debug(f"Set margin mode response: {resp}")
        if not resp or resp.get('code') != "00000":
            logger.error(f"Failed to set isolated margin mode: {resp}")
            return _log_failure(
                'set_margin_mode_failed',
                'Failed to set isolated margin mode',
                event_type='account_setup',
                extra_fields={'api_response': resp},
            )
        hold_side = 'long' if direction == 'BUY' else 'short'
        lev_params = {
            'symbol': symbol,
            'productType': product_type,
            'marginCoin': margin_coin,
            'leverage': str(leverage),
            'holdSide': hold_side
        }
        resp = make_post_request('/api/v2/mix/account/set-leverage', body=lev_params)
        logger.debug(f"Set leverage response: {resp}")
        if not resp or resp.get('code') != "00000":
            logger.error(f"Failed to set leverage {leverage}: {resp}")
            leverage = 10
            lev_params['leverage'] = '10'
            resp = make_post_request('/api/v2/mix/account/set-leverage', body=lev_params)
            if not resp or resp.get('code') != "00000":
                logger.error(f"Failed to set adjusted leverage 10: {resp}")
                return _log_failure(
                    'set_leverage_failed',
                    'Failed to set leverage for placement',
                    event_type='account_setup',
                    extra_fields={'api_response': resp, 'leverage': leverage},
                )

        # ── Always recalculate SL/TP from live price at placement time ──────────
        # The signal may wait for live execution/account setup. By placement time the price may have
        # drifted significantly from the signal generation price, making the
        # precomputed SL/TP anchored to a stale entry — potentially placing SL
        # dangerously close to (or even through) the current price.
        #
        # Solution: reuse the current operational 15m slice, use the LIVE price
        # as entry, and recalculate geometry with full path-specific context preserved:
        atr_col_name   = f'ATRr_{SIGNAL_CONFIG.get("atr_period", 14)}'
        _trigger_type  = signal.get('trigger_type', 'breakout')
        _swept_level   = signal.get('swept_level')

        # Fetch a fresh 15m operational slice for ATR + structure geometry.
        df_live = get_operational_df_sync(
            symbol,
            SIGNAL_CONFIG['candlestick_interval'],
            SIGNAL_CONFIG.get('operational_15m_candle_limit', SIGNAL_CONFIG.get('candlestick_limit', 600)),
            min_candles=SIGNAL_CONFIG.get('min_required_candles', 50),
        )
        if df_live is None or df_live.empty:
            logger.error(f'[{symbol}] Failed to fetch live candle data for SL/TP recalculation')
            return _log_failure(
                'live_geometry_fetch_failed',
                'Failed to fetch live candle data for placement geometry',
                event_type='geometry_refresh',
            )
        df_live    = calculate_all_indicators(df_live)
        atr_value  = (
            df_live[atr_col_name].iloc[-1]
            if atr_col_name in df_live.columns and not pd.isna(df_live[atr_col_name].iloc[-1])
            else entry_price * SIGNAL_CONFIG.get("fallback_buffer_percent", 0.005)
        )
        signal['atr_value'] = float(atr_value)

        # Use live price as entry for geometry — not the stale signal entry
        live_price = float(get_current_price(symbol) or entry_price)
        if live_price > 0:
            entry_price = live_price
            logger.info(f'[{symbol}] SL/TP recalculated from live price {entry_price:.{price_place}f} (was {signal.get("entry_price", "?"):.{price_place}f})')

        sl, tp1, tp2, trailing_sl = calculate_sl_tp(
            entry_price, direction, atr_value, df_live, price_place,
            swept_level                 = _swept_level,
            trigger_type                = _trigger_type,
        )
        if sl is None or tp1 is None or tp2 is None:
            logger.error(f'[{symbol}] SL/TP recalculation failed at placement time — aborting trade')
            return _log_failure(
                'live_geometry_recalc_failed',
                'Failed to recalculate live SL/TP before placement',
                event_type='geometry_refresh',
                extra_fields={'entry_price_live': entry_price},
            )

        logger.info(
            f"[{symbol}] Pre-fill trade geometry: SL={sl:.{price_place}f}, "
            f"TP1={tp1:.{price_place}f}, TP2={tp2:.{price_place}f} "
            f"(trigger={signal.get('trigger_type', 'unknown')})"
        )
        size = trade_value / entry_price
        size = round(round(size / size_multiplier) * size_multiplier, volume_place)
        if size < min_trade_num:
            logger.warning(f"Calculated size {size} < minimum trade amount {min_trade_num} for {symbol}")
            size = round(ceil(min_trade_num / size_multiplier) * size_multiplier, volume_place)
            trade_value = size * entry_price
            margin_needed = trade_value / leverage if leverage > 0 else trade_value
            if available < margin_needed:
                leverage = min(50, max(1, int(trade_value / max(available, 1e-9))))
                lev_params['leverage'] = str(leverage)
                resp = make_post_request('/api/v2/mix/account/set-leverage', body=lev_params)
                if not resp or resp.get('code') != "00000":
                    logger.error(f"Failed to set adjusted leverage {leverage}: {resp}")
                    return _log_failure(
                        'adjusted_leverage_failed',
                        'Failed to set adjusted leverage for minimum tradable size',
                        event_type='account_setup',
                        extra_fields={'api_response': resp, 'leverage': leverage},
                    )
                margin_needed = trade_value / leverage if leverage > 0 else trade_value
                if available < margin_needed:
                    logger.warning(f"Insufficient balance for adjusted size: {available:.2f} USDT < {margin_needed:.2f} USDT required")
                    return _log_failure(
                        'insufficient_balance_after_min_size',
                        'Insufficient balance after adjusting to exchange minimum size',
                        event_type='account_check',
                        event_status='blocked',
                        extra_fields={
                            'available_balance': available,
                            'margin_needed': margin_needed,
                            'min_trade_num': min_trade_num,
                            'trade_value': trade_value,
                            'leverage': leverage,
                        },
                    )
        logger.debug(f"Final size: {size}, trade value: ${trade_value:.2f}")
        client_oid = str(uuid4())
        order_params = {
            'symbol': symbol,
            'productType': product_type,
            'marginMode': 'isolated',
            'marginCoin': margin_coin,
            'size': f"{size:.{volume_place}f}",
            'side': 'buy' if direction == 'BUY' else 'sell',
            'tradeSide': 'open',
            'orderType': 'market',
            'clientOid': client_oid,
        }
        resp = make_post_request('/api/v2/mix/order/place-order', body=order_params)
        logger.debug(f"Place order response: {resp}")
        if not resp or resp.get('code') != "00000":
            logger.error(f"Failed to place order: {resp}")
            return _log_failure(
                'place_order_failed',
                'Bitget place-order call failed',
                event_type='order_submit',
                extra_fields={'api_response': resp, 'trade_value': trade_value, 'leverage': leverage},
            )
        order_id = resp.get('data', {}).get('orderId')
        logger.info(
            f"Market order placed for {symbol}: clientOid={client_oid}, orderId={order_id}; "
            "waiting for actual fill before placing TP/SL"
        )
        detail_params = {
            'symbol': symbol,
            'productType': product_type,
            'orderId': order_id
        }
        detail_resp = make_get_request('/api/v2/mix/order/detail', params=detail_params)
        logger.debug(f"Order detail response: {detail_resp}")
        actual_fill_price = entry_price
        fill_state = 'unknown'
        if detail_resp and detail_resp.get('code') == "00000":
            order_details = detail_resp.get('data', {})
            fill_state = str(order_details.get('state') or 'unknown')
            if order_details.get('state') == 'filled':
                actual_fill_price = float(_extract_exchange_row_price(order_details, entry_price) or entry_price)
                logger.info(f"Actual fill price: {actual_fill_price:.{price_place}f}")
            else:
                logger.warning("Order not yet filled — trailing stop placement may be inaccurate")
        else:
            fill_state = 'detail_fetch_failed'

        prefill_geometry = {
            'prefill_entry_price': round(entry_price, price_place),
            'prefill_stop_loss': sl,
            'prefill_take_profit_1': tp1,
            'prefill_take_profit_2': tp2,
            'prefill_trailing_stop_loss': trailing_sl,
        }
        fill_retry_attempts = max(1, int(SIGNAL_CONFIG.get('order_detail_fill_retry_attempts', 5) or 5))
        fill_retry_sleep = max(0.2, float(SIGNAL_CONFIG.get('order_detail_fill_retry_sleep_seconds', 1.0) or 1.0))
        for attempt in range(fill_retry_attempts):
            if fill_state == 'filled' and actual_fill_price > 0:
                break
            time.sleep(fill_retry_sleep)
            detail_resp = make_get_request('/api/v2/mix/order/detail', params=detail_params)
            logger.debug(f"Order detail response (post-fill attempt {attempt + 1}/{fill_retry_attempts}): {detail_resp}")
            if detail_resp and detail_resp.get('code') == "00000":
                order_details = detail_resp.get('data', {}) or {}
                fill_state = str(order_details.get('state') or 'unknown')
                parsed_fill = _extract_exchange_row_price(order_details, actual_fill_price)
                if parsed_fill is not None and parsed_fill > 0:
                    actual_fill_price = float(parsed_fill)
            else:
                fill_state = 'detail_fetch_failed'

        if fill_state == 'filled':
            logger.info(f"Actual fill price: {actual_fill_price:.{price_place}f}")
        else:
            logger.warning(
                f"Order not confirmed filled after TP/SL retry loop (state={fill_state}); "
                f"using best available fill estimate {actual_fill_price:.{price_place}f}"
            )

        fill_sl, fill_tp1, fill_tp2, fill_trailing_sl = calculate_sl_tp(
            actual_fill_price, direction, atr_value, df_live, price_place,
            swept_level=_swept_level,
            trigger_type=_trigger_type,
        )
        if fill_sl is not None and fill_tp1 is not None and fill_tp2 is not None:
            sl, tp1, tp2, trailing_sl = fill_sl, fill_tp1, fill_tp2, fill_trailing_sl
            entry_price = actual_fill_price
            logger.info(
                f"[{symbol}] Post-fill trade geometry: entry={entry_price:.{price_place}f}, "
                f"SL={sl:.{price_place}f}, TP1={tp1:.{price_place}f}, TP2={tp2:.{price_place}f}"
            )
        else:
            logger.error(f"[{symbol}] Post-fill SL/TP recalculation failed; using pre-fill emergency geometry")

        tpsl_params = {
            "marginCoin": margin_coin,
            "productType": product_type,
            "symbol": symbol,
            "holdSide": hold_side,
            "stopSurplusTriggerPrice": f"{tp2:.{price_place}f}",
            "stopSurplusTriggerType": "fill_price",
            "stopSurplusExecutePrice": "0",
            "stopSurplusSize": f"{size:.{volume_place}f}",
            "stopSurplusClientOid": f"{client_oid}_tp",
            "stopLossTriggerPrice": f"{sl:.{price_place}f}",
            "stopLossTriggerType": "fill_price",
            "stopLossExecutePrice": "0",
            "stopLossSize": f"{size:.{volume_place}f}",
            "stopLossClientOid": f"{client_oid}_sl",
        }
        tpsl_resp = make_post_request('/api/v2/mix/order/place-pos-tpsl', body=tpsl_params)
        tpsl_order_placed = bool(tpsl_resp and tpsl_resp.get('code') == "00000")
        fallback_tpsl_resp = None

        def _place_single_tpsl(plan_type, trigger_price, suffix):
            params = {
                "marginCoin": margin_coin,
                "productType": product_type,
                "symbol": symbol,
                "planType": plan_type,
                "triggerPrice": f"{trigger_price:.{price_place}f}",
                "triggerType": "fill_price",
                "executePrice": "0",
                "holdSide": hold_side,
                "size": f"{size:.{volume_place}f}",
                "clientOid": f"{client_oid}_{suffix}",
            }
            return make_post_request("/api/v2/mix/order/place-tpsl-order", body=params)

        if not tpsl_order_placed:
            logger.error(f"Combined TP/SL placement failed: {tpsl_resp}; trying individual TP/SL fallback")
            profit_resp = _place_single_tpsl("profit_plan", tp2, "tp_fallback")
            loss_resp = _place_single_tpsl("loss_plan", sl, "sl_fallback")
            fallback_tpsl_resp = {
                "profit_plan": profit_resp,
                "loss_plan": loss_resp,
            }
            tpsl_order_placed = bool(
                profit_resp and profit_resp.get("code") == "00000"
                and loss_resp and loss_resp.get("code") == "00000"
            )

        if tpsl_order_placed:
            logger.info(
                f"Post-fill TP/SL placed for {symbol}: SL={sl:.{price_place}f}, TP={tp2:.{price_place}f}"
            )
        else:
            logger.critical(
                f"[{symbol}] TRADE IS OPEN BUT TP/SL PLACEMENT FAILED. "
                f"Manual protection may be required. combined={tpsl_resp}, fallback={fallback_tpsl_resp}"
            )
        signal['entry_price'] = round(actual_fill_price, price_place)
        signal['stop_loss'] = sl
        signal['take_profit_1'] = tp1
        signal['take_profit_2'] = tp2
        signal['trailing_stop_loss'] = trailing_sl
        signal['price_place'] = price_place
        trail_resp = None
        trail_order_placed = None
        trigger_price = None
        if SIGNAL_CONFIG.get('use_trailing_stop', False):
            callback_pct = SIGNAL_CONFIG.get('trailing_callback_percent', 0.8)
            activation_at_tp1 = bool(SIGNAL_CONFIG.get('trailing_activation_at_tp1', False))
            activation_pct = SIGNAL_CONFIG.get('trailing_activation_percent', 2.5)
            if activation_at_tp1 and trailing_sl is not None:
                trigger_price = round(float(trailing_sl), price_place)
                logger.info(
                    f"Trailing stop activates at TP1 {trigger_price:.{price_place}f} "
                    f"(callback={callback_pct}%)"
                )
            else:
                if direction == 'BUY':
                    trigger_price = actual_fill_price * (1 + activation_pct / 100)
                else:
                    trigger_price = actual_fill_price * (1 - activation_pct / 100)
                trigger_price = round(trigger_price, price_place)
                logger.info(
                    f"Trailing stop activates at {trigger_price:.{price_place}f} "
                    f"({activation_pct}% from fill {actual_fill_price:.{price_place}f}), "
                    f"callback={callback_pct}%"
                )
            trail_params = {
                "marginCoin": margin_coin,
                "productType": product_type,
                "symbol": symbol,
                "planType": "moving_plan",
                "triggerPrice": str(trigger_price),
                "triggerType": "mark_price",
                "rangeRate": f"{callback_pct:.2f}",
                "holdSide": hold_side,
                "size": f"{size:.{volume_place}f}",
                "clientOid": f"{client_oid}_trail"
            }
            trail_resp = make_post_request("/api/v2/mix/order/place-tpsl-order", body=trail_params)
            trail_order_placed = bool(trail_resp and trail_resp.get("code") == "00000")
            if trail_order_placed:
                logger.info(
                    f"Trailing stop placed | trigger ≥ {trigger_price:.{price_place}f} "
                    f"| trails {callback_pct}% behind best price"
                )
            else:
                logger.error(f"Trailing stop placement failed: {trail_resp}")
        _record_live_execution_quality(
            signal,
            event_type='order_submit',
            event_status='placed',
            event_reason='market_order_placed',
            requested_entry_price=prefill_geometry.get('prefill_entry_price', entry_price),
            actual_fill_price=actual_fill_price,
            fill_state=fill_state,
            order_id=order_id,
            client_oid=client_oid,
            size=size,
            trade_value=trade_value,
            leverage=leverage,
            trailing_order_placed=trail_order_placed,
            trailing_trigger_price=trigger_price,
            trailing_response=trail_resp,
            order_detail_response=detail_resp,
            tpsl_order_placed=tpsl_order_placed,
            tpsl_response=tpsl_resp,
            fallback_tpsl_response=fallback_tpsl_resp,
            **prefill_geometry,
        )
        market_meta_audit_fields = signal.get("_market_meta_audit_fields")
        if not isinstance(market_meta_audit_fields, dict):
            try:
                market_meta_audit_fields = _build_fresh_market_meta_audit_context(signal)
            except Exception as market_meta_exc:
                logger.warning(f"[{symbol}] Market meta audit fetch failed: {market_meta_exc}")
                market_meta_audit_fields = {
                    "market_meta_available": False,
                    "market_meta_source": "fresh_on_trade_placement",
                    "market_meta_fetched_at": _utc_now_iso(),
                    "market_meta_fetch_error": str(market_meta_exc),
                    "market_meta_snapshot": _to_json_safe(_market_meta_default_snapshot(symbol)),
                }
        audit_payload = _record_live_trade_audit(
            signal,
            audit_status='placed',
            audit_reason_code='trade_placed',
            audit_reason_text='Trade placed successfully',
            requested_entry_price=prefill_geometry.get('prefill_entry_price', entry_price),
            actual_fill_price=actual_fill_price,
            fill_state=fill_state,
            order_id=order_id,
            client_oid=client_oid,
            size=size,
            trade_value=trade_value,
            leverage=leverage,
            trail_order_placed=trail_order_placed,
            trail_trigger_price=trigger_price,
            placement_time=placement_time,
            extra_fields={
                'base_trade_value': base_trade_value,
                'context_trade_value': trade_value,
                'available_balance': available,
                'margin_needed': margin_needed,
                'order_detail_response_code': detail_resp.get('code') if isinstance(detail_resp, dict) else None,
                'tpsl_order_placed': tpsl_order_placed,
                'tpsl_response_code': tpsl_resp.get('code') if isinstance(tpsl_resp, dict) else None,
                'fallback_tpsl_response': fallback_tpsl_resp,
                'trailing_response_code': trail_resp.get('code') if isinstance(trail_resp, dict) else None,
                **prefill_geometry,
                **market_meta_audit_fields,
            },
        )
        tp15_shadow_payload = _record_live_trade_audit_tp15_shadow(audit_payload)
        signal['entry_price'] = round(actual_fill_price, price_place)
        signal['stop_loss'] = sl
        signal['take_profit_1'] = tp1
        signal['take_profit_2'] = tp2
        signal['trailing_stop_loss'] = trailing_sl
        signal['price_place'] = price_place
        logger.info(f"Trade execution completed for {symbol} ({direction})")
        return _result(
            True,
            'trade_placed',
            'Trade placed successfully',
            order_id=order_id,
            client_oid=client_oid,
            audit_id=audit_payload.get('audit_id') if isinstance(audit_payload, dict) else None,
            tp15_shadow_audit_id=tp15_shadow_payload.get('audit_id') if isinstance(tp15_shadow_payload, dict) else None,
            trade_value=trade_value,
            leverage=leverage,
            size=size,
            actual_fill_price=actual_fill_price,
        )
    except Exception as e:
        logger.error(f"Error placing trade for {symbol}: {str(e)}", exc_info=True)
        _record_live_execution_quality(
            signal,
            event_type='placement',
            event_status='failed',
            event_reason='unhandled_exception',
            error=str(e),
        )
        _record_live_trade_audit(
            signal,
            audit_status='placement_failed',
            audit_reason_code='unhandled_exception',
            audit_reason_text=str(e),
            requested_entry_price=entry_price or signal.get('entry_price'),
            placement_time=placement_time,
            trade_value=base_trade_value,
            leverage=leverage,
            extra_fields={'base_trade_value': base_trade_value},
        )
        return _result(False, 'unhandled_exception', str(e))

def _check_signal_confirmation(df, direction, lookback=5):
    """
    Confirm recent candle structure supports the signal direction.

    Fix vs original:
    - Support/resistance holds tolerance changed from hardcoded 0.1% of close
      (trivially easy — consecutive candles almost always passed) to an
      ATR-relative tolerance from SIGNAL_CONFIG. ATR-based tolerance is
      meaningful across symbols and volatility regimes.
    """
    if len(df) < lookback + 1:
        return True, 0

    recent  = df.iloc[-lookback:]
    atr_col = next((c for c in [f"ATRr_{SIGNAL_CONFIG.get('atr_period',14)}",
                                  f"ATR_{SIGNAL_CONFIG.get('atr_period',14)}", "ATR"]
                    if c in df.columns and not pd.isna(df[c].iloc[-1])), None)
    atr_val = df[atr_col].iloc[-1] if atr_col else df["close"].iloc[-1] * 0.005
    tol     = atr_val * SIGNAL_CONFIG.get("confirmation_lows_tolerance_atr", 0.3)

    if direction == "BUY":
        bullish_count = sum(1 for _, r in recent.iterrows() if r["close"] >= r["open"])
        support_holds = sum(
            1 for i in range(1, len(recent))
            if recent.iloc[i]["low"] >= recent.iloc[i - 1]["low"] - tol
        )
        score = bullish_count + (support_holds / 2)
        return score >= (lookback * 0.6), score
    else:
        bearish_count = sum(1 for _, r in recent.iterrows() if r["close"] <= r["open"])
        resistance_holds = sum(
            1 for i in range(1, len(recent))
            if recent.iloc[i]["high"] <= recent.iloc[i - 1]["high"] + tol
        )
        score = bearish_count + (resistance_holds / 2)
        return score >= (lookback * 0.6), score

# ─── Enhanced Failed Retest Detection (Hard Reject) ─────────────────────────
def detect_recent_failed_breakouts(df, direction, lookback=96, post_window=10,
                                  atr_multiple_tolerance=0.3,
                                  reject_threshold=6):
    """
    Detects recent failed breakouts/retests → HARD REJECT if score meets/exceeds threshold.

    Returns:
        (bool, str): (should_reject, rejection_reason)
    """
    if len(df) < lookback + post_window:
        return False, ""

    atr_value = df['ATR'].iloc[-1] if 'ATR' in df.columns else df['close'].iloc[-1] * 0.005
    tolerance = atr_value * atr_multiple_tolerance

    recent_df = df.tail(lookback + post_window)

    # Collect key levels
    swing_highs = recent_df['swing_high'].dropna().unique()
    swing_lows  = recent_df['swing_low'].dropna().unique()
    eq_highs = recent_df['equal_high_zone'].dropna().unique()
    eq_lows  = recent_df['equal_low_zone'].dropna().unique()

    # Order blocks
    ob_bull = identify_order_block(recent_df, is_bullish=True)
    ob_bear = identify_order_block(recent_df, is_bullish=False)
    order_blocks = []
    if ob_bull and isinstance(ob_bull, tuple) and len(ob_bull) == 2: order_blocks.append(ob_bull)
    if ob_bear and isinstance(ob_bear, tuple) and len(ob_bear) == 2: order_blocks.append(ob_bear)

    # Liquidity sweeps
    liquidity_zones = {'highs': list(swing_highs),
                       'lows':  list(swing_lows)}
    _, swept_level, _ = detect_liquidity_sweep(recent_df, liquidity_zones, symbol='')
    swept_levels = [swept_level] if swept_level else []

    if direction == 'BUY':
        key_levels = [l for l in set(list(swing_lows) + list(eq_lows) +
                                     [ob[0] for ob in order_blocks if ob] +
                                     [l for l in swept_levels if l < recent_df['close'].mean()])]
    else:
        key_levels = [l for l in set(list(swing_highs) + list(eq_highs) +
                                     [ob[1] for ob in order_blocks if ob] +
                                     [l for l in swept_levels if l > recent_df['close'].mean()])]

    if not key_levels:
        return False, ""

    failure_score = 0
    failure_details = []
    levels_checked = 0

    for level in key_levels:
        touches = recent_df[
            (recent_df['low']  <= level + tolerance) &
            (recent_df['high'] >= level - tolerance)
        ].index

        # Need at least 2 touches to have a prior touch + a post window to check.
        # A single touch with no history at the level is not a failure pattern.
        if len(touches) < 2:
            continue

        levels_checked += 1
        level_failures = 0  # failures at this specific level only
        touch_failures = 0  # number of touches that resulted in a failure

        # Check all touches except the last — the last touch IS the current
        # setup we're evaluating, so skipping it is correct. But we need at
        # least one prior touch to have a failure pattern to score.
        for touch_idx in touches[:-1]:
            candle = recent_df.loc[touch_idx]
            touch_pos = recent_df.index.get_loc(touch_idx)
            post_slice = recent_df.iloc[touch_pos + 1 : touch_pos + post_window + 1]

            if direction == 'BUY' and candle['close'] > level:
                reclaims = post_slice[post_slice['close'] < level]
            elif direction == 'SELL' and candle['close'] < level:
                reclaims = post_slice[post_slice['close'] > level]
            else:
                continue

            if reclaims.empty:
                continue

            # Score this touch as ONE failure event, sized by the worst
            # reclaim candle only — not every candle that happened to close
            # through the level. Multiple candles drifting through a level
            # after a failure is one event, not three.
            worst_body_ratio = 0.0
            has_vol_spike = False
            for _, rc in reclaims.iterrows():
                rng = rc['high'] - rc['low']
                if rng > 0:
                    worst_body_ratio = max(worst_body_ratio, abs(rc['close'] - rc['open']) / rng)
                if 'volume_ma' in rc and rc.get('volume_ma', 0) > 0:
                    has_vol_spike = has_vol_spike or (rc['volume'] > rc['volume_ma'] * 1.2)

            if worst_body_ratio < 0.3:
                level_failures += 1
                failure_details.append(f"weak @ {level:.5f}")
            elif worst_body_ratio > 0.6 or has_vol_spike:
                level_failures += 3
                failure_details.append(f"strong @ {level:.5f}")
            else:
                level_failures += 2
                failure_details.append(f"medium @ {level:.5f}")

            touch_failures += 1

        # Cap contribution per level at 6
        failure_score += min(level_failures, 6)

    # Normalize: express as failures-per-level so score is comparable
    # regardless of how many levels were found on the chart
    if levels_checked == 0:
        return False, ""
    normalized_score = failure_score / levels_checked

    if normalized_score >= reject_threshold:
        reason = f"Recent failed structure (normalized score: {normalized_score:.1f}/{reject_threshold})"
        if failure_details:
            reason += f" → {', '.join(set(failure_details))[:140]}..."
        return True, reason

    return False, ""

# ─── 15m Touch-and-Reverse Confirmation ─────────────────────────────────────
def check_15m_touch_reverse(df, direction, swept_level, atr_value):
    """
    Checks whether any of the last N 15m candles touched the swept level
    AND closed back away from it with directional intent.

    This is a 15m structural touch-and-reverse check.
    A full 15m candle that wicked to the swept level and closed away means the
    level held for an entire 15-minute period — structurally stronger than a 5m candle.

    Parameters:
        df           : 15m OHLCV DataFrame with indicators already computed
        direction    : 'BUY' or 'SELL'
        swept_level  : the exact price level that was swept
        atr_value    : current ATR for touch tolerance

    Returns:
        (confirmed: bool, entry_price: float | None, reason: str)
    """
    TOUCH_ATR_MULT = SIGNAL_CONFIG.get('conf_15m_touch_atr',    1.0)   # wider than 5m — 15m wicks are larger
    BODY_RATIO     = SIGNAL_CONFIG.get('conf_15m_body_ratio',   0.30)   # lower than 5m — 15m candles are more complex
    SCAN_CANDLES   = SIGNAL_CONFIG.get('conf_15m_scan_candles', 4)      # 4 × 15m = 60min window

    if df is None or len(df) < 3:
        return False, None, "15m data insufficient"

    touch_tol   = atr_value * TOUCH_ATR_MULT
    scan_window = df.iloc[-SCAN_CANDLES:]
    vol_mean    = df['volume'].tail(20).mean()
    if vol_mean <= 0:
        vol_mean = 1.0

    for i in range(len(scan_window) - 1, -1, -1):
        c       = scan_window.iloc[i]
        c_range = c['high'] - c['low']
        if c_range <= 0:
            continue
        body   = abs(c['close'] - c['open'])
        body_r = body / c_range

        if direction == 'BUY':
            # Wick must have reached the swept level
            touched     = c['low'] <= swept_level + touch_tol and c['low'] >= swept_level - touch_tol * 3
            closed_away = c['close'] > swept_level
            vol_ok      = c['volume'] >= vol_mean * 0.75
            if touched and closed_away and body_r >= BODY_RATIO and vol_ok:
                return True, float(c['close']), (
                    f"15m touch-and-reverse: bullish close above {swept_level:.4f} "
                    f"(body={body_r:.2f}, low={c['low']:.4f}, vol={c['volume']:.0f})"
                )
        else:
            touched     = c['high'] >= swept_level - touch_tol and c['high'] <= swept_level + touch_tol * 3
            closed_away = c['close'] < swept_level
            vol_ok      = c['volume'] >= vol_mean * 0.75
            if touched and closed_away and body_r >= BODY_RATIO and vol_ok:
                return True, float(c['close']), (
                    f"15m touch-and-reverse: bearish close below {swept_level:.4f} "
                    f"(body={body_r:.2f}, high={c['high']:.4f}, vol={c['volume']:.0f})"
                )

    return False, None, (
        f"No 15m touch-and-reverse at {swept_level:.4f} in last {SCAN_CANDLES} candles "
        f"(touch_tol={touch_tol:.4f})"
    )


# ─── Quant-Level Swept-Level-Anchored Divergence ─────────────────────────────
def check_swept_level_divergence(df, direction, swept_level, atr_value, sweep_candle_idx=None):
    """
    Quant-level RSI divergence detection anchored to the exact swept level.

    THREE-MODE ARCHITECTURE — handles the full sweep lifecycle:

    MODE A — FRESH SWEEP (no separate retest candle exists yet):
        The sweep candle IS the current candle (or 1-2 bars ago). No second
        structural touch has occurred. Score is built entirely from:
          • RSI absolute exhaustion depth at the sweep candle
          • Volume z-score of the sweep candle vs recent baseline
          • MACD histogram absolute position and direction
          • Wick quality (extension beyond swept level)
          • Stochastic %K position (additional exhaustion confirmation)
        Threshold can apply a configurable fresh-sweep penalty to compensate
        for absence of inter-bar delta.
        Entry price = current close (sweep candle close).

    MODE B — RETEST EXISTS, SAME BAR AS SWEEP (sweep_candle_idx == retest_pos):
        This happens when the sweep candle itself is the current bar and its
        low/high is still within touch tolerance. We have one candle for both
        anchor points. Score uses RSI absolute depth + wick + volume z-score.
        Same scoring as Mode A but logged distinctly.

    MODE C — RETEST EXISTS, SEPARATE CANDLE (normal two-anchor divergence):
        Classic regular divergence: sweep candle vs later retest candle.
          • RSI delta between anchors (primary, 0–40 pts)
          • Exhaustion zone bonus at sweep RSI
          • Volume ratio sweep/retest (0–20 pts)
          • MACD histogram contraction between anchors (0–20 pts)
          • ROC velocity comparison (0–10 pts)
          • Wick quality at sweep candle (0–10 pts)
        Hidden divergence hard-rejected. Minimum RSI delta enforced.

    In all modes, returns (confirmed: bool, score: int, entry_price: float|None, reason: str)
    Score is always 0–100. Gate caller decides pass/fail vs threshold.
    """
    rsi_period = SIGNAL_CONFIG.get('rsi_period', 14)
    rsi_col    = f'RSI_{rsi_period}'

    stoch_k_col = f'STOCHk_14_3_3'   # standard stochastic %K column name from pandas_ta

    macd_fast   = SIGNAL_CONFIG.get('macd_fast_period',   12)
    macd_slow   = SIGNAL_CONFIG.get('macd_slow_period',   26)
    macd_signal = SIGNAL_CONFIG.get('macd_signal_period',  9)
    macd_h_col  = f'MACDh_{macd_fast}_{macd_slow}_{macd_signal}'

    MIN_RSI_DELTA      = SIGNAL_CONFIG.get(
        'sweep_anchor_divergence_min_rsi_delta',
        SIGNAL_CONFIG.get('div_min_rsi_delta', 5.0),
    )
    MIN_SCORE          = SIGNAL_CONFIG.get(
        'sweep_anchor_divergence_min_score',
        SIGNAL_CONFIG.get(
            'sweep_anchor_divergence_strong_score',
            SIGNAL_CONFIG.get('div_min_score', 60),
        ),
    )
    TOUCH_ATR_MULT     = SIGNAL_CONFIG.get('div_touch_atr',          1.2)
    SWEEP_LOOKBACK     = SIGNAL_CONFIG.get('div_sweep_lookback',     40)
    RETEST_LOOKBACK    = SIGNAL_CONFIG.get('div_retest_lookback',    8)
    EXHAUSTION_RSI_OB  = SIGNAL_CONFIG.get('div_exhaustion_ob',      65)
    EXHAUSTION_RSI_OS  = SIGNAL_CONFIG.get('div_exhaustion_os',      35)
    # Fresh sweeps can carry a small extra hurdle because they do not yet have
    # a separate retest anchor. Keep it configurable so the sweep-specific
    # confirmation threshold stays aligned with the live strong threshold.
    FRESH_SWEEP_THRESHOLD_PENALTY = SIGNAL_CONFIG.get(
        'sweep_anchor_divergence_fresh_threshold_penalty',
        SIGNAL_CONFIG.get('div_fresh_sweep_threshold_penalty', 8),
    )

    if df is None or len(df) < 20:
        return False, 0, None, "Insufficient 15m data for divergence check"
    if rsi_col not in df.columns:
        return False, 0, None, f"RSI column {rsi_col} not computed"

    touch_tol = atr_value * TOUCH_ATR_MULT

    # ── Step 1: Identify the sweep candle ────────────────────────────────────
    if sweep_candle_idx is not None and 0 <= sweep_candle_idx < len(df):
        sweep_pos    = sweep_candle_idx
        sweep_idx    = df.index[sweep_candle_idx]
        sweep_candle = df.iloc[sweep_candle_idx]
        if direction == 'BUY':
            sweep_wick = max(0.0, swept_level - sweep_candle['low'])
        else:
            sweep_wick = max(0.0, sweep_candle['high'] - swept_level)
    else:
        sweep_window = df.iloc[-SWEEP_LOOKBACK:-RETEST_LOOKBACK] if len(df) > SWEEP_LOOKBACK else df.iloc[:-RETEST_LOOKBACK]
        if sweep_window.empty:
            return False, 0, None, "No sweep candle window available"

        sweep_idx  = None
        sweep_wick = 0.0

        for i in range(len(sweep_window) - 1, -1, -1):
            c = sweep_window.iloc[i]
            if direction == 'BUY':
                if c['low'] < swept_level + touch_tol:
                    wick_extension = swept_level - c['low']
                    if wick_extension > sweep_wick:
                        sweep_wick = wick_extension
                        sweep_idx  = sweep_window.index[i]
            else:
                if c['high'] > swept_level - touch_tol:
                    wick_extension = c['high'] - swept_level
                    if wick_extension > sweep_wick:
                        sweep_wick = wick_extension
                        sweep_idx  = sweep_window.index[i]

        if sweep_idx is None:
            return False, 0, None, (
                f"No sweep candle found within last {SWEEP_LOOKBACK} candles "
                f"at {swept_level:.4f} (tol={touch_tol:.4f})"
            )
        sweep_candle = df.loc[sweep_idx]
        sweep_pos    = df.index.get_loc(sweep_idx)

    sweep_rsi = sweep_candle.get(rsi_col)
    if pd.isna(sweep_rsi):
        return False, 0, None, "RSI not available at sweep candle"

    # ── Step 2: Find the retest candle ───────────────────────────────────────
    # Widen search: include candles slightly beyond touch_tol using a generous
    # secondary tolerance. The current candle is ALWAYS a candidate regardless
    # of distance — it is the most structurally relevant candle on a fresh sweep.
    GENEROUS_TOL = touch_tol * 2.0   # secondary search range for near-miss candles
    retest_window = df.iloc[-RETEST_LOOKBACK:]
    retest_idx    = None
    retest_touch  = float('inf')

    # Pass 1: strict tolerance (original behaviour)
    for i in range(len(retest_window) - 1, -1, -1):
        c = retest_window.iloc[i]
        retest_win_pos = df.index.get_loc(retest_window.index[i])
        if retest_win_pos <= sweep_pos:
            continue   # skip candles at or before the sweep candle itself
        if direction == 'BUY':
            dist = abs(c['low'] - swept_level)
            if c['low'] <= swept_level + touch_tol and dist < retest_touch:
                retest_touch = dist
                retest_idx   = retest_window.index[i]
        else:
            dist = abs(c['high'] - swept_level)
            if c['high'] >= swept_level - touch_tol and dist < retest_touch:
                retest_touch = dist
                retest_idx   = retest_window.index[i]

    # Pass 2: generous tolerance for near-miss post-sweep candles
    if retest_idx is None:
        for i in range(len(retest_window) - 1, -1, -1):
            c = retest_window.iloc[i]
            retest_win_pos = df.index.get_loc(retest_window.index[i])
            if retest_win_pos <= sweep_pos:
                continue
            if direction == 'BUY':
                dist = abs(c['low'] - swept_level)
                if c['low'] <= swept_level + GENEROUS_TOL and dist < retest_touch:
                    retest_touch = dist
                    retest_idx   = retest_window.index[i]
            else:
                dist = abs(c['high'] - swept_level)
                if c['high'] >= swept_level - GENEROUS_TOL and dist < retest_touch:
                    retest_touch = dist
                    retest_idx   = retest_window.index[i]

    # ── Determine mode ────────────────────────────────────────────────────────
    # Mode A: no separate retest candle found — fresh sweep, score on sweep candle alone
    # Mode B: retest found but it IS the sweep candle (same bar) — also fresh
    # Mode C: genuine two-anchor divergence — classic inter-bar RSI delta scoring
    if retest_idx is not None:
        retest_pos    = df.index.get_loc(retest_idx)
        retest_candle = df.loc[retest_idx]
        retest_rsi    = retest_candle.get(rsi_col)
        if pd.isna(retest_rsi):
            retest_idx = None   # treat as Mode A if RSI unavailable

    is_fresh = retest_idx is None or (retest_idx == sweep_idx)
    mode     = 'A' if retest_idx is None else ('B' if retest_idx == sweep_idx else 'C')

    # ── MODE A / B — Fresh sweep: score on sweep candle alone ────────────────
    if is_fresh:
        score       = 0
        score_parts = [f"Mode={mode} (fresh sweep — no separate retest candle yet)"]

        # — RSI absolute exhaustion depth (0–40 pts) ──────────────────────────
        # How deep into oversold/overbought is RSI at the sweep candle?
        # Deeper = stronger exhaustion = higher probability of reversal.
        if direction == 'BUY':
            rsi_depth = max(0.0, EXHAUSTION_RSI_OS - sweep_rsi)   # how far below 35
            depth_pts = min(40, int(rsi_depth * 2.5))
            in_zone   = sweep_rsi <= EXHAUSTION_RSI_OS
        else:
            rsi_depth = max(0.0, sweep_rsi - EXHAUSTION_RSI_OB)   # how far above 65
            depth_pts = min(40, int(rsi_depth * 2.5))
            in_zone   = sweep_rsi >= EXHAUSTION_RSI_OB

        score += depth_pts
        if in_zone:
            score_parts.append(f"RSI exhaustion depth={rsi_depth:.1f} (sweep RSI={sweep_rsi:.1f}) → +{depth_pts}")
        else:
            # RSI not even in exhaustion zone — significant penalty, not a strong setup
            score_parts.append(f"RSI not in exhaustion zone (sweep RSI={sweep_rsi:.1f}) → +{depth_pts} (weak)")
            score -= 10
            score_parts.append("RSI not in exhaustion zone penalty → -10")

        # — Volume z-score of sweep candle (0–25 pts) ─────────────────────────
        # High z-score = climactic volume at the sweep = institutional participation.
        # Compute z-score vs recent vol_ma baseline from the df.
        sweep_vol  = sweep_candle.get('volume', 0)
        vol_ma_val = df['volume_ma'].iloc[sweep_pos] if 'volume_ma' in df.columns else 0
        vol_std    = df['volume'].iloc[max(0, sweep_pos-20):sweep_pos].std() if sweep_pos >= 5 else 0
        if vol_ma_val > 0 and vol_std > 0:
            vol_z = (sweep_vol - vol_ma_val) / vol_std
            if vol_z >= 3.0:
                vol_pts = 25
            elif vol_z >= 2.0:
                vol_pts = 18
            elif vol_z >= 1.0:
                vol_pts = 10
            elif vol_z >= 0.0:
                vol_pts = 4
            else:
                vol_pts = -5   # below average volume — weak absorption signal
            score += vol_pts
            score_parts.append(f"Sweep vol z-score={vol_z:.2f} → {vol_pts:+d}")
        elif vol_ma_val > 0:
            # No std available — use simple ratio
            vol_ratio_raw = sweep_vol / vol_ma_val
            vol_pts = min(15, int((vol_ratio_raw - 1.0) * 10)) if vol_ratio_raw > 1.0 else -5
            score += vol_pts
            score_parts.append(f"Sweep vol ratio vs MA={vol_ratio_raw:.2f} → {vol_pts:+d}")

        # — MACD histogram absolute position and direction (0–15 pts) ─────────
        # At the sweep candle: histogram should be in the correct exhaustion zone
        # AND showing signs of contraction (moving back toward zero).
        if macd_h_col in df.columns and sweep_pos >= 1:
            sweep_macd_h  = sweep_candle.get(macd_h_col)
            prev_macd_h   = df[macd_h_col].iloc[sweep_pos - 1]
            if pd.notna(sweep_macd_h) and pd.notna(prev_macd_h):
                in_correct_zone = (
                    (direction == 'BUY'  and sweep_macd_h < 0) or
                    (direction == 'SELL' and sweep_macd_h > 0)
                )
                contracting_now = (
                    (direction == 'BUY'  and sweep_macd_h > prev_macd_h) or  # histogram rising = less bearish
                    (direction == 'SELL' and sweep_macd_h < prev_macd_h)     # histogram falling = less bullish
                )
                if in_correct_zone and contracting_now:
                    macd_pts = 15
                    score_parts.append(f"MACD histogram in zone + contracting → +{macd_pts}")
                elif in_correct_zone:
                    macd_pts = 7
                    score_parts.append(f"MACD histogram in zone (not yet contracting) → +{macd_pts}")
                else:
                    macd_pts = -5
                    score_parts.append(f"MACD histogram not in exhaustion zone → {macd_pts}")
                score += macd_pts

        # — Wick quality (0–10 pts) — same as Mode C ─────────────────────────
        wick_atr_extension = sweep_wick / atr_value if atr_value > 0 else 0
        if wick_atr_extension >= 1.0:
            wick_pts = 10
        elif wick_atr_extension >= 0.5:
            wick_pts = 6
        elif wick_atr_extension >= 0.2:
            wick_pts = 3
        else:
            wick_pts = 0
        score += wick_pts
        score_parts.append(f"Sweep wick extension={wick_atr_extension:.2f}×ATR → +{wick_pts}")

        # — Stochastic %K (0–10 pts) — independent exhaustion confirmation ────
        # %K in deep oversold (<20 BUY) or overbought (>80 SELL) confirms RSI reading.
        # Both oscillators agreeing = stronger exhaustion signal.
        if stoch_k_col in df.columns:
            stoch_k = sweep_candle.get(stoch_k_col)
            if pd.notna(stoch_k):
                if direction == 'BUY' and stoch_k <= 20:
                    stoch_pts = min(10, int((20 - stoch_k) * 0.4))
                    score += stoch_pts
                    score_parts.append(f"Stochastic %K={stoch_k:.1f} (oversold) → +{stoch_pts}")
                elif direction == 'SELL' and stoch_k >= 80:
                    stoch_pts = min(10, int((stoch_k - 80) * 0.4))
                    score += stoch_pts
                    score_parts.append(f"Stochastic %K={stoch_k:.1f} (overbought) → +{stoch_pts}")
                else:
                    score_parts.append(f"Stochastic %K={stoch_k:.1f} (not in exhaustion zone) → +0")

        score         = max(0, min(100, score))
        effective_min = MIN_SCORE + FRESH_SWEEP_THRESHOLD_PENALTY
        reason        = (
            f"Fresh-sweep exhaustion at {swept_level:.4f} [Mode {mode}]: "
            f"score={score}/100 (threshold={effective_min}) | " + " | ".join(score_parts)
        )
        entry_price = float(sweep_candle['close'])
        if score >= effective_min:
            return True, score, entry_price, reason
        return False, score, None, reason

    # ── MODE C — Two-anchor regular divergence ────────────────────────────────
    retest_rsi = retest_candle.get(rsi_col)   # already confirmed not NaN above

    # Guard against hidden divergence
    if direction == 'BUY':
        price_lower_low  = retest_candle['low'] <= sweep_candle['low'] + touch_tol
        rsi_higher_low   = retest_rsi > sweep_rsi
        is_regular_div   = price_lower_low and rsi_higher_low
        is_hidden_div    = (not price_lower_low) and (not rsi_higher_low)
    else:
        price_higher_high = retest_candle['high'] >= sweep_candle['high'] - touch_tol
        rsi_lower_high    = retest_rsi < sweep_rsi
        is_regular_div    = price_higher_high and rsi_lower_high
        is_hidden_div     = (not price_higher_high) and (not rsi_lower_high)

    if is_hidden_div:
        # Hidden divergence means the retest candle shows continuation, not reversal.
        # However the sweep candle itself may still show exhaustion — fall back to
        # Mode A scoring anchored to the sweep candle rather than hard-returning 0.
        # The sweep candle evidence is independent of what the retest candle shows.
        score       = 0
        score_parts = [f"Mode=C-hidden (hidden divergence at retest — falling back to sweep-candle exhaustion scoring)"]

        if direction == 'BUY':
            rsi_depth = max(0.0, EXHAUSTION_RSI_OS - sweep_rsi)
        else:
            rsi_depth = max(0.0, sweep_rsi - EXHAUSTION_RSI_OB)
        depth_pts = min(30, int(rsi_depth * 2.0))
        score    += depth_pts
        score_parts.append(f"RSI exhaustion depth={rsi_depth:.1f} (sweep RSI={sweep_rsi:.1f}) → +{depth_pts}")

        sweep_vol  = sweep_candle.get('volume', 0)
        vol_ma_val = df['volume_ma'].iloc[sweep_pos] if 'volume_ma' in df.columns else 0
        vol_std    = df['volume'].iloc[max(0, sweep_pos-20):sweep_pos].std() if sweep_pos >= 5 else 0
        if vol_ma_val > 0 and vol_std > 0:
            vol_z   = (sweep_vol - vol_ma_val) / vol_std
            vol_pts = 20 if vol_z >= 3.0 else (14 if vol_z >= 2.0 else (8 if vol_z >= 1.0 else (3 if vol_z >= 0.0 else -5)))
            score  += vol_pts
            score_parts.append(f"Sweep vol z-score={vol_z:.2f} → {vol_pts:+d}")

        wick_atr_extension = sweep_wick / atr_value if atr_value > 0 else 0
        wick_pts = 10 if wick_atr_extension >= 1.0 else (6 if wick_atr_extension >= 0.5 else 3 if wick_atr_extension >= 0.2 else 0)
        score   += wick_pts
        score_parts.append(f"Wick={wick_atr_extension:.2f}×ATR → +{wick_pts}")

        # Hidden divergence is a meaningful negative signal — apply proportional penalty.
        # Capped at 30% of earned score so strong structural evidence (wick + vol)
        # cannot be fully erased by a single continuation candle at the retest.
        # A flat -15 was zeroing out valid 1.4xATR wicks — too aggressive.
        _hidden_penalty = max(8, min(20, int(score * 0.30)))
        score  -= _hidden_penalty
        score_parts.append(f"Hidden divergence penalty (30% of earned score, min 8) -> -{_hidden_penalty}")

        score         = max(0, min(100, score))
        effective_min = MIN_SCORE + FRESH_SWEEP_THRESHOLD_PENALTY
        reason        = (
            f"Hidden-div fallback at {swept_level:.4f}: score={score}/100 (threshold={effective_min}) | "
            + " | ".join(score_parts)
        )
        entry_price = float(sweep_candle['close'])
        if score >= effective_min:
            return True, score, entry_price, reason
        return False, score, None, reason

    if not is_regular_div:
        # Not regular and not hidden — ambiguous structure. Fall back to Mode A
        # scoring anchored to the sweep candle so we don't hard-reject a valid setup.
        score       = 0
        score_parts = [f"Mode=C-fallback (ambiguous divergence structure at {swept_level:.4f}; "
                       f"sweep_rsi={sweep_rsi:.1f}, retest_rsi={retest_rsi:.1f}) — scoring on sweep candle"]

        if direction == 'BUY':
            rsi_depth = max(0.0, EXHAUSTION_RSI_OS - sweep_rsi)
        else:
            rsi_depth = max(0.0, sweep_rsi - EXHAUSTION_RSI_OB)
        depth_pts = min(30, int(rsi_depth * 2.0))
        score    += depth_pts
        score_parts.append(f"RSI exhaustion depth={rsi_depth:.1f} → +{depth_pts}")

        wick_atr_extension = sweep_wick / atr_value if atr_value > 0 else 0
        wick_pts = 10 if wick_atr_extension >= 1.0 else (6 if wick_atr_extension >= 0.5 else 3 if wick_atr_extension >= 0.2 else 0)
        score   += wick_pts
        score_parts.append(f"Wick={wick_atr_extension:.2f}×ATR → +{wick_pts}")

        score         = max(0, min(100, score))
        effective_min = MIN_SCORE + FRESH_SWEEP_THRESHOLD_PENALTY
        reason        = (
            f"Divergence fallback at {swept_level:.4f}: score={score}/100 (threshold={effective_min}) | "
            + " | ".join(score_parts)
        )
        entry_price = float(retest_candle['close'])
        if score >= effective_min:
            return True, score, entry_price, reason
        return False, score, None, reason

    rsi_delta = abs(retest_rsi - sweep_rsi)
    if rsi_delta < MIN_RSI_DELTA:
        # RSI delta between anchors is too small for classic divergence scoring.
        # Fall back to Mode A — score on sweep candle exhaustion depth alone.
        score       = 0
        score_parts = [f"Mode=C-smalldelta (RSI delta={rsi_delta:.1f} < {MIN_RSI_DELTA} — falling back to sweep-candle exhaustion)"]

        if direction == 'BUY':
            rsi_depth = max(0.0, EXHAUSTION_RSI_OS - sweep_rsi)
        else:
            rsi_depth = max(0.0, sweep_rsi - EXHAUSTION_RSI_OB)
        depth_pts = min(30, int(rsi_depth * 2.0))
        score    += depth_pts
        score_parts.append(f"RSI exhaustion depth={rsi_depth:.1f} (sweep RSI={sweep_rsi:.1f}) → +{depth_pts}")

        sweep_vol  = sweep_candle.get('volume', 0)
        vol_ma_val = df['volume_ma'].iloc[sweep_pos] if 'volume_ma' in df.columns else 0
        vol_std    = df['volume'].iloc[max(0, sweep_pos-20):sweep_pos].std() if sweep_pos >= 5 else 0
        if vol_ma_val > 0 and vol_std > 0:
            vol_z   = (sweep_vol - vol_ma_val) / vol_std
            vol_pts = 20 if vol_z >= 3.0 else (14 if vol_z >= 2.0 else (8 if vol_z >= 1.0 else (3 if vol_z >= 0.0 else -5)))
            score  += vol_pts
            score_parts.append(f"Sweep vol z-score={vol_z:.2f} → {vol_pts:+d}")

        wick_atr_extension = sweep_wick / atr_value if atr_value > 0 else 0
        wick_pts = 10 if wick_atr_extension >= 1.0 else (6 if wick_atr_extension >= 0.5 else 3 if wick_atr_extension >= 0.2 else 0)
        score   += wick_pts
        score_parts.append(f"Wick={wick_atr_extension:.2f}×ATR → +{wick_pts}")

        score         = max(0, min(100, score))
        effective_min = MIN_SCORE + FRESH_SWEEP_THRESHOLD_PENALTY
        reason        = (
            f"Small-delta fallback at {swept_level:.4f}: score={score}/100 (threshold={effective_min}) | "
            + " | ".join(score_parts)
        )
        entry_price = float(retest_candle['close'])
        if score >= effective_min:
            return True, score, entry_price, reason
        return False, score, None, reason

    score       = 0
    score_parts = ["Mode=C (two-anchor divergence)"]

    # — RSI delta (0–40 pts) ──────────────────────────────────────────────────
    rsi_pts = min(40, int(rsi_delta * 2))
    score  += rsi_pts
    score_parts.append(f"RSI delta={rsi_delta:.1f} → +{rsi_pts}")

    # — Exhaustion zone bonus ─────────────────────────────────────────────────
    if direction == 'BUY' and sweep_rsi <= EXHAUSTION_RSI_OS:
        exhaustion_bonus = min(10, int((EXHAUSTION_RSI_OS - sweep_rsi) * 0.5))
        score  += exhaustion_bonus
        score_parts.append(f"Sweep RSI oversold ({sweep_rsi:.1f}) → +{exhaustion_bonus}")
    elif direction == 'SELL' and sweep_rsi >= EXHAUSTION_RSI_OB:
        exhaustion_bonus = min(10, int((sweep_rsi - EXHAUSTION_RSI_OB) * 0.5))
        score  += exhaustion_bonus
        score_parts.append(f"Sweep RSI overbought ({sweep_rsi:.1f}) → +{exhaustion_bonus}")

    # — Volume ratio sweep/retest (0–20 pts) ──────────────────────────────────
    sweep_vol  = sweep_candle.get('volume', 0)
    retest_vol = retest_candle.get('volume', 0)
    if sweep_vol > 0 and retest_vol > 0:
        vol_ratio = sweep_vol / retest_vol
        if vol_ratio >= 2.0:
            vol_pts = 20
        elif vol_ratio >= 1.5:
            vol_pts = 14
        elif vol_ratio >= 1.1:
            vol_pts = 8
        else:
            vol_pts = -8
        score  += vol_pts
        score_parts.append(f"Vol ratio sweep/retest={vol_ratio:.2f} → {vol_pts:+d}")

    # — MACD histogram contraction (0–20 pts) ─────────────────────────────────
    if macd_h_col in df.columns:
        sweep_macd_h  = sweep_candle.get(macd_h_col)
        retest_macd_h = retest_candle.get(macd_h_col)
        if pd.notna(sweep_macd_h) and pd.notna(retest_macd_h):
            if direction == 'BUY':
                contracted = retest_macd_h > sweep_macd_h and sweep_macd_h < 0
            else:
                contracted = retest_macd_h < sweep_macd_h and sweep_macd_h > 0
            if contracted:
                contraction_pct = abs(retest_macd_h - sweep_macd_h) / (abs(sweep_macd_h) + 1e-9)
                macd_pts = min(20, int(contraction_pct * 40))
                score   += macd_pts
                score_parts.append(f"MACD contracting {contraction_pct:.0%} → +{macd_pts}")
            else:
                score -= 5
                score_parts.append("MACD not contracting → -5")

    # — ROC velocity comparison (0–10 pts) ────────────────────────────────────
    roc_period = 3
    if sweep_pos >= roc_period and retest_pos >= roc_period:
        sweep_roc  = abs(df['close'].iloc[sweep_pos]  - df['close'].iloc[sweep_pos  - roc_period])
        retest_roc = abs(df['close'].iloc[retest_pos] - df['close'].iloc[retest_pos - roc_period])
        if sweep_roc > 0:
            roc_ratio = retest_roc / sweep_roc
            roc_pts   = 10 if roc_ratio <= 0.5 else (6 if roc_ratio <= 0.75 else (3 if roc_ratio <= 1.0 else 0))
            score    += roc_pts
            score_parts.append(f"ROC ratio retest/sweep={roc_ratio:.2f} → +{roc_pts}")

    # — Wick quality (0–10 pts) ───────────────────────────────────────────────
    wick_atr_extension = sweep_wick / atr_value if atr_value > 0 else 0
    wick_pts = 10 if wick_atr_extension >= 1.0 else (6 if wick_atr_extension >= 0.5 else (3 if wick_atr_extension >= 0.2 else 0))
    score   += wick_pts
    score_parts.append(f"Wick={wick_atr_extension:.2f}×ATR → +{wick_pts}")

    # — Stochastic %K at sweep candle (0–10 pts) ──────────────────────────────
    if stoch_k_col in df.columns:
        stoch_k = sweep_candle.get(stoch_k_col)
        if pd.notna(stoch_k):
            if direction == 'BUY' and stoch_k <= 20:
                stoch_pts = min(10, int((20 - stoch_k) * 0.4))
                score    += stoch_pts
                score_parts.append(f"Stochastic %K={stoch_k:.1f} (oversold) → +{stoch_pts}")
            elif direction == 'SELL' and stoch_k >= 80:
                stoch_pts = min(10, int((stoch_k - 80) * 0.4))
                score    += stoch_pts
                score_parts.append(f"Stochastic %K={stoch_k:.1f} (overbought) → +{stoch_pts}")

    # ── Final decision ────────────────────────────────────────────────────────
    score  = max(0, min(100, score))
    reason = (
        f"Swept-level divergence at {swept_level:.4f} [Mode C]: "
        f"score={score}/100 | " + " | ".join(score_parts)
    )
    entry_price = float(retest_candle['close'])

    if score >= MIN_SCORE:
        return True, score, entry_price, reason

    return False, score, None, (
        f"Divergence below threshold {MIN_SCORE} at {swept_level:.4f}: "
        + " | ".join(score_parts)
    )


async def generate_trade_signal(symbol: str, df=None, current_price=None, prefetched_order_flow=None):
    start_time = time.time()
    cache_key = _get_signal_cache_key(symbol)
    op_limit = int(
        SIGNAL_CONFIG.get(
            "operational_15m_candle_limit",
            SIGNAL_CONFIG.get("candlestick_limit", 600),
        )
    )
    shadow_pending_for_symbol = _has_live_of_gate_shadow_pending(symbol)
    # Only skip re-analysis if a trade has already been placed for this signal.
    # This prevents duplicate trades on the same setup across cycles.
    # The cache is written ONLY after a trade is placed (see below).
    if cache_key in _signal_cache:
        if shadow_pending_for_symbol:
            try:
                df_shadow = get_operational_df_sync(
                    symbol,
                    SIGNAL_CONFIG.get("candlestick_interval", "15m"),
                    op_limit,
                    min_candles=SIGNAL_CONFIG.get('min_required_candles', 50),
                )
                _update_live_of_gate_shadow_outcomes(symbol, df_shadow)
            except Exception as _shadow_e:
                logger.debug(f"[{symbol}] OF shadow outcome refresh skipped on cached path: {_shadow_e}")
        cached, t = _signal_cache[cache_key]
        timeout = SIGNAL_CONFIG.get('signal_cache_timeout', 72000)
        elapsed = time.time() - t
        if elapsed < timeout and cached and cached.get('direction') in ['BUY', 'SELL']:
            remaining_min = int((timeout - elapsed) / 60)
            logger.debug(
                f"[{symbol}] Returning cached signal — "
                f"{remaining_min}min remaining before expiry"
            )
            # Return the cached signal with cache metadata injected so
            # get_signal_summary can render it with CACHED status and TTL.
            cached_with_meta = dict(cached)
            cached_with_meta['_cached']           = True
            cached_with_meta['_cache_elapsed_s']  = int(elapsed)
            cached_with_meta['_cache_remaining_s'] = int(timeout - elapsed)
            cached_with_meta['_cache_timeout_s']  = int(timeout)
            return cached_with_meta, "cached"
        _signal_cache.pop(cache_key, None)
    # Pending carry-forward is retired for live entry. If any legacy pending row
    # still exists from an older run, discard it and continue with a fresh-now
    # analysis on current candles instead of reviving stale state.

    symbol_config = get_symbol_config(symbol)
    price_place = symbol_config.get('price_place', 4)
    current_price = current_price or get_current_price(symbol)
    if current_price is None:
        return None, "Cannot fetch current price"
    fetched_operational_df = df is None
    if df is None:
        df_raw = get_operational_df_sync(
            symbol,
            SIGNAL_CONFIG.get("candlestick_interval", "15m"),
            op_limit,
            min_candles=SIGNAL_CONFIG.get('min_required_candles', 50),
        )
    else:
        df_raw = df.copy()
    if df_raw is None or df_raw.empty or len(df_raw) < SIGNAL_CONFIG.get('min_required_candles', 50):
        return None, "Insufficient historical data"
    _update_live_of_gate_shadow_outcomes(symbol, df_raw)

    direction_15m_limit = max(1, _get_directional_15m_limit(op_limit))
    if fetched_operational_df and direction_15m_limit > len(df_raw):
        df_direction_raw = get_operational_df_sync(
            symbol,
            SIGNAL_CONFIG.get("candlestick_interval", "15m"),
            direction_15m_limit,
            min_candles=SIGNAL_CONFIG.get('min_required_candles', 50),
        )
        if df_direction_raw is None or df_direction_raw.empty:
            logger.warning(
                f"[{symbol}] 15m direction-context fetch failed for limit={direction_15m_limit} "
                f"- falling back to operational window {len(df_raw)}"
            )
            df_direction_raw = df_raw.copy()
    else:
        df_direction_raw = df_raw.tail(direction_15m_limit).copy()

    df = calculate_all_indicators(df_raw.copy())
    df['range'] = df['high'] - df['low']
    # Fix 18: Use 5-bar rolling mean of ATR instead of point-in-time last candle.
    # A single high-volatility candle inflates ATR and simultaneously loosens ALL
    # proximity gates, displacement thresholds, SL distances, and effort-result
    # normalisation. A 5-bar mean stabilises all of these in the same operation.
    _atr_col = next((col for col in [f"ATRr_{SIGNAL_CONFIG.get('atr_period',14)}",
                                     f"ATR_{SIGNAL_CONFIG.get('atr_period',14)}", "ATR"]
                     if col in df.columns and not df[col].isna().all()), None)
    if _atr_col:
        _atr_series = df[_atr_col].dropna()
        atr_value = float(_atr_series.tail(5).mean()) if len(_atr_series) >= 5 else float(_atr_series.iloc[-1])
    else:
        atr_value = df['close'].iloc[-1] * 0.005
    df = identify_swing_points(df)
    df = identify_equal_highs_lows(df)
    last = df.iloc[-1]
    recent_highs = sorted(v for v in df['swing_high'].dropna().tail(10) if v > 0)
    recent_lows = sorted(v for v in df['swing_low'].dropna().tail(10) if v > 0)
    sr_highs = sorted(set(recent_highs + [v for v in df['equal_high_zone'].dropna().tail(10) if v > 0]))
    sr_lows = sorted(set(recent_lows + [v for v in df['equal_low_zone'].dropna().tail(10) if v > 0]))
    mode_profile = SIGNAL_MODE_PROFILES[SIGNAL_MODE]
    rationale = [f"Mode: {SIGNAL_MODE}"]
    path_blockers = []
    score = 0
    primary_direction = None
    path_trigger_type = None
    regime = "unknown"
    research_regime_ctx = {"trend_regime": "unknown", "vol_regime": "unknown", "adx_regime": "unknown"}
    bucket_context = None
    symbol_bucket = "unknown"
    session_bucket = "unknown"
    live_quote_volume = np.nan
    live_liquidity_bucket = "unknown"
    bucket_filter_applied = False
    static_ensemble_soft_bypassed = False
    static_ensemble_soft_bypass_reason = ""
    div_type, div_strength = None, 0
    sweep_anchor_divergence_confirmed = False
    sweep_anchor_divergence_score = 0.0
    sweep_anchor_divergence_mode = "none"
    sweep_anchor_divergence_reason = None
    sweep_anchor_divergence_entry_price = None
    sweep_anchor_divergence_bonus_points = 0
    htf_score = 0.0
    breakout_retest_details = {}
    breakout_acceptance_low = None
    breakout_acceptance_high = None
    order_block_context = {}
    _cached_swing_snapshot = None
    er_score = 0.0  # effort-result score — set on breakout path; 0.0 default on sweep/flip paths
    sweep_ind_ratio = 0.0   # inducement ratio from check_sweep_inducement — read by divergence gate
    order_flow = {}

    # Step 1: Fetch 4H MA/level context.
    # 4H MA direction is the PRIMARY director of trade alignment.
    # Swing highs/lows are level geometry only; both sides are supplied.
    # 4H MA alignment later decides whether the detected direction is tradable.
    # HTF level cache is off by default in MA-direction mode.
    _now = time.time()
    _cached_htf = _htf_levels_cache.get(symbol)
    if bool(SIGNAL_CONFIG.get("enable_htf_level_cache", False)) and _cache_is_fresh(
        _cached_htf,
        _HTF_LEVELS_TTL,
        interval='4H',
        refresh_on_new_candle=False,
    ):
        htf_highs  = _cached_htf['highs']
        htf_lows   = _cached_htf['lows']
        df_4h_deep = _cached_htf['df']
        logger.debug(f"[{symbol}] 4H levels from cache - "
                     f"{int((_HTF_LEVELS_TTL - (_now - _cached_htf['ts'])) / 60)}min until refresh")
    else:
        try:
            df_4h_deep = fetch_and_prepare_data_sync(
                symbol, '4H',
                SIGNAL_CONFIG.get('htf_deep_candle_limit', 400),
                min_candles=SIGNAL_CONFIG.get("htf_min_required_candles", 100)
            )
        except Exception as e:
            logger.warning(f"[{symbol}] 4H MA/level fetch failed: {e} - skipping signal")
            return None, f"4H MA/level fetch failed: {e}"

        if df_4h_deep is None or df_4h_deep.empty or len(df_4h_deep) < int(SIGNAL_CONFIG.get("htf_min_required_candles", 100) or 100):
            logger.warning(f"[{symbol}] 4H MA/level data insufficient - skipping signal")
            return None, "4H MA/level data insufficient"

        # 4H level extraction only needs ATR for swing significance.
        # MA direction is calculated from the fresh 4H window below.
        df_4h_deep = calculate_atr_only(df_4h_deep)
        df_4h_deep = identify_swing_points(df_4h_deep)
        htf_highs = sorted(v for v in df_4h_deep['swing_high'].dropna() if v > 0)
        htf_lows  = sorted(v for v in df_4h_deep['swing_low'].dropna()  if v > 0)

        if not htf_highs and not htf_lows:
            logger.warning(f"[{symbol}] 4H swing detection yielded no levels - skipping signal")
            return None, "4H swing detection yielded no levels"

        htf_level_cache_enabled = bool(SIGNAL_CONFIG.get("enable_htf_level_cache", False))
        if htf_level_cache_enabled and _history_cache_is_complete_enough(
            df_4h_deep,
            SIGNAL_CONFIG.get('htf_deep_candle_limit', 400),
            min_candles=SIGNAL_CONFIG.get("htf_min_required_candles", 100),
        ):
            _htf_levels_cache[symbol] = {
                'highs': htf_highs,
                'lows': htf_lows,
                'df': df_4h_deep,
                'ts': time.time(),
                'last_data_ts': _extract_last_df_timestamp_s(df_4h_deep),
            }
        elif htf_level_cache_enabled:
            logger.debug(
                f"[{symbol}] Skipping 4H level cache write: incomplete history "
                f"({len(df_4h_deep)}/{SIGNAL_CONFIG.get('htf_deep_candle_limit', 400)} candles)."
            )
        else:
            logger.debug(
                f"[{symbol}] 4H level cache disabled; using fresh "
                f"{len(df_4h_deep)}-candle MA/level window."
            )
        # logger.debug(f"[{symbol}] 4H levels fetched and cached - "
                     # f"{len(htf_highs)} highs, {len(htf_lows)} lows")

    # Derive 4H MA direction from the fresh HTF window.
    # Swing columns are retained only for level geometry and audit context.
    _structure_candles_4h = int(SIGNAL_CONFIG.get('structure_candles_4h', 200) or 200)
    _df_4h_structure = df_4h_deep.iloc[-_structure_candles_4h:].copy()
    _df_4h_structure = calculate_all_indicators(_df_4h_structure)
    _df_4h_structure = identify_swing_points(_df_4h_structure)
    ma_4h_state = _derive_ma_direction_state(_df_4h_structure, timeframe="4H")
    structure_4h = str(ma_4h_state.get("trend") or "ranging")
    last_bos_4h = None
    last_choch_4h = None
    struct_4h_detail = {
        "reason": ma_4h_state.get("reason"),
        "direction_source": "moving_average",
        "structure_quality": ma_4h_state.get("quality", "ranging"),
        "ma_direction_state": ma_4h_state,
    }
    # logger.debug(f"[{symbol}] 4H MA direction: {structure_4h} | {struct_4h_detail.get('reason','')}")

    # Step 2: Supply all available sweep liquidity levels.
    use_15m_levels = bool(SIGNAL_CONFIG.get("sweep_use_15m_levels", False))
    ltf_highs = []
    ltf_lows = []
    if use_15m_levels:
        ltf_highs, ltf_lows = await _get_ltf_swing_levels(symbol)
        if ("swing_high" in df.columns or "swing_low" in df.columns) and (not ltf_highs or not ltf_lows):
            _fb_highs, _fb_lows = _get_filtered_swing_levels_from_df(df)
            if not ltf_highs:
                ltf_highs = _fb_highs
            if not ltf_lows:
                ltf_lows = _fb_lows

    src_highs = ltf_highs if use_15m_levels else htf_highs
    src_lows = ltf_lows if use_15m_levels else htf_lows
    all_sweep_highs = sorted(set([v for v in list(src_highs or []) + list(htf_highs or []) + list(sr_highs or []) if v > 0]))
    all_sweep_lows = sorted(set([v for v in list(src_lows or []) + list(htf_lows or []) + list(sr_lows or []) if v > 0]))
    # Both sides are scanned now. The 4H MA gate later decides whether a detected
    # sweep direction is tradable, instead of pre-filtering away half the levels.
    def not_duplicate(level, existing, tol=0.003):
        return all(abs(level - e) / max(e, 1e-9) > tol for e in existing)

    sweep_zones = {'highs': [], 'lows': []}
    for h in all_sweep_highs:
        if not_duplicate(h, sweep_zones['highs']):
            sweep_zones['highs'].append(h)
    for l in all_sweep_lows:
        if not_duplicate(l, sweep_zones['lows']):
            sweep_zones['lows'].append(l)
    sweep_zones['highs'] = sorted(sweep_zones['highs'])
    sweep_zones['lows'] = sorted(sweep_zones['lows'])
    if False and structure_4h == 'ranging':
        path_blockers.append("sweep path blocked: 4H MA trend is ranging")
        if not SIGNAL_CONFIG.get('enable_breakout_path', True):
            return None, (
            f"No sweep setup: 4H MA trend is ranging - no directional conviction, "
            f"sweep path requires confirmed bearish or bullish 4H MA direction"
        )
    elif False and structure_4h == 'bearish':
        sweep_zones = {'highs': [], 'lows': []}
        for h in src_highs:
            if not_duplicate(h, sweep_zones['highs']):
                sweep_zones['highs'].append(h)
        sweep_zones['highs'] = sorted(sweep_zones['highs'])
    elif False and structure_4h == 'bullish':
        sweep_zones = {'highs': [], 'lows': []}
        for l in src_lows:
            if not_duplicate(l, sweep_zones['lows']):
                sweep_zones['lows'].append(l)
        sweep_zones['lows'] = sorted(sweep_zones['lows'])

    # Step 3: derive 15m MA context for audit and downstream feature logging.
    # The old structural approach-direction reject is disabled; live entry now
    # relies on detected setup, HTF MA alignment, ADX, orderflow, and candle body.
    df_direction_15m = calculate_all_indicators(df_direction_raw.copy())
    df_direction_15m = identify_swing_points(df_direction_15m)
    ma_15m_state = _derive_ma_direction_state(df_direction_15m, timeframe="15m")
    structure_15m = str(ma_15m_state.get("trend") or "ranging")
    last_bos_15m = None
    last_choch_15m = None
    struct_15m_detail = {
        "reason": ma_15m_state.get("reason"),
        "direction_source": "moving_average",
        "structure_quality": ma_15m_state.get("quality", "ranging"),
        "ma_direction_state": ma_15m_state,
    }
    # logger.debug(f"[{symbol}] 15m MA direction: {structure_15m} | {struct_15m_detail.get('reason','')}")

    sweep, swept_level, sweep_candle_idx = None, None, None
    breakout_idx, breakout_level, bo_dir = None, None, None

    def _infer_candidate_direction():
        if primary_direction in ("BUY", "SELL"):
            return primary_direction
        if sweep == "bullish_sweep":
            return "BUY"
        if sweep == "bearish_sweep":
            return "SELL"
        if bo_dir in ("BUY", "SELL"):
            return bo_dir
        return None

    def _infer_candidate_trigger_type():
        if path_trigger_type in {"sweep", "breakout"}:
            return path_trigger_type
        if sweep in {"bullish_sweep", "bearish_sweep"}:
            return "sweep"
        if bo_dir in {"BUY", "SELL"} or breakout_level is not None:
            return "breakout"
        return None

    def _ensure_candidate_context():
        nonlocal regime
        nonlocal bucket_context
        nonlocal symbol_bucket
        nonlocal session_bucket
        nonlocal live_quote_volume
        nonlocal live_liquidity_bucket
        if regime == "unknown":
            regime = detect_market_regime(df, atr_value)
        if bucket_context is None:
            bucket_context = _evaluate_live_bucket_filter(symbol, df)
            symbol_bucket = bucket_context["symbol_bucket"]
            session_bucket = bucket_context["session_bucket"]
        if pd.isna(live_quote_volume) and live_liquidity_bucket == "unknown":
            liquidity_context = _get_live_liquidity_context(symbol)
            live_quote_volume = liquidity_context.get("quote_volume", np.nan)
            live_liquidity_bucket = str(liquidity_context.get("liquidity_bucket", "unknown") or "unknown")

    def _ensure_research_audit_context():
        nonlocal research_regime_ctx
        if str(research_regime_ctx.get("trend_regime") or "unknown") == "unknown":
            research_regime_ctx = classify_research_parity_regime(df, structure_4h)

    def _ensure_swing_snapshot():
        nonlocal _cached_swing_snapshot
        if _cached_swing_snapshot is not None:
            return _cached_swing_snapshot
        current_trigger_type = _infer_candidate_trigger_type()
        _cached_swing_snapshot = _build_live_swing_snapshot(
            df,
            _df_4h_structure,
            atr_value,
            current_price,
            trigger_type=current_trigger_type,
            swept_level=swept_level,
            sweep_candle_idx=sweep_candle_idx,
            breakout_idx=breakout_idx,
        )
        return _cached_swing_snapshot

    _ensure_candidate_context()
    alignment_state = _structure_alignment_relation(structure_4h, structure_15m)
    range_gate_metrics = _compute_range_gate_metrics(
        df,
        atr_value,
        market_regime=regime,
        trend_regime=regime,
        adx_regime=None,
    )
    range_strength = _safe_float(range_gate_metrics.get("range_strength"), 0.0) or 0.0
    compression_score = _safe_float(range_gate_metrics.get("compression_score"), 0.0) or 0.0
    trend_regime_at_reject = range_gate_metrics.get("trend_regime_at_reject")
    precision_profile_passed = None
    failed_precision_checks = []
    entry_distance_atr = None
    entry_proximity_state = {}
    retest_quality = "not_applicable"
    ensemble_votes = None
    ensemble_min_required = None
    vote_breakdown = {}
    missing_vote_types = []
    recent_candle_confirmation_bonus = 0
    quality_score_audit = _safe_float(score, 0.0) or 0.0
    quality_threshold = None
    quality_subscores = _build_quality_subscores(static_score=score, final_score=score)

    def _current_trigger_level(trigger_type_override=None):
        trigger_token = str(trigger_type_override or _infer_candidate_trigger_type() or "").strip().lower()
        if trigger_token == "sweep":
            return swept_level
        return breakout_level

    def _build_gate_audit_snapshot(
        *,
        trigger_type_override=None,
        entry_price_override=None,
        quality_score_override=None,
        quality_threshold_override=None,
        quality_subscores_override=None,
        precision_profile_passed_override=None,
        failed_precision_checks_override=None,
        retest_quality_override=None,
    ):
        trigger_level = _current_trigger_level(trigger_type_override)
        entry_value = entry_price_override if entry_price_override is not None else current_price
        normalized_votes = _normalize_vote_breakdown(vote_breakdown)
        normalized_missing_votes = _derive_missing_vote_types(normalized_votes)
        return {
            "range_strength": range_strength,
            "compression_score": compression_score,
            "trend_regime_at_reject": trend_regime_at_reject,
            "range_span_atr": range_gate_metrics.get("range_span_atr"),
            "average_candle_range_atr": range_gate_metrics.get("average_candle_range_atr"),
            "adx_value_at_reject": range_gate_metrics.get("adx_value_at_reject"),
            "alignment_state": alignment_state,
            "htf_confluence_score": _safe_float(htf_score),
            "ensemble_votes": ensemble_votes,
            "ensemble_min_required": ensemble_min_required,
            "vote_breakdown": normalized_votes,
            "missing_vote_types": normalized_missing_votes,
            "quality_score": _safe_float(quality_score_override, quality_score_audit),
            "quality_threshold": _safe_float(quality_threshold_override, quality_threshold),
            "quality_subscores": _json_safe_default(quality_subscores_override or quality_subscores),
            "precision_profile_passed": (
                precision_profile_passed if precision_profile_passed_override is None else precision_profile_passed_override
            ),
            "failed_precision_checks": _json_safe_default(
                failed_precision_checks if failed_precision_checks_override is None else failed_precision_checks_override
            ),
            "entry_distance_atr": _compute_entry_distance_atr(entry_value, trigger_level, atr_value),
            "retest_quality": retest_quality if retest_quality_override is None else retest_quality_override,
        }

    def _build_candidate_signal_snapshot(*, trigger_type=None, direction=None, entry_price_override=None):
        _ensure_candidate_context()
        _ensure_research_audit_context()
        inferred_trigger = trigger_type or _infer_candidate_trigger_type()
        inferred_direction = direction or _infer_candidate_direction()
        target_entry = float(entry_price_override if entry_price_override is not None else current_price or 0.0)
        if inferred_trigger not in {"sweep", "breakout"} or inferred_direction not in {"BUY", "SELL"} or target_entry <= 0:
            return None

        swing_snapshot = _ensure_swing_snapshot()
        candidate_signal = {
            "symbol": symbol,
            "direction": inferred_direction,
            "trigger_type": inferred_trigger,
            "entry_price": round(target_entry, price_place),
            "price_place": price_place,
            "atr_value": float(atr_value),
            "confidence_score": int(score or 0),
            "rationale": list(rationale),
            "market_regime": regime,
            "research_trend_regime": research_regime_ctx.get("trend_regime"),
            "research_vol_regime": research_regime_ctx.get("vol_regime"),
            "research_adx_regime": research_regime_ctx.get("adx_regime"),
            "structure_4h": structure_4h,
            "structure_15m": structure_15m,
            "direction_source_4h": "moving_average",
            "direction_source_15m": "moving_average",
            "ma_direction_4h_state": _to_json_safe((struct_4h_detail or {}).get("ma_direction_state", {})),
            "ma_direction_15m_state": _to_json_safe((struct_15m_detail or {}).get("ma_direction_state", {})),
            "structure_alignment": _structure_alignment_relation(structure_4h, structure_15m),
            "symbol_bucket": symbol_bucket,
            "liquidity_bucket": live_liquidity_bucket,
            "quote_volume": None if pd.isna(live_quote_volume) else float(live_quote_volume),
            "session_bucket": session_bucket,
            "bucket_filter_applied": bucket_filter_applied,
            "static_ensemble_soft_bypassed": static_ensemble_soft_bypassed,
            "static_ensemble_soft_bypass_reason": static_ensemble_soft_bypass_reason if static_ensemble_soft_bypassed else None,
            "context_risk_multiplier": None,
            "context_risk_tier": None,
            "context_risk_reasons": [],
            "momentum_divergence_type": div_type,
            "momentum_divergence_strength": float(div_strength or 0.0),
            "has_momentum_divergence": bool(div_type),
            "delta_divergence_strength": float(
                ((order_flow.get('footprint', {}) or {}).get('divergence_strength', 0.0))
                if isinstance(order_flow, dict) else 0.0
            ),
            "has_delta_divergence": bool(
                ((order_flow.get('footprint', {}) or {}).get('delta_divergence', False))
                if isinstance(order_flow, dict) else False
            ),
            "sweep_anchor_divergence_confirmed": bool(sweep_anchor_divergence_confirmed),
            "sweep_anchor_divergence_score": float(sweep_anchor_divergence_score or 0.0),
            "sweep_anchor_divergence_mode": sweep_anchor_divergence_mode,
            "sweep_anchor_divergence_reason": sweep_anchor_divergence_reason,
            "sweep_anchor_divergence_bonus_points": int(sweep_anchor_divergence_bonus_points or 0),
            "sweep_anchor_divergence_entry_price": (
                float(sweep_anchor_divergence_entry_price)
                if sweep_anchor_divergence_entry_price is not None
                else None
            ),
            "of_gate_decision": None,
            "of_gate_stage": None,
            "of_gate_final_score": None,
            "of_gate_min_score_final": None,
            "of_gate_directional_pressure": None,
            "of_gate_imbalance": None,
            "htf_confluence": htf_score,
            "swept_level": swept_level if inferred_trigger == "sweep" else None,
            "config_snapshot": _build_live_config_snapshot(),
            "swing_snapshot": swing_snapshot,
        }
        candidate_signal.update(_build_live_config_snapshot_fields())
        candidate_signal.update(swing_snapshot)
        candidate_signal.update(
            _build_gate_audit_snapshot(
                trigger_type_override=inferred_trigger,
                entry_price_override=target_entry,
            )
        )
        return candidate_signal

    def _record_post_path_rejection(rejection_stage, rejection_reason_code, rejection_reason_text, *, trigger_type=None, direction=None, entry_price_override=None):
        if not bool(SIGNAL_CONFIG.get("enable_post_path_rejected_shadow_tracking", True)):
            return None
        candidate_signal = _build_candidate_signal_snapshot(
            trigger_type=trigger_type,
            direction=direction,
            entry_price_override=entry_price_override,
        )
        if not candidate_signal:
            return None
        return _record_live_rejected_shadow(
            candidate_signal,
            rejection_stage=rejection_stage,
            rejection_reason_code=rejection_reason_code,
            rejection_reason_text=rejection_reason_text,
            decision_candle_time=_last_df_timestamp(df) or _utc_now_dt(),
            entry_price_override=entry_price_override,
            atr_value=atr_value,
            df_for_sl=df,
            price_place=price_place,
        )

    def _reject_after_path(rejection_stage, rejection_reason_code, rejection_reason_text, *, track=True, trigger_type=None, direction=None, entry_price_override=None):
        if track:
            _record_post_path_rejection(
                rejection_stage,
                rejection_reason_code,
                rejection_reason_text,
                trigger_type=trigger_type,
                direction=direction,
                entry_price_override=entry_price_override,
            )
        return None, rejection_reason_text

    gate_observations = []
    gate_value_observations = {}
    _audit_only_gate_codes = {
        "stale_sweep",
        "sweep_inducement_failed",
        "dominant_4h_competing_liquidity",
        "sweep_breakout_conflict",
        "sweep_4h_ranging",
        "no_htf_alignment",
        "opposing_momentum_divergence",
        "market_regime_ranging",
        "volume_structure_failed",
        "static_ensemble_failed",
        "signal_below_quality_threshold",
        "signal_below_static_quality_threshold",
        "recent_candle_confirmation_failed",
        "adx_confirmation_failed",
        "path_specific_orderflow_failed",
        "of_final_score_below_threshold",
    }

    def _should_demote_gate(rejection_reason_code):
        return bool(SIGNAL_CONFIG.get("enable_audit_only_quality_gates", False)) and str(
            rejection_reason_code or ""
        ) in _audit_only_gate_codes

    def _log_audit_only_gate(rejection_stage, rejection_reason_code, rejection_reason_text, *, metrics=None):
        observation = {
            "stage": str(rejection_stage or "unknown"),
            "reason_code": str(rejection_reason_code or "unknown"),
            "reason_text": str(rejection_reason_text or ""),
            "timestamp": _utc_now_iso(),
            "mode": "audit_only",
        }
        if metrics:
            safe_metrics = {
                str(key): _json_safe_default(value)
                for key, value in dict(metrics).items()
            }
            observation["metrics"] = safe_metrics
            gate_value_observations[str(rejection_reason_code or "unknown")] = safe_metrics
        gate_observations.append(observation)
        rationale.append(
            f"AUDIT-ONLY gate observed [{rejection_reason_code}]: {rejection_reason_text}"
        )
        return False

    sweep, swept_level, sweep_candle_idx = None, None, None
    if False and structure_15m == 'ranging' and structure_4h in ('bullish', 'bearish'):
        path_blockers.append(f"sweep path blocked: 15m structure is ranging against 4H {structure_4h} bias")
        if not SIGNAL_CONFIG.get('enable_breakout_path', True):
            return None, (
                f"No sweep setup: 15m structure is ranging while 4H is {structure_4h} — "
                f"directional approach into the sweep zone is not established"
            )
    elif False and structure_4h == 'bearish' and structure_15m == 'bearish':
        # Legacy structural approach filter disabled in MA-direction mode.
        path_blockers.append("sweep path blocked: 4H MA bearish but 15m MA also bearish")
        if not SIGNAL_CONFIG.get('enable_breakout_path', True):
            return None, (
            f"No sweep setup: 4H MA bearish but 15m MA also bearish - "
            f"price already moving down, sweep of 4H high already occurred or missed"
        )
    elif False and structure_4h == 'bullish' and structure_15m == 'bullish':
        # Legacy structural approach filter disabled in MA-direction mode.
        path_blockers.append("sweep path blocked: 4H MA bullish but 15m MA also bullish")
        if not SIGNAL_CONFIG.get('enable_breakout_path', True):
            return None, (
            f"No sweep setup: 4H MA bullish but 15m MA also bullish - "
            f"price already moving up, sweep of 4H low already occurred or missed"
        )

    else:
        sweep, swept_level, sweep_candle_idx = detect_liquidity_sweep(df, sweep_zones, symbol)
        expected_sweep_type = None
        if sweep and expected_sweep_type and sweep != expected_sweep_type:
            logger.error(
                f"[{symbol}] Sweep consistency guard mismatch: 4H MA direction={structure_4h}, "
                f"expected={expected_sweep_type}, detected={sweep}. Signal blocked."
            )
            return None, (
                f"Internal sweep consistency guard mismatch: detected {sweep} while 4H MA direction "
                f"is {structure_4h} - signal blocked"
            )

    # Sweep diagnostic log.
    # Logs the 4H/15m liquidity levels fed into the sweep detector, the 15m swing
    # points that were confirmed, and the sweep result. Fires at INFO level so
    # it appears in normal run logs without needing debug mode.
    try:
        _sh_15m = sorted(
            [(df.index.get_loc(i), float(v)) for i, v in df['swing_high'].dropna().items()],
            key=lambda x: x[0]
        )[-10:]
        _sl_15m = sorted(
            [(df.index.get_loc(i), float(v)) for i, v in df['swing_low'].dropna().items()],
            key=lambda x: x[0]
        )[-10:]
        _sh_4h  = sorted(htf_highs)[-5:]  # last 5 4H swing highs (ascending)
        _sl_4h  = sorted(htf_lows)[:5]    # first 5 4H swing lows (ascending = nearest to price)

        """
        logger.info(
            f"[{symbol}] SWEEP DIAGNOSTIC | "
            f"4H MA direction={structure_4h} | "
            f"15m MA direction={structure_15m} | "
            f"sweep_zones highs={[round(h, 6) for h in sweep_zones.get('highs', [])[-5:]]} "
            f"lows={[round(l, 6) for l in sweep_zones.get('lows', [])[:5]]}"
        )
        logger.info(
            f"[{symbol}] SWING POINTS (15m last 10) | "
            f"highs={[round(v,6) for _,v in _sh_15m]} | "
            f"lows={[round(v,6) for _,v in _sl_15m]}"
        )
        logger.info(
            f"[{symbol}] SWING POINTS (4H last 5)  | "
            f"highs={[round(h,6) for h in _sh_4h]} | "
            f"lows={[round(l,6) for l in _sl_4h]}"
        )
        """
        if sweep:
            _sweep_candle = df.iloc[sweep_candle_idx] if sweep_candle_idx is not None else None
            _direction_implied = 'SELL' if sweep == 'bearish_sweep' else 'BUY'
            """
            logger.info(
                f"[{symbol}] SWEEP RESULT | "
                f"type={sweep} → direction={_direction_implied} | "
                f"swept_level={swept_level:.6f} | "
                f"candle_idx={sweep_candle_idx} age={(len(df)-1)-sweep_candle_idx if sweep_candle_idx is not None else 'N/A'} | "
                f"candle H={_sweep_candle['high']:.6f} L={_sweep_candle['low']:.6f} "
                f"O={_sweep_candle['open']:.6f} C={_sweep_candle['close']:.6f}"
                if _sweep_candle is not None else
                f"[{symbol}] SWEEP RESULT | type={sweep} swept_level={swept_level:.6f} candle=unavailable"
            )
            """
        """
        else:
            logger.info(f"[{symbol}] SWEEP RESULT | no sweep detected in last "
                        f"{SIGNAL_CONFIG.get('sweep_lookback_candles', 8)} candles")
        """
    except Exception as _diag_err:
        logger.debug(f"[{symbol}] Sweep diagnostic log failed: {_diag_err}")

    ind_ratio = 0.0
    ind_reason = ""
    ind_diag = {}
    if sweep and not SIGNAL_CONFIG.get('enable_sweep_path', True):
        sweep = None
        swept_level = None
        sweep_candle_idx = None
    if sweep == 'bullish_sweep':
        # ── Fix 1: Stale sweep rejection ─────────────────────────────────────
        # Age alone is not enough — a sweep 6 candles ago that price is still
        # near is fine. Both age AND drift must exceed thresholds to reject.
        # This prevents entering after the optimal zone has been left behind.
        if sweep_candle_idx is not None:
            sweep_age = (len(df) - 1) - sweep_candle_idx
            price_drift = abs(current_price - swept_level) / atr_value if atr_value > 0 else 0
            MAX_SWEEP_AGE = SIGNAL_CONFIG.get('max_sweep_age_candles', 10)
            MAX_DRIFT_ATR = SIGNAL_CONFIG.get('max_sweep_drift_atr', 1.0)
            if sweep_age > MAX_SWEEP_AGE and price_drift > MAX_DRIFT_ATR:
                _stale_sweep_reason = (
                    f"Stale bullish sweep: {sweep_age} candles old, price {price_drift:.2f}xATR "
                    f"from swept level {swept_level:.{price_place}f} - optimal entry zone passed"
                )
                return _reject_after_path(
                    "sweep_staleness",
                    "stale_sweep",
                    _stale_sweep_reason,
                    trigger_type="sweep",
                    direction="BUY",
                )
        long_df = None
        if SIGNAL_CONFIG.get("dol_prior_sweep_lookback_long", 0):
            try:
                long_df = await _get_dol_s3_history(symbol)
            except Exception:
                long_df = None
        is_inducement, ind_ratio, ind_reason, ind_diag = check_sweep_inducement(
            df, 'bullish_sweep', swept_level, atr_value,
            htf_levels={
                'highs': ltf_highs,
                'lows': ltf_lows,
                'htf_highs': htf_highs,
                'htf_lows': htf_lows,
            },
            df_htf=df_4h_deep, df_s3=long_df, sweep_candle_idx=sweep_candle_idx
        )
        if is_inducement:
            _inducement_reason = (
                f"Bullish sweep @ {swept_level:.{price_place}f} DOL audit retained - "
                f"{ind_reason}"
            )
            _log_audit_only_gate(
                "sweep_inducement",
                "sweep_inducement_audit",
                _inducement_reason,
                metrics={
                    "dol_score": round(float(ind_ratio), 4),
                    "direction": "BUY",
                    "swept_level": swept_level,
                    **_to_json_safe(ind_diag or {}),
                },
            )
        if bool(SIGNAL_CONFIG.get("sweep_require_bos_confirmation", False)):
            # FIXED: htf_data was undefined → removed unused argument
            sweep_bos_state, sweep_bos_level = detect_market_structure_shift(df, 'bullish_sweep')

            if sweep_bos_state != 'bullish_break':
                bos_label = sweep_bos_state or 'none'
                bos_level_text = (
                    f" near {sweep_bos_level:.{price_place}f}"
                    if sweep_bos_level is not None else ""
                )
                return _reject_after_path(
                    "sweep_bos_confirmation_gate",
                    "sweep_bos_not_confirmed",
                    (
                        f"Bullish sweep @ {swept_level:.{price_place}f} rejected - "
                        f"BOS not confirmed (state={bos_label}{bos_level_text})"
                    ),
                    trigger_type="sweep",
                    direction="BUY",
                )
            rationale.append(f"Sweep BOS confirmed: bullish break above {sweep_bos_level:.{price_place}f}")
        if swept_level is not None and atr_value > 0:
            entry_proximity_state = _evaluate_confirmation_aware_entry_proximity(
                df=df,
                direction="BUY",
                trigger_type="sweep",
                trigger_level=swept_level,
                entry_price=current_price,
                atr_value=atr_value,
                price_place=price_place,
                stage="sweep_initial",
            )
            entry_distance_atr = _safe_float(entry_proximity_state.get("entry_distance_atr"))
            if not entry_proximity_state.get("passed"):
                return _reject_after_path(
                    "sweep_entry_proximity_gate",
                    "late_sweep_entry",
                    f"Bullish sweep rejected - {entry_proximity_state.get('reason')}",
                    trigger_type="sweep",
                    direction="BUY",
                )
            _sweep_proximity_checked = True
            rationale.append(entry_proximity_state.get("reason"))
        rationale.append(f"Bullish liquidity sweep @ {swept_level:.{price_place}f}")
        score += 35
        rationale.append(f"DOL audit only (score={ind_ratio:.1f}): {ind_reason}")
        sweep_ind_ratio   = ind_ratio   # dol_score stored for divergence gate below
        primary_direction = 'BUY'
        path_trigger_type = 'sweep'
        _cached_swing_snapshot = None
    elif sweep == 'bearish_sweep':
        if sweep_candle_idx is not None:
            sweep_age = (len(df) - 1) - sweep_candle_idx
            price_drift = abs(current_price - swept_level) / atr_value if atr_value > 0 else 0
            MAX_SWEEP_AGE = SIGNAL_CONFIG.get('max_sweep_age_candles', 10)
            MAX_DRIFT_ATR = SIGNAL_CONFIG.get('max_sweep_drift_atr', 1.0)
            if sweep_age > MAX_SWEEP_AGE and price_drift > MAX_DRIFT_ATR:
                _stale_sweep_reason = (
                    f"Stale bearish sweep: {sweep_age} candles old, price {price_drift:.2f}xATR "
                    f"from swept level {swept_level:.{price_place}f} - optimal entry zone passed"
                )
                return _reject_after_path(
                    "sweep_staleness",
                    "stale_sweep",
                    _stale_sweep_reason,
                    trigger_type="sweep",
                    direction="SELL",
                )
        long_df = None
        if SIGNAL_CONFIG.get("dol_prior_sweep_lookback_long", 0):
            try:
                long_df = await _get_dol_s3_history(symbol)
            except Exception:
                long_df = None
        is_inducement, ind_ratio, ind_reason, ind_diag = check_sweep_inducement(
            df, 'bearish_sweep', swept_level, atr_value,
            htf_levels={
                'highs': ltf_highs,
                'lows': ltf_lows,
                'htf_highs': htf_highs,
                'htf_lows': htf_lows,
            },
            df_htf=df_4h_deep, df_s3=long_df, sweep_candle_idx=sweep_candle_idx
        )
        if is_inducement:
            _inducement_reason = (
                f"Bearish sweep @ {swept_level:.{price_place}f} DOL audit retained - "
                f"{ind_reason}"
            )
            _log_audit_only_gate(
                "sweep_inducement",
                "sweep_inducement_audit",
                _inducement_reason,
                metrics={
                    "dol_score": round(float(ind_ratio), 4),
                    "direction": "SELL",
                    "swept_level": swept_level,
                    **_to_json_safe(ind_diag or {}),
                },
            )
        if bool(SIGNAL_CONFIG.get("sweep_require_bos_confirmation", False)):
            sweep_bos_state, sweep_bos_level = detect_market_structure_shift(df, 'bearish_sweep')
            if sweep_bos_state != 'bearish_break':
                bos_label = sweep_bos_state or 'none'
                bos_level_text = (
                    f" near {sweep_bos_level:.{price_place}f}"
                    if sweep_bos_level is not None else ""
                )
                return _reject_after_path(
                    "sweep_bos_confirmation_gate",
                    "sweep_bos_not_confirmed",
                    (
                        f"Bearish sweep @ {swept_level:.{price_place}f} rejected - "
                        f"BOS not confirmed (state={bos_label}{bos_level_text})"
                    ),
                    trigger_type="sweep",
                    direction="SELL",
                )
            rationale.append(f"Sweep BOS confirmed: bearish break below {sweep_bos_level:.{price_place}f}")
        if swept_level is not None and atr_value > 0:
            entry_proximity_state = _evaluate_confirmation_aware_entry_proximity(
                df=df,
                direction="SELL",
                trigger_type="sweep",
                trigger_level=swept_level,
                entry_price=current_price,
                atr_value=atr_value,
                price_place=price_place,
                stage="sweep_initial",
            )
            entry_distance_atr = _safe_float(entry_proximity_state.get("entry_distance_atr"))
            if not entry_proximity_state.get("passed"):
                return _reject_after_path(
                    "sweep_entry_proximity_gate",
                    "late_sweep_entry",
                    f"Bearish sweep rejected - {entry_proximity_state.get('reason')}",
                    trigger_type="sweep",
                    direction="SELL",
                )
            _sweep_proximity_checked = True
            rationale.append(entry_proximity_state.get("reason"))
        rationale.append(f"Bearish liquidity sweep @ {swept_level:.{price_place}f}")
        score += 35
        rationale.append(f"DOL audit only (score={ind_ratio:.1f}): {ind_reason}")
        sweep_ind_ratio   = ind_ratio   # dol_score stored for divergence gate below
        primary_direction = 'SELL'
        path_trigger_type = 'sweep'
        _cached_swing_snapshot = None
    if sweep:
        expected_sweep_dir = None
        if expected_sweep_dir and primary_direction and primary_direction != expected_sweep_dir:
            logger.error(
                f"[{symbol}] Sweep direction consistency guard mismatch: 4H MA direction={structure_4h}, "
                f"expected_direction={expected_sweep_dir}, resolved_direction={primary_direction}, "
                f"sweep={sweep}. Signal blocked."
            )
            return None, (
                f"Internal sweep direction consistency guard mismatch: 4H MA direction is {structure_4h} "
                f"but sweep resolved to {primary_direction} - signal blocked"
            )

        # A dominant 4H competing liquidity pool beyond the swept level means
        # the move is still drawn toward HTF liquidity. Do not try to rescue
        # this class of sweep with local divergence confirmation.
        _dol_warn_threshold = SIGNAL_CONFIG.get('dol_warn_threshold', 40.0)
        _s1_score = float((ind_diag or {}).get('s1_score', 0.0) or 0.0)
        _s1_sources = list((ind_diag or {}).get('s1_beyond_sources', []) or [])
        _strong_4h_dol_warn = (
            ind_ratio >= _dol_warn_threshold
            and _s1_score >= 80.0
            and '4h' in _s1_sources
        )
        if _strong_4h_dol_warn:
            _nearest_beyond = (ind_diag or {}).get('s1_nearest_beyond')
            _nearest_label = (
                f" @ {_nearest_beyond:.{price_place}f}" if isinstance(_nearest_beyond, (int, float)) else ""
            )
            _dominant_liquidity_reason = (
                f"{'Bullish' if primary_direction == 'BUY' else 'Bearish'} sweep @ "
                f"{swept_level:.{price_place}f} DOL audit retained - dominant 4H competing "
                f"liquidity{_nearest_label} observed. {ind_reason}"
            )
            _log_audit_only_gate(
                "sweep_dominant_htf_liquidity",
                "dominant_4h_competing_liquidity_audit",
                _dominant_liquidity_reason,
                metrics={
                    "dol_score": round(float(ind_ratio), 4),
                    "s1_score": round(float(_s1_score), 4),
                    "s1_sources": list(_s1_sources),
                    "nearest_beyond": _nearest_beyond,
                    "direction": primary_direction,
                    **_to_json_safe(ind_diag or {}),
                },
            )
    breakout_idx, breakout_level, bo_dir = detect_breakout_candle(df)

    # ── Path enable gates ────────────────────────────────────────────────────
    # Breakout path: disabled → treat bo_dir as None so the else block below
    # never sets primary_direction from a breakout detection.
    # flag and skips the flip trigger assignment.
    if not SIGNAL_CONFIG.get('enable_breakout_path', True):
        path_blockers.append("breakout path disabled by config")
        bo_dir = None
        breakout_idx = None
        breakout_level = None

    if sweep:
        # ── SWEEP PATH: direction already set by sweep ────────────────────
        # Breakout is NOT used to override direction. If a breakout exists in
        # the same direction it is treated as supportive confluence only.
        # If it opposes, apply conflict penalty per mode profile.
        if bo_dir and bo_dir != primary_direction:
            _sweep_conflict_reason = "Sweep direction conflicts with opposing breakout"
            if _should_demote_gate("sweep_breakout_conflict"):
                _log_audit_only_gate(
                    "sweep_breakout_conflict",
                    "sweep_breakout_conflict",
                    _sweep_conflict_reason,
                    metrics={
                        "sweep_direction": primary_direction,
                        "breakout_direction": bo_dir,
                        "breakout_level": breakout_level,
                    },
                )
                rationale.append("Opposing breakout detected after sweep - audit-only observation")
            elif not mode_profile["allow_sweep_breakout_conflict"]:
                return _reject_after_path(
                    "sweep_breakout_conflict",
                    "sweep_breakout_conflict",
                    _sweep_conflict_reason,
                    trigger_type="sweep",
                )
            else:
                rationale.append("Opposing breakout detected after sweep - allowed by mode profile")
        elif bo_dir and bo_dir == primary_direction:
            # Agreeing breakout: note as confluence, no retest gate required
            rationale.append(f"Breakout {bo_dir} @ {breakout_level:.{price_place}f} agrees with sweep (confluence)")
            score += 10
        # No retest, reclaim check, or effort-result gates — those are
        # breakout-path gates and are irrelevant when sweep sets direction.
        order_block_context = classify_order_block_context(
            df,
            primary_direction,
            trigger_type="sweep",
            swept_level=swept_level,
            atr_value=atr_value,
        )
        if order_block_context.get("blocked"):
            return _reject_after_path(
                "sweep_order_block_gate",
                "sweep_order_block_failed",
                order_block_context.get("reason") or order_block_context.get("block_reason"),
                trigger_type="sweep",
                direction=primary_direction,
            )
        if order_block_context.get("sweep_support"):
            score += int(order_block_context.get("score") or 0)
            rationale.append(f"Order-block sweep context: {order_block_context.get('reason')}")
    else:
        # ── BREAKOUT PATH: only runs when no sweep detected ───────────────
        if bo_dir:
            # ── BOS / CHoCH structure gate ────────────────────────────────
            # A breakout is a continuation signal — it must align with the
            # current market structure. CHoCH tells us the structure just
            # flipped; BOS tells us it is continuing. A BUY breakout in a
            # bearish structure (lower highs, lower lows, no bullish CHoCH)
            # is not a breakout — it is a failing recovery being misread as
            # a continuation. Hard reject on structural misalignment.
            # Ranging structure passes through — regime gate handles it.
            mss_structure = structure_15m
            mss_bos = last_bos_15m
            mss_choch = last_choch_15m
            mss_detail = struct_15m_detail
            if False and mss_structure == 'bearish' and bo_dir == 'BUY':
                return _reject_after_path(
                    "breakout_structure_gate",
                    "breakout_structure_misaligned",
                    (
                        f"Breakout BUY rejected — market structure is bearish "
                        f"({mss_detail['reason']}) — "
                        f"{'bearish CHoCH invalidates bullish continuation' if mss_choch == 'bearish_choch' else 'lower highs and lower lows, no bullish BOS confirmed'}"
                    ),
                    trigger_type="breakout",
                    direction="BUY",
                )
            if False and mss_structure == 'bullish' and bo_dir == 'SELL':
                return _reject_after_path(
                    "breakout_structure_gate",
                    "breakout_structure_misaligned",
                    (
                        f"Breakout SELL rejected — market structure is bullish "
                        f"({mss_detail['reason']}) — "
                        f"{'bullish CHoCH invalidates bearish continuation' if mss_choch == 'bullish_choch' else 'higher highs and higher lows, no bearish BOS confirmed'}"
                    ),
                    trigger_type="breakout",
                    direction="SELL",
                )

            primary_direction = bo_dir
            path_trigger_type = 'breakout'
            _cached_swing_snapshot = None
            # Log which structural event confirmed the direction
            if mss_choch:
                rationale.append(f"Structure: {mss_choch.replace('_', ' ').title()} confirms {bo_dir} breakout direction")
            elif mss_bos:
                rationale.append(f"Structure: {mss_bos.replace('_', ' ').title()} confirms {bo_dir} breakout continuation")
            else:
                rationale.append(f"15m MA context: {mss_structure} - breakout direction {bo_dir} passes to HTF MA gate")

            rationale.append(f"Breakout {bo_dir} @ {breakout_level:.{price_place}f}")

            breakout_retest_details = _validate_breakout_retest_details(
                df,
                breakout_idx,
                breakout_level,
                primary_direction,
            )
            valid_retest = bool(breakout_retest_details.get("valid"))
            retest_msg = str(breakout_retest_details.get("message") or "")
            retest_quality = _classify_retest_quality("breakout", valid_retest=valid_retest, retest_msg=retest_msg)
            if not valid_retest:
                return _reject_after_path(
                    "breakout_retest_gate",
                    "breakout_retest_failed",
                    f"Retest failed: {retest_msg}",
                    trigger_type="breakout",
                )

            breakout_acceptance_low = _safe_float(
                breakout_retest_details.get("best_retest_low"),
                breakout_retest_details.get("latest_retest_low"),
            )
            breakout_acceptance_high = _safe_float(
                breakout_retest_details.get("best_retest_high"),
                breakout_retest_details.get("latest_retest_high"),
            )
            rationale.append(f"Retest valid: {retest_msg}")

            # Breakout trigger + accepted pullback earns points, but cannot carry a trade alone.
            order_block_context = classify_order_block_context(
                df,
                primary_direction,
                trigger_type="breakout",
                breakout_level=breakout_level,
                retest_details=breakout_retest_details,
                atr_value=atr_value,
            )
            if order_block_context.get("blocked"):
                return _reject_after_path(
                    "breakout_order_block_gate",
                    "breakout_into_uncleared_order_block",
                    order_block_context.get("reason") or order_block_context.get("block_reason"),
                    trigger_type="breakout",
                    direction=primary_direction,
                )
            if order_block_context.get("breakout_support"):
                score += int(order_block_context.get("score") or 0)
                rationale.append(f"Order-block breakout context: {order_block_context.get('reason')}")

            # Breakout trigger + accepted pullback earns points, but cannot carry a trade alone.
            score += 30
            # Late-entry guard is zone-based; candle confirmation no longer widens it by default.
            if breakout_level and atr_value > 0:
                entry_proximity_state = _evaluate_confirmation_aware_entry_proximity(
                    df=df,
                    direction=primary_direction,
                    trigger_type="breakout",
                    trigger_level=breakout_level,
                    entry_price=current_price,
                    atr_value=atr_value,
                    price_place=price_place,
                    stage="breakout_initial",
                )
                entry_distance_atr = _safe_float(entry_proximity_state.get("entry_distance_atr"))
                if not entry_proximity_state.get("passed"):
                    return _reject_after_path(
                        "breakout_entry_proximity",
                        "late_breakout_entry",
                        entry_proximity_state.get("reason"),
                        trigger_type="breakout",
                        direction=primary_direction,
                    )
                rationale.append(entry_proximity_state.get("reason"))
            # Fix 11: ER window starts AT breakout candle, not 3 before it.
            # Pre-breakout consolidation candles deflate the average and inflate
            # the breakout signal artificially. Isolate momentum cluster only.
            breakout_slice = df.iloc[breakout_idx: min(breakout_idx + 4, len(df))]
            er_score = check_effort_result_divergence(breakout_slice, primary_direction)
            retest_quality = _classify_retest_quality("breakout", valid_retest=True, retest_msg=retest_msg, er_score=er_score)

    # Without primary_direction all downstream gates are meaningless.
    if not primary_direction:
        blocker_suffix = f" | {'; '.join(path_blockers)}" if path_blockers else ""
        return None, f"No valid sweep or breakout setup detected{blocker_suffix}"

    _ensure_candidate_context()
    bucket_filter_applied = bool(sweep and bucket_context["filter_enabled"])
    if bucket_filter_applied and bucket_context["blocked"]:
        return _reject_after_path(
            "bucket_filter",
            "bucket_filter_blocked",
            bucket_context["reason"],
        )

    # Universal price proximity fallback for any path that did not check earlier.
    trigger_level = swept_level if sweep else breakout_level
    if trigger_level and not entry_proximity_state:
        entry_proximity_state = _evaluate_confirmation_aware_entry_proximity(
            df=df,
            direction=primary_direction,
            trigger_type="sweep" if sweep else "breakout",
            trigger_level=trigger_level,
            entry_price=current_price,
            atr_value=atr_value,
            price_place=price_place,
            stage="universal_fallback",
        )
        entry_distance_atr = _safe_float(entry_proximity_state.get("entry_distance_atr"))
        if not entry_proximity_state.get("passed"):
            return _reject_after_path(
                "entry_proximity_gate",
                "trade_geometry_broken",
                entry_proximity_state.get("reason"),
            )
        rationale.append(entry_proximity_state.get("reason"))

    # Last-candle micro direction gate removed; live entry gates validate timing.

    # Recent failed structures are informative context. Breakout continuation is
    # already guarded by acceptance/retest, HTF alignment, ADX expansion, and
    # candle-derived orderflow before placement.
    if not sweep:
        should_reject, reject_reason = detect_recent_failed_breakouts(
            df,
            primary_direction,
            lookback=96,
            post_window=10,
            reject_threshold=mode_profile["failed_structure_reject_threshold"],
        )
        if should_reject:
            _log_audit_only_gate(
                "failed_structure_context",
                "recent_failed_structure",
                reject_reason,
                metrics={"trigger_type": "breakout", "direction": primary_direction},
            )
            rationale.append(f"Recent failed structure context: {reject_reason}")
    elif sweep:
        should_reject, reject_reason = detect_recent_failed_breakouts(
            df,
            primary_direction,
            lookback=96,
            post_window=10,
            reject_threshold=mode_profile["failed_structure_reject_threshold"],
        )
        if should_reject:
            rationale.append("Prior failed breakout attempts support sweep setup")

    htf_data = fetch_and_analyze_higher_tf_sync(
        symbol,
        df_4h_cached=df_4h_deep,
        canonical_4h_trend=structure_4h,
        canonical_4h_detail=struct_4h_detail,
        canonical_4h_last_bos=last_bos_4h,
        canonical_4h_last_choch=last_choch_4h,
    )
    htf_trigger_type = 'sweep' if sweep else 'breakout'
    htf_check_direction = primary_direction

    # Sweep HTF logic is audit/context only; live WS orderflow is the entry confirmation.
    # 1H MA state only adjusts confidence/timing language when this audit layer is enabled.
    sweep_is_with_trend = False
    if sweep and SIGNAL_CONFIG.get('sweep_htf_trend_alignment', True):
        tf_4h_data  = htf_data.get('4H', {}) or {}
        # Use the Step-1 4H MA direction as the canonical sweep-direction source.
        # The HTF bundle reuses this trend instead of recomputing a second
        # classifier for the same sweep decision.
        trend_4h    = structure_4h
        strength_4h = tf_4h_data.get('strength', 'weak')

        if (trend_4h == 'bullish' and primary_direction == 'BUY') or \
           (trend_4h == 'bearish' and primary_direction == 'SELL'):
            # With-trend sweep - 4H MA confirms direction.
            # 1H MA disagreement is timing context only.
            tf_1h_data  = htf_data.get('1H', {}) or {}
            trend_1h    = tf_1h_data.get('trend', 'ranging')
            strength_1h = str(tf_1h_data.get('strength', 'weak') or 'weak').strip().lower()

            _1h_opposes = (
                (primary_direction == 'BUY'  and trend_1h == 'bearish') or
                (primary_direction == 'SELL' and trend_1h == 'bullish')
            )
            _1h_ranging = trend_1h == 'ranging'

            if False and _1h_opposes and strength_1h == 'strong':
                return _reject_after_path(
                    "sweep_htf_alignment",
                    "sweep_1h_deterioration",
                    (
                        f"Sweep rejected: 4H MA {trend_4h} but 1H already {trend_1h} - "
                        f"intermediate trend deteriorating ahead of 4H confirmation, "
                        f"15m move is structural not a retracement"
                    ),
                )

            sweep_is_with_trend = True
            bonus = 12 if strength_4h == 'strong' else 8
            if _1h_opposes:
                bonus = max(0, bonus - 6)
                rationale.append(
                    f"With-trend sweep: 4H MA {trend_4h} aligns, but weak 1H {trend_1h} "
                    f"opposes timing - reduced bonus (+{bonus})"
                )
            elif _1h_ranging:
                bonus = max(0, bonus - 4)
                rationale.append(
                    f"With-trend sweep: 4H MA {trend_4h} but 1H ranging - "
                    f"reduced bonus (+{bonus})"
                )
            else:
                rationale.append(
                    f"With-trend sweep: 4H MA {'strong ' if strength_4h == 'strong' else ''}"
                    f"{trend_4h} + 1H {trend_1h} aligns with {primary_direction} sweep entry (+{bonus})"
                )
            score += bonus
            htf_score = 1.5

        elif (trend_4h == 'bearish' and primary_direction == 'BUY') or \
             (trend_4h == 'bullish' and primary_direction == 'SELL'):
            logger.info(
                f"[{symbol}] Sweep 4H MA mismatch logged only: 4H={trend_4h}, "
                f"direction={primary_direction}"
            )
            _log_audit_only_gate(
                "sweep_htf_ma_alignment",
                "sweep_htf_ma_direction_mismatch",
                (
                    f"Sweep HTF MA mismatch logged only: {primary_direction} sweep does not align with "
                    f"4H MA direction ({trend_4h})"
                ),
                metrics={"trigger_type": "sweep", "direction": primary_direction, "trend_4h": trend_4h},
            )
            rationale.append(
                f"HTF MA audit-only mismatch: {primary_direction} sweep vs 4H MA {trend_4h}"
            )
            htf_score = 0.0
        else:
            _log_audit_only_gate(
                "sweep_htf_alignment",
                "sweep_4h_ranging",
                (
                    f"Sweep HTF audit-only: 4H MA trend is ranging - no directional conviction "
                    f"to support a sweep entry"
                ),
                metrics={"trigger_type": "sweep", "direction": primary_direction, "trend_4h": trend_4h},
            )
            rationale.append("HTF MA audit-only: 4H trend is ranging for sweep context")
            htf_score = 0.0
    else:
        # Not a sweep, or sweep_htf_trend_alignment=False: use shared HTF alignment.
        htf_score = check_htf_alignment(htf_data, htf_check_direction, trigger_type=htf_trigger_type)

    if htf_score == 0:
        _log_audit_only_gate(
            "htf_alignment_gate",
            "no_htf_alignment",
            f"No HTF alignment (trigger: {htf_trigger_type})",
            metrics={"trigger_type": htf_trigger_type, "direction": htf_check_direction},
        )
        rationale.append(f"HTF alignment audit-only: no alignment (trigger: {htf_trigger_type})")

    htf_ma_confirmation_state = _evaluate_htf_ma_macd_confirmation(
        htf_data,
        htf_check_direction,
        trigger_type=htf_trigger_type,
    )
    configured_htf_ma_hard_gate_requested = bool(
        SIGNAL_CONFIG.get("enable_htf_ma_confirmation_gate", False)
    )
    htf_ma_hard_gate_enabled = False
    htf_ma_confirmation_state["audit_only"] = not htf_ma_hard_gate_enabled
    htf_ma_confirmation_state["hard_gate_enabled"] = htf_ma_hard_gate_enabled
    htf_ma_confirmation_state["configured_hard_gate_requested"] = configured_htf_ma_hard_gate_requested
    if htf_ma_hard_gate_enabled and not htf_ma_confirmation_state.get("passed"):
        return _reject_after_path(
            "htf_ma_confirmation_gate",
            htf_ma_confirmation_state.get("reason_code") or "htf_ma_confirmation_failed",
            htf_ma_confirmation_state.get("reason_text") or "HTF MA confirmation failed",
            trigger_type=htf_trigger_type,
            direction=htf_check_direction,
        )
    if htf_ma_hard_gate_enabled:
        rationale.append(
            "HTF MA hard gate passed: "
            + (htf_ma_confirmation_state.get("reason_text") or "values logged")
        )
    else:
        _log_audit_only_gate(
            "htf_ma_confirmation_audit",
            htf_ma_confirmation_state.get("reason_code") or "htf_ma_confirmation_audit",
            htf_ma_confirmation_state.get("reason_text") or "HTF MA confirmation logged for audit",
            metrics=htf_ma_confirmation_state,
        )
        rationale.append(
            "HTF MA audit-only: "
            + (htf_ma_confirmation_state.get("reason_text") or "values logged")
        )

    if htf_score >= 1.5 and not sweep_is_with_trend:
        score += 12
        rationale.append(f"Strong HTF confluence ({htf_trigger_type})")
    elif htf_score >= 0.5 and not sweep_is_with_trend:
        score += 6
        rationale.append(f"Mild HTF support ({htf_trigger_type})")

    wyckoff_pattern = None
    wyckoff_conf = 0
    phase_info = {}
    wyckoff_pattern, wyckoff_conf, phase_info = detect_wyckoff_pattern(
        df=df,
        higher_tf_data=htf_data,
        is_bullish=(primary_direction == 'BUY'),
        lookback=60,
        min_phase_conf=30,
        vol_mult_climax=1.55,
        vol_mult_sos=1.35,
        range_mult_ar=1.6,
        min_tests=2,
        schematic_bonus=12,
        effort_result_threshold=0.55,
    )
    if wyckoff_pattern:
        rationale.append(f"Wyckoff {wyckoff_pattern} | conf {wyckoff_conf}% | schematic {phase_info.get('Schematic', 'Core')}")
        strong_phases = {k: v for k, v in phase_info.items() if v >= 15 and k != 'Schematic'}
        if strong_phases:
            rationale.append("Key Wyckoff phases:")
            for k, v in strong_phases.items():
                rationale.append(f" - {k}: {v} pts")
        if wyckoff_conf >= 85:
            score += 26
            rationale.append("Very strong Wyckoff confirmation")
        elif wyckoff_conf >= 70:
            score += 18
            rationale.append("Solid Wyckoff confirmation")
        else:
            score += 10
            rationale.append("Moderate Wyckoff support")
        if phase_info.get('Phase C (Spring)', 0) >= 35 or phase_info.get('Phase C (UTAD)', 0) >= 35:
            score += 8
            rationale.append("Strong Phase C test detected")
    else:
        rationale.append("No clear Wyckoff pattern")

    consolidation_break = None
    zone_price = None
    num_touches = 0
    consolidation_break, zone_price, num_touches = detect_consolidation_break(
        df,
        is_bullish=(primary_direction == 'BUY'),
    )
    if consolidation_break:
        cons_dir = 'BUY' if 'up' in consolidation_break else 'SELL'
        scan_n = SIGNAL_CONFIG.get("consolidation_scan_candles", 40)
        cons_scan = df.tail(scan_n)
        cons_bo_idx = None
        for _ci, _cr in cons_scan.iterrows():
            _cpos = df.index.get_loc(_ci)
            if cons_dir == 'BUY' and _cr['close'] > zone_price:
                cons_bo_idx = _cpos
                break
            if cons_dir == 'SELL' and _cr['close'] < zone_price:
                cons_bo_idx = _cpos
                break
        if cons_bo_idx is None:
            cons_bo_idx = len(df) - 2
        cons_bo_idx = min(cons_bo_idx, len(df) - 2)

        valid_retest, msg = validate_retest(df, cons_bo_idx, zone_price, cons_dir)
        if sweep:
            if valid_retest:
                rationale.append(f"Consolidation break confluence ({num_touches} touches): {msg}")
                score += 10
            else:
                rationale.append(
                    f"Consolidation pattern observed ({num_touches} touches), no confluence credit: {msg}"
                )
        else:
            if valid_retest:
                rationale.append(f"Consolidation break confirmed ({num_touches} touches): {msg}")
                score += 18
            else:
                rationale.append(f"Consolidation break rejected: {msg}")

    ibo_type = None
    if not sweep and breakout_idx is not None:
        breakout_recency = (len(df) - 1) - breakout_idx
        if breakout_recency <= 3:
            ibo_type, _ = detect_internal_bar_breakout(
                df,
                is_bullish=(primary_direction == 'BUY'),
                anchor_idx=breakout_idx,
            )
            if ibo_type:
                rationale.append(f"Internal Bar Breakout: {ibo_type} (breakout {breakout_recency} candles ago)")
                score += 12

    candle = confirm_with_candlesticks(df, is_bullish=(primary_direction == 'BUY'))
    if candle:
        rationale.append(f"Candlestick pattern: {candle}")
        score += 12
    if last['volume'] > df['volume_ma'].iloc[-1] * SIGNAL_CONFIG.get("volume_confirmation_multiplier", 1.1):
        rationale.append("Volume spike on latest candle")
        score += 10

    div_type, div_strength = detect_momentum_divergence(df, is_bullish=(primary_direction == 'BUY'))
    if div_type:
        if sweep:
            rationale.append(f"Sweep generic momentum divergence: {div_type} (strength: {div_strength}%)")
        else:
            rationale.append(f"{div_type} (strength: {div_strength}%)")
            score += int(div_strength * 0.12)

    if not sweep:
        div_type_opp, div_strength_opp = detect_momentum_divergence(df, is_bullish=(primary_direction != 'BUY'))
        if div_type_opp:
            caution_text = (
                f"Optional opposing divergence observed: {div_type_opp} "
                f"(strength {div_strength_opp}%) on {primary_direction} breakout"
            )
            rationale.append(caution_text)
            gate_value_observations["opposing_momentum_divergence"] = {
                "divergence_type": div_type_opp,
                "divergence_strength": _safe_float(div_strength_opp, 0.0),
                "primary_direction": primary_direction,
                "hard_reject": False,
            }

    # ── Divergence gate (sweep path) — DISABLED ─────────────────────────────
    # check_swept_level_divergence is preserved in the codebase for future use
    # but is not called here. RSI divergence on 15m closes structurally cannot
    # fire on a fresh sweep: sweep candles wick through the level and close back
    # inside the range, so RSI on the close is always moderate (45-55) regardless
    # of how extreme the wick was. The gate was functioning as a near-universal
    # rejector, not a selective filter.
    #
    # Exhaustion is now covered by:
    #   • DOL Assessment (S1+S2+S3)       — rejects draw-on-liquidity
    #   • 4H counter-trend hard rejection  — only with-trend sweeps
    #   • 1H deterioration check           — rejects trend breakdown
    #   • Market regime gate               — rejects ranging
    #   • Volume structure gate            — rejects low-participation moves
    #   • Fresh entry evidence             — confirms reversal/continuation quality
    #
    _div_score = 0
    if sweep and swept_level is not None and SIGNAL_CONFIG.get("enable_sweep_anchor_divergence_layer", True):
        (
            sweep_anchor_divergence_confirmed,
            sweep_anchor_divergence_score,
            sweep_anchor_divergence_entry_price,
            sweep_anchor_divergence_reason,
        ) = check_swept_level_divergence(
            df,
            primary_direction,
            swept_level,
            atr_value,
            sweep_candle_idx=sweep_candle_idx,
        )
        sweep_anchor_divergence_score = float(sweep_anchor_divergence_score or 0.0)
        sweep_anchor_divergence_mode = _extract_sweep_anchor_divergence_mode(sweep_anchor_divergence_reason)
        _div_score = sweep_anchor_divergence_score
        if sweep_anchor_divergence_confirmed:
            bonus_multiplier = float(SIGNAL_CONFIG.get("sweep_anchor_divergence_bonus_multiplier", 0.12) or 0.12)
            bonus_cap = int(SIGNAL_CONFIG.get("sweep_anchor_divergence_bonus_cap", 12) or 12)
            sweep_anchor_divergence_bonus_points = max(
                0,
                min(bonus_cap, int(round(sweep_anchor_divergence_score * bonus_multiplier))),
            )
            if sweep_anchor_divergence_bonus_points:
                score += sweep_anchor_divergence_bonus_points
            rationale.append(
                f"Sweep-anchored divergence confirmed "
                f"(mode={sweep_anchor_divergence_mode}, score={sweep_anchor_divergence_score:.1f}/100)"
                f"{f' +{sweep_anchor_divergence_bonus_points}pts' if sweep_anchor_divergence_bonus_points else ''}"
            )
        elif sweep_anchor_divergence_score > 0:
            rationale.append(
                f"Sweep-anchored divergence observed "
                f"(mode={sweep_anchor_divergence_mode}, score={sweep_anchor_divergence_score:.1f}/100) "
                f"but below activation threshold"
            )

    # ── GATE 1 (cheap): Market regime — no WS needed ─────────────────────
    # Reject ranging markets before opening any WebSocket connection
    _ensure_candidate_context()
    if regime == 'ranging' and bool(SIGNAL_CONFIG.get("block_ranging_regime", True)):
        if _should_demote_gate("market_regime_ranging"):
            _log_audit_only_gate(
                "market_regime_gate",
                "market_regime_ranging",
                "Market in ranging regime — no trade",
                metrics={"market_regime": regime},
            )
        else:
            return _reject_after_path(
                "market_regime_gate",
                "market_regime_ranging",
                "Market in ranging regime — no trade",
            )

    # ── GATE 2 (cheap): Volume structure — no WS needed ──────────────────
    precision_context = {
        "symbol_bucket": symbol_bucket,
        "session_bucket": session_bucket,
        "trend_regime": trend_regime_at_reject or regime,
        "live_regime": regime,
        "structure_4h": structure_4h,
        "structure_15m": structure_15m,
        "direction_source_4h": "moving_average",
        "direction_source_15m": "moving_average",
        "ma_direction_4h_state": _to_json_safe((struct_4h_detail or {}).get("ma_direction_state", {})),
        "ma_direction_15m_state": _to_json_safe((struct_15m_detail or {}).get("ma_direction_state", {})),
        "vol_regime": "unknown",
        "liquidity_bucket": live_liquidity_bucket,
        "alignment_state": alignment_state,
        "htf_confluence_score": round(float(htf_score or 0.0), 4),
        "range_strength": round(float(range_strength), 4),
        "compression_score": round(float(compression_score), 4),
        "trend_regime_at_reject": trend_regime_at_reject,
        "entry_distance_atr": entry_distance_atr if entry_distance_atr is not None else _compute_entry_distance_atr(current_price, swept_level if sweep else breakout_level, atr_value),
        "entry_proximity_state": _to_json_safe(entry_proximity_state),
        "retest_quality": retest_quality,
    }
    if sweep and SIGNAL_CONFIG.get('enable_precision_sweep_filter', False):
        precision_regime_source = "live"
        allowed_regimes = [
            str(value).strip()
            for value in SIGNAL_CONFIG.get('precision_sweep_allowed_market_regimes', [])
            if str(value).strip()
        ]
        regime_for_precision = regime
        if allowed_regimes:
            if regime_for_precision not in allowed_regimes:
                precision_profile_passed = False
                failed_precision_checks = [
                    f"regime_blocked:{regime_for_precision} not in {', '.join(allowed_regimes)}"
                ]
                return _reject_after_path(
                    "precision_sweep_regime_gate",
                    "precision_sweep_regime_blocked",
                    (
                        f"Sweep precision filter: market regime {regime_for_precision} "
                        f"(source={precision_regime_source}) blocked "
                        f"(allowed: {', '.join(allowed_regimes)})"
                    ),
                    trigger_type="sweep",
                )
            rationale.append(
                f"Precision sweep filter passed: market regime {regime_for_precision} "
                f"(source={precision_regime_source}) in allowed set {allowed_regimes}"
            )
        precision_passed, precision_message, precision_details = _evaluate_precision_sweep_profile(precision_context)
        precision_profile_passed = precision_details.get("precision_profile_passed")
        failed_precision_checks = list(precision_details.get("failed_precision_checks") or [])
        if not precision_passed:
            return _reject_after_path(
                "precision_sweep_profile_gate",
                "precision_sweep_profile_blocked",
                precision_message,
                trigger_type="sweep",
            )
        if precision_message:
            rationale.append(precision_message)
    elif (
        not sweep
        and bo_dir
        and SIGNAL_CONFIG.get('enable_precision_breakout_filter', False)
    ):
        precision_regime_source = "live"
        allowed_regimes = [
            str(value).strip()
            for value in SIGNAL_CONFIG.get('precision_breakout_allowed_market_regimes', [])
            if str(value).strip()
        ]
        regime_for_precision = regime
        if allowed_regimes:
            if regime_for_precision not in allowed_regimes:
                precision_profile_passed = False
                failed_precision_checks = [
                    f"regime_blocked:{regime_for_precision} not in {', '.join(allowed_regimes)}"
                ]
                return _reject_after_path(
                    "precision_breakout_regime_gate",
                    "precision_breakout_regime_blocked",
                    (
                        f"Breakout precision filter: market regime {regime_for_precision} "
                        f"(source={precision_regime_source}) blocked "
                        f"(allowed: {', '.join(allowed_regimes)})"
                    ),
                    trigger_type="breakout",
                )
            rationale.append(
                f"Precision breakout filter passed: market regime {regime_for_precision} "
                f"(source={precision_regime_source}) in allowed set {allowed_regimes}"
            )
        precision_passed, precision_message, precision_details = _evaluate_precision_breakout_profile(precision_context)
        precision_profile_passed = precision_details.get("precision_profile_passed")
        failed_precision_checks = list(precision_details.get("failed_precision_checks") or [])
        if not precision_passed:
            return _reject_after_path(
                "precision_breakout_profile_gate",
                "precision_breakout_profile_blocked",
                precision_message,
                trigger_type="breakout",
            )
        if precision_message:
            rationale.append(precision_message)

    # Reject symbols without climactic volume before opening any WebSocket.
    # Pass that as `direction` so Component 1 identifies the correct displacement
    # volume. Pass `original_direction` so Component 3 hard reject uses the
    # correct RSI direction and does not fire on the displacement candles.
    vol_struct_direction = (
        ('SELL' if primary_direction == 'BUY' else 'BUY')
    )
    vol_struct_passed, vol_struct_score, vol_struct_reason = detect_volume_structure(
        df, vol_struct_direction, atr_value,
        original_direction=primary_direction
    )
    if not vol_struct_passed:
        if _should_demote_gate("volume_structure_failed"):
            _log_audit_only_gate(
                "volume_structure_gate",
                "volume_structure_failed",
                f"Volume structure gate failed: {vol_struct_reason}",
                metrics={"volume_structure_score": vol_struct_score},
            )
        else:
            return _reject_after_path(
                "volume_structure_gate",
                "volume_structure_failed",
                f"Volume structure gate failed: {vol_struct_reason}",
            )
    score += min(30, vol_struct_score // 2)
    rationale.append(f"Volume structure: {vol_struct_reason}")

    # ── Order flow and microstructure — fresh entry evidence ─────────────
    #
    # Static structure is scored first. Candle-derived orderflow is then checked
    # in the same signal cycle before placement, while websocket orderflow remains
    # optional telemetry/confirmation rather than stale pre-entry data.
    #

    order_flow = {
        'buy_pressure': 50.0, 'sell_pressure': 50.0,
        'imbalance': 0.0, 'cvd': 0.0, 'aggression_ratio': 0.0,
        'total_trade_vol': 0.0, 'reject_reason': None, 'fallback': False,
    }
    orderflow_strong      = False
    imbalance_sufficient  = False
    orderflow_gate_passed = False
    microstructure_score  = 0
    _sweep_age            = 0

    rationale.append(
        f"Order flow pending fresh entry gate ({'sweep' if sweep else 'breakout'} path)"
    )

    # ── MICROSTRUCTURE SCORING LAYER — DEFERRED ───────────────────────────────
    # Microstructure depends on order flow data, so it is scored only by the
    # fresh live entry gate rather than the static structure pass.
    microstructure_score     = 0
    microstructure_rationale = []

    # after the fresh live entry gate captures current order flow data.
    # The block below is a no-op placeholder so downstream references to
    # microstructure_score and microstructure_rationale remain valid.
    if False:  # dead branch — kept for structure reference only
        footprint = order_flow.get('footprint', {})
        if footprint.get('sufficient_data', False):
            # Determine data source for rationale labelling
            _fp_source = footprint.get('source', 'live_ws')
            _fp_source_label = (
                f"sweep candle OHLCV (age={_sweep_age}c)"
                if _fp_source == 'candle_historical'
                else f"live WS ({'20' if sweep and _sweep_age <= 1 else '5'}s window)"
            )

            if footprint.get('delta_divergence', False):
                dstr = footprint.get('divergence_strength', 0.0)
                net_d = footprint.get('net_delta', 0.0)
                top_opp = footprint.get('top_opposed_levels', [])

                if sweep:
                    microstructure_score += 12
                    if _fp_source == 'candle_historical':
                        # Candle-historical: divergence = wick-dominant high-volume candle
                        wick_r  = footprint.get('candle_wick_ratio', 0.0)
                        vol_r   = footprint.get('candle_vol_ratio', 0.0)
                        decay_r = footprint.get('post_vol_decay', 1.0)
                        microstructure_rationale.append(
                            f"Delta divergence CONFIRMED (candle-historical, {_fp_source_label}) "
                            f"— wick={wick_r:.2f}, vol_spike={vol_r:.1f}×MA, "
                            f"post_decay={decay_r:.2f} — absorption recorded at sweep candle"
                        )
                    else:
                        microstructure_rationale.append(
                            f"Delta divergence CONFIRMED ({_fp_source_label}) "
                            f"(strength={dstr:.2%}, net_delta={net_d:+.2f}) "
                            f"— institutional absorption at swept level"
                        )
                    if dstr >= 0.30:
                        microstructure_score += 5
                        microstructure_rationale.append(
                            f"High-conviction delta divergence (strength {dstr:.2%} >= 30%)"
                        )
                    if top_opp and _fp_source != 'candle_historical':
                        top_level = top_opp[0]
                        microstructure_rationale.append(
                            f"Peak opposition at ${top_level['price']:.4f} "
                            f"(delta={top_level['delta']:+.2f}, "
                            f"notional=${top_level['notional']:.0f})"
                        )
                else:
                    microstructure_rationale.append(
                        f"Delta divergence on BREAKOUT retest ({_fp_source_label}, "
                        f"strength={dstr:.2%}) "
                        f"— opposing absorption at retest level, continuation less reliable"
                    )
            else:
                # No divergence on live WS — skip clean-flow bonus for candle-historical
                # since absence of divergence in OHLCV means something different
                if _fp_source != 'candle_historical':
                    net_d = footprint.get('net_delta', 0.0)
                    total_v = footprint.get('total_vol', 1.0)
                    confirmation_ratio = abs(net_d) / max(total_v, 1e-9)
                    if confirmation_ratio >= 0.20:
                        microstructure_score += 4
                        microstructure_rationale.append(
                            f"Clean delta confirmation ({_fp_source_label}): no divergence, "
                            f"net_delta={net_d:+.2f} aligns with {primary_direction} "
                            f"(ratio={confirmation_ratio:.2%})"
                        )

        # ── 2. Absorption Detection (with actual key levels) ─────────────────
        # Build key levels list from SMC levels identified earlier in this function
        _key_levels_for_absorption = []
        if swept_level:
            _key_levels_for_absorption.append(swept_level)
        if breakout_level:
            _key_levels_for_absorption.append(breakout_level)
        # Add nearest SR levels
        if sr_highs:
            _key_levels_for_absorption.extend(
                [h for h in sr_highs if abs(h - current_price) / max(atr_value, 1e-9) <= 3.0][:3]
            )
        if sr_lows:
            _key_levels_for_absorption.extend(
                [l for l in sr_lows if abs(l - current_price) / max(atr_value, 1e-9) <= 3.0][:3]
            )

        # Re-run key-level cross-reference for live WS absorption.
        # Candle-historical absorption already has ob_level_absorbed=True
        # (the swept level is by definition the key level) — skip re-check.
        absorption_raw = order_flow.get('absorption', {})
        _abs_source = absorption_raw.get('source', 'live_ws')
        if (_abs_source != 'candle_historical' and
                _key_levels_for_absorption and
                absorption_raw.get('sufficient_data', False)):
            _tick = 10 ** (-symbol_config.get('price_place', 4))
            absorbed_list = absorption_raw.get('absorbed_levels', [])
            for ab in absorbed_list:
                for kl in _key_levels_for_absorption:
                    if kl and abs(ab['price'] - kl) <= _tick * 3:
                        ab['is_key_level'] = True
                        absorption_raw['ob_level_absorbed'] = True
                        break

        absorption = absorption_raw
        if absorption.get('absorption_detected', False):
            max_ratio = absorption.get('max_absorption_ratio', 0.0)
            ob_absorbed = absorption.get('ob_level_absorbed', False)
            _abs_src_label = (
                f"candle-historical (sweep_age={_sweep_age}c)"
                if absorption.get('source') == 'candle_historical'
                else 'live WS'
            )

            if ob_absorbed:
                if max_ratio >= ABSORPTION_RATIO_STRONG:
                    microstructure_score += 14
                    if absorption.get('source') == 'candle_historical':
                        cd = absorption.get('candle_detail', {})
                        microstructure_rationale.append(
                            f"STRONG absorption at swept level ({_abs_src_label}) "
                            f"— wick={cd.get('wick_ratio',0):.2f}, "
                            f"vol={cd.get('vol_ratio',0):.1f}×MA, "
                            f"body={cd.get('body_ratio',0):.2f}, "
                            f"post_decay={cd.get('post_vol_decay',1):.2f}, "
                            f"strength={max_ratio/5.0:.2f}"
                        )
                    else:
                        microstructure_rationale.append(
                            f"STRONG absorption at key SMC level ({_abs_src_label}) "
                            f"(ratio={max_ratio:.1f}×VPT, OB/swept level confirmed defended)"
                        )
                else:
                    microstructure_score += 8
                    microstructure_rationale.append(
                        f"Moderate absorption at key SMC level ({_abs_src_label}) "
                        f"(ratio={max_ratio:.1f}×VPT)"
                    )
            else:
                if max_ratio >= ABSORPTION_RATIO_STRONG:
                    microstructure_score += 6
                    microstructure_rationale.append(
                        f"Strong absorption detected ({_abs_src_label}, "
                        f"ratio={max_ratio:.1f}×VPT) "
                        f"— not at identified key level, possible unlisted OB"
                    )
                elif max_ratio >= ABSORPTION_RATIO_MODERATE:
                    microstructure_score += 3
                    microstructure_rationale.append(
                        f"Moderate absorption ({_abs_src_label}, ratio={max_ratio:.1f}×VPT)"
                    )

        # ── 3. Liquidity Structure (walls + voids + migration) ────────────────
        #
        # Wall and void data comes from top-10 bid/ask depth — this covers only
        # a few ticks around the current touch. It is ENTRY EXECUTION QUALITY
        # data, not path-to-TP data. Scored accordingly.
        #
        # Path-to-TP friction is handled separately via S/R density check below,
        # which operates at the correct spatial scale (ATR multiples, not ticks).
        liquidity = order_flow.get('liquidity', {})
        if liquidity.get('sufficient_data', False):
            walls = liquidity.get('liquidity_walls', [])
            voids = liquidity.get('liquidity_voids', [])
            migs  = liquidity.get('migration_events', [])

            # ── Wall: large resting order at the current touch level ──────────
            # Classify by which side of current price the wall sits on.
            #
            # Opposing wall (ask wall for BUY, bid wall for SELL):
            #   Sweep path  → the sweeping participant has now rested on the other
            #                 side to defend the reversal. This is a positive sign —
            #                 the same institutional hand is present. Score: +5
            #   Breakout path → a resting seller (or buyer) you must consume to
            #                   continue. Genuine execution friction. Score: -6
            #
            # Same-side wall (bid wall for BUY, ask wall for SELL):
            #   Large participant defending your entry level from below (BUY) or
            #   above (SELL). Confirms the level is institutionally supported.
            #   Score: +4 on both paths.
            _queue_data = order_flow.get('queue') if isinstance(order_flow, dict) else {}
            _queue_data = _queue_data if isinstance(_queue_data, dict) else {}
            _best_bid = _queue_data.get('best_bid_price')
            _best_ask = _queue_data.get('best_ask_price')

            _opposing_wall  = None
            _same_side_wall = None

            for wall in walls:
                wp   = wall['price']
                side = wall.get('side', 'unknown')
                if primary_direction == 'BUY':
                    # Opposing = ask side (above current price)
                    if side == 'ask' or (_best_ask and abs(wp - _best_ask) < atr_value * 0.5):
                        if _opposing_wall is None or wall['mult'] > _opposing_wall['mult']:
                            _opposing_wall = wall
                    # Same side = bid side (below current price or at touch)
                    elif side == 'bid' or (_best_bid and abs(wp - _best_bid) < atr_value * 0.5):
                        if _same_side_wall is None or wall['mult'] > _same_side_wall['mult']:
                            _same_side_wall = wall
                else:
                    # SELL: opposing = bid side (below current price)
                    if side == 'bid' or (_best_bid and abs(wp - _best_bid) < atr_value * 0.5):
                        if _opposing_wall is None or wall['mult'] > _opposing_wall['mult']:
                            _opposing_wall = wall
                    elif side == 'ask' or (_best_ask and abs(wp - _best_ask) < atr_value * 0.5):
                        if _same_side_wall is None or wall['mult'] > _same_side_wall['mult']:
                            _same_side_wall = wall

            if _opposing_wall:
                if sweep:
                    microstructure_score += 5
                    microstructure_rationale.append(
                        f"Opposing wall at touch ({_opposing_wall['price']:.4f}, "
                        f"{_opposing_wall['mult']:.1f}×avg, side={_opposing_wall['side']}) "
                        f"on SWEEP path — institutional participant resting on reversal side "
                        f"confirms genuine sweep-and-reverse structure"
                    )
                else:
                    microstructure_rationale.append(
                        f"Opposing wall at touch ({_opposing_wall['price']:.4f}, "
                        f"{_opposing_wall['mult']:.1f}×avg, side={_opposing_wall['side']}) "
                        f"on BREAKOUT path — resting size must be consumed before continuation, "
                        f"execution friction at entry"
                    )

            if _same_side_wall:
                microstructure_score += 4
                microstructure_rationale.append(
                    f"Same-side wall at touch ({_same_side_wall['price']:.4f}, "
                    f"{_same_side_wall['mult']:.1f}×avg) — large participant defending "
                    f"{'bid' if primary_direction == 'BUY' else 'ask'} side of entry level"
                )

            # ── Void: thin book at the touch level ───────────────────────────
            # A void here means the book is genuinely thin at entry.
            # Only scored if queue_drain is False — if queue_drain already fired
            # at +10, this is the same signal (thin book) at lower resolution.
            # Scoring a void on top of a confirmed queue drain is double-counting.
            _queue_drain_already_scored = (
                _queue_data.get(
                    'queue_drain_bid' if primary_direction == 'BUY' else 'queue_drain_ask',
                    False
                )
            )
            _void_at_touch = any(
                (primary_direction == 'BUY' and
                 v.get('price_low', 0) <= (current_price + atr_value * 0.3) and
                 v.get('price_high', 0) >= (current_price - atr_value * 0.3))
                or
                (primary_direction == 'SELL' and
                 v.get('price_low', 0) <= (current_price + atr_value * 0.3) and
                 v.get('price_high', 0) >= (current_price - atr_value * 0.3))
                for v in voids
            )
            if _void_at_touch and not _queue_drain_already_scored:
                microstructure_score += 2
                microstructure_rationale.append(
                    "Thin book (void) at touch level — low resistance to fill, "
                    "entry execution quality high (queue drain not yet confirmed)"
                )

            # ── Migration: informed participant repositioning toward entry ────
            # BUY: bid-side order walking UP toward current price = accumulator
            #      not willing to wait — chasing the fill upward before the move
            # SELL: ask-side order walking DOWN toward current price = distributor
            _aligned_migs = []
            for m in migs:
                if primary_direction == 'BUY' and m['direction'] == 'toward_bid':
                    if m['to_price'] > m['from_price']:
                        _aligned_migs.append(m)
                elif primary_direction == 'SELL' and m['direction'] == 'toward_ask':
                    if m['to_price'] < m['from_price']:
                        _aligned_migs.append(m)

            if _aligned_migs:
                top_mig = sorted(_aligned_migs, key=lambda x: -x['notional'])[0]
                microstructure_score += 6
                microstructure_rationale.append(
                    f"Liquidity MIGRATION: informed participant repositioning toward "
                    f"{'bid' if primary_direction == 'BUY' else 'ask'} before entry "
                    f"(${top_mig['notional']:.0f} notional, "
                    f"{top_mig['from_price']:.4f} → {top_mig['to_price']:.4f})"
                )

        # ── S/R DENSITY: path clearance to TP1 (correct spatial scale) ───────
        # Walls and voids above cover microstructure at the touch (ticks).
        # This check operates at the right scale for TP1 reachability: how many
        # structural S/R levels sit between entry and 2R (the TP1 distance)?
        #
        # Uses sr_highs/sr_lows already identified from swing points + equal
        # highs/lows. A level counts if it sits within the 2R corridor and is
        # not the swept level itself (which is behind us, not in the path).
        #
        # 0 levels: clear run to TP1              → +6
        # 1 level:  one test needed, manageable   →  0 (neutral, log only)
        # 2+ levels: layered structural friction  → -6
        _tp1_distance = atr_value * SIGNAL_CONFIG.get('tp1_rr_multiplier', 1.5) * \
                        SIGNAL_CONFIG.get('atr_sl_multiplier', 1.5)
        if primary_direction == 'BUY':
            _tp1_proxy    = current_price + _tp1_distance
            _levels_in_path = [
                h for h in sr_highs
                if current_price < h <= _tp1_proxy
                and (swept_level is None or abs(h - swept_level) > atr_value * 0.3)
            ]
        else:
            _tp1_proxy    = current_price - _tp1_distance
            _levels_in_path = [
                l for l in sr_lows
                if _tp1_proxy <= l < current_price
                and (swept_level is None or abs(l - swept_level) > atr_value * 0.3)
            ]

        _n_path_levels = len(_levels_in_path)
        if _n_path_levels == 0:
            microstructure_score += 6
            microstructure_rationale.append(
                f"Clear path to TP1 ({_tp1_proxy:.{price_place}f}): "
                f"0 structural S/R levels in the 2R corridor — unobstructed run expected"
            )
        elif _n_path_levels == 1:
            microstructure_rationale.append(
                f"One S/R level in path to TP1 ({_levels_in_path[0]:.{price_place}f}) "
                f"— manageable, price will test it but not structural congestion"
            )
        else:
            _path_str = ', '.join(f"{l:.{price_place}f}" for l in _levels_in_path[:4])
            microstructure_rationale.append(
                f"Layered S/R friction to TP1: {_n_path_levels} levels in path "
                f"[{_path_str}] — multiple structural tests required before target"
            )

        # ── 4. Queue Dynamics Statistical Validation ─────────────────────────
        queue = order_flow.get('queue', {})
        if queue.get('sufficient_data', False):
            # BUY setup: bid queue drain before sweep = support was bait, not real
            # SELL setup: ask queue drain before sweep = resistance was bait
            if primary_direction == 'BUY':
                queue_drain   = queue.get('queue_drain_bid', False)
                queue_stable  = queue.get('queue_stable_bid', False)
                z_val         = queue.get('bid_z_score', 0.0)
                n_events      = queue.get('bid_n', 0)
                session_mean  = queue.get('bid_session_mean', 0.0)
                tw_size       = queue.get('bid_touch_tw_size', 0.0)
            else:
                queue_drain   = queue.get('queue_drain_ask', False)
                queue_stable  = queue.get('queue_stable_ask', False)
                z_val         = queue.get('ask_z_score', 0.0)
                n_events      = queue.get('ask_n', 0)
                session_mean  = queue.get('ask_session_mean', 0.0)
                tw_size       = queue.get('ask_touch_tw_size', 0.0)

            if queue_drain and sweep:
                # Queue was drained before sweep = the level was not genuinely defended.
                # The "support" was withdrawn by the same participant who is now reversing.
                # This is the strongest leading indicator for a genuine institutional sweep.
                microstructure_score += 10
                microstructure_rationale.append(
                    f"Queue DRAIN confirmed before sweep "
                    f"(z={z_val:.2f}, n={n_events}, "
                    f"tw_size={tw_size:.2f} vs session_mean={session_mean:.2f}) "
                    f"— touch-level liquidity withdrawn pre-sweep = institutional bait and reverse"
                )
            elif queue_stable and not sweep:
                # On breakout path: stable queue at touch = level is genuinely defended.
                # Price will need to consume this queue before continuing — healthy retest.
                microstructure_score += 5
                microstructure_rationale.append(
                    f"Queue STABILITY confirmed at touch level "
                    f"(z={z_val:.2f}, n={n_events}) "
                    f"— genuine size defending level, healthy retest structure"
                )
            elif queue_drain and not sweep:
                # Breakout path: queue drain at touch level = book is thin.
                # Could be a clean path (void) OR a setup for a fake breakout.
                # Score neutral — log it for context.
                microstructure_rationale.append(
                    f"Queue drain at touch (z={z_val:.2f}) on breakout path "
                    f"— thin book, move may be fast but could also be low-conviction"
                )
            elif abs(z_val) >= QUEUE_Z_SCORE_SIGNIFICANT * 0.7 and n_events >= 5:
                # Sub-threshold but notable — log for context, no score change
                direction_str = "thinning" if z_val < 0 else "thickening"
                microstructure_rationale.append(
                    f"Queue {direction_str} at touch (z={z_val:.2f}, n={n_events}) "
                    f"— below significance threshold, monitoring"
                )

        # Apply microstructure score
        if microstructure_score != 0:
            score += microstructure_score
            direction_str = f"+{microstructure_score}" if microstructure_score > 0 else str(microstructure_score)
            rationale.append(
                f"Microstructure layer: {direction_str} pts "
                f"({'confirming' if microstructure_score > 0 else 'friction detected'})"
            )
        for mr in microstructure_rationale:
            rationale.append(f"  ↳ {mr}")

    # ── Wyckoff bonus + regime scoring (after all gates) ─────────────────
    wyckoff_strong = wyckoff_pattern and wyckoff_conf >= 68
    if wyckoff_strong:
        score += 8
        rationale.append(f"Wyckoff bonus: {wyckoff_pattern} (conf {wyckoff_conf}%)")
    if regime == 'trending_strong':
        score += 8
        rationale.append("Strong trending market")
    elif regime == 'trending_weak':
        score += 4
        rationale.append("Weak trending market")
    fibs = calculate_fibonacci_levels(df)
    if any(abs(current_price - v) / v < SIGNAL_CONFIG.get('fib_tolerance', 0.02) for v in fibs.values()):
        score += 4
        rationale.append("Price near Fibonacci retracement")
    # ── Path-tailored ensemble voting ────────────────────────────────────────
    # Sweep path: reversal setup — weights favour exhaustion/reversal signals.
    #   Wyckoff Phase C, HTF exhaustion, and order flow are the strongest
    #   confirmations. Breakout patterns (IBO) are excluded entirely.
    #   The sweep trigger itself contributes 4 votes automatically.
    #
    # Breakout path: continuation setup — weights favour structure,
    #   momentum, and trend alignment. Wyckoff SOS/LPS, consolidation
    #   breaks, IBO, and trend regime are primary confirmations.
    #   No free votes — all votes must be earned from secondary confluence.
    #
    # order_flow voter: uses actual gate pass (pressure OR imbalance) rather
    #   than the tight 4-condition 'signal' field which can be None even when
    #   order flow clearly passed GATE 3 and GATE 4. This closes the gap where
    #   order flow passes all gates but contributes 0 ensemble votes.
    # NOTE: orderflow_strong and orderflow_gate_passed are already set correctly
    # Do NOT recompute them here; that would override the flip path's False values.

    if sweep:
        # ── SWEEP ensemble voters ─────────────────────────────────────────
        wyckoff_phase_c = (
            phase_info.get('Phase C (Spring)', 0) >= 25 or
            phase_info.get('Phase C (UTAD)', 0) >= 25
        ) if wyckoff_pattern else False

        # order_flow voter is zeroed in the static ensemble; fresh entry
        # evidence is checked separately before placement.
        voters = {
            'liquidity_sweep'       : 4,
            'agreeing_breakout'     : 2 if (bo_dir and bo_dir == primary_direction) else 0,
            'wyckoff_phase_c'       : 5 if wyckoff_phase_c else (3 if wyckoff_pattern else 0),
            'htf_exhaustion'        : 3 if htf_score >= 1.5 else (1 if htf_score >= 0.5 else 0),
            'order_flow'            : 0,   # DEFERRED — re-evaluated with fresh data at confirmation
            'consolidation'         : 1 if consolidation_break else 0,
            'candle'                : 2 if candle else 0,
            'divergence'            : 0,   # divergence gate removed
            'failed_structure'      : 2 if (not sweep or (sweep and score > 0 and
                                       "Prior failed breakout" in str(rationale))) else 0,
            'trend'                 : 1 if 'trending' in regime else 0,
        }
        ensemble_min = mode_profile["ensemble_min_static_sweep"]
        path_label = "sweep"

        # Pure price-action path. No order flow voters.
        # effort-result score on the exact displacement candles.
        # Wyckoff Phase C and HTF exhaustion are strongest confirmations.
        # The failed breakout is always present as the setup precondition —
        # fixed 2 votes, no conditional check needed.
        wyckoff_phase_c = (
            phase_info.get('Phase C (Spring)', 0) >= 25 or
            phase_info.get('Phase C (UTAD)', 0) >= 25
        ) if wyckoff_pattern else False

        # failed_structure tiered by er_score — the degree of absorption on
        # the exact displacement candles is the primary quality signal for a flip.
        # type but also the least certain — institutions CAN keep running.
        # Score it lowest (1 vote) so ensemble forces other confirmation.
        # Strong absorption (er < -0.5) = institutions sold INTO the breakout
        # decisively — this is the highest-confidence flip setup (4 votes).
        if er_score < -0.5:
            failed_structure_votes = 4   # strong absorption — decisive institutional fade
        elif er_score < -0.3:
            failed_structure_votes = 3   # moderate absorption — clear effort/result failure
        elif er_score < 0.0:
            failed_structure_votes = 2   # mild absorption — marginal exhaustion
        else:
            failed_structure_votes = 1   # momentum spike trap — real but uncertain

        voters = {
            'liquidity_sweep'       : 0,
            'wyckoff_phase_c'       : 4 if wyckoff_phase_c else (2 if wyckoff_pattern else 0),
            'htf_exhaustion'        : 3 if htf_score >= 1.5 else (1 if htf_score >= 0.5 else 0),
            'candle'                : 2 if candle else 0,
            'divergence'            : 3 if div_type else 0,
            # Tiered by er_score — reflects actual absorption strength on displacement candles
            'failed_structure'      : failed_structure_votes,
            'trend'                 : 1 if 'trending' in regime else 0,
            # consolidation voter removed — always None on flip path, misleading slot
            'order_flow'            : 0,
        }

    else:
        # ── BREAKOUT ensemble voters ──────────────────────────────────────
        # Continuation-weighted: structure, momentum, trend alignment, and
        # volume are primary. Wyckoff SOS/LPS and IBO are strong confirmations.
        # No free votes — sweep voter is 0, all votes earned.
        wyckoff_sos = (
            phase_info.get('Phase E (Markup)', 0) >= 15 or
            phase_info.get('Phase D (SOS)', 0) >= 15 or
            phase_info.get('Phase E (Markdown)', 0) >= 15 or
            phase_info.get('Phase D (SOW)', 0) >= 15
        ) if wyckoff_pattern else False

        voters = {
            # No free trigger votes on breakout path
            'liquidity_sweep'       : 0,
            # Fix 14: retest voter weighted by quality, not just existence.
            # bo_dir is always set on the breakout path — a flat 5 votes regardless
            # of retest quality means every breakout path earns 5 votes unconditionally.
            # Tier by ER score: strong momentum cluster = 5, acceptable = 3, weak = 2.
            'breakout_retest'       : (5 if er_score > 0.3 else (3 if er_score >= -0.1 else 2)) if bo_dir else 0,
            # Wyckoff: SOS/LPS/SOW/LPSY are continuation signals
            'wyckoff_sos'           : 4 if wyckoff_sos else (2 if wyckoff_pattern else 0),
            # HTF trend alignment — mandatory confirmation for continuation
            'htf_alignment'         : 3 if htf_score >= 1.5 else (2 if htf_score >= 0.5 else 0),
            # order_flow voter zeroed at cycle 1 — re-evaluated fresh at confirmation
            'order_flow'            : 0,   # DEFERRED — re-evaluated with fresh data at confirmation
            # Consolidation break with retest — strong continuation signal
            'consolidation'         : 3 if consolidation_break else 0,
            # IBO — microstructure breakout confirmation, relevant here
            'ibo'                   : 2 if ibo_type else 0,
            # Candlestick continuation pattern
            'candle'                : 1 if candle else 0,
            # Momentum divergence — less critical for continuation, still useful
            'divergence'            : 2 if div_type else 0,
            # Trend regime — breakouts in strong trends are higher probability
            'trend'                 : 3 if regime == 'trending_strong' else (2 if regime == 'trending_weak' else 0),
        }
        ensemble_min = mode_profile["ensemble_min_static_breakout"]
        path_label = "breakout"

    total_votes = sum(voters.values())
    ensemble_votes = int(total_votes)
    ensemble_min_required = int(ensemble_min)
    vote_breakdown = _normalize_vote_breakdown(voters)
    missing_vote_types = _derive_missing_vote_types(vote_breakdown)
    static_ensemble_soft_bypassed = False
    static_ensemble_soft_bypass_reason = ""
    ensemble_hard_floor = int(SIGNAL_CONFIG.get("ensemble_min_votes_hard_floor", 5) or 5)
    if total_votes < ensemble_hard_floor:
        _ensemble_floor_reason = (
            f"Ensemble hard floor audit ({total_votes} votes, "
            f"hard floor {ensemble_hard_floor}, path={path_label})"
        )
        if bool(SIGNAL_CONFIG.get("enable_ensemble_hard_gate", False)):
            return _reject_after_path(
                "static_ensemble_gate",
                "static_ensemble_hard_floor_failed",
                _ensemble_floor_reason,
                trigger_type=path_label,
            )
        _log_audit_only_gate(
            "static_ensemble_gate",
            "static_ensemble_hard_floor_audit",
            _ensemble_floor_reason,
            metrics={
                "ensemble_votes": total_votes,
                "ensemble_hard_floor": ensemble_hard_floor,
                "path_label": path_label,
                "vote_breakdown": vote_breakdown,
            },
        )
    if total_votes < ensemble_min:
        _ensemble_min_reason = (
            f"Ensemble voting audit ({total_votes} votes, required {ensemble_min}, path={path_label})"
        )
        if bool(SIGNAL_CONFIG.get("enable_ensemble_hard_gate", False)):
            return _reject_after_path(
                "static_ensemble_gate",
                "static_ensemble_failed",
                _ensemble_min_reason,
                trigger_type=path_label,
            )
        _log_audit_only_gate(
            "static_ensemble_gate",
            "static_ensemble_audit",
            _ensemble_min_reason,
            metrics={
                "ensemble_votes": total_votes,
                "ensemble_min": ensemble_min,
                "path_label": path_label,
                "vote_breakdown": vote_breakdown,
            },
        )
        static_ensemble_soft_bypassed, static_ensemble_soft_bypass_reason = _evaluate_static_ensemble_soft_bypass(
            precision_context,
            path_label,
        )
        if not static_ensemble_soft_bypassed:
            static_ensemble_soft_bypass_reason = (
                f"Ensemble retained for audit only despite low votes"
            )
        rationale.append(
            f"{static_ensemble_soft_bypass_reason} "
            f"({total_votes} votes, required {ensemble_min}, path={path_label})"
        )
        logger.info(
            f"[{symbol}] {static_ensemble_soft_bypass_reason}: "
            f"{total_votes} votes < required {ensemble_min} (path={path_label})"
        )
    rationale.append(f"Ensemble [{path_label}]: {total_votes} votes (min {ensemble_min}) — {dict((k,v) for k,v in voters.items() if v > 0)}")
    score += total_votes * 2
    score = int(score)  # No cap — full score reflects true confluence depth

    # Funding rate (late-fetch to avoid cost on rejected signals)
    # Only run when the mode explicitly requires funding alignment.
    # Balanced/relaxed skip funding entirely to avoid needless fetches.
    # Funding gate retired from live decisioning.

    # Static score gate. Fresh ADX/orderflow checks run in the live entry gate below.
    if sweep:
        min_score_static = mode_profile["min_score_static_sweep"]
        min_score_final = mode_profile["min_score_sweep"]
    else:
        min_score_static = mode_profile["min_score_static_breakout"]
        min_score_final = mode_profile["min_score_breakout"]

    quality_score_audit = round(float(score), 4)
    quality_threshold = round(float(min_score_static), 4)
    quality_subscores = _build_quality_subscores(static_score=score, final_score=score)
    if not primary_direction:
        return _reject_after_path(
            "static_score_gate",
            "missing_primary_direction",
            f"No primary direction established for {path_label} setup",
            trigger_type=path_label,
        )
    if score < min_score_static:
        _static_score_reason = (
            f"Static quality score audit: score={score}, "
            f"required={min_score_static}, path={path_label}"
        )
        if bool(SIGNAL_CONFIG.get("enable_static_quality_hard_gate", False)):
            return _reject_after_path(
                "static_score_gate",
                "signal_below_static_quality_threshold",
                _static_score_reason,
                trigger_type=path_label,
            )
        _log_audit_only_gate(
            "static_score_gate",
            "signal_below_static_quality_threshold_audit",
            _static_score_reason,
            metrics={
                "score": score,
                "required_score": min_score_static,
                "path_label": path_label,
            },
        )
    min_score = min_score_static

    signal_direction = 'BUY' if primary_direction == 'BUY' else 'SELL'
    entry_price = float(current_price)
    if atr_value and atr_value > 0:
        if sweep and swept_level is not None:
            sweep_entry_buffer = atr_value * float(SIGNAL_CONFIG.get("sweep_entry_buffer_atr", 0.1) or 0.1)
            entry_price = (
                float(swept_level) + sweep_entry_buffer
                if signal_direction == 'BUY'
                else float(swept_level) - sweep_entry_buffer
            )
        elif breakout_level is not None:
            breakout_entry_buffer = atr_value * float(SIGNAL_CONFIG.get("breakout_entry_buffer_atr", 0.05) or 0.05)
            entry_price = (
                float(breakout_level) + breakout_entry_buffer
                if signal_direction == 'BUY'
                else float(breakout_level) - breakout_entry_buffer
            )

    sl, tp1, tp2, trailing_sl = calculate_sl_tp(
        entry_price,
        signal_direction,
        atr_value,
        df,
        price_place,
        swept_level=swept_level if sweep else None,
        trigger_type='sweep' if sweep else 'breakout',
        acceptance_low=breakout_acceptance_low if not sweep else None,
        acceptance_high=breakout_acceptance_high if not sweep else None,
    )
    if sl is None:
        return None, "SL/TP calculation failed"
    _cached_swing_snapshot = None
    swing_snapshot = _ensure_swing_snapshot()
    config_snapshot = _build_live_config_snapshot()
    config_snapshot_fields = _build_live_config_snapshot_fields()
    if bool(SIGNAL_CONFIG.get("use_exchange_min_order_size", True)):
        notional, estimated_min_size = _estimate_exchange_min_trade_value(symbol_config, entry_price)
        notional = notional or TRADE_CONFIG.get('fixed_trade_amount', 10)
    else:
        estimated_min_size = None
        notional = TRADE_CONFIG.get('fixed_trade_amount', 10)
    position_size = notional / entry_price if entry_price > 0 else 0
    _ensure_research_audit_context()
    signal = {
        'symbol': symbol,
        'direction': signal_direction,
        'trigger_type': path_trigger_type or ('sweep' if sweep else 'breakout'),
        'primary_setup': path_trigger_type or ('sweep' if sweep else 'breakout'),
        'entry_price': round(entry_price, price_place),
        'price_place': price_place,
        'atr_value': float(atr_value),
        'stop_loss': sl,
        'take_profit_1': tp1,
        'take_profit_2': tp2,
        'trailing_stop_loss': trailing_sl,
        'position_size': position_size,
        'estimated_trade_value': round(float(notional), 6) if notional else None,
        'estimated_exchange_min_trade_size': estimated_min_size,
        'sizing_mode': 'exchange_minimum' if bool(SIGNAL_CONFIG.get("use_exchange_min_order_size", True)) else 'fixed_notional',
        'confidence_score': score,
        'static_score': score,
        'rationale': rationale,
        'timestamp': time.time(),
        'market_regime': regime,
        'research_trend_regime': research_regime_ctx.get('trend_regime'),
        'research_vol_regime': research_regime_ctx.get('vol_regime'),
        'research_adx_regime': research_regime_ctx.get('adx_regime'),
        'structure_4h': structure_4h,
        'structure_15m': structure_15m,
        'direction_source_4h': 'moving_average',
        'direction_source_15m': 'moving_average',
        'ma_direction_4h_state': _to_json_safe((struct_4h_detail or {}).get("ma_direction_state", {})),
        'ma_direction_15m_state': _to_json_safe((struct_15m_detail or {}).get("ma_direction_state", {})),
        'structure_alignment': _structure_alignment_relation(structure_4h, structure_15m),
        'symbol_bucket': symbol_bucket,
        'liquidity_bucket': live_liquidity_bucket,
        'quote_volume': None if pd.isna(live_quote_volume) else float(live_quote_volume),
        'session_bucket': session_bucket,
        'bucket_filter_applied': bucket_filter_applied,
        'static_ensemble_soft_bypassed': static_ensemble_soft_bypassed,
        'static_ensemble_soft_bypass_reason': (
            static_ensemble_soft_bypass_reason if static_ensemble_soft_bypassed else None
        ),
        'gate_observations': gate_observations,
        'gate_value_observations': gate_value_observations,
        'entry_distance_atr': entry_distance_atr if entry_distance_atr is not None else _compute_entry_distance_atr(current_price, swept_level if sweep else breakout_level, atr_value),
        'entry_proximity_state': _to_json_safe(entry_proximity_state),
        'entry_proximity_mode': entry_proximity_state.get("mode") if isinstance(entry_proximity_state, dict) else None,
        'entry_proximity_max_atr': _safe_float((entry_proximity_state or {}).get("max_entry_atr")) if isinstance(entry_proximity_state, dict) else None,
        'entry_proximity_base_atr': _safe_float((entry_proximity_state or {}).get("base_entry_atr")) if isinstance(entry_proximity_state, dict) else None,
        'entry_proximity_confirmed_atr': _safe_float((entry_proximity_state or {}).get("confirmed_entry_atr")) if isinstance(entry_proximity_state, dict) else None,
        'entry_proximity_last_candle_confirmed': bool((entry_proximity_state or {}).get("last_candle_confirmed")) if isinstance(entry_proximity_state, dict) else False,
        'context_risk_multiplier': None,
        'context_risk_tier': None,
        'context_risk_reasons': [],
        'momentum_divergence_type': div_type,
        'momentum_divergence_strength': float(div_strength or 0.0),
        'has_momentum_divergence': bool(div_type),
        'delta_divergence_strength': float(
            ((order_flow.get('footprint', {}) or {}).get('divergence_strength', 0.0))
            if isinstance(order_flow, dict) else 0.0
        ),
        'has_delta_divergence': bool(
            ((order_flow.get('footprint', {}) or {}).get('delta_divergence', False))
            if isinstance(order_flow, dict) else False
        ),
        'sweep_anchor_divergence_confirmed': bool(sweep_anchor_divergence_confirmed),
        'sweep_anchor_divergence_score': float(sweep_anchor_divergence_score or 0.0),
        'sweep_anchor_divergence_mode': sweep_anchor_divergence_mode,
        'sweep_anchor_divergence_reason': sweep_anchor_divergence_reason,
        'sweep_anchor_divergence_bonus_points': int(sweep_anchor_divergence_bonus_points or 0),
        'sweep_anchor_divergence_entry_price': (
            float(sweep_anchor_divergence_entry_price)
            if sweep_anchor_divergence_entry_price is not None
            else None
        ),
        'of_gate_decision': None,
        'of_gate_stage': None,
        'of_gate_final_score': None,
        'of_gate_min_score_final': None,
        'of_gate_directional_pressure': None,
        'of_gate_imbalance': None,
        'htf_confluence': htf_score,
        'htf_ma_confirmation_state': _to_json_safe(htf_ma_confirmation_state),
        'htf_4h_ma_price': _safe_float((htf_ma_confirmation_state or {}).get("price")),
        'htf_4h_ema_fast': _safe_float((htf_ma_confirmation_state or {}).get("ema_fast")),
        'htf_4h_ema_slow': _safe_float((htf_ma_confirmation_state or {}).get("ema_slow")),
        'htf_4h_ema_fast_slope': _safe_float((htf_ma_confirmation_state or {}).get("ema_fast_slope_per_bar")),
        'htf_4h_ema_slow_slope': _safe_float((htf_ma_confirmation_state or {}).get("ema_slow_slope_per_bar")),
        'htf_4h_ma_stack_passed': bool((htf_ma_confirmation_state or {}).get("ma_stack_passed")),
        'htf_4h_price_side_passed': bool((htf_ma_confirmation_state or {}).get("price_vs_slow_ma_passed")),
        'htf_4h_fast_slope_passed': bool((htf_ma_confirmation_state or {}).get("fast_ma_slope_passed")),
        'htf_4h_macd_hist': _safe_float((htf_ma_confirmation_state or {}).get("macd_hist")),
        'htf_4h_macd_hist_slope': _safe_float((htf_ma_confirmation_state or {}).get("macd_hist_slope_per_bar")),
        'htf_4h_macd_support': (htf_ma_confirmation_state or {}).get("macd_support"),
        'order_block_context': _to_json_safe(order_block_context),
        'order_flow': order_flow,
        'sr_nearest_high': max([h for h in sr_highs if h <= current_price] or [0]),
        'sr_nearest_low': min([l for l in sr_lows if l >= current_price] or [0]),
        # ── Path-specific geometry fields — required for SL/TP recalculation at placement ──
        'swept_level':                swept_level if sweep else None,
        'sweep_candle_idx':           sweep_candle_idx if sweep else None,
        'breakout_level':             breakout_level if not sweep else None,
        'breakout_idx':               breakout_idx if not sweep else None,
        'breakout_retest_details':    _to_json_safe(breakout_retest_details if not sweep else {}),
        'breakout_acceptance_low':    breakout_acceptance_low if not sweep else None,
        'breakout_acceptance_high':   breakout_acceptance_high if not sweep else None,
        'config_snapshot':            config_snapshot,
        'swing_snapshot':             swing_snapshot,
        # ── Microstructure fields ─────────────────────────────────────────────
        'microstructure': {
            'score':              microstructure_score,
            'footprint':          order_flow.get('footprint', {}) if isinstance(order_flow, dict) else {},
            'absorption':         order_flow.get('absorption', {}) if isinstance(order_flow, dict) else {},
            'liquidity':          order_flow.get('liquidity', {}) if isinstance(order_flow, dict) else {},
            'queue':              order_flow.get('queue', {}) if isinstance(order_flow, dict) else {},
            'delta_divergence':   (order_flow.get('footprint', {}) or {}).get('delta_divergence', False),
            'ob_level_absorbed':  (order_flow.get('absorption', {}) or {}).get('ob_level_absorbed', False),
            'queue_drain':        (
                (order_flow.get('queue', {}) or {}).get('queue_drain_bid', False)
                if signal_direction == 'BUY'
                else (order_flow.get('queue', {}) or {}).get('queue_drain_ask', False)
            ),
            'migration_count':    len((order_flow.get('liquidity', {}) or {}).get('migration_events', [])),
        },
    }
    signal.update(config_snapshot_fields)
    signal.update(swing_snapshot)
    signal.update(
        _build_gate_audit_snapshot(
            trigger_type_override=signal.get('trigger_type', path_trigger_type or ('sweep' if sweep else 'breakout')),
            entry_price_override=signal['entry_price'],
            quality_score_override=quality_score_audit,
            quality_threshold_override=quality_threshold,
            quality_subscores_override=quality_subscores,
        )
    )
    confirmed, conf_score = _check_signal_confirmation(df, signal_direction)
    if not confirmed and score < mode_profile["confirmation_min_score_if_unconfirmed"]:
        _log_audit_only_gate(
            "recent_candle_confirmation_gate",
            "recent_candle_confirmation_audit",
            "Recent multi-candle confirmation score retained for audit only",
            metrics={"recent_candle_score": conf_score},
        )

    if conf_score >= 4.0:
        signal['rationale'].append(f"Recent candles confirm direction ({conf_score:.1f}/5)")
        recent_candle_confirmation_bonus = int(conf_score * 2)
        signal['recent_candle_confirmation_bonus'] = recent_candle_confirmation_bonus
        signal['confidence_score'] = score + recent_candle_confirmation_bonus
        quality_subscores = _live_quality_subscores_from_signal(
            signal,
            static_score=score,
            recent_candle_bonus=recent_candle_confirmation_bonus,
            final_score=signal['confidence_score'],
        )
        signal.update(
            _build_gate_audit_snapshot(
                trigger_type_override=signal['trigger_type'],
                entry_price_override=signal['entry_price'],
                quality_score_override=signal['confidence_score'],
                quality_threshold_override=quality_threshold,
                quality_subscores_override=quality_subscores,
            )
        )

    logger.info(
        f"[{symbol}] Base {signal_direction} setup assembled | "
        f"score={signal['confidence_score']} | "
        f"reasons={len(signal['rationale'])}"
    )

    # Direct entry anchor. Lower-timeframe pending confirmation has been removed.
    _trigger_type = signal['trigger_type']
    if _trigger_type == 'sweep':
        _trigger_level = swept_level
    else:
        _trigger_level = locals().get('breakout_level') or None

    if _trigger_level is None:
        return _reject_after_path(
            "entry_confirmation_anchor",
            "missing_confirmation_anchor",
            f"{_trigger_type} signal rejected: no structural anchor level available for live entry gate",
            trigger_type=_trigger_type,
            direction=signal_direction,
        )

    conf_entry = None

    signal.update(
        _build_gate_audit_snapshot(
            trigger_type_override=_trigger_type,
            entry_price_override=signal.get('entry_price'),
            quality_score_override=signal.get('confidence_score'),
            quality_threshold_override=quality_threshold,
            quality_subscores_override=quality_subscores,
        )
    )

    # Fresh-now entry gate for sweep/breakout.
    # 5m is retired. Breakout ADX expansion and candle-derived orderflow
    # confirmation are live gates; websocket orderflow remains optional telemetry.
    _entry_gate_price = _safe_float(
        signal.get('entry_price'),
        _safe_float(conf_entry, _safe_float(current_price, 0.0) or 0.0),
    ) or 0.0
    if _trigger_type in ('sweep', 'breakout') and _entry_gate_price > 0:
        _min_score_final_immediate = (
            mode_profile["min_score_sweep"] if _trigger_type == 'sweep'
            else mode_profile["min_score_breakout"]
        )
        try:
            adx_audit_states_imm = _collect_path_adx_audit_states(symbol, fallback_df=df)
            signal['adx_audit_states'] = _to_json_safe(adx_audit_states_imm)
            signal.update(_flatten_adx_audit_states(adx_audit_states_imm))
            adx_passed_imm, adx_score_imm, adx_rationale_imm, adx_state_imm = _evaluate_path_adx_confirmation(
                symbol,
                _trigger_type,
                fallback_df=df,
                adx_states=adx_audit_states_imm,
            )
            signal['adx_confirmation_state'] = _to_json_safe(adx_state_imm)
            signal['adx_confirmation_score'] = adx_score_imm
            adx_gate_decision_imm = 'passed' if adx_passed_imm else 'audit_only_failed'
            if not adx_passed_imm:
                if bool(SIGNAL_CONFIG.get("enable_path_adx_hard_gate", True)):
                    return _reject_after_path(
                        "cycle1_adx_gate",
                        "adx_confirmation_failed",
                        adx_rationale_imm[-1],
                        trigger_type=_trigger_type,
                        direction=signal_direction,
                    )
                _log_audit_only_gate(
                    "cycle1_adx_gate",
                    "adx_confirmation_failed",
                    adx_rationale_imm[-1],
                    metrics=adx_state_imm,
                )
                logger.info(
                    f"[{symbol}] ADX confirmation logged for audit only ({_trigger_type}): "
                    f"{adx_rationale_imm[-1]}"
                )
                signal['rationale'].append(
                    f"ADX confirmation logged for audit only ({_trigger_type}): {adx_rationale_imm[-1]}"
                )

            _tick_size_imm = 10 ** (-symbol_config.get('price_place', 4))
            _sweep_age_imm = (
                (len(df) - 1) - sweep_candle_idx
                if sweep and sweep_candle_idx is not None else 0
            )

            orderflow_requested_at_imm = _utc_now_iso()
            fresh_of_imm = await calculate_book_order_flow_imbalance(
                symbol,
                trigger_type='sweep' if sweep else 'breakout',
                tick_size=_tick_size_imm,
                sweep_age_candles=_sweep_age_imm,
                df=df if _trigger_type in {'sweep', 'breakout'} else None,
                sweep_candle_idx=sweep_candle_idx if sweep else None,
                breakout_idx=breakout_idx if _trigger_type == 'breakout' else None,
                breakout_level=breakout_level if _trigger_type == 'breakout' else None,
                key_levels=[_trigger_level] if _trigger_level else None,
                atr_value=atr_value,
                is_bullish=(signal_direction == 'BUY'),
            )
            orderflow_captured_at_imm = _utc_now_iso()
            if isinstance(fresh_of_imm, dict):
                fresh_of_imm["requested_at"] = orderflow_requested_at_imm
                fresh_of_imm["captured_at"] = orderflow_captured_at_imm
            else:
                fresh_of_imm = {
                    "reject_reason": "Orderflow fetch returned no usable payload",
                    "live_orderflow_source": "unavailable",
                    "requested_at": orderflow_requested_at_imm,
                    "captured_at": orderflow_captured_at_imm,
                }

            orderflow_unavailable_reason_imm = fresh_of_imm.get('reject_reason')
            of_gate_decision_imm = 'passed'
            if orderflow_unavailable_reason_imm:
                return _reject_after_path(
                    "cycle1_orderflow_unavailable",
                    "orderflow_unavailable_cycle1",
                    orderflow_unavailable_reason_imm,
                    trigger_type=_trigger_type,
                    direction=signal_direction,
                    entry_price_override=signal.get('entry_price'),
                )

            of_eval_imm = _evaluate_live_ws_orderflow_entry_confirmation(
                trigger_type=_trigger_type,
                direction=signal_direction,
                fresh_of=fresh_of_imm,
                mode_profile=mode_profile,
                price_place=price_place,
                entry_price=signal.get('entry_price'),
                tp1=signal.get('take_profit_1', signal.get('entry_price')),
            )
            of_score_imm = int(of_eval_imm['of_score'])
            of_votes_imm = int(of_eval_imm['of_votes'])
            ms_score_imm = int(of_eval_imm['microstructure_score'])
            of_rationale_imm = list(of_eval_imm['rationale'])
            rel_p_imm = float(of_eval_imm['directional_pressure'])
            imb_imm = float(of_eval_imm['imbalance'])
            rel_p_slope_imm = float(of_eval_imm.get('directional_pressure_slope', 0.0) or 0.0)
            imb_slope_imm = float(of_eval_imm.get('imbalance_slope', 0.0) or 0.0)
            soft_bypassed_final_score_imm = False

            if of_eval_imm.get('hard_block_reason'):
                return _reject_after_path(
                    "cycle1_orderflow_gate",
                    "path_specific_orderflow_failed",
                    of_eval_imm['hard_block_reason'],
                    trigger_type=_trigger_type,
                    direction=signal_direction,
                    entry_price_override=signal.get('entry_price'),
                )

            final_score_imm = int(score + adx_score_imm + of_score_imm + (of_votes_imm * 2) + ms_score_imm)
            quality_threshold = round(float(_min_score_final_immediate), 4)
            quality_score_audit = round(float(final_score_imm), 4)
            quality_subscores = _build_quality_subscores(
                static_score=score,
                recent_candle_bonus=recent_candle_confirmation_bonus,
                of_score=of_score_imm,
                of_votes=of_votes_imm,
                microstructure_score=ms_score_imm,
                adx_score=adx_score_imm,
                final_score=final_score_imm,
            )
            signal['of_score'] = of_score_imm
            signal['of_votes_raw'] = of_votes_imm
            signal['microstructure_score'] = ms_score_imm
            signal['quality_score'] = quality_score_audit
            signal['quality_threshold'] = quality_threshold
            signal['quality_subscores'] = quality_subscores
            signal['order_flow_signal'] = fresh_of_imm.get('signal')
            signal['order_flow_buy_pressure'] = fresh_of_imm.get('buy_pressure')
            signal['order_flow_sell_pressure'] = fresh_of_imm.get('sell_pressure')
            signal['order_flow_imbalance'] = fresh_of_imm.get('imbalance')
            signal['order_flow_cvd'] = fresh_of_imm.get('cvd')
            signal['order_flow_cvd_slope_per_trade'] = fresh_of_imm.get('cvd_slope_per_trade')
            signal['order_flow_cvd_intensity_delta_halves'] = fresh_of_imm.get('cvd_intensity_delta_halves')
            signal['order_flow_aggression_ratio'] = fresh_of_imm.get('aggression_ratio')
            signal['order_flow_aggression_ratio_delta_halves'] = fresh_of_imm.get('aggression_ratio_delta_halves')
            signal['order_flow_total_trade_vol'] = fresh_of_imm.get('total_trade_vol')
            signal['order_flow_icebergs_detected'] = fresh_of_imm.get('icebergs_detected')
            signal['order_flow_iceberg_direction'] = fresh_of_imm.get('iceberg_direction')
            signal['order_flow_bid_icebergs'] = fresh_of_imm.get('bid_icebergs')
            signal['order_flow_ask_icebergs'] = fresh_of_imm.get('ask_icebergs')
            signal['order_flow_bid_notional'] = fresh_of_imm.get('bid_notional')
            signal['order_flow_ask_notional'] = fresh_of_imm.get('ask_notional')
            signal['order_flow_spoofs_detected'] = fresh_of_imm.get('spoofs_detected')
            signal['order_flow_pressure_slope'] = rel_p_slope_imm
            signal['order_flow_imbalance_slope'] = imb_slope_imm
            signal['order_flow_live_source'] = fresh_of_imm.get('live_orderflow_source')
            signal['order_flow_requested_at'] = orderflow_requested_at_imm
            signal['order_flow_captured_at'] = orderflow_captured_at_imm
            signal['order_flow_window_seconds'] = _safe_int(fresh_of_imm.get('live_orderflow_window_seconds'))
            signal['order_flow_sweep_age_candles'] = _safe_int(fresh_of_imm.get('sweep_age_candles'))
            signal['order_flow_footprint'] = _to_json_safe(fresh_of_imm.get('footprint', {}))
            signal['order_flow_absorption'] = _to_json_safe(fresh_of_imm.get('absorption', {}))
            signal['order_flow_liquidity'] = _to_json_safe(fresh_of_imm.get('liquidity', {}))
            signal['order_flow_queue'] = _to_json_safe(fresh_of_imm.get('queue', {}))
            signal['order_flow_ws_diagnostics'] = _to_json_safe(fresh_of_imm.get('ws_diagnostics', {}))
            signal['candle_absorption_proxy'] = _to_json_safe(fresh_of_imm.get('candle_absorption_proxy'))
            signal['candle_divergence_proxy'] = _to_json_safe(fresh_of_imm.get('candle_divergence_proxy'))
            signal['breakout_candle_proxy'] = _to_json_safe(fresh_of_imm.get('breakout_candle_proxy'))
            signal.update(
                {
                    **_flatten_candle_proxy_fields(
                        fresh_of_imm.get('candle_absorption_proxy'),
                        fresh_of_imm.get('candle_divergence_proxy'),
                    ),
                    **_flatten_breakout_candle_proxy_fields(
                        fresh_of_imm.get('breakout_candle_proxy')
                    ),
                }
            )
            signal['order_flow_entry_snapshot'] = _to_json_safe(fresh_of_imm)
            if bool(SIGNAL_CONFIG.get("require_candlestick_orderflow_confirmation", True)):
                if _trigger_type == "breakout":
                    breakout_proxy = fresh_of_imm.get("breakout_candle_proxy") or {}
                    if not (
                        bool(breakout_proxy.get("available"))
                        and bool(breakout_proxy.get("continuation_confirmed"))
                    ):
                        return _reject_after_path(
                            "candlestick_orderflow_gate",
                            "breakout_candle_orderflow_failed",
                            (
                                "Breakout rejected: candle-derived orderflow continuation "
                                "proxy did not confirm acceptance/participation"
                            ),
                            trigger_type=_trigger_type,
                            direction=signal_direction,
                        )
                elif _trigger_type == "sweep":
                    absorption_proxy = fresh_of_imm.get("candle_absorption_proxy") or {}
                    if not (
                        bool(absorption_proxy.get("available"))
                        and bool(absorption_proxy.get("absorbed"))
                    ):
                        return _reject_after_path(
                            "candlestick_orderflow_gate",
                            "sweep_candle_absorption_failed",
                            (
                                "Sweep rejected: candle-derived absorption proxy "
                                "did not confirm wick/volume absorption"
                            ),
                            trigger_type=_trigger_type,
                            direction=signal_direction,
                        )
            signal['order_flow_confirmation_state'] = _to_json_safe(
                {
                    "trigger_type": _trigger_type,
                    "direction": signal_direction,
                    "requested_at": orderflow_requested_at_imm,
                    "captured_at": orderflow_captured_at_imm,
                    "directional_pressure": rel_p_imm,
                    "opposing_pressure": of_eval_imm.get('opposing_pressure'),
                    "directional_pressure_slope": rel_p_slope_imm,
                    "opposing_pressure_slope": of_eval_imm.get('opposing_pressure_slope'),
                    "imbalance": imb_imm,
                    "imbalance_slope": imb_slope_imm,
                    "buy_pressure": of_eval_imm.get('buy_pressure'),
                    "sell_pressure": of_eval_imm.get('sell_pressure'),
                    "buy_pressure_slope": of_eval_imm.get('buy_pressure_slope'),
                    "sell_pressure_slope": of_eval_imm.get('sell_pressure_slope'),
                    "cvd": of_eval_imm.get('cvd'),
                    "cvd_slope_per_trade": of_eval_imm.get('cvd_slope_per_trade'),
                    "cvd_intensity_delta_halves": of_eval_imm.get('cvd_intensity_delta_halves'),
                    "aggression_ratio": of_eval_imm.get('aggression_ratio'),
                    "aggression_ratio_delta_halves": of_eval_imm.get('aggression_ratio_delta_halves'),
                    "icebergs_detected": of_eval_imm.get('icebergs_detected'),
                    "iceberg_direction": of_eval_imm.get('iceberg_direction'),
                    "bid_icebergs": of_eval_imm.get('bid_icebergs'),
                    "ask_icebergs": of_eval_imm.get('ask_icebergs'),
                    "bid_notional": of_eval_imm.get('bid_notional'),
                    "ask_notional": of_eval_imm.get('ask_notional'),
                    "spoofs_detected": of_eval_imm.get('spoofs_detected'),
                    "footprint": of_eval_imm.get('footprint'),
                    "absorption": of_eval_imm.get('absorption'),
                    "liquidity": of_eval_imm.get('liquidity'),
                    "queue": of_eval_imm.get('queue'),
                    "ws_diagnostics": of_eval_imm.get('ws_diagnostics'),
                    "live_orderflow_source": fresh_of_imm.get('live_orderflow_source'),
                    "live_orderflow_window_seconds": fresh_of_imm.get('live_orderflow_window_seconds'),
                    "sweep_age_candles": fresh_of_imm.get('sweep_age_candles'),
                    "candle_absorption_proxy": fresh_of_imm.get('candle_absorption_proxy'),
                    "candle_divergence_proxy": fresh_of_imm.get('candle_divergence_proxy'),
                    "breakout_candle_proxy": fresh_of_imm.get('breakout_candle_proxy'),
                    "of_score": of_score_imm,
                    "of_votes": of_votes_imm,
                    "microstructure_score": ms_score_imm,
                    "hard_block_reason": of_eval_imm.get('hard_block_reason'),
                    "confirmation_model": of_eval_imm.get('confirmation_model'),
                    "confirmation_passed": of_eval_imm.get('passed'),
                    "confirmation_evidence": of_eval_imm.get('confirmation_evidence'),
                    "confirmation_failures": of_eval_imm.get('confirmation_failures'),
                    "sweep_event_evidence": of_eval_imm.get('sweep_event_evidence'),
                    "sweep_absorption_strength": of_eval_imm.get('sweep_absorption_strength'),
                    "sweep_delta_divergence_strength": of_eval_imm.get('sweep_delta_divergence_strength'),
                    "rationale": of_rationale_imm,
                }
            )
            live_of_snapshot_imm, candle_of_snapshot_imm = _build_orderflow_decision_snapshots(
                signal,
                df=df,
                captured_at=orderflow_captured_at_imm,
            )
            signal['order_flow_live_snapshot'] = _to_json_safe(live_of_snapshot_imm)
            signal['order_flow_candle_snapshot'] = _to_json_safe(candle_of_snapshot_imm)
            signal['decision_time_provenance'] = _to_json_safe(
                _build_decision_time_provenance(
                    signal,
                    df=df,
                    captured_at=orderflow_captured_at_imm,
                )
            )

            last_candle_state_imm = _evaluate_last_candle_directional_body(
                df,
                signal_direction,
                atr_value,
            )
            signal['last_candle_confirmation_state'] = _to_json_safe(last_candle_state_imm)
            simplified_gate_imm = _evaluate_simplified_live_entry_gate(
                trigger_type=_trigger_type,
                direction=signal_direction,
                fresh_of=fresh_of_imm,
                of_eval=of_eval_imm,
                adx_passed=adx_passed_imm,
                adx_state=adx_state_imm,
                last_candle_state=last_candle_state_imm,
            )
            signal['simplified_live_entry_gate'] = _to_json_safe(simplified_gate_imm)
            if bool(SIGNAL_CONFIG.get("enable_simplified_live_entry_gate", True)) and not simplified_gate_imm.get("passed"):
                _simplified_reason = (
                    "Simplified live entry gate failed: "
                    + "; ".join(str(item) for item in simplified_gate_imm.get("failures", [])[:8])
                )
                return _reject_after_path(
                    "simplified_live_entry_gate",
                    "simplified_live_entry_gate_failed",
                    _simplified_reason,
                    trigger_type=_trigger_type,
                    direction=signal_direction,
                    entry_price_override=signal.get('entry_price'),
                )
            signal['rationale'].append(
                "Simplified live entry gate passed: "
                + ", ".join(simplified_gate_imm.get("evidence") or [])
            )

            if final_score_imm < _min_score_final_immediate:
                _final_score_reason = (
                    f"Fresh-now entry gate below threshold: final={final_score_imm} < "
                    f"required={_min_score_final_immediate}"
                )
                _final_score_metrics = {
                    "final_score": final_score_imm,
                    "required_score": _min_score_final_immediate,
                    "static_score": score,
                    "adx_score": adx_score_imm,
                    "of_score": of_score_imm,
                    "of_votes": of_votes_imm,
                    "microstructure_score": ms_score_imm,
                }
                if _use_orderflow_final_score_gate():
                    return _reject_after_path(
                        "cycle1_final_score_gate",
                        "of_final_score_below_threshold",
                        _final_score_reason,
                        trigger_type=_trigger_type,
                        direction=signal_direction,
                        entry_price_override=signal.get('entry_price'),
                    )
                soft_bypassed_final_score_imm = True
                _log_audit_only_gate(
                    "cycle1_final_score_gate",
                    "of_final_score_below_threshold",
                    _final_score_reason,
                    metrics=_final_score_metrics,
                )
                logger.info(
                    f"[{symbol}] Fresh-now entry final-score logged for audit only "
                    f"({_trigger_type}): final={final_score_imm} < required={_min_score_final_immediate}"
                )
                of_rationale_imm.append(
                    f"Order flow final-score logged for audit only: final={final_score_imm} "
                    f"< required={_min_score_final_immediate}"
                )
                if of_gate_decision_imm == 'passed':
                    of_gate_decision_imm = 'audit_only_final_score_below_threshold'

            logger.info(
                f"[{symbol}] "
                f"{'ENTRY GATE SCORE-AUDIT' if soft_bypassed_final_score_imm else 'ENTRY GATE PASSED'} "
                f"({_trigger_type} cycle-1): final={final_score_imm} "
                f"{'<' if soft_bypassed_final_score_imm else '>='} required={_min_score_final_immediate} | "
                f"static={score} + adx={adx_score_imm} + of={of_score_imm} + "
                f"of_votes={of_votes_imm * 2} + ms={ms_score_imm} | "
                f"pressure={rel_p_imm:.0f}% imbalance={imb_imm:.3f}"
            )
            for r in adx_rationale_imm:
                logger.info(f"  [ADX@CYCLE1] {r}")
            for r in of_rationale_imm:
                logger.info(f"  [OF@CYCLE1] {r}")

            _live_price_final = get_current_price(symbol)
            if _live_price_final is not None and _trigger_level and atr_value > 0:
                _post_of_proximity_state = _evaluate_confirmation_aware_entry_proximity(
                    df=df,
                    direction=signal_direction,
                    trigger_type=_trigger_type,
                    trigger_level=_trigger_level,
                    entry_price=float(_live_price_final),
                    atr_value=atr_value,
                    price_place=price_place,
                    stage="cycle1_post_orderflow",
                )
                if not _post_of_proximity_state.get("passed"):
                    return _reject_after_path(
                        "cycle1_post_of_proximity_gate",
                        "cycle1_post_of_proximity_failed",
                        f"Post-OF {_post_of_proximity_state.get('reason')}",
                        trigger_type=_trigger_type,
                        direction=signal_direction,
                        entry_price_override=_safe_float(_live_price_final, signal.get('entry_price')),
                    )
                else:
                    signal['post_of_proximity_state'] = _to_json_safe(_post_of_proximity_state)
                    signal['proximity_dist_atr_at_entry'] = _safe_float(_post_of_proximity_state.get("entry_distance_atr"))
                    signal['proximity_max_atr_at_entry'] = _safe_float(_post_of_proximity_state.get("max_entry_atr"))
                    signal['post_of_proximity_mode'] = _post_of_proximity_state.get("mode")
                logger.info(
                    f"[{symbol}] {_post_of_proximity_state.get('reason')}"
                )

            signal['rationale'].append(
                f"ADX checked at entry: {'PASSED' if adx_passed_imm else 'AUDIT-ONLY FAIL'} "
                f"(current={adx_state_imm.get('current_adx')}, prior={adx_state_imm.get('prior_adx')}, "
                f"delta={adx_state_imm.get('adx_delta')}, score={adx_score_imm:+d})"
            )
            signal['rationale'].append(
                f"Order flow checked at entry: "
                f"{'SCORE-AUDIT' if soft_bypassed_final_score_imm else ('AUDIT-ONLY ISSUE' if of_gate_decision_imm != 'passed' else 'PASSED')} "
                f"(final_score={final_score_imm}, pressure={rel_p_imm:.0f}%, "
                f"imbalance={imb_imm:.3f}, ms={ms_score_imm:+d}pts, adx={adx_score_imm:+d}pts)"
            )
            signal['rationale'].extend([f"  [ADX@CYCLE1] {r}" for r in adx_rationale_imm])
            signal['rationale'].extend([f"  [OF@CYCLE1] {r}" for r in of_rationale_imm])
            signal['confidence_score'] = final_score_imm
            if soft_bypassed_final_score_imm:
                of_gate_decision_imm = 'audit_only_final_score_below_threshold'
            signal['of_gate_decision'] = of_gate_decision_imm
            signal['of_gate_stage'] = 'cycle1'
            signal['of_gate_final_score'] = final_score_imm
            signal['of_gate_min_score_final'] = _min_score_final_immediate
            signal['of_gate_directional_pressure'] = rel_p_imm
            signal['of_gate_imbalance'] = imb_imm
            signal['of_gate_directional_pressure_slope'] = rel_p_slope_imm
            signal['of_gate_imbalance_slope'] = imb_slope_imm
            signal.update(
                _build_gate_audit_snapshot(
                    trigger_type_override=_trigger_type,
                    entry_price_override=signal.get('entry_price'),
                    quality_score_override=quality_score_audit,
                    quality_threshold_override=quality_threshold,
                    quality_subscores_override=quality_subscores,
                )
            )
            _record_live_of_gate_shadow(
                signal,
                stage='cycle1',
                of_gate_decision='audit_only_final_score_below_threshold' if soft_bypassed_final_score_imm else 'passed',
                of_gate_reason_code='of_gate_final_score_audit_low' if soft_bypassed_final_score_imm else 'of_gate_passed',
                of_gate_reason_text=(
                    (
                        f"Cycle-1 entry score audit below threshold: final={final_score_imm} < "
                        f"required={_min_score_final_immediate}"
                    )
                    if soft_bypassed_final_score_imm
                    else (
                        f"Cycle-1 entry gate passed: final={final_score_imm} >= "
                        f"required={_min_score_final_immediate}"
                    )
                ),
                final_score=final_score_imm,
                static_score=score,
                min_score_final=_min_score_final_immediate,
                of_score=of_score_imm,
                of_votes=of_votes_imm,
                microstructure_score=ms_score_imm,
                directional_pressure=rel_p_imm,
                imbalance=imb_imm,
                decision_candle_time=_last_df_timestamp(df),
                atr_value=atr_value,
                df_for_sl=df,
                price_place=price_place,
                direction=signal_direction,
                trigger_type=_trigger_type,
                swept_level=swept_level if sweep else None,
            )

        except Exception as _of_imm_e:
            logger.warning(
                f"[{symbol}] Fresh-now order flow/ADX gate failed at cycle-1 confirmation: {_of_imm_e}"
            )
            signal['rationale'].append(
                f"Fresh-now entry gate failed on live data fetch: {_of_imm_e}"
            )
            return None, str(_of_imm_e)

    if bool(SIGNAL_CONFIG.get("enable_live_confirmation_evidence_gate", True)):
        live_evidence_gate = _evaluate_live_confirmation_evidence(
            signal,
            trigger_type=_trigger_type,
            direction=signal_direction,
        )
        signal["live_confirmation_evidence_gate"] = _to_json_safe(live_evidence_gate)
        if not live_evidence_gate.get("passed"):
            required_any = ", ".join(live_evidence_gate.get("required_any") or [])
            return _reject_after_path(
                "live_confirmation_evidence_gate",
                "missing_live_confirmation_evidence",
                (
                    "Missing required live confirmation evidence before placement "
                    f"(need any of: {required_any})"
                ),
                trigger_type=_trigger_type,
                direction=signal_direction,
                entry_price_override=signal.get("entry_price"),
            )
        signal["rationale"].append(
            "Live confirmation evidence present: "
            + ", ".join(live_evidence_gate.get("evidence") or [])
        )

    signal["signal_decision_record"] = _to_json_safe(_build_signal_decision_record(signal))

    # Optional: auto-place trade if live trading is enabled.
    # Cache the signal ONLY after placing the trade — this prevents the same
    # setup from triggering duplicate trades across cycles. If live trading is
    # disabled, we do NOT cache so every cycle re-evaluates fresh market data.
    if os.getenv("ENABLE_LIVE_TRADING", "False").lower() == "true":
        placement_result = await place_trade(signal)
        signal["_placement_result"] = placement_result
        if placement_result and placement_result.get('placed'):
            cache_trade_signal(signal, symbol=symbol, reason="trade placement")

    logger.info(f"Signal generation completed in {time.time() - start_time:.2f}s")

    return signal, None


# ─── Signal Summary Wrapper ────────────────────────────────────────────────
async def get_signal_summary(symbol: str, signal=None, reason=None):
    """
    High-level wrapper that returns a clean summary dict,
    suitable for API responses, dashboards, alerts, etc.
    Accepts a pre-computed signal dict to avoid calling generate_trade_signal twice.
    If signal is not provided, generates it fresh (standalone use).
    """
    if signal is None:
        signal, reason = await generate_trade_signal(symbol)

    if not signal:
        current_price = get_current_price(symbol) or 0
        return {
            'symbol': symbol,
            'signal': 'NO_SIGNAL',
            'strength': 0,
            'conditions_met': False,
            'market_structure': 'UNKNOWN',
            'current_price': current_price,
            'timestamp': time.time(),
            'rationale': [reason] if reason else ["No valid setup detected"]
        }

    # ── Cached signal: always surface with full detail + cache status ─────────
    is_cached         = signal.get('_cached', False)
    cache_elapsed_s   = signal.get('_cache_elapsed_s', 0)
    cache_remaining_s = signal.get('_cache_remaining_s', 0)
    cache_timeout_s   = signal.get('_cache_timeout_s', SIGNAL_CONFIG.get('signal_cache_timeout', 72000))

    cache_status = None
    if is_cached:
        elapsed_min   = cache_elapsed_s   // 60
        remaining_min = cache_remaining_s // 60
        total_min     = cache_timeout_s   // 60
        cache_status  = {
            'is_cached'    : True,
            'elapsed_min'  : elapsed_min,
            'remaining_min': remaining_min,
            'total_min'    : total_min,
            'pct_elapsed'  : round(cache_elapsed_s / max(cache_timeout_s, 1) * 100, 1),
        }
        # Prepend cache notice to rationale so it's visible at position 0
        cached_rationale = [
            f"[CACHED SIGNAL — {elapsed_min}min ago, expires in {remaining_min}min "
            f"({cache_elapsed_s//60*60}s / {cache_timeout_s}s elapsed)]"
        ] + list(signal.get('rationale', []))
    else:
        cached_rationale = signal.get('rationale', [])

    return {
        'symbol': symbol,
        'signal': signal['direction'],
        'trigger_type': signal.get('trigger_type', 'unknown'),
        'orderflow_basis': (
            signal.get('orderflow_basis')
            or ((signal.get('order_flow_entry_snapshot') or {}).get('coverage') or {}).get('basis')
        ),
        'strength': signal['confidence_score'],
        'conditions_met': True,
        'cache_status': cache_status,
        'market_structure': 'BULLISH' if signal['direction'] == 'BUY' else 'BEARISH',
        'current_price': signal['entry_price'],
        'timestamp': time.time(),
        'entry': signal['entry_price'],
        'stop_loss': signal['stop_loss'],
        'take_profit_1': signal['take_profit_1'],
        'take_profit_2': signal['take_profit_2'],
        'trailing_stop_loss': signal['trailing_stop_loss'],
        'position_size': round(signal['position_size'], 6),
        'rationale': cached_rationale,
        'market_regime': signal['market_regime'],
        'htf_confluence_score': signal['htf_confluence'],
        'order_flow': {
            'buy_pressure': signal['order_flow'].get('buy_pressure'),
            'sell_pressure': signal['order_flow'].get('sell_pressure'),
            'imbalance': signal['order_flow'].get('imbalance'),
            'aggression_ratio': signal['order_flow'].get('aggression_ratio'),
            'total_trade_vol': signal['order_flow'].get('total_trade_vol')
        },
        # ── Microstructure summary (quant-level signal quality indicators) ────
        'microstructure': {
            'score':             signal.get('microstructure', {}).get('score', 0),
            'delta_divergence':  signal.get('microstructure', {}).get('delta_divergence', False),
            'ob_level_absorbed': signal.get('microstructure', {}).get('ob_level_absorbed', False),
            'queue_drain':       signal.get('microstructure', {}).get('queue_drain', False),
            'migration_count':   signal.get('microstructure', {}).get('migration_count', 0),
            # Detailed sub-fields for downstream consumers (dashboard/reporting, etc.)
            'footprint': {
                'divergence_strength': (
                    signal.get('microstructure', {}).get('footprint', {}) or {}
                ).get('divergence_strength', 0.0),
                'net_delta': (
                    signal.get('microstructure', {}).get('footprint', {}) or {}
                ).get('net_delta', 0.0),
                'top_opposed_levels': (
                    signal.get('microstructure', {}).get('footprint', {}) or {}
                ).get('top_opposed_levels', [])[:3],  # top 3 for summary
            },
            'absorption': {
                'max_ratio':   (
                    signal.get('microstructure', {}).get('absorption', {}) or {}
                ).get('max_absorption_ratio', 0.0),
                'level_count': len(
                    (signal.get('microstructure', {}).get('absorption', {}) or {})
                    .get('absorbed_levels', [])
                ),
            },
            'liquidity': {
                'wall_count':  len(
                    (signal.get('microstructure', {}).get('liquidity', {}) or {})
                    .get('liquidity_walls', [])
                ),
                'void_count':  len(
                    (signal.get('microstructure', {}).get('liquidity', {}) or {})
                    .get('liquidity_voids', [])
                ),
                'migration_count': len(
                    (signal.get('microstructure', {}).get('liquidity', {}) or {})
                    .get('migration_events', [])
                ),
            },
            'queue': {
                'bid_z':       (
                    signal.get('microstructure', {}).get('queue', {}) or {}
                ).get('bid_z_score', 0.0),
                'ask_z':       (
                    signal.get('microstructure', {}).get('queue', {}) or {}
                ).get('ask_z_score', 0.0),
            }
        }
    }


# ─── Batch Processing Example ──────────────────────────────────────────────
async def process_tickers(tickers):
    """
    Batch processor for multiple symbols using synchronous market-data fetches.
    """
    tickers = list(dict.fromkeys(tickers))
    interval = SIGNAL_CONFIG['candlestick_interval']
    limit = SIGNAL_CONFIG['candlestick_limit']

    batch_data = get_batch_candlestick_data_sync(tickers, interval, limit)

    df_dict = {}
    for symbol in tickers:
        if symbol in batch_data and batch_data[symbol]:
            df = fetch_and_prepare_data_sync(symbol, interval, limit, batch_mode=True)
            if df is not None:
                df_dict[symbol] = df

    # Clean old cache entries
    current_time = time.time()
    stale = [k for k, (_, t) in _signal_cache.items() if current_time - t > SIGNAL_CONFIG.get('signal_cache_timeout', 72000)]
    for k in stale:
        del _signal_cache[k]

    summaries = []
    for symbol in tickers:
        try:
            signal, reason = await generate_trade_signal(symbol, df_dict.get(symbol))
            summary = await get_signal_summary(symbol, signal=signal, reason=reason)
            summaries.append(summary)
        except Exception as exc:
            logger.warning(f"[{symbol}] Batch signal generation failed: {exc}")
    return summaries


# ─── Utility to clear caches (useful during development) ───────────────────
def clear_data_cache():
    _operational_tf_cache.clear()
    logger.info("Operational candle cache cleared")


